const KZ = {
  "䲡鱼":{o:[],src:["本草纲目"],d:"新五。\n消渴饮水︰用泥鳅鱼（十头阴干，去头尾，烧灰）、干荷叶等分。为末。每服二钱，新汲水调下，日三。名沃焦散。（《普济方》）\n喉中物哽︰用生鳅鱼，线牢缚其头，以尾先入喉中，牵拽出之。（《普济方》）\n揩牙乌髭︰泥鳅入瓦罐内，盐泥固济阳事不起︰泥鳅煮食之。（《集简方》）\n牛狗羸瘦︰取鳅鱼一、二枚，从口鼻送入，立肥也。（陈藏器）"},
  "不灰木":{o:[],src:["本草纲目"],d:"新四。\n肺热咳嗽，卧时盛者︰不灰木一两半，太阴玄精石二两，甘草（炙）半两，贝母一两半，天南星（白矾水煮过）半两。为末。每服半钱，姜汤下。（《圣济录》）\n咽喉肿痛，五心烦热︰不灰木（以牛粪烧赤）四两，太阴玄精石（ 赤）四两，真珠一钱。为末，糯米粥丸芡子大。每服一丸，以生地黄汁、粟米泔研化服，日二次。（《圣济录》）\n霍乱烦满，气逆腹胀，手足厥冷︰不灰木、阳起石（煅）、阿魏各半两，巴豆（去心）、杏仁（去皮）各二十五个。为末，粟饭丸樱桃大，穿一孔。每服一丸，灯上烧烟尽，研末，米姜汤下，以利为度。（《圣济录》）\n阴毒腹痛︰回阳丹︰用不灰木、牡蛎（煅）、高良姜（炒）、川乌头（炮）、白芍药各一钱。为末，入麝香少许。每用一钱，男，用女唾调涂外肾；女，用男唾调涂乳上，得汗即愈。（《玉机微义》）"},
  "丝瓜":{o:["丝瓜"],src:["本草备要", "本草纲目"],d:"泻热凉血，宣通经络\n甘平（苏颂曰冷）。凉血解毒，除风化痰，通经络，行血脉（老者筋络贯穿，象人经络，故可借其气以引之），消浮肿，稀痘疮（出不快者，烧存性，入朱砂，蜜水调服）。治肠风崩漏，疝痔痈疽，滑肠下乳。"},
  "丹砂":{o:["丹砂"],src:["本草备要", "本草纲目"],d:"重，镇心，定惊，泻热\n体阳性阴（内含阴汞），味甘而凉，色赤属火（性反惊者，离中虚有阴也。味不苦而甘者，火中有土也）。泻心经邪热（心经血分主药），镇心清肝，明目发汗（汗为心液），定惊祛风，辟邪（胡玉少卿多恶梦，遇推官胡用之，胡曰∶昔常患此，有道士教戴灵砂而验。逐解髻中绛囊授之，即夕无梦）解毒（胎毒、痘毒宜之），止渴安胎（《博救方》∶水煮一两，研，酒服，能下死胎。李时珍曰∶同远志、龙骨之类养心气；同丹参、当归之类养心血；同地黄、枸杞之类养肾；同浓朴，川椒之类养脾；同南星、川乌之类祛风。多服反令人痴呆）。辰产，明如箭镞者良（名箭镞砂）。细研，水飞三次用（生用无毒，火炼则有毒，服饵常杀人）。恶磁石。畏盐水。忌一切血（郑康成注《周礼》，以丹砂、雄黄、石胆、矾石、磁石为五毒，古人用以攻疡）。"},
  "乌头":{o:[],src:["本草纲目"],d:"旧二十七，新九十二。少阴伤寒，初得二、三日，脉微细，但欲寐，小便色白者，麻黄附子甘草汤微发其汗︰麻黄（去节）二两，甘草（炙）二两，附子（炮去皮）一枚，水七升，先煮麻黄去沫，纳二味，煮取三升，分作三服，取微汗。（张仲景《伤寒论》）\n少阴发热，少阴病始得，反发热脉沉者，麻黄附子细辛汤发其汗︰麻黄（去节）二两，附子（炮去皮）一枚，细辛二两，水一斗，先煮麻黄去沫，乃纳二味，同煮三升，分三服。（同上）人面赤色，或腹痛，或干呕，或咽痛，或利止脉不出者︰通脉四逆汤︰用大附子一个（去皮生破八片），甘草（炙）二两，干姜三两，水三升，煮一升二合，分温再服，其脉即出者愈。面赤加葱九茎；腹痛，加芍药二两；呕，加生姜二两；咽痛，加桔梗一两；利止脉不出，加人参二两。（同上）阴病恶寒，伤寒已发汗不解，反恶寒者，虚也，芍药甘草附子汤补之︰芍药三两，甘草（炙）三两，附子（炮去皮）一枚，水五升，煮取一升五合，分服。（同上）伤寒发躁，伤寒下后，又发其汗，昼日烦躁不得眠，夜而安静，不呕不渴，无表证，脉沉微，身无大热者，干姜附子汤温之︰干姜一阴盛格阳，伤寒阴盛格阳，其人必躁热而不欲饮水，脉沉手足厥逆者，是此证也︰霹雳散︰用大附子一枚。烧存性，为末。蜜水调服。逼散寒气，然后热气上行而汗出，乃愈。（孙兆《口诀》）\n热病吐下及下利，身冷脉微，发躁不止者︰附子（炮）一枚（去皮脐，分作八片）。入盐一钱，阴毒伤寒︰孙兆《口诀》云︰房后受寒，少腹疼痛，头疼腰重，手足厥逆，脉息沉细，或作呃逆，并宜退阴散︰用川乌头、干姜等分，切炒，放冷为散。每服一钱，水一盏，盐一撮，煎取半盏，温服，得汗解。《本事方》玉女散︰治阴毒心腹痛厥逆恶候。川乌头去皮脐，冷水浸七日，切晒，纸裹收之。遇有患者，取为末一钱，入盐八分，水一盏，煎八分服，压下阴毒，如猪血相似，再进一服。《济生》回阳散︰治阴毒伤寒，面青，四肢厥逆，腹痛身冷，一切冷气。大附子三枚，炮裂去皮脐为末。每服三钱，姜汁半盏，冷酒半盏，调服。良久，脐下如火暖为度。\n《续传信方》︰治阴毒伤寒，烦躁迷闷，急者。用半两重附子一个（生破作四片），生姜一大块（作三片），糯米一撮，以水一升，煎六合，温服。暖卧，或汗出，或不出。候心定，则以水解散之类解之，不得与冷水。如渴，更煎滓服。屡用多效。中风痰厥，昏不知人，口眼斜，并体虚之人患疟疾寒多者︰三生饮︰用生川乌头、生附子（并去皮脐）各半两，生南星一两，生木香二钱五分。每服五钱，生姜十片，水二盏，煎一盏，温服。（《和剂局方》）\n中风气厥痰壅，昏不知人，六脉沉伏︰生附子（去皮）、生南星（去皮）、生木香半两。每服四钱，姜九片，水二盏，煎七分，温服之。（《济生方》）\n中风偏废︰羌活汤︰用生附子一个（去皮脐），羌活、乌药各一两。每服四钱，生姜三片，水一盏，煎七分服。（王氏《简易方》）\n半身不遂，遂令癖疰︰用生附子一两，以无灰酒一升，浸一七日，隔日饮一合。（《延年秘录》）\n风病瘫缓︰手足 曳，口眼 斜，语音蹇涩，步履不正，宜神验乌龙丹主之︰川乌头（去皮脐）、五灵脂各五两，为末。入龙脑、麝香五分，滴水为丸，如弹子大。每服一丸，先以生姜汁研化，暖酒调服，一日二服。至五、七丸，便觉抬得手、移得步，十丸可以梳头也。（《梅师方》）\n风寒湿痹，麻木不仁，或手足不遂︰生川乌头末，每以香白米煮粥一碗，入末四钱，慢熬得所，下姜汁一匙，蜜三大匙，空腹啜之。或入薏苡末二钱。《左传》云︰风淫末疾，谓四末也。脾主四肢，风淫客肝，则侵脾而四肢病也。此汤极有力，予每授人良验。（许学士《本事方》）\n体虚有风，外受寒湿，身如在空中︰生附子、生天南星各二钱，生姜十片，水一盏半，慢火煎服。予曾病此，医博士张发授此方，三服愈。（《本事方》）\n口眼 斜︰生乌头、青矾各等分。为末。每用一字，搐入鼻内，取涕吐涎，立效无比，名通产后中风，身如角弓反张，口噤不语︰川乌头五两（锉块），黑大豆半升，同炒半黑，以酒三升，倾锅内急搅，以绢滤取酒，微温服一小盏，取汗。若口不开，拗开灌之。未效，加乌鸡粪一合炒，纳酒中服，以瘥为度。（《圣惠方》）\n诸风血风︰乌荆丸︰治诸风纵缓，言语蹇涩，遍身麻痛，皮肤瘙痒，及妇人血风，头痛目眩，肠风脏毒，下血不止者，服之尤效。有痛风挛搐，颐颔不收者，服六、七服即瘥也︰川乌头（炮去皮脐）一两，荆芥穗二两，为末，醋面糊丸梧子大。温酒或熟水，每服二十丸。（《和剂方》）\n妇人血风虚冷，月候不匀，或手脚心烦热，或头面浮肿顽麻︰用川乌头一斤（清油四两，盐四两，铛内同熬，令裂如桑椹色为度，去皮脐），五灵脂四两，为末，捣匀，蒸饼丸如梧子大。空心温酒、盐汤下二十丸。亦治丈夫风疾。（《梅师方》）\n诸风痫疾︰生川乌头（去皮）二钱半，五灵脂半两，为末，猪心血丸梧子大。每姜汤化服一丸小儿慢惊搐搦，涎壅厥逆︰川乌头（生去皮脐）一两，全蝎十个（去尾），分作三服，水一盏，姜七片，煎服。（汤氏《婴孩宝鉴》）\n小儿项软，乃肝肾虚，风邪袭入︰用附子（去皮脐）、天南星各二钱，为末，姜汁调摊，贴天小儿囟陷︰绵乌头、附子（并生去皮脐）二钱，雄黄八分，为末，葱根捣和作饼，贴陷处。（《全幼心鉴》）\n麻痹疼痛︰仙桃丸︰治手足麻痹，或瘫痪疼痛，腰膝痹痛，或打扑伤损闪肭，痛不可忍︰生川乌（不去皮）、五灵脂各四两，威灵仙五两。洗焙为末，酒糊丸梧子大。每服七丸至十丸，盐汤下，忌茶。此药常服，其效如神。（《普济方》）\n风痹肢痛，营卫不行︰川乌头二两（炮去皮，以大豆同炒，至豆汁出为度，去豆焙干），全蝎半两（焙）。为末，酽醋熬稠，丸绿豆大。每温酒下七丸，日一服。（《圣惠方》）\n腰脚冷痹疼痛，有风︰川乌头三个生，去皮脐，为散。醋调涂帛上，贴之。须臾痛止。（《大风诸痹，痰 胀满︰大附子（半两者）二枚，炮拆，酒渍之，春冬五日，夏秋三日。每服一脚气腿肿，久不瘥者︰黑附子一个（生，去皮脐）。为散。生姜汁调如膏，涂之。药干再涂，十指疼痛，麻木不仁︰生附子（去皮脐）、木香各等分，生姜五片，水煎温服。（王氏《易简搜风顺气︰乌附丸︰用川乌头二十个，香附子半斤，姜汁淹一宿，炒焙为末，酒糊丸梧子大头风头痛︰《外台秘要》︰用腊月乌头一升，炒令黄，末之，以绢袋盛，浸三斗酒中。逐日温服。孙兆《口诀》︰用附子（炮）、石膏（煅）等分，为末，入脑、麝少许。每服半钱，茶酒任下。《修真秘旨》︰用附子一枚（生，去皮脐），绿豆一合，同入铫子内煮，豆熟为度，去附子，食绿豆，立瘥。每个可煮五次，后为末服之。风毒头痛︰《圣惠方》︰治风毒攻注头目，痛不可忍︰大附子一枚（炮去皮为末）。以生姜一两，大黑豆一合，炒熟，同酒盏，煎七分，调附末一钱，温服。又方︰治二三十年头风不愈者，用大川乌头（生去皮）四两，天南星（炮）一两。为末，每服二钱，细茶三钱，薄荷七叶，盐梅一个，水一盏，煎七分，临卧温服。《朱氏集验方》︰治头痛连睛者。生乌头一钱，白芷四钱。为末。茶服一字。仍以末搐鼻。有人用之得效。风寒头痛︰《十便良方》︰治风寒客于头中，清涕，项筋急硬，胸中寒痰，呕吐清水︰用大附子或大川乌头二枚（去皮蒸过），芎 、生姜各一两，焙研，以茶汤调服一钱。或锉片，每用五钱，水煎服。隔三、四日一服。或加防风一两。《三因方》必效散︰治风寒流注，偏正头痛，年久不愈，最有神效。用大附子一个（生切四片，以姜汁一盏浸炙，再浸再炙，汁尽乃止），高良姜等分，为末。每服一钱，腊茶清调下，忌热物少时。头风摩散，沐头中风，头面多汗恶风，当先风一日则痛甚︰用大附子一个（炮）、食盐等分，为末。以方寸匕摩囟上，令药力行。或以油调稀亦可，一日三上。（张仲景方）\n年久头痛︰川乌头、天南星等分，为末。葱汁调涂太阳穴。（《经验》）\n头风斧劈难忍︰川乌头末烧烟熏碗内，温茶泡服之。（《集简方》）\n痰厥头痛如破，厥气上冲，痰塞胸膈︰炮附子三分，釜墨四钱，冷水调服方寸匕，当吐即愈。忌猪肉、冷水。肾厥头痛︰《指南方》︰用大附子一个（炮熟去皮），生姜半两，水一升半煎，分三服。《经验良方》韭根丸︰治元阳虚，头痛如破，眼睛如锥刺。大川乌头（去皮微炮）、全蝎（以糯米炒过，去米）等分为末，韭根汁丸绿豆大。每薄荷茶下十五丸，一日一服。气虚头痛，气虚上壅，偏正头痛，不可忍者︰大附子一枚（去皮脐）。研末，葱汁面糊丸绿豆大。每服十丸，茶清下。僧继洪《澹寮方》蝎附丸︰元气虚头痛，惟此方最合造化之妙。附子助阳扶虚，钟乳补阳镇坠，全蝎取其钻透，葱涎取其通气。汤使用椒以达下，盐以引用，使虚气下归。对证用之，无不作效。大附子一枚剜心，入全蝎（去毒）三枚在内，以余附末同钟乳粉二钱半，白面少许，水和作剂，包附煨熟，去皮研末，葱涎和丸梧子大。每椒盐汤下五十丸。肾气上攻，头项不能转移︰椒附丸︰用大熟附子一枚，为末。每用二钱，以椒二十粒，用白面填满椒口，水一盏半，姜七片，煎七分，去椒入盐，空心点服。椒气下达，以引逆气归经也。（《本事方》）\n鼻渊脑泄︰生附子末，葱涎和如泥， 涌泉穴。（《普济》）\n耳鸣不止，无昼夜者︰乌头（烧作灰）、菖蒲等分，为末，绵裹塞之，日再用，取效。（《杨氏产乳》）\n耳卒聋闭︰附子醋浸，削尖插之。或更于上灸二七壮。（《本草拾遗》）\n耳脓血︰生附子为末，葱涕和，灌耳中。（《肘后》）\n喉痹肿塞︰附子去皮，炮令拆，以蜜涂上，炙之令蜜入，含之勿咽汁。已成者即脓出，未成者即消。（出《本草拾遗》）\n久患口疮︰生附子为末，醋、面调贴足心，男左女右，日再换之。（《经验后方》）\n风虫牙痛︰《普济方》︰用附子一两（烧灰），枯矾一分，为末，揩之。又方︰川乌头、川附眼暴赤肿，碜痛不得开，泪出不止︰削附子赤皮末，如蚕砂大，著 中，以定为度。（张文仲《备急方》）。一切冷气︰去风痰，定遍身疼痛，益元气，强精力，固精益髓，令人少病︰川乌头一斤，用五升大瓷钵子盛，以童子小便浸七日，逐日添令溢出，拣去坏者不用。余以竹刀切作四片，新汲水淘七次，乃浸之，日日换水，日足，取焙为末，酒煮面糊丸绿豆大。每服十丸，空心盐汤下，少粥饭压之。（《经验方》）\n升降诸气，暖则宣流︰熟附子一大个，分作二服，水二盏，煎一盏，入沉香汁温服。（《和剂局方》）\n中寒昏困︰姜附汤︰治体虚中寒，昏不知人，及脐腹冷痛，霍乱转筋，一切虚寒之病︰生附子一两（去皮脐），干姜（炮）一两，每服三钱，水二钟，煎一钟，温服。（《和剂局方》）\n心腹冷痛，冷热气不和︰山栀子、川乌头等分，生研为末，酒糊丸梧子大。每服十五丸，生姜汤下。小肠气痛，加炒茴香，葱酒下二十丸。（王氏《博济方》）\n心痛疝气，湿热因寒郁而发︰用栀子降湿热，乌头破寒郁。乌头为栀子所引，其性急速，不留胃中也。川乌头、山栀子各一钱，为末。顺流水入姜汁一匙，调下。（《丹溪纂要》）\n寒厥心痛，及小肠膀胱痛不可止者︰神砂一粒丹︰用熟附子（去皮）、郁金、橘红各一两，为末，醋面糊丸如酸枣大，朱砂为衣。每服一丸，男子酒下；女人醋汤下。（《宣明方》）\n寒疝腹痛绕脐，手足厥冷，自汗出，脉弦而紧，用大乌头煎主之︰大乌头五枚（去脐）。水三升，煮取一升，去滓，纳蜜二升，煎令水气尽。强人服七合，弱人服五合。不瘥，明日更服。（张仲景《金匮玉函方》）\n寒疝身痛腹痛，手足逆冷不仁，或身痛不能眠，用乌头桂枝汤主之︰乌头一味，以蜜二斤，煎减半，入桂枝汤五合解之，得一升。初服二合，不知再服，又不知，加至五合。其知者如醉状，得吐为中病也。（《金匮玉函》）\n寒疝引胁，肋心腹皆痛，诸药不效者︰大乌头五枚（去角，四破）。以白蜜一斤，煎令透，取焙为末，别以熟蜜和丸梧子大。每服二十丸，冷盐汤下，永除。（崔氏方）\n寒疝滑泄，腹痛肠鸣，自汗厥逆︰熟附子（去皮脐）、延胡索（炒）各一两，生木香半两。每服四钱，水二盏，姜七片，煎七分，温服。（《济生方》）\n小肠诸疝︰《苏沈良方》仓卒散︰治寒疝腹痛，小肠气、膀胱气、脾肾诸痛，挛急难忍，汗出厥逆︰大附子（炒去皮脐）一枚，山栀子（炒焦）四两。每用三钱，水一盏，酒半盏，煎七分，入盐一捻，温服。《宣明方》︰治阴疝小腹肿痛，加蒺藜子等分。虚者︰加桂枝等分，姜糊为丸，酒服五十丸。虚寒腰痛︰鹿茸（去毛，酥炙微黄）、附子（炮去皮脐）各二两，盐花三分，为末，枣肉和丸梧子大。每服三十丸，空心温酒下。《夷坚志》云︰时康祖大夫，病心胸一漏，数窍流汁，已二十年。又苦腰痛，行则伛偻，形神憔悴，医不能治。通判韩子温为检《圣惠方》，得此方令服。旬余，腰痛减。久服遂瘥，心漏亦瘥。精力倍常，步履轻捷。此方本治腰，而效乃如此。元脏伤冷︰《斗门方》︰用附子（炮去皮脐），为末，以水二盏，入药二钱，盐、葱、姜、枣同煎取一盏，空心服。去积冷，暖下元，肥肠益气，酒食无碍。《梅师方》二虎丸︰补元脏，进饮食，壮筋骨。用乌头、附子各四两（酽醋浸三宿，切作片子）炭火烧赤，以醋三升，同药倾入坑内，用盆合之。一宿取出，去砂土，入青盐四两，同炒赤黄色，为末，醋打面糊丸如梧子大。空心冷酒下十五丸，妇人亦宜。胃冷有痰，脾弱呕吐︰生附子、半夏各二钱，姜十片，水二盏，煎七分，空心温服。一方︰并炮熟，加木香五分。（《奇效良方》）\n久冷反胃︰《经验方》︰用大附子一个，生姜一斤，锉细同煮，研如面糊。每米饮化服一钱。《卫生家宝方》︰用姜汁打糊，和附子末为丸，大黄为衣。每温水服十丸。《斗门方》︰用最大附子一个，坐于砖上，四面著火渐逼，以生姜自然汁淬之。依前再逼再淬，约姜汁尽半碗乃止，研末。每服一钱，粟米饮下，不过三服瘥。或以猪腰子切片，炙熟蘸食。《方便集》︰用大附子一个，切下头子，剜一窍，安丁香四十九个在内，仍合定，线扎，入砂铫内，以姜汁浸过，文火熬干，为末。每挑少许，置掌心舐吃，日十数次。忌毒物、生冷。脾寒疟疾︰《济生方》云︰五脏气虚，阴阳相胜，发为 疟，寒多热少，或但寒不热，宜七枣汤主之︰用附子一枚，炮七次，盐汤浸七次，去皮脐，分作二服。水一碗，生姜七片，枣七枚，煎七分，露一宿。发日空心温服，未久再进一服。王璆《百一选方》云︰寒痰，宜附子；风痰，宜乌头法。用乌头性热，泡多则热散也。又果附汤︰用熟附子（去皮）、草果仁各二钱半，水一盏，姜七片，枣一枚，煎七分，发日早温服。《肘后方》︰临发时，以醋和附子末涂于背上。寒热疟疾︰附子一枚（重五钱者，面煨），人参、丹砂各一钱，为末，炼蜜丸梧子大。每服二十丸，未发前连进三服。中病则吐，或身体麻木。未中病，来日再服。（庞安常《伤寒论》）\n瘴疟寒热，冷瘴，寒热往来，头痛身疼，呕痰，或汗多引饮，或自利烦躁，宜姜附汤主之︰大附子一枚，四破。每以一片，水一盏，生姜十片，煎七分，温服。李待制云︰此方极妙。章杰云︰岭南以哑瘴为危急，不过一二日而死。医谓极热感寒也，用生附子一味治之多愈。得非以热攻热而发散小便虚闭，两尺脉沉，微用利小水药不效者，乃虚寒也︰附子一个（炮去皮脐，盐水浸良久），泽泻一两。每服四钱，水一盏半，灯心七茎，煎服即愈。（《普济方》）\n肿疾喘满，大人小儿男女肿因积得，既取积而肿再作，小便不利。若再用利药性寒，而小便愈不通矣。医者到此多束手。盖中焦下焦气不升降，为寒痞隔，故水凝而不通。惟服沉附汤，则小便自通，喘满自愈︰用生同煎，食前冷冻饮料。附子虽三、五十枚亦无害。小儿每服三钱，水煎服。（《朱氏集验方》）\n脾虚湿肿︰大附子五枚（去皮四破），以赤小豆半升，藏附子于中，慢火煮熟，去豆焙研末，以薏苡仁粉打糊丸梧子大。每服十丸，萝卜汤下。（《朱氏集验方》）\n阴水肿满︰乌头一升，桑白皮五升，水五升，煮一升，去滓铜器盛之，重汤煎至可丸，丸小豆大。每服三、五丸，取小便利为佳。忌油腻酒面鱼肉。又方︰大附子，童便浸三日夜，逐日换尿，以布擦去皮，捣如泥，酒糊和丸小豆大。每服三十丸，煎流气饮送下。（《普济方》）\n大肠冷秘︰附子（一枚，炮去皮，取中心如枣大，为末）二钱，蜜水空心服之。（《圣济总录》）\n老人虚泄不禁︰熟附子一两，赤石脂一两，为末，醋糊丸梧子大。米饮下五十丸。（《杨氏家藏方》）\n冷气洞泄︰生川乌头一两，木香半两，为末，醋糊丸梧子大。每陈皮汤下二十丸。（《本事方》）\n脏寒脾泄，及老人中气不足，久泄不止︰。肉豆蔻二两（煨熟），大附子（去皮脐）一两五钱，为末，粥丸梧子大。每服八十丸，莲肉煎汤下。《十便良方》︰治脾胃虚冷，大肠滑泄，米谷不化，乏力。用大附子十两（连皮，同大枣二升，于石器内，以水煮一日，常令水过两指。取出，每个切作三片，再同煮半日，削去皮，切焙）。为末，别以枣肉和丸梧子大。每空心米饮服三、四十丸。小儿吐泄注下，小便少︰白龙丸︰用熟附子五钱，白石脂（煅）、龙骨（煅）各二钱半，为末，醋面糊丸黍米大。每米饮量儿大小服。（《全幼心鉴》）\n霍乱吐泄不止︰附子重七钱者，炮去皮脐，为末。每服四钱，水二盏，盐半钱，煎一盏，温服立止。（孙兆《秘宝方》）\n水泄久痢︰川乌头二枚，一生用，一以黑豆半合约煮熟，研丸绿豆大。每服五丸，黄连汤下。（《普济方》）\n久痢赤白︰独圣丸︰用川乌头一个，灰火烧烟欲尽，取出地上，盏盖良久，研末，酒化蜡丸如大麻子大。每服三丸，赤痢，黄连、甘草、黑豆煎汤，放冷吞下；白痢，甘草、黑豆煎汤，冷吞。如泻及肚痛，以水吞下。并空心服之。忌热物。（《经验后方》）\n久痢休息︰熟附子半两（研末），鸡子白二枚，捣和丸梧子大。倾入沸汤，煮数沸，漉出，作两服，米饮下。（《圣济总录》）\n下痢咳逆，脉沉阴寒者，退阴散主之︰陈自明云︰一人病此不止，服此两服而愈。方见前阴下血虚寒，日久肠冷者︰熟附子（去皮）、枯白矾一两，为末。每服三钱，米饮下。又方︰熟附子一枚（去皮），生姜三钱半，水煎服。或加黑豆一百粒。（并《圣惠阳虚吐血︰生地黄一斤，捣汁，入酒少许，以熟附子一两半，去皮脐，切片，入汁内，石器煮成膏。取附片焙干，入山药三两，研末，以膏和捣，丸梧子大。每空心米饮下三十丸。昔葛察判妻苦此疾，百药皆试，得此而愈，屡发屡效。（余居士《选奇方溲数白浊︰熟附子为末。每服二钱，姜三片，水一盏，煎六分，温服。（《普济方》）\n虚火背热，虚火上行，背内热如火炙者︰附子末，津调，涂涌泉穴。（《摘玄方》）\n经水不调，血脏冷痛，此方平易捷径︰熟附子（去皮）、当归等分。每服三钱，水煎服。（《普济方》）\n断产下胎︰生附子为末，淳苦酒和涂右足心，胎下去之。（《短剧方》）\n折腕损伤︰卓氏膏︰用大附子四枚，生切，以猪脂一斤，三年苦醋同渍三宿，取脂煎三上三下，日摩敷之。（《深师方》）\n痈疽肿毒︰川乌头（炒）、黄柏（炒）各一两，为末，唾调涂之，留头，干则以米泔润之。（同上）痈疽久漏，疮口冷，脓水不绝，内无恶肉︰大附子以水浸透，切作大片，浓三分，安疮口上，以艾灸之。隔数日一灸，灸至五七次。仍服内托药，自然肌肉长满。研末作饼子，亦可。（薛己《外科心法》）\n痈疽 肉，如眼不敛，诸药不治，此法极妙︰附子削如棋子大，以唾粘贴上，用艾火灸之。附子焦，复唾湿再灸，令热气彻内，即瘥。（《千金方》）\n痈疽肉突︰乌头五枚，浓醋三升，渍三日洗之，日夜三、四度。（《古今录验》）\n疔疮肿痛︰醋和附子末涂之。干再上。（《千金翼》）\n久生疥癣︰川乌头，生切，以水煎洗，甚验。（《圣惠》）\n手足冻裂︰附子去皮为末，以水、面调涂之，良。（《谈野翁试验方》）\n足钉怪疾，两足心凸肿，上生黑豆疮，硬如钉，胫骨生碎孔，髓流出，身发寒颤，惟思饮酒，此是肝肾冷热相吞。用炮川乌头末敷之，内服韭子汤，效。（夏氏《奇疾方》）\n乌头附子尖\n\n旧一，新七。\n风厥癫痫，凡中风痰厥，癫痫惊风，痰涎上壅，牙关紧急，上视搐搦，并宜碧霞丹主之︰乌头尖、附子尖、蝎梢各七十个，石绿（研九度，飞过）十两，为末，面糊丸芡子大。每用一丸，薄荷汁半盏化下，更服温酒半合，须臾吐出痰涎为妙。小儿惊痫，加白僵蚕等分。（《和剂局方》）\n脐风撮口︰生川乌尖三个，金赤蜈蚣半条（酒浸炙干），麝香少许，为末。以少许吹鼻得嚏，乃以薄荷汤灌一字。（《永类方》）\n木舌肿胀︰川乌尖、巴豆研细，醋调涂刷。（《集简方》）\n牙痛难忍︰附子尖、天雄尖、全蝎各七个，生研为末，点之。（《永类方》）\n奔豚疝气作痛，或阴囊肿痛︰去铃丸︰用生川乌尖七个，巴豆七枚（去皮油）。为末，糕糊丸梧子大，朱砂、麝香为衣。每服二丸，空心冷酒或冷盐汤下。三、两日一服，不可多。（寮方》）\n割甲成疮，连年不愈︰川乌头尖、黄柏等分，为末。洗了贴之，以愈为度。（《古今录验》）\n老幼口疮︰乌头尖一个，天南星一个，研末，姜汁和涂足心，男左女右，不过二、三次即愈。"},
  "乌烂死蚕":{o:[],src:["本草纲目"],d:"新一。\n消渴烦乱︰蚕蛹二两，以无灰服。（《圣惠方》）\n茧卤汁\n藏器曰︰此是茧中蛹汁，非碱卤也。于盐茧瓮下收之。"},
  "乌臼木":{o:["乌臼木"],src:["本草备要"],d:"泻热毒\n苦凉、性沉而降。利水通肠，功胜大戟。疗疔肿，解砒毒（极能泻下。凡患肿毒，中砒毒者，不拘根、皮、枝、叶，捣汁多饮，得大利即愈。虚人忌用）。子，可作烛。"},
  "乌蛇":{o:[],src:["本草纲目"],d:"旧二，新五。\n大风︰《朝野佥载》云︰商州有人患大风。家人恶之，山中为起茅屋。有乌蛇堕酒罂病患不知，饮酒渐瘥。罂底见有蛇骨，始知其由。《治例》︰治大风。用乌蛇三条蒸熟，取焙研末，蒸饼丸米粒大，以喂乌鸡。待尽杀鸡烹熟，取肉焙研末，酒服一钱。或蒸饼丸服。\n不过三、五鸡即愈。《秘韫》︰用大乌蛇一条，打死盛之。待烂，以水二碗浸七日，去皮骨，入糙米一升，浸一日晒干。用白鸡一只，饿一日，以米饲之。待毛羽脱去，杀鸡煮熟食，以酒下壳（麸炒）、羌活、牛膝、天麻各三两，熟地黄四两，白蒺藜（炒）、五加皮、防风、桂心各二两，锉片。以绢袋盛，于无灰酒二斗中浸之，密封七日。每日三度，温服一小盏。忌鸡、鹅、鱼肉、发物。（《圣惠》）\n面疮 ︰乌蛇肉二两，烧灰，腊猪脂调敷。（《圣惠》）\n婴儿撮口不能乳者︰乌蛇（酒浸，去皮骨，炙）半两，麝香一分，为末。每用半分，荆芥煎汤调灌之。（《圣惠》）\n破伤中风︰项强身直，定命散主之。用白花蛇、乌蛇（并取项后二寸，酒洗润取肉）、蜈蚣一条（全者，并酒炙）。上为末。每服三钱，温酒调服。（\n膏\n\n新二。\n大风龙胆膏︰治大风疾神效。用冬瓜一个，截去五寸长，去瓤，掘地坑深三尺，令净，安瓜于内。以乌蛇胆一个，消梨一个，置于瓜上，以土隔盖之。至三七日，看一度，瓜未甚坏。候七七日，三物俱化为水，在瓜皮内小可风疾，每服一匙头。（王氏《博济方敷舌上，有涎吐去。（《圣济总录》）\n皮\n\n新一。\n小儿紧唇，脾热唇疮︰并用乌蛇皮烧灰，酥和敷之。（《圣惠》）\n卵"},
  "乌贼鱼":{o:[],src:["本草纲目"],d:"旧三。新二十一。\n女子血枯︰见上。\n赤白目翳︰《圣惠》︰治伤寒热毒攻眼，生赤白翳。用乌 鱼骨一两，去皮为末，入龙脑少许点之，日三。治诸目翳︰用乌赤翳攀睛︰照水丹︰治眼翳（惟浓者尤效）及赤翳攀睛贯瞳人。用海螵蛸一钱，辰砂半钱，乳细水飞澄取，以黄蜡少许，化和成剂收之。临卧时，火上旋丸黍米大，揉入 中。睡至天明，温水洗下。未退，更用一次，即效。（《海上方》）\n雀目夜眼︰乌贼骨半斤为末，化黄蜡三两和，捏作钱大饼子。每服一饼，以猪肝二两，竹刀批开，掺药扎定，米泔水半碗，煮熟食之，以汁送下。（《杨氏家藏》）\n血风赤眼︰女人多之。用乌贼鱼骨二钱，铜青一钱，为末。每用一钱，热汤泡洗。（《杨氏疳眼流泪︰乌贼鱼骨、牡蛎等分。为末，糊丸皂子大。每用一丸，同猪子肝一具，米泔煮熟食。（《经验》）\n底耳出脓︰海螵蛸半钱，麝香一字，为末。以绵杖缴净，吹入耳中。（《澹寮方》）\n鼻疮疳 ︰乌贼鱼骨、白芨各一钱，轻粉二字，为末，搽之。（钱乙小儿脐疮出血及脓︰海螵蛸、胭脂为末，油调搽之。（《圣惠方》）\n头上生疮︰海螵蛸、白胶香各二钱，轻粉五分，为末。先以油润净乃搽末，二、三次即愈。（《卫生易简方》）\n疡白驳︰先以布拭赤，用乌贼骨磨三年酢，涂之。（《外台秘要》）\n疔疮恶肿︰先刺出血，以海螵蛸末掺之，其疔即出。（《普济方》）\n蝎螫痛楚︰乌贼骨一钱，白矾二分，为末 鼻。在左壁者生宝鉴》）\n灸疮不瘥︰乌贼骨、白矾等分为末。日日涂之。（《千金》）\n小儿痰 多年︰海螵蛸末，米饮服一钱。（叶氏《摘玄方》）\n小便血淋︰海螵蛸末一钱，生地黄汁调服。又方︰海螵蛸、生地黄、赤每服一钱，柏叶、车前汤下。（《经验方》）\n大肠下血︰不拘大人小儿，脏毒肠风及内痔，下血日久，多食易饥。先用海螵蛸炙黄，去皮研末。每服一钱，木贼汤下。三日后，服猪脏黄连丸。（《直指方》）\n卒然吐血︰乌贼骨末，米饮服二钱。（《圣惠》）\n骨鲠在喉︰象牙屑、乌贼鱼骨、陈橘红（焙）等分为末，寒食面和饧，丸芡子大。每用一丸，含化咽汁。（《圣济总录》）\n舌肿出血如泉︰乌贼骨、蒲黄各等分，炒为细末。每用涂之。（《简便单方》）\n跌破出血︰乌贼鱼骨末，敷之。（《直指方》）\n阴囊湿痒︰乌贼骨、蒲黄，扑之。（《医宗三法》）\n血"},
  "乌韭":{o:[],src:["本草纲目"],d:"新三。\n腰脚风冷︰石花，浸酒饮之。（《圣惠方》）。\n妇人血崩︰石花、细茶（焙为末）、旧漆碟（烧存性）各一匙。以碗盛酒，放锅内煮一滚。\n乃汤火伤灼︰石苔焙研，敷之。（《海上方》）"},
  "乌骨鸡":{o:["乌骨鸡"],src:["本草备要"],d:"补虚劳\n甘平。鸡属木，而骨黑者属水，得水木之精气，故能益肝肾，退热补虚。治虚劳消渴，下痢噤口（煮汁益胃），带下崩中，肝、肾血分之病。鬼击卒死者，用其血涂心下效（《睽车志》∶夏侯弘捉得一小鬼，问∶所持何物？曰∶杀人以此矛戟，中心腹者，无不辄死。弘曰∶治此有方否？鬼曰∶以乌鸡敷之即瘥）。骨肉俱黑者良，舌黑者骨肉俱黑。男用雌，女用雄（女科有乌鸡丸，治百病）。"},
  "云实":{o:[],src:["本草纲目"],d:"新一。\n下不止︰云实、女萎各一两，桂半两，川乌头二两，为末，蜜丸梧子大。每服五丸，水下，日三服。（《肘后方》）\n花"},
  "云母":{o:["云母"],src:["本草备要", "本草纲目"],d:"补中\n甘平属金，色白入肺。下气补中，坚肌续绝。治劳伤疟痢，疮肿痈疽（同黄丹熬膏贴之。《千金翼》∶用敷金疮。青城山人康道丰，有云母粉方，能治百病）。有五色，以色白光莹者为上。古人亦有炼服者（云母入火，经时不焦，入土不腐，故云服之长生）。使泽泻。恶羊肉。"},
  "五色石脂":{o:[],src:["本草纲目"],d:"旧四，新二。\n小儿水痢形羸，不胜汤药。白石脂半两研粉，和白粥空肚食之。（《子母秘录》）\n小儿滑泄︰白龙丸︰白石脂、白龙骨等分。为末，水丸黍米大。每量大小，木瓜、紫苏汤下。（《全幼心鉴》）\n久泄久痢︰白石脂、干姜等分。研，百沸汤和面为稀糊搜之，并手丸梧子大。每米饮下三十丸。（《斗门方》）\n儿脐汁出赤肿︰白石脂末熬温，扑之，日三度，勿揭动。（韦宙《独行方》）\n儿脐血出，多啼︰方同上。（寇氏《衍义》）\n粉滓面 ︰白石脂六两，白蔹十二两。为末。鸡子白和，夜涂旦洗。（《圣济录》）\n\n旧五，新七。\n小儿疳泻︰赤石脂末，米饮调服半钱，立瘥。加京芎等分，更妙。（《斗门方》）\n大肠寒滑，小便精出︰赤石脂、干姜各一两，胡椒半两。为末，醋糊丸梧子大。每空心米饮下五、七十丸。有人病此，热药服至一斗二升，不效；或教服此，终四剂而愈。（寇氏\n《衍义》）\n赤白下痢︰赤石脂末，饮服一钱。（《普济方》）\n冷痢腹痛，下白冻如鱼脑。桃花丸︰赤石脂（煅）、干姜（炮）等分。为末，蒸饼和丸。量大小服，日三服。（《和剂局方》）\n老人气痢虚冷︰赤石脂五两（水飞），白面六两。水煮熟，入葱酱作 ，空心食三、四次，即愈。（《养老方》）\n伤寒下痢，便脓血不止，桃花汤主之。赤石脂一斤（一半全用，一半末用），干姜一两，粳米半升。水七升，煮米熟去滓。每服七合，纳末方寸匕，日三服，愈乃止。（仲景方）\n痢后脱肛︰赤石脂、伏龙肝为末，敷之。一加白矾。（钱氏小儿方）\n反胃吐食︰绝好赤石脂为末，蜜丸梧子大。每空腹姜汤下一、二十丸。先以巴豆仁一枚，勿令破，以津吞之。后乃服药。（《圣惠方》）\n痰饮吐水无时节者，其原因冷冻饮料过度，遂令脾胃气弱，不能消化饮食。饮食入胃，皆变成冷水，反吐不停，赤石脂散主之。赤石脂一斤，捣筛，服方寸匕，酒饮自任，稍加至三匕。服尽一斤，则终身不吐痰水，又不下痢，补五脏，令人肥健。有人痰饮，服诸药不效，用此遂愈。（《千金翼方》）\n心痛彻背︰赤石脂、干姜、蜀椒各四分，附子（炮）二分，乌头（炮）一分。为末，蜜丸梧子大。先食服一丸。不知，稍增之。（张仲景《金匮方》）\n经水过多︰赤石脂、破故纸一两。为末。每服二钱，米饮下。（《普济方》）\n小便不禁︰赤石脂（煅）、牡蛎（煅）各三两，盐一两。为末，糊丸梧子大。每盐汤下十五丸。（《普济方》）"},
  "五谷虫":{o:["五谷虫"],src:["本草备要"],d:"（即粪蛆）\n泻热，疗疳寒。治热病谵（音占，妄语）妄，毒痢作吐，小儿疳积疳疮。漂净晒干，或炒，或 ，为末用。"},
  "井泉水":{o:["井泉水"],src:["本草备要"],d:"补\n将旦首汲，曰井华水；出瓮未放，曰无根水，无时初出，曰新汲水。解热闷烦渴（凡热病不可解者，新汲水浸青色衣服互熨之炒。心闷汗出，新汲水蜜和饮炒），煎补阴之药宜之（井以有地脉山泉者为上；从江湖渗来者次之；其城市近沟渠污秽者，咸而有碱。煮粥煎茶，味各有异，以之入药，其可无择乎？）。"},
  "井泉石":{o:[],src:["本草纲目"],d:"新四。\n膀胱热闭，小便不快︰井泉石、海金沙、车前子、滑石各一两。为末。每服二钱，蜜汤下。（《圣济录》）\n风毒赤目︰井泉石半两，井中苔（焙）、谷精草一两，豉（焙）一合。为末。每服二钱，空心井华水服。（《圣济录》）\n产后搐搦，俗名鸡爪风。舒筋散︰用井泉石四两（另研），天麻（酒浸）、木香各一两，人参、川芎、官桂、丁香各半两。为末。每服三钱，大豆淋酒调下，出汗即愈。（《宣明方》）\n痤痱瘙痒︰井泉石（生）三两，寒水石（煅）四两，脑子半钱。为末扑之。（《圣济录》）"},
  "人中白":{o:["人中白"],src:["本草备要"],d:"泻火\n咸平。降火散瘀，治肺瘀鼻衄（刮人中白，新瓦火上逼干，调服即止），劳热消渴，痘疮倒陷，牙疳口疮。即溺 ， 研用（以蒙馆童子便桶、山中老僧溺器刮下者，尤佳）。"},
  "人中黄":{o:["人中黄"],src:["本草备要"],d:"泻热\n甘寒入胃。清痰火，消食积，大解五脏实热。治天行热狂，痘疮血热，黑陷不起。纳甘草末于竹筒中，紧塞其孔，冬月浸粪缸中。至春取出洗，悬风处阴干，取甘草用（亦有用皂荚末者，竹须削去青皮）。一云即粪缸多年黄 ， 存性用。"},
  "人乳":{o:["人乳"],src:["本草备要"],d:"补虚，润燥\n甘咸。润五脏，补血液，止消渴，泽皮肤，治风火证（昂按∶老人便秘，人乳最良）。本血所化，目得血而能视，用点赤涩多泪（热者，黄连浸点）。然性寒滑，脏寒胃弱人不宜多服（时珍曰∶人乳无定性。其人和平，饮食冲淡，其乳必平。其人躁暴，饮酒食辛，或有火病，其乳必热。又有孕之乳，为忌乳，最有毒，小儿食之吐泻，成疳魃之病，内亦损胎。昂按∶乳乃阴血所化，生于脾胃，摄于冲任。未受孕则下为月水，既受孕则留而养胎，已产则变赤为白，上为乳汁，以食小儿，乃造化之玄微也。服之益气血，补脑髓，乃谓以人养人也。然能滑肠、湿脾、腻膈，天设之以为小儿，非壮者所当常服。唯制为粉，则有益无损，又须旋用，久则油膻。须用一妇人之乳为佳，乳杂则其气杂。乳粉、参末等分蜜丸，名参乳丸，大补气血）。取年少无病妇人乳、白而稠者，如儿食良。黄赤清色、气腥秽者，并不堪用。或曝晒、用茯苓粉收，或水顿、取粉尤良。取粉法，小锅烧水滚，用银瓢如碗大（锡瓢亦可）。倾乳少许入瓢，浮滚水上顿，再浮冷水上立干，刮取粉用，再顿再刮，如摊粉皮法。"},
  "人牙":{o:["人牙"],src:["本草备要"],d:"宣，发痘\n咸温有毒。治痘疮倒 （《痘疹论》∶出不快而黑陷者， 猪血调下一钱；服凉药而血涩倒陷者，麝香酒调服。时珍曰∶欲其窜入肾经，发出毒瓦斯，盖劫剂也。若伏毒在心，不省人事，气虚色白、痒塌无脓，及热痱紫泡之证，只宜补虚解毒。苟误服此，则郁闷声哑，反成不救）。 退火毒，研用。"},
  "人虱":{o:[],src:["本草纲目"],d:"新一。\n脚指鸡眼︰先挑破。取黑、白虱各一枚置于上缚之，数用自愈也。（《便民图纂》）。"},
  "伏龙肝":{o:["伏龙肝"],src:["本草备要"],d:"重，调中，止血，燥湿，消肿\n辛温。调中止血、去湿消肿。治咳逆反胃，吐衄崩带，尿血遗精，肠风痈肿（醋调涂），脐疮（研敷）丹毒（腊月猪脂或鸡子白调敷），催生下胎（《博救方》子死腹中，水调三钱服，其土当儿头上戴出）。斧心多年黄土，一云灶额内火气，积久结成如石，外赤中黄。研细，水飞用。"},
  "假苏":{o:[],src:["本草纲目"],d:"旧四，新二十七。头项风强︰八月后，取荆芥穗作枕，及铺床下，立春日去之。（《千金方》）\n风热头痛︰荆芥穗、石膏等分，为末。每服二钱，茶调下。（《永类钤方》）\n风热牙痛︰荆芥根、乌 根、葱根等分煎汤频含漱之。小儿惊痫一百二十种。用荆芥穗二两，白矾（半生半枯）一两，为末，糊丸黍米大，朱砂为衣。每姜汤下二十丸，日二服。（《医学集成》）\n一切偏风，口眼 斜。用青荆芥一斤，青薄荷一斤，同入砂盆内研烂，生绢绞汁，于瓷器中煎成膏，漉去滓三分之一，将二分晒干，为末，以膏和丸梧子大。每服三十丸，白汤下，早暮各一服。忌动风物。（《经验后方》）\n中风口噤︰荆芥穗为末，酒服二钱，立愈，名荆芥散。贾似道云︰此方出《曾公谈录》，前后用之甚验。其子名顺者，病此已革，服之立定，真再生丹也。产后中风︰华佗愈风散︰治妇人产后中风口噤，手足螈 如角弓，或产后血运，不省人事，四肢强直，或筑心眼倒，吐泻欲死。用荆芥穗子，微焙为末。每服三钱，豆淋酒调服，或童子小便服之。口噤则挑齿灌之，龈噤则灌入鼻中，其效如神。大抵产后太暖，则汗出而腠理疏，则易于中风也。\n时珍曰︰此方诸书盛称其妙。姚僧坦《集验方》以酒服，名如圣散，云药下可立待应效。陈氏方名举卿古拜散。萧存敬方用古老钱煎汤服，名一捻金。王贶《指迷方》加当归等分，水煎服。许叔微《本事方》云︰此药委有奇效神圣之功。一妇人产后睡久，及醒则昏昏如醉，不省人事。医用此药及交加散，云︰服后当睡，睡中必以左手搔头。用之果然。昝殷《产宝方》云︰此病多因怒气伤肝，或忧气内郁，或坐草受风而成，急宜服此药也。戴原礼《证治要诀》名独行散。贾似道《悦生随抄》呼为再生丹。产后迷闷，因怒气发热迷闷者。独行散︰用荆芥穗，以新瓦半炒半生为末。童子小便服一二钱。若角弓反张，以豆淋酒下。或锉散，童尿煎服极妙。盖荆芥乃产后要药，而角弓反张，乃妇人急候，得此证者，十存一二而已。（戴原礼《要诀》）\n产后血运︰筑心眼倒，风缩欲死者。取干荆芥穗捣筛末。每用二钱匕，童子小便一酒盏，调匀，热服。立效。口噤者挑齿，口闭者灌鼻中，皆效。近世名医用之，无不如神也。（《图经本草》）\n产后血眩风虚，精神昏冒。荆芥穗一两三钱，桃仁五钱（去皮尖）。炒为末。水服三钱。若喘加杏仁（去皮尖，炒）、甘草（炒）产后下痢︰大荆芥四、五穗（于盏内烧存性，不得犯油火），入麝香少许。以沸汤些须调下。此药虽微，能愈大病，不可忽之。（《深师方》）\n产后鼻衄︰荆芥（焙）研末。童子小便服二钱，《海上方》也。（《妇人良方》）\n九窍出血︰荆芥煎酒，通口服之。（《直指方》）\n口鼻出血如涌泉，因酒色太过者。荆芥烧研，陈皮汤服二钱，不过二服也。吐血不止︰《经验方》︰用荆芥（连根，洗），捣汁半盏服。干穗为末亦可。《圣惠方》︰用荆芥穗为末。生地黄汁调服二钱。小便尿血︰荆芥、缩砂等分，为末。糯米饮下三钱，日三服。（《集简》）\n崩中不止︰荆芥穗（于麻油灯上烧焦，为末）。每服二钱，童子小便服。此夏太君娘娘方也。（《妇人良方》）\n痔漏肿痛︰荆芥煮汤，日日洗之。（《简易方》）\n大便下血︰《经验方》︰用荆芥（炒）为末，每米饮服二钱，妇人用酒下，亦可拌面作馄饨食之。《简便方》︰用荆芥二两，槐花一两，同炒紫为末。每服三钱，清茶送下。小儿脱肛︰荆芥、皂角等分，煎汤洗之，以铁浆涂上。亦治子宫脱出。（《经验方》）\n阴 肿痛︰荆芥穗（瓦焙）为散。酒服二钱，即消。（《寿域神方》）\n小儿脐肿︰荆芥煎汤洗净，以煨葱刮薄出火毒，贴之即消。（《海上方》）\n瘰疬溃烂︰ 疮牵至胸前两腋，块如茄子大，或牵至两肩上，四、五年不能疗者，皆治之，其效如神。武进县朱守仁传，云其项不能回头，用此数日减可。如疮烂破者，用荆芥根下一段剪碎，煎沸汤温洗，良久，看烂破处紫黑，以针一刺去血，再洗三四次愈。用樟脑、雄黄等分，为末，麻油调，扫上出水。次日再洗再扫，以愈为度。（《活法机要》）\n疔肿诸毒︰荆芥一握（切）。以水五升，煮取二升，分二服冷冻饮料。（《药性论》）\n一切疮疥︰荆芥末，以地黄自然汁熬膏，和丸梧子大。每服三、五十丸，茶酒任下。（《普济方》）\n脚桠湿烂︰荆芥叶捣敷之。（《简便方》）\n缠脚生疮︰荆芥烧灰，葱汁调敷，先以甘草汤洗之。（《摘玄方》）\n小儿风寒，烦热有痰，不省人事。荆芥穗半两（焙），麝香、片脑各一字，为末。每茶服半钱。大人亦治。（《普济方》）\n头目诸疾︰一切眼疾，血劳，风气头痛，头旋目眩。荆芥穗为末，每酒服三钱。（《龙树论》）\n癃闭不通，小腹急痛，无问久新。荆芥、大黄（为末）等分，每温水服三钱。小便不通，大黄减半；大便不通，荆芥减半。名倒换散。（《普济方》）"},
  "兔矢":{o:["兔矢"],src:["本草备要"],d:"（一名明月砂）\n宣，明目，杀虫杀虫明目，治痨瘵五疳，痘后生翳。兔肝泻肝热，故能明目。兔肉治消渴（《海上方》∶澄汁冷冻饮料），小儿食之稀痘疮（陶弘景曰∶孕妇食之，令儿缺唇。保寿堂兔血丸，令小儿永不出痘，虽出亦稀。腊八日取生兔刺血，和荞麦面，加雄黄四五分，和丸，如绿豆大。初生小儿，乳汁送下二三丸，遍身发出红点，此其验也）。"},
  "兰草":{o:[],src:["本草纲目"],d:"新一。\n食牛马毒杀人者。省头草（连根叶），煎水服，即消。（《唐瑶经验方》）"},
  "冬瓜":{o:["冬瓜"],src:["本草备要", "本草纲目"],d:"（又名白瓜）\n泻热，补脾寒泻热，甘益脾。利二便，消水肿（冬瓜任吃效），止消渴（苗、叶皆治消渴），散热毒痈肿（切片敷之。丹溪曰∶冬瓜性急而走，久病阴虚者忌之。昂按∶冬瓜日食常物，于诸瓜中尤觉宜人，且味甘而不辛，何以见其性急而走乎？）。子，补肝明目（凡药中所用瓜子，皆冬瓜子也）。"},
  "冬葵子":{o:["冬葵子"],src:["本草备要"],d:"滑肠，利窍\n甘寒淡滑。润燥利窍，通营卫，滋气脉，行津液，利二便，消水肿（用榆皮等分煎服），通关格，下乳滑胎。秋葵复种，经冬至春作子者，名冬葵子。根、叶同功。春葵子亦滑，不堪入药。蜀葵花，赤者治赤带，白者治白带，赤者治血燥，白者治气燥。亦治血淋、关格，皆取其寒润滑利之功也。"},
  "冰":{o:["冰"],src:["本草备要"],d:"泻热\n甘寒。太阴之精，水极似土。伤寒阳毒热甚昏迷者，以一块置膻中（两乳中间）良。解烧酒毒（陈藏器曰∶盛夏食冰，与气候相反，冷热相激，却致诸疾。宋徽宗食冰太过，病脾疾，国医不效。杨介进大理中丸，上曰∶服之屡矣。介曰∶病因食冰，臣请以冰煎此药，治受病之源也，果愈）。"},
  "决明":{o:[],src:["本草纲目"],d:"旧一，新七。\n积年失明︰决明子二升为末，每食后粥饮服方寸匕。（《外台秘要》）\n青盲雀目︰决明一升，地肤子五两，为末，米饮丸梧子大，每米饮下二三十丸。（《普济方》）\n补肝明目︰决明子一升，蔓荆子二升，以酒五升煮，曝干为末。每饮服二钱，温水下，日二服。（《圣惠方》）\n目赤肿痛︰决明子炒研，茶调敷两太阳穴，干则易之，一夜即愈。（《医方摘玄》）\n头风热痛︰方同上。\n鼻衄不止︰方见主治。\n癣疮延蔓︰决明子一两为末，入水银、轻粉少许，研不见星，擦破上药，立瘥。此东坡家藏方也。（《奇效良方》）\n两，水三升，煮一升，分二服。大抵血滞则生疮，肝主藏血，决明和肝气，不损元气也。（许学士《本事方》）"},
  "凝水石":{o:[],src:["本草纲目"],d:"旧二，新二。\n男女转脬，不得小便︰寒水石二两，滑石一两，葵子一合。为末。水一斗，煮五升，时服一升，即利。（《永类方》）\n牙龈出血有窍︰寒水石粉三两，朱砂二钱，甘草脑子一字。为末。干掺。（《普济方》）\n汤火伤灼︰寒水石，烧研敷之。（《卫生易简方》）\n小儿丹毒，皮肤热赤︰寒水石半两，白土一分。为末。米醋调涂之。（《经验方》）"},
  "凤仙":{o:[],src:["本草纲目"],d:"新五。\n产难催生︰凤仙子二钱，研末。水服，勿近牙。外以蓖麻子，随年数捣涂足心。（《集简方》）\n噎食不下︰凤仙花子酒浸三宿，晒干为末，酒丸绿豆大。每服八粒，温酒下。不可多用，即急性子也。（《摘玄方》）\n咽中骨哽，欲死者︰白凤仙子研水一大呷，以竹筒灌入咽，其物即软。不可近牙。或为末吹之。（《普济方》）\n牙齿欲取︰金凤花子研末，入砒少许，点疼牙根，取之。（《摘玄方》）\n小儿痞积︰急性子、水荭花子、大黄各一两，俱生研末。每味取五钱，外用皮硝一两拌匀。将白鹁鸽一个，或白鸭亦可，去毛屎，剖腹，勿犯水，以布拭净，将末装入内，用绵扎定，沙锅内入水三碗，重重纸封，以小火煮干，将鸽鸭翻调焙黄色，冷定。早辰食之，日西时疾软，三日大便下血，病去矣。忌冷物百日。（孙天仁《集效方》）\n花\n\n新一。\n风湿卧床不起︰用金凤花、柏子仁、朴硝、木瓜煎汤洗浴，每日二、三次。内服独活寄生汤。（吴 《扶寿精方》）\n根、叶\n\n新三。\n咽喉物哽︰金凤花根嚼烂噙咽，骨自下，鸡骨尤效。即以温水漱口，免损齿也。亦治误吞铜铁。（危氏《得效方》）\n打杖肿痛︰风仙花叶捣如泥，涂肿破处，干则又上，一夜血散，即愈。冬月收取干者研末，水和涂之。（叶廷器《通变要法》）\n马患诸病︰白凤仙花连根叶熬膏。遇马有病，抹其眼四角上，即汗出而愈。（《卫生易简方》）"},
  "刀豆":{o:["刀豆"],src:["本草备要"],d:"宣，下气\n甘平。温中止呃（煅存性服），胜于柿蒂。"},
  "列当":{o:[],src:["本草纲目"],d:"旧一。\n阳事不兴︰栗当（好者）二斤（即列当）。捣筛毕，以好酒一斗浸之经宿，随性日饮之。（昝殷《食医心镜》）"},
  "刘寄奴草":{o:["刘寄奴草"],src:["本草备要", "本草纲目"],d:"泻，破血，止血\n苦温。破血通经，除症下胀，止金疮血。多服令人吐利。一茎直上，叶尖长、糙涩，花白芯黄，如小菊花，有白絮如苦 絮，子细长亦似苦 子。茎、叶、花、子皆可用（刘裕，小字寄奴。微时，曾射一蛇，明日，见童子林中捣药，问之，答曰∶吾王为刘寄奴所伤，合药敷之。裕曰∶王何不杀之？童曰∶寄奴，王者，不可杀也。叱之不见，乃收药回。每遇金疮，敷之立愈）。"},
  "剪草":{o:[],src:["本草纲目"],d:"新二。\n风虫牙痛︰剪草、细辛、 本等分，煎水热漱，少顷自止。（《中藏经》）\n风疮瘙痒︰滑肌散︰治风邪客于肌中，浑身瘙痒，致生疮疥，及脾肺风毒攻冲，生疮干湿，日久不瘥︰用剪草七两（不见火），轻粉一钱。为末。掺之。干者，麻油调掺。（《和剂局方》）"},
  "卤碱":{o:[],src:["本草纲目"],d:"新二。\n风热赤眼，虚肿涩痛︰卤碱一升，青梅二十七个，古钱二十一文。新瓶盛，密封，汤中煮一炊时。三日后取点，日三、五度。（《圣惠方》）\n齿腐龈烂，不拘大人小儿︰用上好碱土，热汤淋取汁，石器熬干刮下，入麝香少许研，掺之。（《宣明方》）"},
  "卫矛":{o:["卫矛"],src:["本草备要"],d:"（一名鬼箭羽）\n泻，破血苦寒（时珍曰∶酸涩）。破陈血，通经落胎，杀虫祛祟。干有三羽，叶似野茶。酥炙用。"},
  "卷柏":{o:["卷柏"],src:["本草备要", "本草纲目"],d:"生用破血，炙用止血\n生用辛平，破血通经，治症瘕淋结。炙用辛温，止血，治肠风脱肛。生石上，拳挛如鸡足，俗呼万年松。凡使盐水煮半日，井水煮半日，焙用。"},
  "原蚕":{o:[],src:["本草纲目"],d:"旧二，新八。\n丈夫阴痿︰未连蚕蛾二升、去头、翅、足，炒为末，蜜丸梧子大。每夜服一丸，可御十室。以菖蒲酒止之。（《千金方遗精白浊︰晚蚕蛾焙干，去翅、足，为末，饭丸绿豆大。每服四十丸，淡盐汤下。此丸常以火烘，否则易糜湿也。（唐氏方）\n血淋疼痛︰晚蚕蛾为末，热酒服二钱。（《圣惠方》）\n小儿口疮及风疳疮︰《宫气方》︰用晚蚕蛾，为末，贴之，妙。《普济方》︰治小儿口疮，及百日内口疮。入麝香少许，掺之。\n止血生肌︰蚕蛾散︰治刀斧伤创，血出如箭。用晚蚕蛾炒为末，敷之即止，甚效。（《胜金方》）\n刀斧金疮︰端午午时，取晚蚕蛾、锻石、茅花，捣成团，草盖令发热过，收贮。每用，刮下末掺之。\n竹刺入肉︰五月五日，取晚蚕蛾生投竹筒中，令自干死，为末。取少许，津和涂之。（《便民图纂》）\n蛇虺咬伤︰生蚕蛾研，敷之。（《必效方》）\n玉枕生疮︰生枕骨上如痈，破后如箸头。用原蚕蛾（炒）、石苇等分，为末。干贴取瘥。（《圣济总录》）\n原蚕砂\n颂曰︰蚕砂、蚕蛾，皆用晚出者良。\n时珍曰︰蚕砂用晒干，淘净再晒，可久收不坏。\n\n旧四，新六。\n半身不遂︰蚕砂二硕，以二袋盛之，蒸熟，更互熨患处。仍以羊肚，粳米煮粥，日食一枚，十日即止。（《千金方》）\n风瘙瘾疹作痒成疮︰用蚕砂一升，水二斗，煮取一斗二升，去滓，洗浴。避风。（《圣惠方》）\n头风白屑作痒︰蚕砂烧灰淋汁，洗之。（《圣惠方》）\n瞇目不出︰蚕砂拣净，空心以新汲水吞下十枚。勿嚼破。（《圣惠》）\n消渴饮水︰晚蚕砂焙干为末。每用冷水下二钱，不过数服。（《斗门方》）\n妇人血崩︰蚕砂为末，酒服三、五钱。（《儒门事亲》）\n月经久闭︰蚕砂四两，砂锅炒半黄色，入无灰酒一壶，煮沸，澄去沙。每温服一盏，即通。\n转女为男︰妇人始觉有孕，用原蚕屎一枚，井华水服之，日三。（《千金》）\n扭闪出骨窍等证。蚕砂四两（炒黄），绿豆粉四两（炒黄），枯矾二两四钱，为末。醋调敷之，绢包缚定。换三男妇心痛不可忍者︰晚蚕砂一两，滚汤泡过，滤净，取清水服，即止。（《瑞竹堂方》）"},
  "原蚕砂":{o:["原蚕砂"],src:["本草备要"],d:"燥湿，去风\n蚕食而不饮，属火性燥，燥能去风胜湿（经曰∶燥胜风，燥属金，风属木也）其沙辛甘而温。炒黄浸酒，治风湿为病，支节不随，皮肤顽痹，腰脚冷痛，冷血瘀血（史国公药酒中用之）。炒热，熨患处亦良（寇宗奭曰∶醇酒三升，拌蚕沙五升，蒸热铺暖室席上，令患冷风气痹人以患处就卧，浓复取汗。不愈，间日再作，须防昏闷）。麻油调敷，治烂弦风眼（目上下胞属脾。脾有风湿，则虫生弦烂。又新瓦炙，为末，少加雄黄，麻油调敷，治蛇串疮。有人食乌梢蛇，浑身变黑，渐生鳞甲，见者惊缩。郑奠一令日服晚蚕沙五钱，尽一二斗，久之乃退）。晚蚕矢也，淘净晒干。"},
  "及己":{o:[],src:["本草纲目"],d:"新一。头疮白秃：獐耳细辛，其味香辣，为末，以槿木煎油调搽。（《活幼全书》）"},
  "发":{o:["发"],src:["本草备要"],d:"（一名血余）\n补，和血发者血之余。味苦微寒，入足少阴、厥阴（肾、肝）。补阴消瘀，通关格，利二便。治诸血疾（能去心窍之血，故亦治惊痫），血痢血淋，舌血（ 末，茅根汤服）鼻血（烧灰吹鼻），转胞不通（烧灰，服），小儿惊热（合鸡子黄，煎为汁服，鸡子能去风痰）。合诸药煎膏，凉血去瘀长肉（发属心，禀火气而上生；眉属肝，禀木气而侧生；须属肾，禀水气而下生。或曰发属肝，禀木气而直生；眉属金，禀金气而横生，金无余气，故短而不长，至老金气钝，则眉长矣。昂按∶肺主皮毛，毛亦短而不长者也，何以独无所属乎？毛既为肺之合，自当属肺、属金。眉当属肝、属木，以其侧生象木枝也。此乃臆说，附质明者。经曰∶肾者，精之处也，其华在发。王冰注曰∶肾主髓，脑者，髓之海，发者。脑之华，脑髓减，则发素。时珍曰∶发入土，千年不朽；以火 之，凝为血质；煎炼至枯，复有液出；误吞入腹，化为症虫； 炼服食，使发不白，故《本经》有自还神化之称。陈藏器曰∶生人发挂果树上，则乌鸟不敢来。又人逃走，取其发于纬车上缚之，则迷乱不知所适，此皆神化。《子母秘录》∶乱发烧灰，亦治尸疰。猪脂调涂小儿燕口，即两角生疮也。宋丞相王郇公，小腹切痛，备治不效。用附子、硫黄、五夜叉丸之类，亦不瘥。张驸马取妇人油头发，烧灰研筛，酒服二钱，其痛立止。《内经》∶脑为髓海，冲为血海，命门为精海，丹田为气海，胃为水谷之海）。皂荚水洗净， 罐固 存性用。胎发尤良，补衰涸。头垢，治淋及噎膈劳复。"},
  "古文钱":{o:[],src:["本草纲目"],d:"旧一，新二十一。\n时气欲死︰大钱百文，水一斗煮八升，入麝香末三分，稍饮至尽，或吐或下愈。（《肘后方》）\n时气温病，头痛壮热脉大，始得一日者。比轮钱一百五十七文，水一斗，煮取七升，服汁。须臾复以水五升，更煮一升，以水二升投中，合得三升，出钱饮汁，当吐毒出也。（《肘后方》）\n心腹烦满及胸胁痛欲死者。比轮钱二十枚，水五升，煮三升，分三服。（《肘后方》）\n急心气痛︰古文钱一个（打碎），大核桃三个，同炒热，入醋一碗冲服。（《杨诚经验方》）\n霍乱转筋︰青铜钱四十九枚，木瓜一两，乌梅（炒）五枚。水二盏，煎分温服。（《圣济录》）\n慢脾惊风，利痰奇效︰用开元通宝钱背后上下有两月痕者，其色淡黑，颇小。以一个放铁匙上，炭火烧四围上下，各出珠子，取出候冷，倾入盏中，作一服，以南木香汤送下，或人参汤亦可。钱虽利痰，非胃家所好，须以木香佐之。（《杨仁斋直指方》）\n下血不止︰大古钱四百文，酒三升，煮二升，分三服。（《普济方》）\n赤白带下︰铜钱四十文。酒四升，煮取二升，分三服。（《千金方》）\n小便气淋︰比轮钱三百文。水一斗，煮取三升，温服。（《千金方》）\n沙石淋痛︰古文钱，煮汁服。（《普济方》）\n伤水喘急，因年少饮冷水惊恐所致者。古文钱七枚（洗净），白梅七个，水一钟，同浸三宿，空心一呷，良久得吐效。（《仁存方》）\n唇肿黑痛，痒不可忍︰四文大钱于石上磨猪脂汁涂之，不过数遍愈。（《幼幼新书》）\n口内热疮︰青钱二十文，烧赤投酒中服之，立瘥。（陈藏器《本草》）\n眼赤生疮，连年不愈。古钱一文，青江石一个，洗净，以钱于石上磨蜜，取浓汁三、四滴在盏，覆瓦上，以艾灸瓦内七壮熏蜜，取点之，效。（《普济方》）\n赤目浮翳︰古钱一文，盐方寸匕，治筛点之。（《千金方》）\n目猝不见︰钱于石上磨汁，注 中。（《普济方》）\n目生珠管及肤翳。铜钱青一两，细墨半两，为末，醋丸白豆大。每以一丸，乳汁、新汲水各少许，浸化点之。（《圣惠方》）\n腋下狐臭︰古文钱十文，铁线串烧，醋淬十次，入麝香研末，调涂。（《应急良方》）\n跌扑伤损︰半两钱五个（火 醋淬四十九次），甜瓜子五钱，珍珠二钱。研末。每服一字，好酒调，随上下，食前后。（《青囊》）\n误吞铁钱︰古文铜钱十个，白梅肉十个，淹过即烂，捣丸绿豆大。每服一丸，流水吞下，即吐出。（《圣济录》）\n百虫入耳︰青钱十四文，煎猪膏二合，少少滴之。（《圣济录》）\n便毒初起︰方见发明下。"},
  "古镜":{o:[],src:["本草纲目"],d:"新一。\n小儿夜啼︰明鉴挂床脚上。（《圣惠方》）\n锡铜镜鼻（《本经》下品）\n\n新一。\n小儿客忤，面青惊痛。铜照子鼻烧赤，少酒淬过，与儿饮。（《圣惠方》）\n镜锈（即镜上绿也。俗名杨妃垢）"},
  "吊":{o:[],src:["本草纲目"],d:"新二。\n阳事痿弱︰紫梢花、生龙骨各二钱，麝香少许，为末。蜜丸梧子大。每服二十丸，烧酒下。欲解，饮生姜甘草汤。（《集次即愈。（《总微论》）"},
  "土菌":{o:[],src:["本草纲目"],d:"新一。\n疔肿︰黑牯牛撒粪石上，待生菌子，焙干， 草等分为末。以竹筒去两头，紧缚，合住疔上。用水和末一钱，入筒内。\n少顷沸起，则根拔出。未出，再作二、三次。（《医学正传》）。"},
  "土蜂":{o:[],src:["本草纲目"],d:"新一。\n面黑令白︰土蜂子未成头翅者，炒食，并以酒浸敷面。（《圣惠方》）\n房\n\n新一。\n疔肿疮毒已笃者︰二服即愈，轻者一服立效。用土蜂房一个，蛇蜕一条，黄存性，为末。每服一钱，空心好酒下。少顷腹中大痛，痛止，其疮已化为黄水矣。（《普济方》）"},
  "土马鬃":{o:[],src:["本草纲目"],d:"新五。\n九窍出血︰墙头苔， 塞之。（《海上方》）。\n鼻衄不止︰寸金散︰用墙上土马鬃二钱半，石州黄药子五钱。为末。新水服二钱，再服立止。（《卫生宝鉴》）。\n二便不通︰土马鬃，水淘净，瓦爆过，切。每服二钱，水一盏，煎服。（《普济》）。\n耳上湿疮︰土马鬃、井中苔等分。为末。灯盏内油和，涂之。（《圣济录》）。\n少年发白︰土马鬃、石马鬃、五倍子、半夏各一两，生姜二两，胡桃十个，胆矾半两为末，捣作一块。每以绢袋盛一弹子，用热酒入少许，浸汁洗发。一月神效。（《圣济录》）"},
  "地浆":{o:["地浆"],src:["本草备要"],d:"泻热，解毒\n甘寒。治泻痢冷、热、赤、白，腹内热毒绞痛。解一切鱼肉、菜、果、药物、诸菌毒（菌，音郡，生朽木湿地上。亦名蕈，音寻，上声），及虫蜞入腹（如误食马蟥蜞入腹，生子为患，用地浆下之），中 （暑热）卒死者（取道上热土围脐，令人尿脐中，以热土大蒜等分，捣水去渣，灌之即活）。以新水沃黄土搅浊，再澄清用（凡跌打损伤，取净土蒸热，以布裹更互熨之，勿大热，恐破肉。虽瘀血凝积，气绝欲死者亦活。宋神宗皇子病螈 ，国医不能治。钱乙进黄土汤而愈。帝问其故，对曰∶以土伏水，水得其平，风自止矣）。"},
  "地肤":{o:[],src:["本草纲目"],d:"旧三，新七。\n风热赤目︰地肤子（焙）一升，生地黄半斤，取汁和作饼，晒干研末。每服三钱，空心酒服。\n目痛瞇目︰凡目痛及瞇目中伤有热瞑者。取地肤子白汁，频注目中。（王焘《外台秘要》）\n雷头风肿，不省人事︰落帚子同生姜研烂，热冲酒服，取汗即愈。（《圣济总录》）\n胁下疼痛︰地肤子为末，酒服方寸匕。（《寿域神方》）\n疝气危急︰地肤子（即落帚子），炒香研末。每服一钱，酒下。（《简便方》）\n狐疝阴 ，超越举重，卒得阴 ，及小儿狐疝，伤损生 ︰并用地肤子五钱，白术二钱半，桂心五分，为末。饮或酒服三钱，忌生葱、桃、李。（《必效方》）\n腰痛积年，有时发动︰六月、七月取地肤子，干末。酒服方寸匕，日五、六服。（《肘后》）\n血痢不止︰地肤子五两，地榆、黄芩各一两，为末。每服方寸匕，温水调下。（《圣惠方》）\n妊娠患淋，热痛酸楚，手足烦疼︰地肤子十二两，水四升，煎二升半，分服。（《子母秘录》）\n肢体疣目︰地肤子、白矾等分，煎汤频洗。（《寿域神方》）\n苗叶\n\n新一。\n物伤睛陷， 肉突出︰地肤（洗去土）二两。捣绞汁，每点少许。冬月以干者煮浓汁。（《圣惠方》）"},
  "地胆":{o:[],src:["本草纲目"],d:"新三。\n小肠气痛︰地胆（去翅、足、头，微炒）、朱砂各半两，滑石一两，为末。每苦杖酒食前调服二钱，即愈。（《宣明》）\n鼻中息肉︰地胆，生研汁，灌之。干者，酒煮取汁。又方︰细辛、白芷等分。为末，以生地胆汁和成膏。每用少许点之，取消为度。（并《圣惠方》）"},
  "地衣草":{o:[],src:["本草纲目"],d:"新三。\n身面丹肿，如蛇状者︰以雨滴阶上苔痕水花，涂蛇头上，即愈。（危氏《得效方》）。\n雀目夜昏︰七月七日、九月九日取地衣草，阴干为末。酒服方寸匕，日三服，一月愈。（崔知悌方）。\n阴上粟疮︰取停水湿处干卷皮，为末。敷之，神效。（《外台秘要》）"},
  "地锦":{o:[],src:["本草纲目"],d:"旧一，新十一。\n脏毒赤白︰地锦草洗，曝干为末。米饮服一钱，立止。（《经验方》）。\n血痢不止︰地锦草晒研。每服二钱，空心米饮下。（《乾坤生意》）。\n大肠泻血︰血见愁少许，姜汁和捣，米饮服之。（戴原礼《证治要诀》）。\n妇人血崩︰草血竭（嫩者）蒸熟，以油、盐、姜淹食之，饮酒一、二杯送下。或阴干为末，姜酒调服一、二钱，一服即止。生于砖缝井砌间，少在地上也。（危亦林《得效方》）。\n小便血淋︰血风草，井水擂服，三度即愈。（刘长春《经验方》）。\n金疮出血不止。血见愁草研烂涂之。（危氏《得效方》）。\n恶疮见血︰方同上。\n疮疡刺骨︰草血竭捣罨之，自出。（《本草权度》）。\n痈肿背疮︰血见愁一两，酸浆草半两（焙），当归二钱半（焙），乳香、没药各一钱二分半，为末。每服七钱，热酒调下。如有生者，擂酒热服，以渣敷之亦效。血见愁惟雄疮用之，雌疮不用。（杨清叟《外科方》）。\n风疮疥癣︰血见愁草同满江红草捣末，敷之。（《乾坤秘韫》）。\n趾间鸡眼，割破出血︰以血见愁草捣敷之妙。（《乾坤秘韫》）。\n脾劳黄胆︰如圣丸︰用草血竭、羊膻草、桔梗、苍术各一两，甘草五钱，为末。先以陈醋二碗入锅，下皂矾四两煎熬，良久下药末，再入白面不拘多少，和成一块，丸如小豆大。每服三、五十丸，空腹醋汤下，一日二服。数日面色复旧也。（《乾坤秘韫》）"},
  "地黄":{o:[],src:["本草纲目"],d:"旧十二，新五十三。可丸，丸如梧子大。每晨温酒送下三十丸，日三服。亦可以青州枣和丸。或别以干地黄末入膏，丸服亦可。百日面如桃花，三年身轻不老。《抱朴子》云︰楚文子服地黄八年，夜视有光。（《神仙方》）\n三捣三压，取汁令尽，以瓦器盛之，密盖勿泄气，汤上煮减半，绞去滓，再煎如饧，丸弹子大。每温酒服一丸，日二服。（《千金》）\n斤半，生姜半斤（绞取汁），蜜二升，酒四升。文武火煮地黄汁数沸，即以酒研紫苏子四两，取汁入煎一二十沸，下胶；胶化，下姜汁、蜜再煎；候稠，瓦器盛之。每空心酒化一匕服，大补益。（同上）\n地黄粥︰大能利血生精。地黄（切）二合，与米同入罐中煮之，候熟，以酥二合，蜜一合，同炒香入内，再煮熟食。（《 仙神隐》）\n地黄酒︰见谷部酒下。\n疽劳瘵，咳嗽唾血等病，乃铁瓮城申先生方也︰生地黄汁十六斤（取汁），人参末一斤半，白茯苓末三斤，白沙蜜十斤，滤净拌匀，入瓶内，箬封，安砂锅中，桑柴火煮三日夜。再换蜡纸重封，浸井底一夜，取起，再煮一伏时。每以白汤或酒点服一匙。\n丹溪云︰好色虚人，咳嗽唾血者，服之甚捷。国朝太医院进御服食，议加天门冬、麦门冬、枸杞子末各一斤，赐名益寿永真。\n《 仙方》︰明目补肾︰生 、熟 各二两，川椒红一两，为末，蜜丸梧桐子大，每空心盐汤下三十丸。（《普济方》）\n固齿乌须，一治齿痛，二生津液，三变白须，其功极妙。地黄五斤，柳木甑内，以土盖上，蒸熟晒干。如此三次，捣为小饼。每噙咽一枚。（《御药院方》）\n男女虚损，或大病后，或积劳后，四体沉滞，骨肉酸痛，吸吸少气，或小腹拘急，腰背强痛，咽干唇燥，或饮食无味，多卧少起，久者积年，轻者百日，渐至瘦削︰用生地黄二斤，面一斤。捣烂，炒干为末。每空心酒服方寸匕，日三服。忌如法。（《肘后方》）。\n虚劳困乏︰地黄一石，取汁，酒三斗，搅匀煎收。日服。（《必效方》）\n口干心躁︰熟地黄五两，水三盏，煎一盏半，分三服，一日尽。（《圣惠方》）\n骨蒸劳热︰张文仲方︰用生地黄一斤，捣三度，绞取汁尽，分再服。若利即减之，以身轻凉为度。（《外台秘要》）\n妇人发热，欲成劳病，肌瘦食减，经候不调︰地髓煎︰用干地黄一斤，为末，炼蜜丸梧子大，每酒服五十丸。（《保庆集》）\n妇人劳热心忪︰地黄煎︰用生，干地黄、熟干地黄等分，为末，生姜自然汁，入水相和，打糊丸梧子大。每服三十丸，用地黄汤下，或酒醋茶汤下亦可，日二服。觉脏腑虚冷，则晨服八味丸，地黄性冷坏脾。阴虚则发热，地黄补阴血故也。（《妇人良方》）\n咳嗽唾血劳瘦骨蒸，日晚寒热︰生地黄汁三合，煮白粥临熟，入地黄汁搅匀，空心食之。（《食医心镜》）\n吐血咳嗽︰熟地黄末，酒服一钱，日三。（《圣惠方》）\n吐血不止︰生地黄汁一升二合，白胶香二两，以瓷器盛，入甑蒸，令胶消，服之。（《梅师》）\n肺损吐血，或舌上有孔出血。生地黄八两（取汁），童便五合（同煎热），入鹿角胶（炒研）一两，分三服。心热吐衄，脉洪数者。生 汁半升，熬至一合，入大黄末一两，待成膏，丸梧子大，每熟水下五丸至十丸。（并《圣惠方》）\n鼻出衄血︰干地黄、龙脑薄荷等分，为末，冷水调下。（孙兆《秘宝方》）\n吐血便血︰地黄汁六合，铜器煎沸，入牛皮胶一两，待化入姜汁半杯，分三服，便止。或微转一行，不妨。（《圣惠方》）\n肠风下血 生地黄、熟地黄（并酒浸）、五味子等分，为末，以炼蜜丸梧子大，每酒下七十丸。（《百一选方》）\n初生便血，小儿初生七、八日，大小便血出，乃热传心肺︰不可服凉药，只以生地黄汁五七匙，酒半匙，蜜半匙，和服之。（《全幼心鉴》）\n小便尿血吐血，及耳鼻出血︰生地黄汁半升，生姜汁半合，蜜一合，和服。（《圣惠方》）\n小便血淋︰生地黄汁、车前叶汁各三合，和煎服。（《圣惠方》）\n小儿蛊痢︰生 汁一升二合，分三、四服，立效。（《子母秘录》）\n月水不止︰生地黄汁，每服一盏，酒一盏，煎服，日二次。（《千金方》）\n而无子，乃冲任伏热也︰熟地黄半斤，当归二两，黄连一两，并酒浸一夜，焙研为末，炼蜜丸梧子大。每服七十丸，米饮温酒任下。（禹讲师方）\n妊娠漏胎，下血不止︰《百一方》︰用生地黄汁一升，渍酒四合，煮三、五沸服之。不止又服。\n崔氏方︰用生地黄为末，酒服方寸匕，日一夜一。《经心录》︰加干姜为末。《保命集》︰\n二黄丸︰用生地黄、熟地黄等分，为末。每服半两，白术、枳壳煎汤，空心调下，日二服。\n胎寒腹痛，妊妇冲任脉虚，惟宜抑阳助阴︰内补丸︰用熟地黄二两，当归一两，微炒为末，蜜丸梧子大，每温酒下三十丸。（许学士《本事方》）\n妊娠胎动︰生地黄捣汁，煎沸，入鸡子白一枚，搅服。（《圣惠方》）\n产后血痛有块，并经脉行后，腹痛不调︰黑神散︰用熟地黄一斤，陈生姜半斤，同炒干为末。每服二钱，温酒调下。（《妇人良方》）\n产后恶血不止︰干地黄捣末，每食前热酒服一钱，连进三服。（《瑞竹堂方》）\n产后中风，胁不得转︰交加散︰用生地黄五两（研汁），生姜五两（取汁）。交互相浸一夕，次日各炒黄，浸汁干，乃焙为末。每酒服一方寸匕。（《济生方》）\n产后烦闷，乃血气上冲︰生地黄汁、清酒各一升，相和煎沸，分二服。（《集验方》）\n产后百病︰地黄酒︰用地黄汁渍曲二升，净秫米二斗，令发，如常酿之。至熟，封七日，取清，常服令相接。忌生冷、酢、滑蒜、鸡、猪、鱼一切毒物。未产先一月酿成。夏月不可造。（《千金方》）\n胞衣不出︰生地黄汁一升，苦酒三合，相和暖服。\n寒疝绞痛来去︰用乌鸡一只（治如常法），生地黄七斤（锉细）。甑中同蒸，下以铜器承取汁。清旦服，至日晡令尽。其间当下诸寒 讫，作白粥食之。久疝者作三剂。（《肘后方》）\n小儿阴肿︰以葱椒汤暖处洗之，唾调地黄末敷之。外肾热者，鸡子清调。或加牡蛎少许。（危氏方）\n小儿热病，壮热烦渴，头痛︰生地黄汁三合，蜜半合，和匀，时时与服。（《普济方》）\n热 昏沉︰地黄汁一盏服之。生薄荷叶方》）\n温毒发斑，黑膏︰治温毒发斑呕逆︰生地黄二两六钱二字半，好豆豉一两六钱二字半，以猪膏十两合之，露一夜，煎减三分之一，绞去滓，入雄黄、麝香如豆大，搅匀，分作三服，毒从皮中出则愈。忌芜荑。（《千金方》）\n血热生癣︰地黄汁频服之。（《千金方》）\n疔肿乳痈︰地黄捣敷之，热即易。性凉消肿，无不效。（《梅师方》）\n痈疖恶肉︰地黄三斤，水一斗，煮取三升，去滓煎稠，涂纸上贴之，日三易。（《鬼遗》方》）\n一切痈疽，及打扑伤损，未破疼痛者︰以生地黄杵如泥，摊在上，掺木香末于中，又摊地黄泥一重贴之，不过三五度即内消也。（王衮《博济方》）\n打扑损伤、骨碎及筋伤烂：用生地黄熬膏裹之。以竹简编夹急缚，勿令转动。一日一夕，可十易之，则瘥。《类说》云：许元公过桥堕马，右臂臼脱，左右急挼入臼中，昏迷不知痛苦。急召田录事视之，曰：尚可救。乃以药封肿处，中夜方苏，达旦痛止，痛处已白。日日换贴，其瘀肿移至肩背，乃以药下去黑血三升而愈。即上方也（出《肘后方》中）。\n损伤打扑，瘀血在腹者：用生地黄汁三升，酒一升半，煮二升半，分三服。（出《千金方》）\n物伤睛突，轻者睑胞肿痛，重者目睛突出，但目系未断者︰即纳入，急捣生地黄，绵裹敷之。仍以避风膏药，护其四边。（《圣济总录》）\n睡起目赤肿起，良久如常者，血热也。卧则血归于肝，故热则目赤肿。良久血散，故如常也︰用生地黄汁，浸粳米半升，晒干，三浸三晒。每夜以米煮粥食一盏，数日即愈。有人病此，用之得效。（《医余》）\n眼暴赤痛︰水洗生地黄、黑豆各二两，捣膏。卧时以盐汤洗目，闭目以药浓罨目上，至晓，水润取下。（《圣济总录》）\n蓐内赤目︰生地黄薄切，温水浸贴。（《短剧方》）\n牙疳宣露，脓血口气︰生地黄一斤，盐二合，末，自捣和团，以面包煨令烟断，去面入麝一分，研匀，日夜贴之。（《圣济录》）\n牙齿挺长，出一分者︰常咋生地黄，甚妙。（张文仲《备急方》）\n牙动欲脱︰生地黄绵裹咂之，令汁渍根，并咽之，日五六次。（《千金方》）\n食蟹龈肿，肉 出者︰生地黄汁一碗，牙皂角数条火炙，蘸尽地黄汁，为末敷之。（《永类耳中常鸣︰生地黄截，塞耳中，日数易之。或煨熟，尤妙。（《肘后方》）\n须发黄赤︰生地黄一斤，生姜半斤，各洗，研自然汁，留滓。用不蛀皂角十条，去皮弦，蘸汁，炙至汁尽为度。同滓入罐内泥固， 存性，为末，用铁器盛。末三钱汤调，停二日，临卧刷染须发上，即黑。（《本事方》）\n竹木入肉︰生地黄嚼烂罨之。（《救急方》）\n毒箭入肉︰煎生地黄汁作丸服。至百日，箭出。（《千金方》）\n犬咬伤︰地黄捣汁，饭饼涂之，百度愈。（《百一方》）\n\n新一。\n（晒）、槐点少许，日三、四次。（《圣惠方》）"},
  "堇":{o:[],src:["本草纲目"],d:"旧二，新一。\n结核气：堇菜，晒干为末，油煎成膏。摩之，日三、五度，便瘥。（孟诜《食疗》）\n湿热气：旱芹菜晒干为末，糊丸梧子大。每服四十丸，空心温酒下。大杀百虫毒。（《寿域神方》）。\n蛇咬疮：生杵堇汁涂之。（《万毕术》）"},
  "墨":{o:["墨"],src:["本草备要"],d:"辛温。止血生肌。飞丝、尘芒入目，浓磨点之；点鼻止衄；猪胆汁磨，涂诸痈肿（醋磨亦可）。酒磨服，治胞不下。"},
  "壁钱":{o:[],src:["本草纲目"],d:"新一。\n喉痹乳蛾︰已死者复活。用墙上壁钱七个，内要活蛛二枚，捻作一处，以白矾七分一块，化开，以壁钱惹矾，烧存性，出火\n窠幕\n\n虫牙疼痛︰《普济方》︰以壁上白丸之，纳入牙中甚效。又以乳香入耳，左痛塞右，右痛塞左，手"},
  "壶卢":{o:[],src:["本草纲目"],d:"新一。\n腹胀黄肿︰用亚腰壶卢连子烧存性，每服一个，食前温酒下。不饮酒者，白汤下。十余日见效。（《简便方》）\n叶\n\n新一。\n预解胎毒︰七、八月，或三伏日，或中秋日，剪壶卢须如环子脚者，阴干，于除夜煎汤浴小儿，则可免出痘。（唐瑶《经验方》）\n子"},
  "夜明砂":{o:["夜明砂"],src:["本草备要"],d:"（一名天鼠矢）\n泻，散血，明目辛寒。肝经血分药。活血消积，治目盲障翳（加石决明猪肝煎，名决明夜灵散，治鸡盲眼）疟 （音奇。小儿鬼）惊疳（蝙蝠及矢，并治惊、疳、疟、痫、厥阴之病），血气腹痛（《经疏》曰∶辛能散内外滞气，寒能除血热气壅，明目之外，余皆可略。吴鹤皋曰∶古人每用虻虫、水蛭治血积，以其善吮血耳。若天鼠矢，乃食蚊而化者也，当亦可以攻血积，《本草》称其下死胎，则其能攻血块也何疑）。同鳖甲烧烟辟蚊。蝙蝠矢也，食蚊，砂皆蚊眼，故治目疾。淘净焙用。恶白薇、白蔹。"},
  "大戟":{o:["大戟"],src:["本草备要", "本草纲目"],d:"大泻，通脏腑水湿\n苦寒有毒。能泻脏腑水湿，行血发汗，利大小便。治十二种水，腹满急痛，积聚症瘕，颈腋痈肿，风毒脚肿，通经堕胎。误服损真气（时珍曰∶痰涎为物，随气升降，无处不到。入心则迷，成癫痫；入肺则塞窍，为咳喘背冷；入肝则胁痛干呕，寒热往来；入经络则麻痹疼痛；入筋骨则牵引隐痛；入皮肉则瘰 痈肿。陈无择并以控涎丹主之，殊有奇效，此乃治痰之本。痰之本，水也，湿也，得气与火。则结为痰。大戟能泄脏腑水湿，甘遂能行经络水湿，白芥子能散皮里膜外痰气，惟善用者能收奇功也。又曰∶钱仲阳谓肾为真水，有补无泻。复云痘症变黑归肾者，用百祥膏下之，非泻肾也，泻其腑，则脏自不实。腑者，膀胱也。百祥惟大戟一味，能行膀腕之水故也。窍谓非独泻腑，乃肾邪实而泻肝也。实则泻其子，大戟浸水青绿，肝胆之色也。痘症毒盛火炽，则水益涸，风挟火势，则土受亏，故津液内竭，不能化脓，而成黑陷之证，泻其风火之毒，所以救肾扶脾也。昂按∶泻心乃所以补心，泻肾即所以救肾，邪热退，则真阴复矣。《机要》用大戟一两，枣三枚，同煮焙干，去戟，用枣丸服，名枣变百祥丸）。杭产紫者为上，北产白者伤人。浆水煮，去骨用。得大枣则不损脾。畏菖蒲。反甘草。"},
  "大腹皮":{o:["大腹皮"],src:["本草备要"],d:"泻，下气，通，行水\n辛泄肺、温和脾。下气行水，通大、小肠。治水肿香港脚，痞胀痰膈，瘴疟霍乱。气虚者忌用。子，似槟榔，腹大形扁（故与槟榔同功）。取皮，酒洗，黑豆汤再洗。煨用（鸠鸟多栖其树，故宜洗净）。"},
  "大蒜":{o:["大蒜"],src:["本草备要"],d:"（张骞使西域，始得种入中国，故一名葫）\n宣，通窍，辟恶辛温。开胃健脾，通五脏，达诸窍（凡极臭极香之物，皆能通窍），去寒湿，解暑气，辟瘟疫，消痈肿（捣烂，麻油调敷），破症积，化肉食，杀蛇虫蛊毒。治中暑不醒（捣，和地浆温服），鼻衄不止（捣，贴足心，能引热下行），关格不通（捣，纳肛中，能通幽门）。敷脐能达下焦，消水，利大、小便。切片，灼艾，灸（音九）一切痈疽，恶疮肿核。独头者尤良（李迅曰∶痈疽着灸，胜于诸药。缘热毒中膈，上下不通，必得毒瓦斯发泄，然后解散。初起便用独头大蒜，切片灸之，三壮一易，百壮为率。但头项以上，切不可灸，恐引气上，更生大祸也。史源曰∶有灸至八百壮者，约艾一筛，初坏肉不痛，直灸到好肉方痛。至夜，火满背高阜，头孔百数，则毒外出，否则内逼五脏而危矣。《纲目》曰∶《精要》谓头上毒不得灸，此言过矣。头为诸阳所聚，艾宜小如椒粒，炷宜三五壮而已。又按∶李东垣灸元好问脑疽，艾大如两核许，灸至百壮，始觉痛而痊。由是推之，头毒若不痛者，艾大壮多，亦无妨也）。然其气熏臭，多食生痰动火，散气耗血，损目昏神（五荤皆然，而蒜尤甚。《楞严经》云∶五荤熟食发淫，生啖增恚，故释氏戒之。释家以大蒜、小蒜、兴渠、慈葱、 葱为五荤。慈葱，冬葱也； 葱，山葱也；兴渠，西域菜，云即中国之荽。道家以韭、薤、蒜、胡荽、芸苔为五荤。芸苔，油菜也）。忌蜜。"},
  "大蓟、小蓟":{o:[],src:["本草纲目"],d:"旧六，新九。\n心热吐血口干︰用刺蓟叶及根，捣绞取汁，每顿服二小盏。（《圣惠方》）\n舌硬出血不止︰刺蓟捣汁，和酒服。干者为末，冷水服。（《普济方》）\n九窍出血︰方同上。（《简要济众》）\n卒泻鲜血︰小蓟叶捣汁，温服一升。（《梅师方》）\n崩中下血︰大、小蓟根一升，酒一斗，渍五宿，任饮。亦可酒煎服，或生捣汁。温服。又方︰小蓟茎叶洗切，研汁一盏，入生地黄汁一盏，白术半两，煎减半，温服。（《千金方》）\n堕胎下血︰小蓟根叶、益母草五两。水二大碗，煮汁一碗，再煎至一盏，分二服，一日服尽。（《圣济总录》）\n金疮出血不止︰小蓟苗捣烂涂之。（孟诜《食疗本草》）\n小便热淋︰马蓟根，捣汁服。（《圣惠方》）\n鼻塞不通︰小蓟一把，水二升，煮取一升，分服。（《外台秘要》方）\n小儿浸淫，疮痛不可忍，发寒热者︰刺蓟叶新水调敷疮上，干即易之。（《简要济众方》）\n癣疮作痒︰刺蓟叶，捣汁服之。（《千金方》）\n妇人阴痒︰小蓟煮汤，日洗三次。（《普济方》）\n诸 不合︰虎蓟根、猫蓟根、酸枣根、枳根、杜衡各一把，斑蝥三分。炒为末，蜜丸枣大。疔疮恶肿︰千针草四两，乳香一两，明矾五钱，为末。酒服二钱，出汗为度。（《普济方》）"},
  "大青":{o:["大青"],src:["本草备要", "本草纲目"],d:"泻心胃热毒\n微苦咸，大寒。解心胃热毒。治伤寒，时疾热狂，阳毒发斑（热甚伤血，里实表虚，则发斑。轻如疹子，重如锦纹。紫黑者，热极而胃烂也，多死。《活人书》∶治赤斑烦痛，有犀角大青汤），黄胆热痢，丹毒喉痹。处处有之。高二三尺，茎圆叶长，叶对节生，八月开小红花成簇，实大如椒，色赤。用茎叶。"},
  "大风子":{o:["大风子"],src:["本草备要"],d:"燥痰，外用治疮\n辛热有毒。取油治疮癣疥癞，有杀虫劫毒之功（丹溪曰∶粗工治大风病，佐以大风油，殊不知此物性热，有燥痰之功而伤血，至有病将愈而先失明者）。出南番。子中有仁，白色，久则油黄，不可用。入丸药，压去油。"},
  "大麦芽":{o:["大麦芽"],src:["本草备要"],d:"开胃健脾，行气消积\n咸温。能助胃气上行，而资健运，补脾宽肠，和中下气，消食除胀，散结祛痰（咸能软坚），化一切米、面、果、食积，通乳下胎（《外台方》∶麦芽一升、蜜一升服，下胎神验。薛立斋治一妇人，丧子乳胀，几欲成痈，单用麦芽一二两炒，煎服立消，其破血散气如此。《良方》云∶神曲亦下胎，皆不可轻用）。久服消肾气（王好古曰∶麦芽，神曲，胃虚人宜服之，以伐戊己，腐熟水谷。李时珍曰∶无积而服之，消人元气。与白术诸药，消补兼施，则无害也。胃为戊土，脾为己土）。炒用。豆蔻、砂仁、乌梅、木瓜、芍药、五味为使。"},
  "大麻仁":{o:["大麻仁"],src:["本草备要"],d:"（大麻，即作布之麻，俗作火麻）\n润燥滑肠甘平滑利。脾、胃、大肠之药，缓脾润燥。治阳明病、胃热汗多而便难（三者皆燥也，汗出愈多，则津枯而大便愈燥。张仲景治脾约有麻仁丸。成无己曰∶脾欲缓，急食甘以缓之，麻仁之甘，以缓脾润燥。张子和曰∶诸燥皆三阳病），破积血，利小便，通乳催生。又木谷也，亦能治风。极难去壳，帛裹置沸汤，待冷，悬井中一夜，晒干，就新瓦上 去壳，捣用。畏茯芩、白薇、牡蛎。"},
  "大黄蜂":{o:[],src:["本草纲目"],d:"新一。\n雀斑面 ︰七月七日取露蜂子，于漆碗中水酒浸过，滤汁，调胡粉敷之。（《普济方》）"},
  "天仙藤":{o:["天仙藤"],src:["本草备要", "本草纲目"],d:"通，活血，消肿\n苦温。疏气活血。治风劳腹痛，妊娠水肿（有天仙藤散，专治水肿）。叶似葛，圆而小，有白毛，根有须，四时不凋（一云即青木香藤）。"},
  "天名精":{o:[],src:["本草纲目"],d:"旧二，新九。\n男女吐血︰皱面草（即地菘），晒干为末。每服一、二钱，以茅花泡汤调服，日二次。（《卫生易简》）\n根、叶捣汁，鹅翎扫入，去痰最妙。《圣济总录》︰用杜牛膝、鼓锤草，同捣汁灌之。不得下者，灌鼻得吐为妙。又方︰杜牛膝（春夏用茎，秋冬用根）一把，青矾半两，同研，点患处，令吐脓血痰沫，即愈。二丸，即愈。干者为末，蜜丸亦可。名救生丸。（《经效济世方》）\n诸骨哽咽︰地菘、马鞭草各一握（去根），白梅肉一个，白矾一钱，捣作弹丸，绵裹含咽，其骨自软而下也。（《普济方》）\n疔疮肿毒︰鹤虱草叶，浮酒糟，同捣敷之，立效。（孙氏《集效方》）\n发背初起︰地菘杵汁一升，日再服，瘥乃止。（《伤寒类要》）\n恶疮肿毒︰地菘捣汁，日服三、四次。（《外台秘要》）\n恶蛇咬伤︰地菘捣敷之。（《易简方》）\n\n新一。\n大肠虫出不断，断之复生，行坐不得︰鹤虱末，水调半两服，自愈。（《怪疾奇方》）"},
  "天牛":{o:[],src:["本草纲目"],d:"新三。\n疔肿恶毒︰透骨膏︰用八角儿（杨柳上者，阴干去壳）四个（如冬月无此，用其窠代之），蟾酥半钱，巴豆仁一个，粉霜、雄黄、麝香少许。先以八角儿研如泥，入熔化黄蜡少许，同众药末和作膏子，密收。每以针刺疮头破出血，用榆条送膏子（麦粒大）入疮中，以雀粪二个放疮口。疮回即止，不必再用也。忌冷水。如针破无血，系是著骨疔。即男左女右中指甲末，刺出血糊药。又无血，即刺足箭镞入肉︰用天水牛（取一角者），小瓶盛之，入 砂一钱，同水数滴在内。待自然化水，取滴伤处，即出也。\n寒热疟疾︰猪膏丸︰治疟疾发渴，往来不定。腊猪膏二两，独角仙一枚，独头蒜一个，楼葱一握，五月五日三家粽尖。于五月五日五更时，净处露头赤脚，舌拄上 ，回面向北，捣一千杵，丸皂子大。每以新绵裹一丸，系臂上，男左女右。（《圣惠》）"},
  "天竹黄":{o:["天竹黄"],src:["本草备要"],d:"泻热，豁痰，凉心\n甘而微寒。凉心经，去风热，利窍豁痰，镇肝明目。功同竹沥，而性和缓，无寒滑之患。治大人中风不语，小儿客忤惊痫为尤宜。出南海。大竹之津气结成（即竹内黄粉），片片如竹节者真。"},
  "天蓼":{o:[],src:["本草纲目"],d:"新一。\n生肌肉 水荭花根，煎汤淋洗，仍以其叶晒干研末，撒疮上，每日一次。（《谈野翁试验方》）"},
  "天门冬":{o:[],src:["本草纲目"],d:"旧三，新十五。末。每服方寸匕，日三服。无问山中人间，久服补中益气，治虚劳绝伤，年老衰损，偏枯不随，风湿不仁，冷痹恶疮，痈疽癞疾。鼻柱败烂者，服之皮脱虫出。酿酒服，去症瘕积聚，风痰颠狂，三虫伏尸，除湿痹，轻身益气，则香美，诸酒不及也。忌鲤鱼。每服方寸匕。名仙人粮。\n辟谷不饥︰天门冬二斤，熟地黄一斤，为末，炼蜜丸弹子大。每温酒化三丸，日三服。居山远行，辟谷良。服至十日，身轻目明；二十日，百病愈，颜色如花；三十日，发白更黑，齿落重生；五十日，行及奔马；百日，延年。又法︰天门冬捣汁，微火煎取五斗，入白蜜一斗，胡麻（炒末）二升，合煎至可丸，即止火。下大豆黄末，和作饼，径三寸，浓半寸。一服一饼，一日三服，百日以上有益。又法︰天门冬末一升，松脂末一升，蜡、蜜一升和煎，丸如梧子大。每日早、午、晚各服三十丸。天门冬酒，补五脏，调六腑，令人无病︰天门冬三十斤，去心捣碎，以水二石，煮汁一石，糯米一斗，细曲十斤，如常炊酿，酒熟，日饮三杯。\n天门冬膏，去积聚风痰，补肺，疗咳嗽失血，润五脏，杀三虫伏尸，除瘟疫，轻身益气，令人不饥︰以天门冬流水泡过，去皮心，捣烂取汁，砂锅文武炭火煮，勿令大沸。以十斤为率，熬至三斤，却入蜜四两，熬至滴水不散，瓶盛埋土中一七，去火毒。每日早、晚白汤调服一匙。若动大便，以酒服之。（《医方摘要》）\n肺痿咳嗽吐涎沫，心中温温，咽燥而不渴︰生天门冬（捣汁）一斗，酒一斗，饴一升，紫菀四合，铜器煎至可丸。每服杏仁大一丸，日三服。（《肘后方》）\n阴虚火动有痰，不堪用燥剂者︰天门冬一斤（水浸洗去心，取肉十二两，石臼捣烂），五味子（水洗去核，取肉四两，晒干，不见火）。共捣丸梧子大。每服二十丸，茶下，日三服。（《简便方》）\n酒洒之，九蒸九晒，待干秤之）。人参一两为末，蒸枣肉捣和，丸梧子大。每服三十丸，食前温酒下，日三服。（洁古《活法机要》）\n虚劳体痛︰天门冬末，酒服方寸匕，日三。忌鲤鱼。（《千金方》）\n天门冬去皮心，煮食。或曝干为末，蜜丸服，尤佳。亦可洗面。（孟诜《食疗》）\n热寝汗，口干引饮，气喘︰天门冬十两，麦门冬八两（并去心为末）。以生地黄三斤，取汁熬膏，和丸梧子大。每服五十丸，以逍遥散去甘草，煎汤下。（《活法机要》）\n耳如蝉鸣，引胁牵痛︰天门冬去心皮，曝捣为末。酒服方寸匕，日三服，久服良。（《外台秘要》）\n面黑令白︰天门冬曝干，同蜜捣作丸。日用洗面。（《圣济总录》）\n门冬、麦门冬（并去心）、玄参等分。为末，炼蜜丸弹子大。每噙一丸，乃僧居寮所传方也。（齐德之《外科精义》）\n未效，再服必愈。此祖传经验方也。（虞抟《医学正传》）"},
  "天雄":{o:[],src:["本草纲目"],d:"新三。\n三建汤，治元阳素虚，寒邪外攻，手足厥冷，大小便滑数，小便白浑，六脉沉微，除固冷，扶元气，及伤寒阴毒。用乌头、附子、天雄（并炮裂去皮脐）等分。㕮咀。每服四钱，水二盏，姜十五片，煎八分，温服。（《肘后方》）\n男子失精︰天雄三两（炮），白术八两，桂枝六两，龙骨三两，为散。每酒服半钱。（张仲景《金匮要略》）\n大风恶癞，三月、四月采天雄、乌头苗及根，去土勿洗，捣汁，渍细粒黑豆，摩去皮不落者，一夜取出，晒干又浸，如此七次。初吞三枚，渐加至六七枚。禁房室、猪鱼、鸡、蒜，犯之即死。"},
  "太阴玄精石":{o:["太阴玄精石"],src:["本草备要"],d:"泻热，补阴\n太阴之精，咸寒而降。治上盛下虚，救阴助阳，有扶危拯逆之功（正阳丹，用治伤寒壮热。来复丹，用治伏暑热泻）。出解池、通泰积盐处，咸卤所结，青白莹彻，片皆六棱者良。今世用者，多是绛石。"},
  "女萎":{o:[],src:["本草纲目"],d:"新三。\n下不止︰女萎、云实各一两，川乌头二两，桂心五钱。为末，蜜丸梧子大。每服五丸，水下，一日三服。（《肘后方》）\n身体 疡斑驳︰女葳膏︰用鲁国女葳、白芷各一分，附子一枚，鸡舌香、木香各二分。为末，腊猪脂"},
  "女青":{o:[],src:["本草纲目"],d:"旧三。\n人卒暴死︰捣女青屑一钱，安咽中，以水或酒送下，立活也。（《南岳魏夫人内传》）\n吐利卒死，及大人小儿，卒腹皮青黑赤，不能喘息︰即急用女青末纳口中，酒送下。（《子母秘录》）\n辟禳瘟疫︰正月上寅日，捣女青末，三角绛囊盛，系帐中，大吉。（《肘后方》）"},
  "姜石":{o:[],src:["本草纲目"],d:"旧二，新二。\n疔疮肿痛︰白姜石末，和鸡子清敷之，干即易，疗自出，神效。（崔氏方）乳痈肿大如碗肿痛︰方同上。（《外台秘要》）\n产后胀冲气噎︰ KT 石、代赭石等分，为末，醋糊丸梧子大。每服三、五十丸，醋汤下。（洁古《保命集》）\n通身水肿︰姜石烧赤，纳黑牛尿中，热服，日饮一升。（《千金方》）"},
  "孔公孽":{o:[],src:["本草纲目"],d:"新一。\n风气脚弱︰孔公 二斤，石斛五两，酒二斗，浸服。（《肘后方》）"},
  "孩儿茶":{o:["孩儿茶"],src:["本草备要"],d:"泻热，生津，涩，收湿\n苦涩、清上膈热，化痰生津，止血收湿，定痛生肌。涂金疮口疮（硼砂等分），阴疳痔肿。出南番，云是细茶末。纳竹筒，埋土中，日久取出，捣汁熬成。块小、润泽者上，大而枯者次之。"},
  "守宫":{o:[],src:["本草纲目"],d:"新十四。\n小儿脐风︰用壁虎后半截焙为末，男用女乳，女用男乳，调匀，入稀鸡矢少许，掺舌根及牙关。仍以手蘸摩儿，取汗出，甚妙。（笔峰《杂兴方》）\n（剪去四足，连血研烂），入珍珠、麝香、龙脑香各一字，研匀，以薄荷汤调服。仍先或吐或下去痰涎，而后小儿撮口︰用朱砂末安小瓶内，捕活蝎虎一个入瓶中，食砂末月余，待体赤，阴干为末。\n每薄荷汤服三、四分。（方广《附余》）\n末少许，薄荷汤调服。继服二陈汤，神效。（《仁斋直指》）\n瘫痪走痛︰用蝎虎（即 蜓）一枚（炙黄），陈皮五分，罂粟壳（蜜炒）一钱，甘草、乳香、没药各二钱半，为末。每服水煎服。（《医学正传》）\n包，煨研），地龙五条（生研），草乌头三枚（生研），木香五钱，乳香末二钱龙脑五分，合研成膏。入酒糊捣，丸如梧桐子大。每日空心乳香酒服三十丸，取效。（《总录》）\n破伤中风︰身如角弓反张，筋急口噤者，用守宫丸治之。守宫（炙干去足）七枚，天南星（酒浸三日晒干）一两，腻粉半钱，为末，以薄面糊丸绿豆大。每以七丸，酒灌下，少顷汗出得解，更与一服，再汗即瘥。或加白附子一两，以蜜丸。（《用东行蝎虎一条（焙干），大蚕砂五升（水淘炒）。各为末，以小麦面四升，拌作络索，曝干研末。每服一二合，煎柏叶汤下，日三服，取效。（研。每日服半分，酒服。（《作饼瘦、下痢，证候全备，及无辜疳毒，如邪病者。用干雄蝎虎一个（微炙），蜗牛壳、兰香根、靛花、雄黄、麝香各一分，龙脑半分，各研为末，米醋煮糊丸黍米大。每脂麻汤下十丸，日二服，取效。（《奇效良方》）\n每以一星敷上即止，神效。（《青囊》）\n反胃膈气︰地塘虫（即壁虎也）七个（砂锅炒焦），木香、人参、朱砂各一钱半，乳香一钱。为末，蜜丸梧子大。每服七丸，木香汤下，早晚各一服。\n《\n粪\n\n新一。\n胎赤烂眼昏暗︰用蝎虎数枚，以罐盛黄土按实，入蝎虎在内，勿令损伤。以纸封口，穿数孔出气。候有粪数粒，去粪上一点黑者，只取一头白者，唾津研成膏，涂眼睫周回，不得揩拭。来早以温浆水洗三次，甚效。（《圣济总录》）"},
  "密陀僧":{o:["密陀僧"],src:["本草备要", "本草纲目"],d:"重，镇惊，劫痰，消积\n辛咸小毒。感银铅之气而结。坠痰镇惊，止血散肿，消积杀虫，疗肿毒，愈冻疮（用桐油调敷），解狐臭（油调搽腋。以馒头蒸热劈开，掺末夹腋下亦佳），染髭须。出银坑难得，今用者乃倾银 底。入药煮一伏时。"},
  "小青":{o:[],src:["本草纲目"],d:"新三。\n蛇虺螫伤︰《卫生易简方》︰用小青一握（细研），入香白芷半两。酒调服。手 患处，候黄水出为效。《摘玄方》︰用小青、大青、牛膝叶同捣汁，和酒服，以渣敷之。中暑发昏︰小青叶（井水浸去泥），控干，入沙糖擂汁，急灌之。（《寿域方》）"},
  "小麦":{o:["小麦"],src:["本草备要"],d:"补\n味甘微寒。养心除烦，利溲止血（李时珍曰∶《素问》麦属火，心之谷也；郑玄谓属木；许慎谓属金；《别录》云养肝，与郑说合；孙思邈云养心，与《素问》合，当以《素问》为准。按∶麦，秋种夏熟，备受四时之气。南方地暖下湿，不如北产者良。张仲景治妇人脏躁证，悲伤欲绝，状若神灵，用甘麦大枣汤。大枣十枚，小麦一升，甘草一两，每服一两，亦补脾气。《圣惠方》∶小麦饭治烦热。少睡，多渴）。面粉甘温。补虚养气，助五脏，浓肠胃，然能壅气作渴，助湿发热。陈者良（寒食日，纸袋盛，悬风处，名寒食面，年久不热，入药尤良）。浮小麦（即水淘浮起者）咸凉。止虚汗盗汗，劳热骨蒸（汗为心液，麦为心谷，浮者无肉，故能凉心。麦麸同功）。麦麸醋拌蒸，能散血止痛，熨腰脚折伤，风湿痹痛，寒湿香港脚，互易至汗出良（麦之凉，全在皮，故面去皮即热，凡疮疡痘疮溃烂不能着席者，用麦麸装褥卧，性凉而软，诚妙法也）。"},
  "屋游":{o:[],src:["本草纲目"],d:"新一。\n犬咬︰旧屋瓦上刮下青苔屑，按之即止。（《经验方》）"},
  "山柰":{o:["山柰"],src:["本草备要", "本草纲目"],d:"宣，温中，辟恶\n辛温。暖中辟恶。治心腹冷痛，寒湿霍乱，风虫牙痛。生广中，据叶皆如生姜，入合诸香用。"},
  "山茶花":{o:["山茶花"],src:["本草备要"],d:"泻，凉血\n甘微辛寒。色赤，入血分。治吐衄肠风。麻油调末，涂汤火伤。用红者为末，入童便、姜汁、酒调服，可代郁金。"},
  "山豆根":{o:["山豆根"],src:["本草备要", "本草纲目"],d:"泻热，解毒\n苦寒。泻心火以保金气，去肺，大肠之风热（心火降，则不灼肺而金清。肺与大肠相表里，肺金清，则大肠亦清），消肿止痛。治喉痈喉风，龈肿齿痛（含之咽汁），喘满热咳，腹痛下痢，五痔诸疮。解诸药毒，敷秃疮、蛇狗蜘蛛伤，疗人、马急黄（血热极所致）。苗蔓如豆，经冬不凋。"},
  "常山":{o:["常山"],src:["本草备要"],d:"宣，吐痰，截疟，通，行水\n辛苦而寒，有毒。能引吐行水，祛老痰积饮（痰有六∶风痰、寒痰、湿痰、热痰、食痰、气痰也。饮有五，流于肺为支饮，于肝为悬饮，于心为伏饮，于经络为溢饮，于肠胃为痰饮也。常山力能吐之，下之），专治诸疟。然悍暴能损真气，弱者慎用（时珍曰∶常山蜀漆，韧痰截疟，须在发散表邪及提出阳分之后用之。疟有经疟、脏疟、风、寒、暑、湿、痰、食、瘴、鬼之别，须分阴、阳、虚、实，不可概论。常山蜀漆，得甘草则吐，得大黄则利，得乌梅、穿山甲则入肝，得小麦、竹叶则入心，得秫米、麻黄则入肺，得龙骨、附子则入肾，得草果、槟榔则入脾。盖无痰不作疟，一物之功，亦在驱逐痰水而已。李士材曰∶常山发吐，唯生用、多用为然。与甘草同用亦必吐。若酒浸炒透，但用钱许，每见奇功，未见其或吐也。世人泥于雷 老人久病忌服之说，使良药见疑，沉 难起，抑何愚也。常山吐疟痰，瓜蒂吐热痰，乌附尖吐湿痰，莱菔子吐气痰，藜芦吐风痰）。鸡骨者良。酒浸蒸或炒用。栝蒌为使。忌葱、茗。茎叶名蜀漆，功用略同（古方有蜀漆散，取其苗性轻扬，发散上焦邪结）。甘草水拌蒸。"},
  "常山、蜀漆":{o:[],src:["本草纲目"],d:"旧三，新二十五。截疟诸汤︰《外台秘要》︰用常山三两，浆水三升，浸一宿，煎取一升，欲发前顿服，取吐。\n《肘后方》︰用常山一两，秫米一百粒，水六升，煮三升，分三服。先夜、未发、临发时服尽。《养生主论》︰王隐者驱疟汤云︰予用此四十年，奇效不能尽述，切勿加减，万无一吐者。常山（酒煮晒干）、知母发前服。少顷再云︰乃桂广州方也，甚验。恒山一钱二分，大黄二钱半，炙甘草一钱二分。水一盏半，煎减半，曰醇，发日五更温服；再以水一盏，煎减半，曰治久疟不止。常山一钱半，槟榔一钱，丁香五分，乌梅一个，酒一盏，浸一宿，五更饮之。一服便止，永不再发，如神。以来者，一剂瘥。恒山三两，研末，鸡子白和丸梧子大，瓦器煮熟，杀腥气，则取晒干收之。每服二十丸，竹叶汤下，五更一服，天明一服，发前一服，或吐或否即止。《肘后》丹砂丸︰恒山（捣末）三两，真丹一两研，白蜜和杵百下，丸梧子大。先发服三丸，少顷再服三丸，临时服三丸，酒下，无两，乌梅（连核瓦焙）一两，为末，糯米粉糊丸梧子大。每服三、五十丸，凉酒下，隔一夜一服，平旦一服。午后方食。葛洪《肘后方》︰用恒山三两，知母一两，甘草半两，捣末，蜜丸梧子大。先发时服十丸，次服七丸，后服五六丸，以瘥为度。《和剂局方》瞻仰丸︰治一切疟。常山四两（炒存性），草果二两（炒存性）。为末，薄糊丸梧子大。每卧时冷酒服五十丸，五更再服。忌鹅羊热物。又胜金丸︰治一切疟，胸膈停痰，发不愈者。常山八两（酒浸蒸焙），槟榔二两（生）。研末，糊丸梧子大。如上法服。《集简方》二圣丸︰治诸疟，不拘远近大小。鸡骨恒山、鸡心槟榔各一两（生研），鲮鲤甲（煨焦）一两半。为末，糯粉糊丸绿豆大，黄丹为衣。每服三、五十丸，如上法服。厥阴肝疟，寒多热少，喘息如死状，或少腹满，小便如脓，不问久近，不吐不泄，如神︰恒山一两，醋浸一夜，瓦器煮干。每用二钱，水一盏，煎半盏，五更冷服。（赵真人《济急方》）\n太阴肺疟，痰聚胸中，病至令人心寒，寒甚乃热，热间善惊，如有所见︰恒山三钱，甘草半钱，秫米三十五粒，水二钟，煎一钟，发日早分三次服。（《千金方》）\n少阴肾疟，凄凄然寒，手足寒，腰脊痛，大便难，目 然。恒山二钱半，豉半两，乌梅一钱，竹叶一钱半，葱白三根，水一升半，煎一升，发前分三服。（《千金方》）\n牝疟独寒不热者︰蜀漆散︰用蜀漆、云母（ 三日夜）、龙骨各二钱。为末。每服半钱，临发日旦一服，发前一服，酢浆水调下。温疟，又加蜀漆一钱。（张仲景《金匮要略》）\n牡疟独热不冷者。蜀漆一钱半，甘草一钱，麻黄二钱，牡蛎粉二钱。水二钟，先煎麻黄、蜀漆，去沫，入药再煎至一钟，未发前温服，得吐则止。（王焘《外台秘要》）\n温疟热多︰恒山一钱，小麦三钱，淡竹叶二钱。水煎，五更服，甚良。（《药性论》）\n三十年疟︰《肘后方》︰治三十年老疟及积年久疟︰常山、黄连各一两。酒三升，渍一宿，以瓦釜煮取一升半。发日早服五合，发时再服。热当吐，冷当利，无不瘥者。张文仲《备急方》︰用恒山一两半，龙骨五钱，附子（炮）二钱半，大黄一两。为末，鸡子黄和丸梧子大。未发时五丸，将发时五丸，白汤下。支太医云︰此方神验，无不断者。方》︰常山一寸，草果一枚，热酒一碗，浸一夜，五更望东服之，盖卧，酒醒即愈。《谈野翁试验方》︰用常山、槟榔、甘草各二钱，黑豆一百粒，水煎服之。乃彭司寇所传。葛稚川《肘后方》︰用常山、黄连、香豉各一两，附子（炮）七钱，捣末，蜜丸梧子大。空腹饮服四丸，欲发时三丸。至午后乃食。妊娠疟疾︰酒蒸常山、石膏（煅）各一钱，乌梅（炒）五分，甘草四分。水一盏，酒一盏，浸一夜，平旦温服。（姚僧坦《集验方》）\n寒热攻，直须术治免成空。常山刻作人形状，钉在孩儿生气宫。如金生人，金生在巳，即钉巳上；木生人，钉亥上；火生人，钉寅上；水土生人，钉申上也。二钱，左顾牡蛎一钱二分，浆水煎服，当吐痰而愈。名千金汤。（阮氏）胸中痰饮︰恒山、甘草各一两，水五升，煮取一升，去滓，入蜜二合。温服七合，取吐。不吐更服。（《千金方》）"},
  "常春藤":{o:[],src:["本草纲目"],d:"新二。\n疔疮黑凹︰用发绳扎住，将尖叶薜荔捣汁，和蜜一盏服之。外以葱、蜜捣敷四围。（《圣惠方》）\n衄血不止︰龙鳞薜荔，研水饮之。（《圣济录》）"},
  "庵䕡":{o:[],src:["本草纲目"],d:"旧一，新二。\n月水不通，妇人宿有风冷，留血积聚，月水不通︰庵 子一升，桃仁二升（酒浸去皮尖）。研匀入瓶内，以酒二斗浸，封五日后，每饮三合，日三服。（《圣惠方》）\n产后血痛︰庵 子一两。水一升，童子小便二杯，煎饮。（《频湖集简方》）"},
  "庵子":{o:["庵子"],src:["本草备要"],d:"泻，行水，散血\n苦辛微寒（《别录》微温）。入肝经血分。行水散血，散中有补。治阳痿经涩，腰、膝、骨节重痛，产后血气作痛，闪锉折伤（扑打方多用之）。能制蛇（见之则烂）。叶似菊而薄，茎似艾而粗。薏苡为使。"},
  "律草":{o:[],src:["本草纲目"],d:"旧三，新六。\n小便石淋︰葛 掘出根，挽断，以杯于坎中承取汁。服一升，石当出。不出更服。（《范汪方》）\n小便膏淋︰ 草，捣生汁三升，酢二合，合和顿服，当尿下白汁。\n尿血淋沥︰同上。产妇汗血，污衣赤色︰方同上。\n久痢成疳︰葛勒蔓末，以管吹入肛门中，不过数次，如神。\n新久疟疾︰用葛 草一握（一名勒蔓，去两头，秋冬用干者）、恒山末等分。以淡浆水二大盏，浸药，星月下露一宿，遍体癞疮︰ 草一担。以水二石，煮取一石，渍之。不过三作愈。（并韦宙《独行方》）\n乌癞风疮︰葛 草三秤（切洗），益母草一秤（切）。以水二石五斗，煮取一石五斗，去滓入瓮中，浸浴一时方出，坐密室中，又暖汤浴一时，乃出，暖卧取汗，勿令见风。明日又浴。如浴时瘙痒不可忍，切勿搔动，少顷渐定。后隔三日一作，以愈为度。（《圣济录》）"},
  "徐长卿":{o:[],src:["本草纲目"],d:"新二。\n小便关格：徐长卿汤：治气壅关格不通，小便淋结，脐下妨闷。徐长卿（炙）半两，茅根三分，木通、冬葵子一两，滑石二两，槟榔一分，瞿麦穗半两。每服五钱，水煎，入朴硝一钱，温服，日二服。（《圣惠方》）\n注车注船：凡人登车船烦闷，头痛欲吐者。宜用徐长卿、石长生、车前子、车下李根皮各等分。捣碎，以方囊系半合于衣带及头上，则免此患。（《肘后方》）"},
  "御米壳":{o:["御米壳"],src:["本草备要"],d:"（即罂粟壳）\n涩肠，敛肺，固肾酸涩微寒。敛肺涩肠而固肾。治久嗽泻痢，遗精脱肛，心腹筋骨诸痛（东垣曰∶收涩固气，能入肾，故治骨病尤宜），嗽、痢初起者忌用（丹溪曰∶此是收后药，要先除病根）。一名丽春花，红黄紫白，艳丽可爱。凡使壳，洗去蒂及筋膜，取薄皮。醋炒或蜜炒用（性紧涩，不制多令人吐逆）。得醋、乌梅、陈皮良。罂中有米极细，甘寒润燥，煮粥食，治反胃（加参尤佳）。"},
  "忍冬":{o:[],src:["本草纲目"],d:"旧一，新十七。\n忍冬酒︰治痈疽发背，不问发在何处，发眉发颐，或头或项，或背或腰，或胁或乳，或手足，皆有奇效。乡落之间，僻陋之所，贫乏之中，药材难得，但虔心服之，俟其疽破，仍以神异膏贴之，其效甚妙︰用忍冬藤（生取）一把，以叶入砂盆研烂，入生饼子酒少许，稀稠得所，涂于四围，中留一口泄气。其藤只用五两（木槌槌损，不可犯铁），大甘草节（生用）一两。同入沙瓶内，以水二碗，文武火慢煎至一碗，入无灰好酒一大碗，再煎十数沸，去滓分为三服，一日一夜吃尽。病势重者，一日二剂。服至大小肠通利，则药力到。沈内翰云︰如无生者，只用干者，然力终不及生者效速。（陈自明《外科精要》）\n忍冬圆︰治消渴愈后，预防发痈疽，先宜服此︰用忍冬草根、茎、花、叶皆可，不拘多少。入瓶内，以无灰好酒浸，以糠火煨一宿，取出晒干，入甘草少许，碾为细末，以浸药酒打面糊，丸梧子大。每服五十丸至百丸，汤酒任下。此药不特治痈疽，大能止渴。（《外科精要》）\n五痔诸 ︰方同上。\n一切肿毒，不问已溃未溃，或初起发热︰用金银花（俗名甜藤，采花连茎叶）自然汁半碗。煎八分，服之，以滓敷上。败毒托里，散气和血，其功独胜。（万表《积善堂方》）\n疔疮便毒︰方同上。\n喉痹乳蛾︰方同上。\n敷肿拔毒︰金银藤（大者，烧存性）、叶（焙干为末）各三钱，大黄（焙为末）四钱。\n凡肿毒初发，以水酒调搽四围，留心泄气。（杨诚《经验方》）\n痈疽托里，治痈疽发背，肠痈奶痈，无名肿毒， 痛寒热，状类伤寒，不问老幼虚实服之，未成者内消，已成者即溃︰忍冬叶、黄 各五两，当归一两，甘草八钱。为细末。每服二钱，酒一盏半，煎一盏，随病上下服，日再服，以渣敷之。（《和剂局方》）\n恶疮不愈︰左缠藤一把（捣烂），入雄黄五分。水二升，瓦罐煎之，以纸封七重，穿一孔，轻粉毒痈︰方同上。\n疮久成漏︰忍冬草浸酒，日日常饮之。（戴原礼《要诀》）\n热毒血痢︰忍冬藤浓煎饮。（《圣惠方》）\n五种尸注︰飞尸者，游走皮肤，洞穿脏腑，每发刺痛，变动不常也。遁尸者，附骨入肉，攻凿血脉，每发不可见死尸，闻哀哭便作也。风尸者，淫跃四末，不知痛之所在，每发恍惚，得风雪便作也。沉尸者，缠结脏腑，冲引心胁，每发绞切，遇寒冷便作也。尸注者，举身沉重，精神错杂，常觉昏废，每节气至则大作也。并是身中尸鬼，引接外邪︰宜用忍冬（茎叶，锉）数斛，煮取浓汁煎稠。每服鸡子大许，温酒化下，一日二、三服。（《肘后方》）\n鬼击身青作痛︰用金银花一两。水煎饮之。（李楼《怪病奇方》）\n脚气作痛，筋骨引痛︰鹭鸶藤（即金银花）为末。每服二钱，热酒调下。（《卫生易简方》）\n中野菌毒︰急采鸳鸯藤啖之，即今忍冬草也。（洪迈《夷坚志》）\n口舌生疮︰赤梗蜜桶藤、高脚地铜盘、马蹄香等分，以酒捣汁，鸡毛刷上，取涎出即愈。（《普济方》）\n忍冬膏，治诸般肿痛，金刃伤疮恶疮︰用金银藤四两，吸铁石三钱。香油一斤，熬枯去滓"},
  "急流水":{o:["急流水"],src:["本草备要"],d:"通\n性速而趋，下通二便，风痹药宜之（昔有病小便闭者，众不能瘥。张子和易以急流之水，煎前药一饮而溲。时珍曰∶天下之水，灭火濡枯则同。至于性从地变，质与物迁者，未尝同也）。"},
  "恶实":{o:[],src:["本草纲目"],d:"旧四，新十二。\n风水身肿欲裂︰鼠粘子二两，炒研为末。每温水服二钱，日三服。（风热浮肿，咽喉闭塞︰牛蒡子一合（半生半熟），为末。热酒服一寸匕痰厥头痛︰牛蒡子（炒）、旋复花等分，为末。腊茶清服一钱，日二服头痛连睛︰鼠粘子、石膏等分，为末，茶清调服。（《医方摘要》）\n咽膈不利，疏风壅，涎唾多︰牛蒡子（微炒）、荆芥穗各一两，炙甘草半两，为末。食后汤服二钱，当缓缓取效。（寇氏《本草衍义》）\n悬痈喉痛，风热上抟也。恶实（炒）、甘草（生）等分，水煎含咽，名启关方》）\n喉痹肿痛︰牛蒡子六分，马蔺子八分，为散。每空心温水服方寸匕，日再服。仍以牛蒡子三两，盐二两，研匀，炒热包熨喉外。（《广济方》）\n咽喉痘疹︰牛蒡子二钱，桔梗一钱半，粉甘草节七分，水煎服。（《痘风热瘾疹︰牛蒡子（炒）、浮萍等分，以薄荷汤服二钱，日二服。（初虞世《古今录验》）\n风龋牙痛︰鼠粘子（炒），煎水含，冷吐之。（《延年方》）\n小儿痘疮，时出不快，壮热狂躁，咽膈壅塞，大便秘涩，小儿咽喉肿，胸膈不利︰若大便利者，勿服。牛蒡子（炒）一钱二分，荆芥穗二分，甘草节四分。水一盏，同煎至七分，温服。已出亦可服。名必胜散。（《和剂局方》）\n妇人吹乳︰鼠粘二钱，麝香少许，温酒细吞下。（《袖珍方》）\n便痈肿痛︰鼠粘子二钱，炒研末，入蜜一匙，朴硝一匙，空心温酒服。（《袖珍方》）\n蛇蝎蛊毒︰大力子，煮汁服。（《卫生易简方》）\n水蛊腹大︰恶实（微炒）一两，为末，面糊丸梧子大，每米饮下十丸。（张文仲方）\n历节肿痛，风热攻手指，赤肿麻木，甚则攻肩背两膝，遇暑热则大便秘︰牛蒡子三两，新豆豉（炒）、羌活各一两，为末。每服二钱，白汤下。（《本事方》）\n根、茎\n\n旧五，新一十六。时气余热不退，烦躁发渴，四肢无力，不能饮食︰用牛蒡根捣汁，服一小盏，效。（《圣惠方》）\n天行时疾︰生牛蒡根，捣汁五合，空腹分为二服。服讫，取桑叶一把，炙黄，以水一升，煮取五合，顿服取汗，无叶用枝。（孙真人《食忌》）\n热攻心烦恍惚︰以牛蒡根（捣汁）一升，食后分为二服。（《食医心镜》）\n伤寒搐搦，汗后覆盖不密，致腰背手足搐搦者，牛蒡根散主之︰牛蒡根十条，麻黄、牛膝、天南星各六钱锉，于盆内研细，好酒一升同研，以新布绞取汁。以炭火半秤烧一地坑令赤，扫净，倾药汁入坑内，再烧令黑色，取出于乳钵内细研。每服一钱，温酒下，日三服。（朱肱《活人书》）\n一切风疾十年、二十年者︰牛蒡根一升，生地黄、枸杞子、牛膝各三升，用袋盛药，浸无灰酒三升内，每任意饮之。（《外台秘要》方）\n老人中风，口目 动，烦闷不安。牛蒡根（切）一升（去皮晒干，杵为面），白米四合（淘净）。和作 ，豉汁中煮，加葱、椒五味，空心食之。恒服极效。（《寿亲养老书》）\n老人风湿久痹，筋挛骨痛。服此壮肾，润皮毛，益气力︰牛蒡根一升（切），生地黄一升（切），大豆二升（炒），以绢袋盛，浸一斗酒中，五六日，任性空心温服二、三盏，日二服。（《集验方》）\n头面忽肿，热毒风气内攻，或连手足赤肿，触著痛者︰牛蒡子根（一名蝙蝠刺），洗净研烂，酒煎成膏，绢摊贴肿处。仍以热酒服一、二匙，肿消痛减。（《斗不可禁者，摩膏主之︰取牛蒡茎叶，捣取浓汁二升，无灰酒一升，盐花一匙头， 火煎稠成膏，以摩痛处，风毒自散。摩时须极力令热，乃效。冬月用根。（《箧中方》）\n头风白屑︰牛蒡叶捣汁，熬稠涂之。至明，皂荚水洗去。（《圣惠方》）\n喉中热肿︰鼠粘根一升，水五升，煎一升，分三服。（《延年方》）\n小儿咽肿︰牛蒡根捣汁，细咽之。（《普济方》）\n热毒牙痛，热毒风攻头面，齿龈肿痛不可忍︰牛蒡根一斤（捣汁），入盐花一钱。银器中熬成膏。每用涂齿龈上，重者不过三度，瘥。（《圣惠方》）\n项下瘿疾︰鼠粘子根一升。水三升，煮取一升半，分三服。或为末，蜜丸常服之。（《救急方》）\n小便不通，脐腹急痛︰牛蒡叶汁、生地黄汁二合，和匀，入蜜二合。每服一合，入水半盏，煎三五沸，调滑石末一钱服。（《圣济总录》）\n疖子肿毒︰鼠粘子叶贴之。（《千金方》）\n石 出脓，坚实寒热︰鼠粘子叶为末，和鸡子白封之。（《外台秘要》）\n诸疮肿毒︰牛蒡根三茎（洗）。煮烂捣汁，入米煮粥，食一碗，甚良。（《普济方》）\n积年恶疮，反花疮、漏疮不瘥者。牛蒡根捣，和腊月猪脂，日日封之。（《千金方》）\n月水不通，结成症块，腹肋胀大，欲死︰牛蒡根二斤（锉）。蒸三遍，以生绢袋盛之，以酒二斗浸五日，每食前温服一盏。（《普济方》）"},
  "悬钩子":{o:[],src:["本草纲目"],d:"新二。\n血崩不止︰木莓根四两，酒一碗，煎七分。空心温服。（ 仙《乾坤生意》）\n治妇人崩中及下痢，日夜数十起欲死者，以此入腹即活︰悬钩根、蔷薇根、柿根、菝 各一斛，锉入釜中，水淹上四、五寸，煮减三之一，去滓取汁，煎至可丸，丸梧子大。每温酒服十丸，日三服。（《千"},
  "戎盐":{o:[],src:["本草纲目"],d:"新五。\n小便不通︰戎盐汤︰用戎盐（弹丸大）一枚，茯苓半斤，白术二两。水煎，服之。（仲景《金匮方》）\n风热牙痛︰青盐一斤，槐枝半斤。水四碗，煎汁二碗，煮盐至干，炒研。日用揩牙、洗目。（唐氏《经验方》）\n牢牙明目︰青盐二两，白盐四两，川椒四两。煎汁拌盐炒干。日用揩牙洗目，永无齿疾、目疾。（《通变要法》）\n风眼烂弦︰戎盐化水，点之。（《普济方》）\n痔疮漏疮︰白矾四两，青盐四两。为末，猪尿脬一个盛之，阴干。每服五钱，空心温水下。（赵氏《经验方》）"},
  "扁青":{o:[],src:["本草纲目"],d:"新一。\n顽痰不化︰石青一两，石绿半两，并水飞为末，面糊丸绿豆大。每服十丸，温水下。吐去痰一、二碗，不损人。（《瑞竹堂方》）"},
  "旋花":{o:[],src:["本草纲目"],d:"旧一，新一。\n被斫断筋︰旋葍根捣汁，沥疮中，仍以滓敷之，日三易。半月即断筋便续。此方出苏景中家獠奴，用效。（王焘《外台秘要》）\n秘精益髓︰太乙金锁丹︰用五色龙骨五两，复盆子五两，莲花蕊四两（未开者，阴干），鼓子花三两（五月五日采之），鸡头子仁一百颗。并为末。以金樱子二百枚，去毛，木水七升，煎浓汁一升，去渣。和药，杵二千下，丸梧子大。每空心温盐酒下三十丸。服之至百日，永不泄。如要泄，以冷水调车前末半合服之。忌葵菜。（萨谦斋《瑞竹堂方》）"},
  "无名异":{o:["无名异"],src:["本草备要", "本草纲目"],d:"重，和血，行伤\n咸入血，甘补血。治金疮折伤，痈疽肿毒（醋磨涂），止痛生肌（人受杖时，须服三五钱，不甚痛伤）。生川广。小黑石子也，一包数百枚。"},
  "旱莲草":{o:["旱莲草"],src:["本草备要"],d:"（一名鲤肠，又名金陵草）\n补肾甘咸，汁黑。补肾止血，黑发乌髭（《千金》云∶当及时多收，其效甚速。《经疏》云∶性凉不益脾胃，故《千金方》金陵煎丸用姜汁和剂）。苗如旋复，实似莲房，断之有计，须臾而黑。熬膏良。"},
  "昨叶何草":{o:[],src:["本草纲目"],d:"旧一，新九。\n小便沙淋︰瓦松（即屋上无根草），煎浓汤乘热熏洗小腹，约两时即通。（《经验良方》）。\n通经破血︰旧屋阴处瓦花（活者）五两（熬膏），当归须、干漆一两（烧烟尽），当门子二钱。为末，枣肉和丸梧子大。每服七十丸，红花汤下。（《摘玄方》）。\n染乌髭发︰干瓦松一斤半，生麻油二斤，同煎令焦，为末。另以生麻油浸涂，甚妙。（《圣济录》）。\n头风白屑︰瓦松曝干，烧灰淋汁热洗，不过六、七次。（《圣惠方》）。\n牙龈肿痛︰瓦花、白矾等分，水煎。漱之立效。（《摘玄方》）。\n唇裂生疮︰瓦花、生姜，入盐少许，捣涂。（《摘玄方》）。\n汤火灼伤︰瓦松、生柏叶，同捣敷。干者为末。（《医方摘要》）。\n灸疮不敛︰瓦松，阴干为末。先以槐枝、葱白汤洗，后掺之。立效。（《济生秘览》）。\n恶疮不敛︰方同上。\n风狗咬伤︰瓦松、雄黄，研贴，即不发。（《生生编》）"},
  "景天":{o:[],src:["本草纲目"],d:"旧四，新五。\n惊风烦热︰慎火草煎水浴之。（《普济方》）。\n小儿中风︰汗出中风，一日头颈腰背热，二日即腹热，手足不屈。用慎火草（干者）半两，麻\n婴孺风疹︰在皮肤不出，及疮毒。取慎火苗叶五大两，和盐三大两，同研绞汁。以热手摩涂，日再上之。（《图经》）。热毒丹疮 《千金》︰用慎火草捣汁拭之。日夜拭一、二十遍。一方︰入苦酒捣泥涂之。\n杨氏《产乳》︰治烟火丹毒，从两股两胁起，赤如火。景天草、真珠末一两，捣如泥。涂之，干则易。\n漆疮作痒︰挼慎火草涂之。（《外台》）。\n眼生花翳，涩痛难开。景天捣汁，日点三、五次。（《圣惠》）。\n产后阴脱︰慎火草一斤（阴干），酒五升，煮汁一升，分四服。（《子母秘录》）。\n花"},
  "曼陀罗花":{o:[],src:["本草纲目"],d:"新三。\n面上生疮︰曼陀罗花，晒干研末。少许贴之。（《卫生易简方》）\n小儿慢惊︰曼陀罗花七朵（重一字），天麻二钱半，全蝎（炒）十枚，天南星（炮）、丹砂、乳香各二钱半，为末。每服半钱，薄荷汤调下。（《御药院方》）\n大肠脱肛︰曼陀罗子（连壳）一对，橡斗十六个，同锉，水煎三五沸，入朴硝少许，洗之。（《儒门事亲》）"},
  "曾青":{o:[],src:["本草纲目"],d:"新三。\n斑疮入目不退者︰曾青一钱，丹砂二钱。为末。蛴螬五枚，捣汁和点。（《圣济录》）\n风热目病︰曾青散︰治一切风热毒气上攻，目赤或烂，怕日羞明，隐涩眵泪，或痒或痛。曾青四两，蔓荆子二两，白姜（炮）、防风各一两。为末。每以少许 鼻中，立有功效。（《和剂局方》）\n耳内恶疮︰曾青五钱，雄黄七钱半，黄芩二钱五分。为末，敷之。（《卫生宝鉴》）"},
  "月季花":{o:[],src:["本草纲目"],d:"新一。\n瘰疬未破︰用月季花头二钱，沉香五钱，芫花（炒）三钱，碎锉，入大鲫鱼腹中，就以鱼肠封固，酒、水各一盏，煮熟食之，即愈。鱼须安粪水内游死者方效。此是家传方，活人多矣。"},
  "木槿":{o:["木槿"],src:["本草备要"],d:"泻热\n苦凉。活血润燥。治肠风泻血，痢后热渴。作饮服，令人得睡。川产者治癣疮（癣疮有虫，用川槿皮肥皂水浸，时时搽之，或浸汁磨雄黄尤妙）。用根、皮。"},
  "木耳":{o:[],src:["本草纲目"],d:"新六。\n眼流冷泪︰木耳一两（烧存性），木贼一两，为末。每服二钱，以清米泔煎服。（《惠济方》）。\n血注脚疮︰桑耳、楮耳、牛屎菰各五钱，胎发灰（男用女，女用男）三钱，研末，油和涂之，或干涂之。（《奇效良方》）。\n崩中漏下︰木耳半斤，炒见烟，为末，每服二钱一分，头发灰三分，共二钱四分，以应二十四气。好酒调服，出汗。（孙氏《集效方》）\n新久泄痢︰干木耳一两（炒），鹿角胶二钱半（炒），为末。每服三钱，温酒调下，日二。（《御药院方》）。\n血痢下血︰木耳（炒研）五钱，酒服即可。亦用井花水服。或以水煮盐、醋食之，以汁送下。（《普济方》）。\n一切牙痛︰木耳、荆芥等分，煎汤频漱。（《普济方》）\n桑耳\n\n旧三，新十一。\n少小鼻衄，小劳辄出︰桑耳熬焦捣末，每发时，以杏仁大塞鼻中，数度即可断。（《肘后方》）。\n五痔下血︰桑耳作羹，空心饱食，三日一作。待孔卒痛如鸟啄状，取大、小豆各一升合捣，作两囊蒸之，及热，更互坐之，即瘥。（《外台》）。\n脱肛泻血不止︰用桑黄一两，熟附子一两，为末，炼蜜丸梧子大，每米饮下二十丸。（《圣惠》）。\n血淋疼痛︰桑黄、槲白皮各二钱，水煎服，日一次。（《圣惠方》）。\n月水不断，肉色黄瘦，血竭暂止，数日复发，小劳辄剧，久疾失治者，皆可服之︰桑黄焙研，每服二钱，食前热酒下，日二服。（《普济方》）。\n崩中漏下︰桑耳炒黑为末，酒服方寸匕，日三服取效。（《千金方》）。\n赤白带下︰桑耳切碎，酒煎服。（苏颂《图经》）。\n遗尿且涩︰桑耳为末，每酒下方寸匕，日三服。（《圣济总录》）。\n留饮宿食︰桑耳二两，巴豆一两（去皮），五升米下蒸过，和枣膏捣丸麻子大。每服一、二丸，取利止。（《范汪方》）。\n心下急痛︰桑耳烧存性，热酒服二钱。（《集简方》）。\n瘰疬溃烂︰桑黄菰五钱，水红豆一两，百草霜三钱，青苔二钱，片脑一分，为末，鸡子白调敷，以车前、艾叶、桑皮煎汤洗之。（《纂要奇方》）。\n咽喉痹痛︰五月五日，收桑上木耳，白如鱼鳞者，临时捣碎，绵包弹子大，蜜汤浸，含之立效。（《便民方》）。\n面上黑斑︰桑耳焙研，每食后热汤服一钱，一月愈。（《摘玄方》）。\n足趾肉刺︰先以汤浸，刮去一层，用黑木耳贴之，自消烂不痛。（《近效方》）。\n槐耳\n\n旧三，新三。\n肠痔下血︰槐树上木耳，为末。饮服方寸匕，日三服。（《肘后方》）。\n崩中下血，不问年月远近︰用槐耳烧存性，为末。每服方寸匕，温酒下。（《产宝》方）。\n产后血疼，欲死者︰槐鸡半两为末，酒浓煎饮服，立愈。（《妇人良方》）。\n蛔虫心痛︰槐木耳烧存性，为末，水服枣许。若不止，饮热水一升，蛔虫立出。（张文仲《备急方》）。\n月水不断，劳损黄瘦，暂止复发，小劳辄剧者︰槐蛾（炒黄）、赤石脂各一两，为末，食前热酒服二钱。桑黄亦可。（《圣惠方》）。\n脏毒下血︰槐耳（烧）二两，干漆（烧）一两，为末。每服一钱，温酒下。（《圣济总录》）\n榆耳八月采之。\n\n新一。\n服食方《淮南万毕术》云︰八月榆 ，以美酒渍曝，同青粱米、紫苋实蒸熟为末。每服三指撮，酒下，令人辟谷不饥。\n柳耳\n\n新一。\n反胃吐痰︰柳树蕈五、七个，煎汤服即愈。（《活人心统》）\n柘耳"},
  "木莲":{o:[],src:["本草纲目"],d:"新八。\n惊悸遗精︰木馒头（炒）、白牵牛等分，为末。每服二钱，用米饮调下。 （《乾坤秘韫》）\n阴 囊肿︰木莲（即木馒头），烧研，酒服二钱。又方︰木馒头子、小茴香等分。为末。每空心酒服二钱，取效。（《集简》）\n酒痢肠风︰黑散子︰治风入脏，或食毒积热，大便鲜血，疼痛肛出，或久患酒痢︰木馒头（烧存性）、棕榈皮（烧存性）、乌梅（去核）、粉草（炙）等分。为末。每服二钱，水一盏，煎服肠风下血，大便更涩︰木馒头（烧）、枳壳（炒）等分。为末。每服二钱，槐花酒下。（杨\n《家藏方》）。\n大肠脱下︰木馒头（连皮子切炒）、茯苓、猪苓等分，为末。每服二钱，米饮下。亦治梦遗，名锁阳丹。（《普济方》）\n一切痈疽初起，不问发于何处︰用木莲四十九个。揩去毛，研细，酒解开，温服。功与忍冬草相上下。（陈自明《外科精要》）\n乳汁不通︰木莲二个，猪前蹄一个。烂煮食之，并饮汁尽，一日即通。无子妇人食之，亦"},
  "木贼":{o:["木贼"],src:["本草备要", "本草纲目"],d:"轻，发汗，退目翳\n温微甘苦。中空轻扬，与麻黄同形、性；亦能发汗解肌，升散火郁、风湿，入足厥阴，少阳血分。益肝胆。治目疾，退翳膜（翳乃肝邪郁遏，不能上通于目），及疝痛脱肛，肠风痔 ，赤痢崩中诸血病。"},
  "木鳖子":{o:["木鳖子"],src:["本草备要", "本草纲目"],d:"泻热，外用治疮\n苦温微甘。有小毒，利大肠。治泻痢疳积，瘰 疮痔，乳痈蚌毒。消肿追毒，生肌除 （音旱，黑斑），专入外科。核扁如鳖，绿色。拣去油者，能毒狗。"},
  "本":{o:["本"],src:["本草备要"],d:"宣，去风寒湿\n辛温雄壮，为太阳经（膀胱）风药，寒郁本经、头痛连脑者必用之（凡巅顶痛，宜 本、防风、酒炒升、柴）。治督脉为病，脊强而厥（督脉并太阳经贯脊）；又能下行去湿，治妇人疝瘕，阴寒肿痛，腹中急痛（皆太阳寒湿），胃风泄泻（夏英公病泄，医以虚治不效。霍翁曰∶此风客于胃也，饮以 本汤而愈。盖 本能除风湿耳），粉刺酒 （音查，和白芷作面脂良）。根紫色似芎 而轻虚，气香味麻。"},
  "朴硝":{o:[],src:["本草纲目"],d:"旧十七，新一十五。紫雪︰疗伤寒温疟，一切积热烦热，狂易叫走，瘴疫毒疠，猝死脚气，五尸五疰，心腹诸疾，疠刺切痛，解诸热毒，邪热发黄，蛊毒鬼魅，野道热毒，小儿惊痫百病。黄金一百两，石膏、寒水石、滑石、磁石各三斤。捣碎，水一斛，煮四斗，去滓；入犀角屑、羚羊角、青木香、沉香各五两，玄参（洗焙）、升麻各一斤，甘草（炒）八两，丁香一两，入前汁中煮取一斗五升，去滓；入炼朴硝十斤，硝石三十二两，于药汁中，微火煎之，柳木不住搅，至水气欲尽，倾木盆中。待欲凝，入麝香一两二钱半，朱砂末三两，搅匀，收之。每服一、二钱，凉水服。临时加减，甚者一两。（《和剂局方》）\n红雪︰治烦热，消宿食，解酒毒，开三焦，利五脏，除毒热，破积滞。治伤寒狂躁，胃烂发斑，温瘴脚气，黄胆头痛，目昏鼻塞，口疮喉痹，重舌肠痈等病。用川朴硝十斤（炼去滓），羚羊角（屑）、黄芩、升麻各三两，人参、赤芍药、槟榔、枳壳（麸炒）、生甘草、淡竹叶、木香各二两，木通、栀子、葛根、桑白皮、大青、蓝叶各一两半，苏方木六两。并锉片。水二斗五升，煎至九升，去滓，滤过煎沸；下硝不住手搅，待水气将尽，倾入器中；欲凝，下朱砂一两，麝香半两，经宿成雪。每服一、二钱，新汲水调下。欲行，则热汤化服一两（《和剂方》）\n碧雪︰治一切积热，天行时疾，发狂昏愦，或咽喉肿塞，口舌生疮，心中烦躁，或大小便不通，胃火诸病。朴硝、芒硝、马牙硝、硝石、石膏（水飞）、寒水石（水飞）各一斤，以甘草一斤，煎水五升，入诸药同煎，不住手搅，令硝熔得所；入青黛一斤，和匀，倾盆内，经宿结成雪，为末。每含咽，或吹之，或水调服二、三钱。欲通利，则热水服一两。（《和剂局方》）\n凉膈驱积︰王 山人甘露饮︰治热壅，凉胸膈，驱积滞。蜀芒硝末一大斤。用蜜十二两，冬加一两，和匀，入新竹筒内，半筒以上即止，不得令满。却入炊甑中，令有药处在饭内，其虚处出其上，蒸之。候饭熟取出，绵滤入瓷钵中，竹篦搅勿停手，待凝，收入瓷盒。每卧时含半匙，渐渐咽之。如要通转，即多服之。（刘禹锡《传信方》）\n乳石发动烦闷︰芒硝，蜜水调服一钱，日三服。（《圣惠方》）\n骨蒸热病︰芒硝末，水服方寸匕，日二服良。（《千金方》）\n腹中痞块︰皮硝一两，独蒜一个，大黄末八分。捣作饼。贴于患处，以消为度。（邵氏\n《经验方》）\n食物过饱不消，遂成痞膈︰马牙硝一两，吴茱萸半斤。煎汁投硝，乘热服之。良久未转，更进一服，立效。窦群在常州，此方得效也。（《经验方》）\n关格不通，大小便闭，胀欲死，两三日则杀人。芒硝三两，泡汤一升服，取吐即通。（《百一方》）\n小便不通︰白花散︰用芒硝三钱，茴香酒下。（《简要济众方》）\n时气头痛︰朴硝末二两，生油调涂顶上。（《圣惠方》）\n赤眼肿痛︰朴硝，置豆腐上蒸化，取汁收点。（《简便方》）\n风眼赤烂︰明净皮硝一盏。水二碗煎化，露一夜，滤净澄清。朝夕洗目。三日其红即消，虽半世者亦愈也。（杨诚《经验方》）\n退翳明目︰白龙散︰用马牙硝光净者，浓纸裹实，安在怀内著肉，养一百二十日，研粉，入少龙脑。不计年岁深远，眼生翳膜，远视不明，但瞳人不破散者，并宜日点之。（《经验方》）\n诸眼障翳︰牙硝十两，汤泡汁，浓纸滤过，瓦器熬干，置地上一夜，入飞炒黄丹一两，麝香半分。再罗过，入脑子。日点。（《济急仙方》）\n逐月洗眼︰芒硝六钱。水一盏六分，澄清。依法洗目，至一年，眼如童子也。正月初三，二月初八，三月初四，四月初四，五月初五，六月初四，七月初三，八月初一，九月十三，十月十三，十一月十六，十二月初五日。（《圣惠方》）\n牙齿疼痛︰皂荚浓浆，同朴硝煎化，淋于石上，待成霜。擦之。（《普济方》）\n食蟹龈肿︰朴硝敷之，即消。（《普济方》）\n喉痹肿痛︰《外台》︰用朴硝一两，细细含咽，立效。或加丹砂一钱。气塞不通，加生甘草末二钱半，吹之。小儿重舌︰马牙硝涂于舌上下，日三。（姚和众）口舌生疮︰朴硝含之，良。（孙真人方）\n小儿鹅口︰马牙硝，擦舌上，日五度。（《简要济众》）\n豌豆毒疮未成脓者。猪胆汁和芒硝末涂之。（《梅师》）\n代指肿痛︰芒硝煎汤渍之。（《圣惠方》）\n火焰丹毒︰水调芒硝末涂之。（《梅师》）\n一切风疹︰水煮芒硝汤拭之。（《梅师》）\n漆疮作痒︰芒硝汤，涂之。（《千金》）\n灸疮飞蝶︰因艾灸火疮痂退落，疮内鲜肉片子，飞如蝶状，腾空飞去，痛不可言，是血肉俱热，怪病也。用朴硝、大黄各半两。为末。水调下，微利即愈。（夏子益《奇疾方》）\n妇人难产︰芒硝末二钱，童子小便温服，无不效者。（《信效方》）\n死胎不下︰方同上。丰城曾尉有猫孕五子，一子已生，四子死腹中，用此灌之即下。又治一牛亦下。（《信效方》）\n女人扎足︰脱骨汤︰用杏仁一钱，桑白皮四钱。水五碗，新瓶煎三碗，入朴硝五钱，乳香一钱，封口煎化。置足于上，先熏后洗。三日一作，十余次后，软若束绵也。（《闺阁事宜》）\n风化硝"},
  "杉木":{o:["杉木"],src:["本草备要"],d:"宣，散肿胀\n辛温。去恶气，散风毒。治香港脚肿痛，心腹胀满，洗毒疮（柳子浓纂《救死方》云∶得香港脚夜半痞绝，胁块如石，昏困且死。郑洵美传杉木汤，食顷大下，块散气通。用杉木节一升，橘叶一升，无叶以皮代，大腹槟榔七枚，连子槌碎，童便三升煮，分二服。若一服得快利，即停后服）。有赤、白二种，赤、油斑如野鸡者，作棺尤贵。性直，烧炭最发火药。"},
  "杜衡":{o:[],src:["本草纲目"],d:"新六。风寒头痛：伤风伤寒，头痛发热，初觉者。马蹄香为末，每服一钱，热酒调下，少顷饮热茶一碗，催之出汗即愈，名香汗散。（王英《杏林摘要》）\n饮水停滞：大热行极，及食热饼后，饮冷水过多不消，停滞在胸不利，呼吸喘息者。杜衡三分，瓜蒂二分，人参一分。为末。汤服一钱，日二服，取吐为度。（《肘后方》）\n痰气哮喘：马蹄香焙研，每服二、三钱，正发时淡醋调下，少顷吐出痰涎为验。（《普济方》）\n噎食膈气：马蹄香四两。为末，好酒三升，熬膏。每服二匙，好酒调下，日三服。（孙氏《集效方》）\n吐血瘀聚：凡吐血后，心中不闷者必止；若烦躁闷乱刺胀者，尚有瘀血在胃，宜吐之。方同饮水停滞。喉闭肿痛：草药金锁匙，即马蹄草，以根捣，井华水调下即效。（《救急方》）"},
  "松节":{o:["松节"],src:["本草备要"],d:"燥湿，去风\n松之骨也，坚劲不凋，故取其苦温之性，以治骨节间之风湿（丹溪曰∶能燥血中之湿）。杵碎浸酒良（史国公药酒中用之）。松脂 苦甘性燥。祛风去湿，化毒杀虫，生肌止痛。养生家炼之服食，今熬膏多用之（龋齿有孔，松脂 塞，虫即从脂出）。松毛 酿酒（煮汁代水），亦治风痹香港脚。"},
  "枫脂香":{o:["枫脂香"],src:["本草备要"],d:"（即白胶香）\n宣，调气血苦平。活血解毒，止痛生肌。治血衄咯血，齿痛风疹，痈疽金疮。外科要药。色白微黄，能乱乳香，功颇相近。"},
  "枳子":{o:["枳子"],src:["本草备要"],d:"（一名木蜜）\n润，解酒甘平。止渴除烦，润五脏，解酒毒（葛根解酒毒，而发散不如枳 。屋外有枳 树，屋内酿酒多不佳。赵以得治酒毒、房劳病热者，加葛根于补气血药中，一贴微汗，反解怠，热如故。知气血虚，不禁葛根之散也，必得枳 方可，偶得干者加入即愈。《东坡集》曰∶杨颖臣病消渴，日饮水数斗，饭亦倍进，小便频数，服消渴药，日甚。延张肱诊之，笑曰∶君几误死，取麝香当门子，以酒濡作十许丸，枳 子煎汤吞之遂愈。问其故，肱曰∶消渴消中，皆脾弱肾败、土不制水而成。今颖臣脾脉极热，肾脉不衰，当由酒果过度，积热在脾，所以多食多饮，饮多溲不得不多，非消非渴也。麝香坏酒果，枳 能胜酒，故假二物以去其酒果之毒也。雷𢽾曰∶凡使麝香，用当门子尤妙）。俗名鸡距，以实拳曲如鸡距。蜀呼为棘枸。经霜黄赤，甚甘。其叶入酒，酒化为水。"},
  "枳实、枳壳":{o:["枳实、枳壳"],src:["本草备要"],d:"泻，破气，行痰。枳实小，枳壳大\n苦酸微寒。其功皆能破气。气行则痰行喘止，痞胀消（脾无积血；心下不痞；浊气在上，则生腹胀。东垣曰∶枳实治下而主血，枳壳治上而主气），痛刺息，后重除。治胸痹结胸，食积五膈，痰癖症结，呕逆咳嗽，水肿胁胀（肝郁），泻痢淋闭，痔肿肠风。除风去痹（辛散风），开胃健脾。所主略同，但枳实利胸膈，枳壳宽肠胃。枳实力猛（大、小承气汤皆用之。丹溪曰∶枳实泻痰，能冲墙倒壁），枳壳力缓为少异。孕妇及气虚人忌用（按∶《本草》壳、实皆云明目。思之不得其解，然目疾方中多用之，岂以其破浊气？即能升清气乎？《本经》又言枳实益气，想亦同此理也。故浓朴调中，亦有益气明目之文。王好古曰∶枳实佐以参、术、干姜则益气，佐以硝、黄、牵牛则破气，此本经所以言益气，而复言消痞也。张元素曰∶枳壳泄肺、走大肠，多用损胸中至高之气。昔湖阳公主难产，方士进瘦胎饮，用枳壳四两，甘草三两，五月后日服一钱。张洁古改以枳术名束胎丸。寇宗 明其不然，盖孕妇全赖血气以养胎，血气充实，胎乃易生。彼公主奉养太过，气实有余，故可服之，若概施则误矣。时珍曰∶八九月胎，气盛壅滞，用枳壳、苏梗以顺气，胎前无滞，则产后无虚也。气弱者，大非所宜矣）。皮浓而小为枳实，壳薄虚大为枳壳。陈者良。麸炒用（时珍曰∶壳、实上世未分，魏、晋始分用。洁古、东垣，始分壳治上，实治下。海藏始分壳主气，实主血。然仲景治上焦胸痹、痞满用枳实；诸方治下血、痢、痔、肠秘、后重用枳壳，则实不独治下，而壳不独治高也。盖自飞门至魄门，皆肺主之，三焦相通，一气而已。飞门，口也。魄门，即肛门）。"},
  "柳蠹虫":{o:[],src:["本草纲目"],d:"新三。\n口疮风疳︰小儿病此，用柳木蛀虫矢，烧存性为末，入麝香少许，搽之。杂木亦可。（《幼幼新书》）\n齿龈风肿︰用柳蠹末半合，赤小豆（炒）、黑豆（炒）各一合，柳枝一握，地骨皮一两。\n每用三钱，煎水热漱。（《御药院方》）\n耳肿风毒，肿起出血︰取柳虫粪化水，取清汁，调白矾末少许，滴之。（《肘后》）。"},
  "柿干":{o:["柿干"],src:["本草备要"],d:"润肺，涩肠，宁嗽\n甘平性涩（生柿性寒）。脾、肺血分之药。健脾涩汤，润肺宁嗽，而消宿血。治肺痿热咳，咯血反胃（有人三世病反胃，得一方，柿干同干饭日日食，不饮水，遂愈），肠风痔漏（肺与大肠相表里，脏清则腑热亦除。《泊宅编》∶柿干烧灰饮，服二钱，治下血）。忌蟹。柿霜乃其精液。生津化痰，清上焦心、肺之热为尤佳。治咽喉口舌疮痈。柿蒂止呃逆（古方单用，取其苦温降气。《济生》加丁香、生姜，取其开郁散痰，亦从治之法。《产宝》云∶产后呃逆、烦乱。柿饼一个，煮汁热饮）。"},
  "栗":{o:["栗"],src:["本草备要"],d:"补肾\n咸温。浓肠胃，补肾气（寇宗奭曰∶小儿不可多食。生则难化，熟则滞气。能解羊膻）。"},
  "栝蒌":{o:[],src:["本草纲目"],d:"旧十二，新二十八。\n痰咳不止︰栝蒌仁一两，文蛤七分，为末，以姜汁澄浓脚，丸弹子大。噙之。（《摘玄方》）\n干咳无痰︰熟栝蒌捣烂绞汁，入蜜等分，加白矾一钱，熬膏。频含咽汁。（杨起《简便方》）\n咳嗽有痰︰熟栝蒌十个，明矾二两，捣和饼阴干，研末，糊丸梧子大。每姜汤下五、七十丸。（《医方摘要》）\n痰喘气急︰ KT 二个，明矾一枣大。同烧存性，研末。以熟萝卜蘸食，药尽病除。（《普济热咳不止︰用浓茶汤一钟，蜜一钟，大熟栝蒌一个去皮，将瓤入茶蜜汤洗去子，以碗盛，于饭上蒸，至饭熟取出。时时挑三四匙咽之。（《摘玄方》）\n肺热痰咳，胸膈塞满︰用栝蒌仁、半夏（汤泡七次，焙研）各一两。姜汁打面糊丸梧子大。每服五十丸，食后姜汤下。（严用和《济生方》）\n肺痿咳血不止︰用栝蒌五十个（连瓤瓦焙），乌梅肉五十个（焙），杏仁（去皮尖炒）二十一个，为末。每用一捻，以猪肺一片切薄，掺末入内炙熟，冷嚼咽之，日二服。（《圣济录》）\n酒痰咳嗽，用此救肺︰栝蒌仁、青黛等分，研末，姜汁蜜丸芡子大。每噙一丸。（《丹溪心法》）\n饮酒发热︰即上方研膏，日食数匙。一男子年二十病此，服之而愈。（《摘玄方》）\n饮酒痰 ，两胁胀满，时复呕吐，腹中如水声︰栝蒌实（去壳，焙）一两，神曲（炒）半两，为小儿痰喘，咳嗽，膈热久不瘥︰瓜蒌实一枚（去子）。为末，以寒食面和作饼子，炙黄再研末。每服一钱，温水化下，日三服，效乃止。\n妇人夜热痰嗽，月经不调，形瘦者︰用栝蒌仁一两，青黛、香附（童尿浸晒）一两五钱，为末。蜜调，噙化之。（《丹溪心法》）\n胸痹痰嗽，胸痛彻背，心腹痞满，气不得通，及治痰嗽︰大栝蒌去瓤，取子炒熟，和壳研末，面糊丸梧子大。每米饮下二、三十丸，日二服。（《杜壬方》）\n胸中痹痛引背，喘息咳唾，短气，寸脉沉迟，关上紧数。用大栝蒌实一枚（切），薤白半斤。以白酒七斤，煮二升，分再服。加半夏四两更善。（仲景《金匮》方） 清痰利膈，治咳嗽︰用肥大栝蒌（洗取子，切焙）、半夏四十九个（汤洗十次，捶焙）等分。为末，用洗栝蒌水并瓤同熬成膏，和丸中风 斜︰用栝蒌绞汁，和大麦面作饼，炙热熨之。正便止，勿令太过。（《圣惠方》）\n热病头痛，发热进退︰用大栝蒌一枚，取瓤细锉，置瓷碗中。用热汤一盏沃之，盖定良久，去滓服。（《圣惠方》）\n时疾发黄，狂闷烦热，不识人者︰大栝蒌实（黄者）一枚，以新汲水九合浸淘取汁，入蜜半合，朴硝八分，合搅令消尽，分再服，便瘥。（苏颂《图经本草》）\n小儿黄胆，眼黄脾热︰用青栝蒌焙研。每服一钱，水半盏，煎七分，卧时服。五更泻下黄物，立可。名逐黄散。（《普济方》）\n酒黄胆疾︰方同上。\n小便不通腹胀︰用栝蒌焙研。每服二钱，热酒下。频服，以通为度。绍兴刘驻云︰魏明州病此，御医用此方治之，得效。（《圣惠方》）\n消渴烦乱︰黄栝蒌一个，酒一盏，洗去皮子，取瓤煎成膏，入白矾末一两，丸梧子大。每米饮下十丸。（《圣惠方》）\n燥渴肠秘︰九月、十月熟 KT 实，取瓤拌干葛粉，银石器中慢火炒熟，为末。食后、夜卧各以沸汤点服二钱。（寇宗奭《衍义》）\n吐血不止︰栝蒌（泥固 存性研）三钱，糯米饮服，日再服。（《圣济录》）\n肠风下血︰栝蒌一个（烧灰），赤小豆半两，为末。每空心酒服一钱。（《普济方\n久痢五色︰大熟 蒌一个。 存性，出火毒，为末。作一服，温酒服之。胡大卿一仆，患痢半年，杭州一道人传此而愈。（《本事方》）\n大肠脱肛︰生栝蒌捣汁，温服之。以猪肉汁洗手， 之令暖，自小儿脱肛，唇白齿焦，久则两颊光，眉赤唇焦，啼哭︰黄 蒌一个，入白矾五钱在内，固济 存性，为末，糊丸梧子大。每米饮下二十丸。（《摘玄方》）\n牙齿疼痛︰ 蒌皮、露蜂房烧灰擦牙。以乌 根、荆柴根、葱根煎汤嗽之。（危氏《得效方》）\n咽喉肿痛，语声不出︰经进方用栝蒌皮、白僵蚕（炒）、甘草（炒）各二钱半，为末。每服三钱半，姜汤下。或以绵裹半钱，含咽。一日二服。名发声散。（《御药院方》）\n坚齿乌须︰大栝蒌一个（开顶），入青盐二两，杏仁（去皮尖）三七粒，原顶合扎定，蚯蚓泥和盐固济，炭火 存性，研末。每日揩牙三次，令热，百日有验。如先有白须，拔去以药投之，即生黑者。其治口齿之功，未易具陈。（《普济方》）\n面黑令白︰栝蒌瓤三两，杏仁一两，猪胰一具。同研如膏。每夜涂之，令人光润，冬月不皴。（《圣济录》）\n胞衣不下︰栝蒌实一个，取子细研，以酒与童子小便各半盏，煎七分，温服。无实，用根亦可。（陈良甫《妇人良方》）\n乳汁不下︰ 蒌子淘洗，控干炒香，瓦上拓令白色，为末。酒服一钱匕，合面卧，一夜流出。（\n乳痈初发︰大熟栝蒌一枚熟捣，以白酒一斗，煮取四升，去滓，温服一升，日三服。（《子母秘录》）\n诸痈发背，初起微赤︰栝蒌捣末，井华水服方寸匕。（《梅师方》）\n便毒初发︰黄 蒌一个，黄连五钱，水煎。连服效。（李仲南《永类方》）\n风疮疥癞︰生栝蒌一、二个、打碎，酒浸一日夜。热饮。（ 仙《乾坤秘韫》）\n热游丹肿︰栝蒌子仁末二大两，酽醋调涂。（杨氏《产乳集验方》）\n指顶，遍身者。先服败毒散，后用此解皮肤风热，不过十服愈︰用栝蒌皮为末。每服三钱，烧酒下，日三服。（《集简方》）\n根\n\n旧十二，新十三。\n消渴饮水︰《千金方》作粉法︰取大栝蒌根去皮寸切，水浸五日，逐日易水，取出捣研，滤过澄粉晒干。每服方寸匕，水化下，日三服。亦可入粥及乳酪中食之。《肘后方》︰用栝蒌根薄切炙，取五两，水五升，煮四升，随意饮之。《外台秘要》︰用生栝蒌根三十斤，以水一石，煮取一斗半，去滓，以牛脂五合，煎至水尽。用暖酒先食服如鸡子大，日三服。最妙。《圣惠方》︰用栝蒌根、黄连三两。为末，蜜丸梧子大。每服三十丸，日二服。\n又玉壶丸︰用栝蒌根、人参等分，为末，蜜丸梧子大。每服三十丸，麦门冬汤下。\n伤寒烦渴思饮︰栝蒌根三两。水五升，煮一升，分二服。先以淡竹沥一升，水二升，煮好\n百合病渴︰栝蒌根、牡蛎（熬）等分。为散。饮服方寸匕。（《永类方》）\n黑疸危疾︰ 蒌根一斤，捣汁六合，顿服。随有黄水从小便出。如不出，再服。（杨起\n《简便方》）\n小儿发黄，皮肉面目皆黄︰用生栝蒌根捣取汁二合，蜜二大匙和匀，暖服，日一服。（《利方》）\n虚热咳嗽︰天花粉一两，人参三钱。为末。每服一钱，米汤下。（《集简方》）\n偏疝痛极，劫之立住︰用绵袋包暖阴囊。取天花粉五钱，以醇酒一碗浸之，自卯至午，微煎滚，露一夜。次早低凳坐定，两手按膝，饮下即愈。未效，再一服。（《本草蒙筌》）\n小儿囊肿︰天花粉一两，炙甘草一钱半，水煎，入酒服。（《全幼心耳卒烘烘︰栝蒌根削尖，以腊猪脂煎三沸，取塞耳，三日即愈。（《肘后方》）\n耳聋未久︰栝蒌根三十斤细切，以水煮汁，如常酿酒。久服甚良。（《肘后方》）\n产后吹乳，肿硬疼痛，轻则为妒乳，重则为乳痈︰用栝蒌根末一两，乳香一钱。为末。温酒每服二钱。（李仲南《永类方》）\n乳汁不下︰栝蒌根烧存性，研末。饮服方寸匕。或以五钱，酒水煎服。（杨氏《产乳》）\n痈肿初起︰孟诜《食疗》︰用栝蒌根苦酒熬燥，捣筛，以苦酒和，涂纸上，贴之。杨文蔚方︰用栝蒌根、天泡湿疮︰天花粉、滑石等分，为末，水调搽之。（《普济方》）\n杨梅天泡︰天花粉、川芎 各四两，槐花一两，为末，米糊丸梧子大。每空心淡姜汤下七、八十丸。（《简便方》）\n折伤肿痛︰栝蒌根捣涂，重布裹之。热除，痛即止。（葛洪《肘后方》）\n箭镞不出︰栝蒌根，捣敷之，日三易，自出。（崔元亮《海上方》）\n针刺入肉︰方同上。\n痘后目障︰天花粉、蛇蜕（洗焙）等分。为末。羊子肝批开，入药在内，米泔汁煮熟，切食。次女病此，服之旬余而愈。（周密《齐东野语》）\n茎、叶"},
  "桂心":{o:["桂心"],src:["本草备要"],d:"燥，补阳，活血\n苦入心，辛走血。能引血、化汗、化脓，内托痈、疽、痘疮（同丁香，治痘疮灰塌），益精明目，消瘀生肌，补劳伤，暖腰膝，续筋骨。治风痹症瘕，噎膈腹满，腹内冷痛，九种心痛（一虫、二疰、三风、四悸、五食、六饮、七冷、八热、九去来痛，皆邪乘于手少阴之络，邪正相激，故令心痛）。"},
  "桑花":{o:[],src:["本草纲目"],d:"新一。\n大便后血︰桑树上白藓花，水煎服，或末服。亦止吐血。（《圣惠方》）"},
  "桑蠹虫":{o:[],src:["本草纲目"],d:"新二。\n崩中漏下赤白︰用桑蝎烧灰，温酒服方寸匕，日二。（《千金》）\n堕胎下血不止︰桑木中蝎虫，烧末。酒服方寸匕，日二。虫屎亦可。（《普济方》）\n粪\n\n新四。\n肠风下血︰枯桑树下虫矢，烧存性，酒服一钱。（《圣惠》）\n产后下痢，日五十行︰用桑木里蠹虫粪，炒黄，急以水沃之，稀稠得所，服之，以瘥为度。此独孤讷祭酒方也。（《小儿胎癣︰小儿头生疮，手爬处即延生，谓之胎癣。先以葱盐汤洗净，用桑木蛀屑，烧存性，入轻粉等分，油和敷之。（《圣惠》）\n咽喉骨鲠︰桑木上虫粪，米醋煎呷。（《永类钤方》）"},
  "梨":{o:["梨"],src:["本草备要"],d:"润肠，泻火，清热\n甘微酸寒。润肺凉心，消痰降火，止渴解酒，利大小肠。治伤寒发热，热嗽痰喘，中风失音（捣汁频服。《圣惠方》梨汁煮粥，治小儿心脏风热昏躁）。切片，贴汤火伤。多食冷利。脾虚泄泻及乳妇、血虚人忌之（生者清六腑之热，熟者滋五脏之阴。实火宜生，虚火宜熟。《泊宅编》有仕宦病消渴，医谓不过三十日死。亟弃官归，途遇一医，令致北梨二担，食尽则瘥。宦如其言，食及五六十枚而病愈。杨吉老介医木甚着，一士有疾，厌厌不聊，往谒之。杨曰∶汝证热已极，气血全消，三年当以疽死，不可为也。士不乐而退，闻茅山一道士，医术通神，但不肯以技自名。乃衣僮仆之服，诣山拜之，愿执役席下，道士喜留，只事左右，历两月久。觉其与常隶别，扣所从来，再拜谢过，始以实告。道士笑曰∶世间那有医不得的病，试诊脉。又笑曰∶吾亦无药与汝，便可下山买好梨，日食一颗，梨尽取干者泡汤，和滓食之，疾自当平。士人如戒，经一岁复见吉老，颜貌腴泽，脉息和平。惊曰∶君必遇异人，士人以告。杨衣冠焚香，望茅山设拜。盖自咎其学之未至也）。捣汁用，熬膏亦良（加姜汁、蜂蜜佳。清痰止嗽。与莱菔相间收藏则不烂，或削梨蒂扦莱菔上）。"},
  "棕榈":{o:["棕榈"],src:["本草备要"],d:"涩，止血\n苦能泄热，涩可收脱，烧黑能止血（红见黑则止，不可烧过。棕榈、侧柏、卷柏烧存性，饭丸，止远年下血。亦可煎服）。治吐衄下痢，崩带肠风，失血过多者，初起未可遽用。年久败棕尤良。（与发灰同用更良）。"},
  "椿樗白皮":{o:["椿樗白皮"],src:["本草备要"],d:"涩肠，燥湿\n苦燥湿，寒胜热，涩收敛。入血分而涩血。去肺、胃之陈痰。治湿热为病，泄泻久痢，崩带肠风，梦遗便数，有断下之功（痢疾滞气未尽者勿遽用，勉强固涩，必变他证），去疳、樗皮尤良（时珍曰∶椿皮入血气而性涩；樗皮入气分而胜利。凡血分受病不足者宜椿皮；气分受病有郁者宜樗皮。《乾坤生意》治疮肿下药，用樗皮水研，服汁取利，是其验矣。昂按∶樗皮止泻痢，终是涩剂。寇氏曰∶一妇年四十余，耽饮无度，多食鱼蟹，积毒在脏，日夜二三十泻，便与脓血杂下，大肠连肛门甚痛。用止血痢药不效，用肠风药益甚，盖肠风有血无脓也。服热药，腹愈痛，血愈下。服冷药，注泻食减。服温平药，则若不知，年余待毙。或教服人参散，樗皮、人参各一两为末，空心温酒或米饮下二钱，遂愈。昂按∶此方仍是作痢疾治）香者为椿，肌实而赤嫩，其苗可茹；臭者为樗，肌虚而白，主治略同。根东引者良。去粗皮，或醋炙、蜜炙用。忌肉面。"},
  "楮实":{o:["楮实"],src:["本草备要"],d:"平，补，助阳\n甘寒。助阳气，起阴痿，补虚劳，壮筋骨，明目充肌（时珍曰∶《别录》、《大明》皆云楮实大补益，而《修真秘书》又云久服令人骨痿，《济生秘览》治骨哽用楮实煎汤，岂非软骨之征乎？《本草发明》甚言其功，而云今补药中罕用，惜未之察耳）。取子浸去浮者，酒蒸用。楮皮善行水。治水肿气满（皮可为纸。楮汁和白芨飞面，调糊接纸，永不解脱）。"},
  "榆白皮":{o:["榆白皮"],src:["本草备要"],d:"滑，利窍\n甘滑下降。入大、小肠、膀胱经。行经脉、利诸窍，通二便，渗湿热，滑胎产（或胎死腹中，服汁可下），下有形留着之物。治五淋肿满（《备急方》∶捣屑作粥食，小便利差）喘咳不眠（嵇康《养生论》∶榆令人瞑），疗疥癣秃疮，消赤肿妒乳（乳痈汁不出，内结成肿，名妒乳。和陈醋滓调，日六七易效。《十剂》曰∶滑可去着，冬葵子、榆白皮之属是也）。有赤白二种，去粗皮，取白用（采皮为面，荒年当粮可食。香剂以之调和，粘滑胜于胶漆）。"},
  "榧实":{o:["榧实"],src:["本草备要"],d:"润肺\n甘涩。润肺（《本草》未尝言润，然润剂也。故寇氏云∶多食润肠）杀虫（有虫积者，宜上旬日日食之，食一斤，虫乃绝）。"},
  "榼藤子":{o:[],src:["本草纲目"],d:"旧一，新三。\n喉痹肿痛︰ 藤子烧研，酒服一钱。（《圣惠方》）\n五痔下血︰ 藤子烧存性。米饮服二钱，有功。（寇氏《衍义》）\n肠风下血︰华陀《中藏经》︰用 藤子二个，不蛀皂荚子四十九个。烧存性为末。每服二钱，温酒下，少顷再饮酒一盏，趁口服，极效。\n《圣惠方》︰用 藤子三枚，厚重者，湿纸七重包，煨熟去壳，取肉为末。每服一钱，食前黄 汤下，日一服。"},
  "槐实":{o:["槐实"],src:["本草备要"],d:"（即槐角）\n泻风热，凉大肠苦寒纯阴。入肝经气分。疏风热，润肝燥，凉大肠。治烦闷风眩，痔血肠风（粪前有血名外痔，粪后有血名内痔，谷道 肉名举痔，头上有孔名痔 ，疮内有虫名虫痔。大法用槐角、地榆、生地以凉血，芩、连、栀、柏以清热。防风、秦艽以祛风湿，芎、归、人参以和血生血，枳壳以宽肠，升麻以升提。治肠风略同，不宜专用寒凉，须兼补剂收功），阴疮湿痒，明目止泪（清肝，泪为肝热），固齿乌髭（十月上已采，渍牛胆中，阴干百日。食后吞一枚，明目补脑，发白还黑，肠风痔血，尤宜服之），杀虫（根、皮皆能洗痔）堕胎。去单子及五子者，铜槌槌碎，牛乳拌蒸（槐乃虚星之精）。槐花苦凉，入肝、大肠血分而凉血（血凉则阴自足）。治风热目赤，赤白泄痢，五痔肠风，吐崩诸血（舌上无故出血如线者，名血衄，炒研掺之）。陈者良。"},
  "樗鸡":{o:[],src:["本草纲目"],d:"新四。\n子宫虚寒︰《杏林摘要》云︰妇人无子，由子宫虚寒，下元虚，月水不调，或闭或漏，或崩中豆一百二十枚，为末。枣肉为丸，如弹子大。以绵裹留系，用竹筒送入阴户。一时许发热渴，用熟炒瘰疬结核︰用红娘子十四枚，乳香、砒霜各一钱， 砂一钱半，黄丹五分，为末，糯米粥和作饼，贴之。不过一月，其核自然脱下矣。（《卫生易简方》）\n疯狗咬伤，不治即死︰用红娘子二个、斑蝥五个（并去翅、足，若四十岁各加一个，五十岁各加续随子一分，乳香、沉香、桔梗各半分，酥油少许，为末。十岁者作四服，十五岁作三服，二十岁作二服，三十岁作一服。（《谈野翁方》）\n横 便毒︰鸡子一个开孔，入红娘子六个，纸包煨熟。去红娘子，食鸡子，以酒下。小便淋沥出浓血即愈。（陆氏《积德堂方》）"},
  "樟脑":{o:["樟脑"],src:["本草备要"],d:"宣，通窍，除湿\n辛热香窜，能于水中发火（置水中焰益炽）。通关利滞，除湿杀虫。置鞋中去香港脚（《集要》曰∶和乌头为末，醋丸弹子大，置足心，微火烘之，汗出为效）熏衣箧，辟疰虫。以樟木切片，浸水煎成。升打得法，能乱冰片。"},
  "橄榄":{o:["橄榄"],src:["本草备要"],d:"宣，清肺\n甘涩而温。肺、胃之果，清咽生津，除烦醒酒，解河豚毒（投入煮佳）及鱼骨鲠（如无橄榄，以核磨水服。橄榄木作舟楫，鱼拨即浮出，物之相畏有如此者）。核，烧灰，敷疰疳良。"},
  "水斳":{o:[],src:["本草纲目"],d:"旧一，新二。\n小儿吐泻：芹菜切细，煮汁饮之，不拘多少。（《子母秘录》）。\n小便淋痛：水芹菜白根者，去叶捣汁，井水和服。（《圣惠方》）。\n小便出血：水芹捣汁，日服六、七合。（《圣惠方》）\n花"},
  "水杨柳":{o:["水杨柳"],src:["本草备要"],d:"宣，行气血\n苦平。痘疮顶陷，浆滞不起者，用枝煎汤浴之（此因气凝血滞，或风寒外束而热，得此暖气透达，浆随暖而行，再用助气血药更效）。枝，煎汁，治黄胆。"},
  "水苏":{o:[],src:["本草纲目"],d:"旧六，新九。\n漏血欲死︰鸡苏煮汁一升，服之。（《梅师方》）\n吐血下血︰鸡苏茎叶，煎汁饮之。（《梅师方》）\n吐血咳嗽︰龙脑薄荷焙研末。米饮服一钱，取效。衄血不止︰《梅师方》︰用鸡苏五合，香豉二合，同捣，搓如枣核大，纳鼻孔中，即止。\n《用龙脑薄荷、生地黄等分，为末，冷水服。脑热鼻渊，肺壅多涕。鸡苏叶、麦门冬、川芎 、桑白皮（炒）、黄 （炙）、甘草（炙）、生地黄（焙）等分，为末，炼蜜丸梧子大。每服四十丸，人参汤下。（《圣济总录》）\n风热头痛︰热结上焦，致生风气、痰厥头痛。用水苏叶五两，皂荚（炙去皮子）三两，芫花（醋炒焦）一两，为末，炼蜜丸梧子大。每服二十丸，食后荆芥汤下。（《圣惠方》）\n耳猝聋闭︰鸡苏叶生捣，绵裹塞之。（孟诜《食疗》）\n沐发令香︰鸡苏煮汁，或烧灰淋汁，沐之。（《食疗》）\n头生白屑︰方同上。暑月目昏，多眵泪生。龙脑薄荷叶捣烂，生绢绞汁，点之。（《圣济总录》）\n中诸鱼毒︰香苏浓煮汁饮之，良。（《肘后方》）\n蛇虺螫伤︰龙脑薄荷叶研末，酒服，并涂之。（《易简方》）"},
  "水萍":{o:[],src:["本草纲目"],d:"旧七，新十八。\n夹惊伤寒︰紫背浮萍一钱，犀角屑半钱，钓藤钩三七个，为末。每服半钱，蜜水调下，连\n消渴饮水︰日至一石者。浮萍捣汁服之。又方︰用干浮萍、栝蒌根等分，为末，人乳汁和丸梧子大。空腹饮服二十丸。三年者，数日愈。（《千金方》）。小便不利，膀胱水气流滞。浮萍日干为末。饮服方寸匕，日二服。（《千金翼》）。\n水气洪肿︰小便不利。浮萍日干为末。每服方寸匕，白汤下，日二服。（《圣惠方》）。\n霍乱心烦︰芦根（炙）一两半，水萍（焙）、人参、枇杷叶（炙）各一两。每服五钱，入薤白四寸，酒煎温服。（《圣惠方》）。\n吐血不止︰紫背浮萍（焙）半两，黄 （炙）二钱半，为末。每服一钱，姜、蜜水调下。（《鼻衄不止︰浮萍末，吹之。（《圣惠方》）\n中水毒病︰手足指冷至膝肘，即是。以浮萍日干为末。饮服方寸匕良。（《千金方》）。\n大肠脱肛︰水圣散︰用紫浮萍为末，干贴之。（危氏《得效方》）\n身上虚痒︰浮萍末一钱，以黄芩一钱同四物汤煎汤调下。（《丹溪纂要》）。\n风热瘾疹︰浮萍（蒸过焙干），牛蒡子（酒煮晒干炒）各一两，为末。每薄荷汤服一、二钱，风热丹毒︰浮萍捣汁，遍涂之。（《子母秘录》）。\n汗斑癜风︰端午日收紫背浮萍晒干。每以四两煎水浴，并以萍擦之。或入汉防己二钱亦可。（《袖珍方》）\n少年面 ︰《圣惠方》︰用浮萍日 之，并饮汁少许。《普济方》︰用紫背萍四两，防己一两，煎浓汁洗之。仍以萍于斑 上热擦，日三、五次。物虽微末，其功甚大，不可小看。（《普济方》）。\n粉滓面 ︰沟渠小萍为末。日敷之。（《圣惠方》）。\n大风疠疾︰浮萍草三月采，淘三、五次，窨三、五日，焙为末，不得见日。每服三钱，食前温酒下。常持观音圣号。忌猪、鱼、鸡、蒜。又方︰七月七日，取紫背浮萍（日干为末）半升，入好消风散五两。每服五钱，水煎频饮，仍以煎汤洗浴之。（《十便良方》）。\n疮入目︰浮萍阴干为末，以生羊子肝半个，同水半盏煮熟，捣烂绞汁，调末服。甚者，不过一服；已伤者，十服见效。（危氏《得效方》）。\n弩肉攀睛︰青萍少许，研烂，入片脑少许，贴眼上效。（危氏《得效方》）。\n毒肿初起︰水中萍子草，捣敷之。（《肘后方》）。\n发背初起，肿 赤热。浮萍捣和鸡子清贴之。（《圣惠方》）。\n杨梅疮癣︰水萍煎汁，浸洗半日。数日一作。（《集简方》）。\n烧烟去蚊︰五月取浮萍阴干用之。（孙真人方）"},
  "水蛇":{o:[],src:["本草纲目"],d:"新一。\n《圣惠》水蛇丸︰治消渴，四肢烦热，蜗牛五十个（水浸五日取涎），入天花粉末煎稠，丸，姜汤下。\n皮\n\n新二。\n小儿骨疮︰《海上方》诗云︰小儿骨痛不堪言，出血流脓实可怜。寻取水蛇皮一个，烧灰蛇一条，去头尾，取中截如手指长，剖去骨肉。勿令病者见，以蛇皮包手指，自然束紧，以纸外裹之。顿觉遍身皆凉，其病即愈。数日后解视，手指有一沟如小绳，蛇皮内宛然有一蛇，头目俱全也。"},
  "水银":{o:["水银"],src:["本草备要", "本草纲目"],d:"重，外用杀虫\n辛寒，阴毒。功专杀虫。治疮疥虮虱（性滑重，且入肉。头疮切不可用，恐入经络，令人筋骨拘挛），解金、银、铜、锡毒（能杀五金），堕胎绝孕。从丹砂烧 而出。畏磁石、砒霜。得铅则凝，得硫则结，并枣肉入唾研则碎。散失在地者，以花椒、茶末收之。"},
  "水银粉":{o:[],src:["本草纲目"],d:"旧三，新三十一。\n小儿初生︰浴汤中入盐少许，拭干，以腻粉少许摩其身，既不畏风，又散诸气。（《全幼心鉴》）\n初生锁肚︰证由胎中热毒，结于肛门，儿生之后，闭而不通三日者。急令妇人咂儿前后心手足心并脐七处，四、五次。以轻粉半钱，蜜少许，温水化开，时时与少许，以通为度。（《全幼心鉴》）\n小儿涎喘，服药不退者︰用无雄鸡子一个取清，入轻粉（炒）十钱拌和，银器盛，置汤瓶上蒸熟。三岁儿尽食，当吐痰或泄而愈。气实者乃可用。（演山《活幼口议》）\n幼儿 乳不止，服此立效︰腻粉一钱，盐豉七粒（去皮）。研匀，丸麻子大。每服三丸，藿香汤下。（《活幼口议》）\n小儿吃泥及KT 肚。用腻粉一分，沙糖和丸麻子大。空心米饮下一丸，良久泄出泥土，瘥。（《经验方》）\n大小便闭，胀闷欲死，二三日则杀人。腻粉一钱，生麻油一合，相和，空心服。（《圣惠方》）\n大便壅结︰腻粉半钱，沙糖一弹丸。研丸梧子大。每服五丸，临卧温水下。又方︰腻粉二钱，黄丹一钱。为末。每米饮服一钱。（《普济方》）\n血痢腹痛︰腻粉五钱，定粉三钱。同研，水浸蒸饼心少许，和丸绿豆大。每服七丸或十丸，艾一枚，水一盏，煎汤下。（《秘宝方》）\n消中嗜食，多因外伤瘅热，内积忧思，啖食咸物及面，致脾胃干燥，饮食倍常，不生肌肉，大便反坚，小便无度。轻粉一钱为末，姜汁拌匀，长流水下，齿浮是效，后服猪肚丸补之。（危氏《得效方》）\n一切虚风︰不二散︰用腻粉一两（汤煎五度如麻脚，慢火焙干），麝香半两。细研。每服一字，温水调下。（孙用和《秘宝方》）\n水气肿满︰汞粉一钱（乌鸡子去黄，盛粉，蒸饼包，蒸熟取出），苦葶苈（炒）一钱，同蒸饼杵丸绿豆大。每车前汤下三、五丸，日三服，神效。（《医垒元戎》）\n痘疮生翳︰轻粉、黄丹等分。为末。左目患吹右耳，右目吹左耳，即退。（王氏《痘疹方》）\n女人面脂︰太真红玉膏︰轻粉、滑石、杏仁（去皮）等分。为末。蒸过，入脑、麝少许，以鸡子清调匀，洗面毕敷之。旬日后，色如红玉。（《闺阁事宜》）\n抓破面皮︰生姜自然汁调轻粉末搽之。更无痕迹。（《救急方》）\n牙齿疼痛︰轻粉一钱，大蒜一瓣，杵饼，安膈骨前陷中。先以铜钱隔了，用蚬壳盖定扎住，一宿愈。左疼安右，右疼安左。（《摘玄方》）\n风虫牙疳，脓血有虫︰轻粉一钱，黄连一两，为末掺之。（《普济方》）\n小儿耳烂︰轻粉、枣子灰等分，研，油调敷。（《摘玄方》）\n底耳肿痛，汁水不绝︰轻粉一钱，麝香一分，为末掺之。（《简便方》）\n烂弦风眼︰腻粉末，口津和，点大 ，日二、三次。（《圣惠方》）\n小儿头疮︰葱汁调腻粉涂之。又方︰鸡子黄炒出油，入麻油及腻粉末，敷之。（《集简方》）\n小儿生癣︰猪脂和轻粉抹之。（《直指方》）\n牛皮恶癣︰五更食炙牛肉一片，少刻以轻粉半钱，温酒调下。（《直指方》）\n杨梅疮癣︰《岭南卫生方》︰用汞粉、大风子肉等分，为末，涂之即愈。《医方摘玄》︰用轻粉二钱，杏仁四十二个（去皮）。洗疮拭干，搽之。不过三次，即愈。干，则以鹅胆汁调。\n杨梅毒疮︰《医学统旨》︰用轻粉一钱，雄黄、丹砂各二钱半，槐花（炒）、龟板（炙）各一两。为末，糊丸梧子大。每服一钱，冷茶下，日二服，七日愈。《杨诚经验方》︰用轻粉、胡桃仁、槐花（炒研）、红枣肉各二钱。捣丸。分作三服，初日鸡汤下，二日酒下，三日茶下，三日服尽，五日疮干，七日痂落。\n一方︰用 猪肾一对，去膜批开，各掺轻粉一钱扎定，麻油二两炸熟。顿食，不破口肿牙。仍服金银花药。\n一方︰用大鸡卵一个，去黄留白，入轻粉一钱搅匀，纸糊饭上蒸熟食。下疳阴疮︰轻粉末，干掺之，即结靥而愈。（万表《积善堂方》）\n疮不合︰以齑汁温洗拭干，用葱汁调轻粉，敷之。一方︰轻粉五分，黄蜡一两。以粉掺纸上，以蜡铺之。缚在疮上，黄水出即愈。（《永类方》）\n痈疽恶疮，杨梅诸疮︰水银一两，朱砂、雄黄各二钱半，白矾、绿矾各二两半。研匀罐盛，灯盏盖定，盐泥固济，文武火炼，升罐口扫收。每以三钱，入乳香、没药各五分，洒太乙膏上贴之，绝效，名曰五宝霜。"},
  "汤瓶内碱":{o:[],src:["本草纲目"],d:"新二。\n消渴引饮︰汤瓶内碱、葛根、水萍（焙）等分。每服五钱，水煎服。又方︰汤瓶内碱、菝根（炒）各一两，乌梅（连核）二两（焙）。为散。每服二钱，水一盏，石器煎七分，温呷，日一服。（《圣济录》）"},
  "沙参":{o:["沙参"],src:["本草备要", "本草纲目"],d:"补阴，泻肺火\n甘苦微寒。味淡体轻，专补肺气，清肺养肝，兼益脾肾（脾为肺母，肾为肺子）。久嗽肺痿，金受火克者宜之，寒客肺中作嗽者勿服（人参补五脏之阳，沙参补五脏之阴，肺热者用之，以代人参）。似人参而体轻松，白实者良，生沙地者长大，生黄土者瘦小。畏防己。反黎芦（北地真者难得。郑奠一曰∶能疗胸痹、心腹痛、邪热结，去皮肤游风、疥癣、恶疮、疝气、崩带）。"},
  "没石子":{o:["没石子"],src:["本草备要"],d:"涩精，外用染须\n苦温入肾。须精固气，收阴汗，乌须发。出大食诸番。颗小、纹细者佳。炒研用，虫食成孔者拣去。忌铜、铁器。"},
  "河砂":{o:[],src:["本草纲目"],d:"新一。\n人溺水死︰白沙（炒），覆死人面上下，惟露七孔，冷湿即易。（《千金》）"},
  "泽漆":{o:["泽漆"],src:["本草备要", "本草纲目"],d:"通，行水\n辛苦微寒。消痰退热，止嗽杀虫，利大、小肠。治大腹水肿，益丈夫阴气。生平泽，叶园黄绿，颇类猫睛，一名猫儿眼睛草。茎中有白汁，黏人（时珍曰∶《别录》云是大戟苗，非也。功相类耳）。"},
  "浮石":{o:["浮石"],src:["本草备要", "本草纲目"],d:"（一名海石）\n泻火，软坚咸润下，寒降火。色白体轻，入肺清其上源（肺为水之上源）。止渴止嗽，通淋软坚，除上焦痰热，消瘿瘤结核（顽痰所结，咸能软坚。俞琰《席上腐谈》云∶肝属木，当浮而反沉；肺属金，当沉而反浮何也？以肝实而肺虚也。故石入水则沉，而南海有沉水之香，虚实之反如此）。水沫日久结成，海中者味咸更良。"},
  "浮萍":{o:["浮萍"],src:["本草备要"],d:"轻，发汗，利湿\n辛散轻浮。入肺经，达皮肤，能发扬邪汗（丹溪曰∶浮萍发汗，甚于麻黄），止瘙痒、消渴（捣汁服）生于水，又能下水气，利小便。治一切风湿瘫痪（浮萍一味，蜜丸酒服，治三十六种风；浓煮汁浴，治恶疾疮癞遍身）。烧烟辟蚊。紫背者良。"},
  "海带":{o:["海带"],src:["本草备要"],d:"下水消瘿，功同海藻。似海藻而粗，柔弱而长。"},
  "海松子":{o:["海松子"],src:["本草备要"],d:"润燥\n甘温。润肺温胃，散水除风。治咳嗽（松子一两，胡桃二两，炼蜜和服，治肺燥咳嗽）虚秘（同柏子仁、麻仁，溶蜡为丸，名三仁丸）。出辽东云南，松须五鬣。"},
  "海桐皮":{o:["海桐皮"],src:["本草备要"],d:"宣，祛风湿\n苦温（《经疏》云∶应兼辛）。入血分。祛风、去湿、杀虫，能行经络达病所。治风蹶顽痹，腰膝疼痛（《传信方》∶海桐、薏苡各二两，芎 、羌活、地骨皮、五加皮各二两，甘草五钱，生地七两，酒二斗浸，此方不得增减。早、中、晚饮，常令醺醺），疳 疥癣，目赤（煎洗）牙虫（煎服，或含漱）。出广南。皮白坚韧，作索不烂。"},
  "海狗肾":{o:["海狗肾"],src:["本草备要"],d:"（一名腽肭脐）\n补肾，助阳甘咸大热。补肾助阳，治虚损劳伤，阴痿精冷，功近苁蓉、锁阳。出西番，今东海亦有之。似狗而鱼尾。置器中长年湿润，腊月浸水不冻。置睡犬旁，犬惊跳者为真（或曰∶连脐取下故名脐，或曰∶乃腽肭兽之脐也。昂按∶两名不类，恐一是海鱼之肾。一是山兽之脐也。《纲目》以此条入兽部）。"},
  "海马":{o:[],src:["本草纲目"],d:"新二。\n海马汤︰治远年虚实积聚症块。用海马雌雄各一枚，木香一两，大黄（炒）、白牵牛（炒）各二两，巴豆四十九粒，青皮二两（童子小便浸软，包巴豆扎定，入小便内再浸七日，取出麸炒黄色，去豆不用），取皮同众药为末。每服二钱，水一盏，煎三五沸，临卧温服。（《圣济录》）\n海马拔毒散︰治疔疮发背恶疮有奇效。用海马（炙黄）一对，穿山甲（黄土炒）、朱砂、水银各一钱，雄黄三钱，龙脑、麝香各少许为末，入水银研不见星。每以少许点之，一日一点，毒自出也。（《秘"},
  "淡竹叶":{o:["淡竹叶"],src:["本草备要"],d:"泻上焦烦热\n辛淡甘寒。凉心暖脾，消痰止渴。除上焦风邪烦热（叶生竹上，故治上焦。仲景治伤寒发热、大渴，有竹叶石膏汤。乃假其辛寒，以散阳明之邪热也），咳逆喘促，呕哕吐血，中风失音，小儿惊痫。竹生一年以上者，嫩而有力。"},
  "淡豆豉":{o:["淡豆豉"],src:["本草备要"],d:"宣，解表，除烦\n苦泄肺、寒胜热（陈藏器曰∶豆性生平，炒熟、热煮食寒，作豉冷）。发汗解肌，调中下气。治伤寒头痛，烦躁满闷，懊 不眠，发斑呕逆（凡伤寒呕逆烦闷，宜引吐，不宜用下药以逆之。淡豉合栀子，名栀子豉汤，能吐虚烦），血痢温疟（时珍曰∶黑豆性平，作豉则温，既经蒸 ，故能升能散。得葱则发汗，得盐则能吐，得酒能治风，得薤则治痢，得蒜则止血，炒熟又能止汗。孟诜治盗汗，炒香渍酒服。《肘后》∶合葱白煎，名葱豉汤，用代麻黄汤，通治伤寒，发表，亦治酒病）。造淡豉法，用黑大豆水浸一宿，淘净蒸熟，摊匀，蒿复，候上黄衣，取晒，簸净，水拌，干湿得所，安瓮中，筑实。桑叶浓盖，泥封。晒七日取出，曝一时，又水拌入瓮。如此七次，再蒸，去火气，瓮收用。"},
  "清风藤":{o:[],src:["本草纲目"],d:"新二。\n风湿痹痛︰青藤根三两，防己一两， 咀。入酒一瓶煮饮。（《普济方》）\n一切诸风︰青藤膏︰用青藤，出太平荻港上者，二、三月采之，不拘多少，入釜内，微火熬七日夜成膏，收入瓷器内。用时先备梳三、五把，量人虚实，以酒服一茶匙毕，将患人身上拍一掌，其后遍身发痒，不可当，急以梳梳之。要痒止，即饮冷水一口便解，风病皆愈也。避风数日良。（《集简方》）"},
  "漆":{o:["漆"],src:["本草备要"],d:"泻，破血，消积，杀虫\n辛温有毒。功专行血杀虫，削年深坚结之积滞（丹溪曰∶漆性急而飞补，用之中节，积滞去后，补性内行，人不知也），破日久凝结之瘀血（能化瘀血为水），续筋骨绝伤（损伤必有瘀血停滞）。治传尸劳瘵，瘕疝蛔虫。炒令烟尽入药，或烧存性，用半夏为使。畏川椒、紫苏、鸡子、蟹（漆得蟹而成水）。"},
  "漏篮子":{o:[],src:["本草纲目"],d:"新一。\n一切恶痢杂下，及休息痢︰百岁丸︰用漏篮子一个（大者），阿胶、木香、黄连、罂粟壳各半两，俱炒焦存性，入乳香少许为末，糊丸梧子大。每一岁一丸，米饮下。（罗天益《卫生宝鉴》）"},
  "漏芦":{o:["漏芦"],src:["本草备要", "本草纲目"],d:"泻热，解毒\n咸软坚，苦下泄，寒胜热。入胃、大肠，通肺、小肠。散热解毒，通经下乳，排脓止血，生肌杀虫。治遗精尿血，痈疽发背（古方以漏芦汤为称首），及预解时行痘疹毒（取其寒胜热，又能入阳明故也）。出闽中，茎如油麻，枯黑如漆者真。甘草拌蒸。连翘为使。"},
  "灯心草":{o:["灯草"],src:["本草备要", "本草纲目"],d:"轻，通，利水，清热\n甘淡而寒。降心火（心能入心），清肺热，利小肠（心与小肠相表里，心火清则肺热小肠亦清，而热从小便出矣），通气止血。治五淋水肿，烧灰吹喉痹，涂乳止夜啼，擦癣最良（缚成把，擦摩极痒时，虫从草出，浮水可见，十余次则能断也）。"},
  "灰藋":{o:[],src:["本草纲目"],d:"新一。\n疔疮恶肿︰野灰 菜叶烧灰，拨破疮皮，唾调少许点之，血出为度。（《普济》）\n子仁"},
  "灵砂":{o:[],src:["本草纲目"],d:"新七。\n伏热吐泻︰阴阳丸︰用硫黄半两，水银一钱，研黑，姜汁糊丸小豆大。三岁三丸，冷水下；大人三、四十丸。（郑氏《小儿方》）\n诸般吐逆︰方同上。霍乱吐逆︰不问虚实冷热。二气散，一名青金丹︰用水银、硫黄等分。研不见星。每服一字至半钱，生姜汤调下。（钱氏《小儿方》）\n脾疼反胃︰灵砂一两，蚌粉一两（同炒赤），丁香、胡椒各四十九粒。为末，自然姜汁煮，半夏粉糊丸梧子大。每姜汤下二十丸。（《普济方》）\n冷气心痛︰灵砂三分，五灵脂一分。为末，稀糊丸麻子大。每服二十丸，食前石菖蒲、生姜汤下。（《直指方》）\n九窍出血，因暴惊而得，其脉虚者。灵砂三十粒，人参汤下，三服愈。此证不可错认作血得热则流，妄用凉药误事。（杨仁斋《直指方》）。\n养正丹︰又名交泰丹，乃宝林真人谷伯阳方也。却邪辅正，助阳接真。\n治元气亏虚，阴邪交荡，上盛下虚，气不升降，呼吸不足，头旋气短，心怯惊悸，虚烦狂言，盗汗，腹痛腰痛，反胃吐食，霍乱转筋，咳逆。又治中风涎潮，不省人事，阳气欲脱，四肢厥冷。伤寒阴盛自汗，唇青脉沉。妇人产后月候不匀，带下腹痛。用黑盏一只，入黑铅熔汁，次下水银，次下朱砂末，炒不见星，少顷乃下硫黄末，急搅。有焰，酒醋解之。取出研末，糯粉煮糊丸绿豆大。每服二十丸，盐汤下。四味皆等分。此药升降阴阳，既济心肾，神效。不可具述。（《和济局方》）"},
  "炉甘石":{o:["炉甘石"],src:["本草备要", "本草纲目"],d:"燥温，治目疾\n甘温。阳明胃经药。受金、银之气，金胜木，燥胜湿，故止血消肿，收湿除烂，退赤去翳，为目疾要药。产金银坑中，金银之苗也。状如羊脂，松似石脂，能点赤铜为黄（今之黄铜，皆其所点也）。 红、童便淬七次，研粉，水飞用。"},
  "烟草":{o:["烟草"],src:["本草备要"],d:"（新增）\n宣，行气，辟寒辛温有毒。治风寒湿痹，滞气停痰，山岚瘴雾。其气入口，不循常度，顷刻而周一身，令人通体俱快，醒能使醉，醉能使醒，饥能使饱，饱能使饥。人以代酒代茗，终身不厌（故一名相思草）。然火气熏灼，耗血损年，人自不觉耳。闽产者佳（烟筒中水，能解蛇毒）。"},
  "熊胆":{o:["熊胆"],src:["本草备要"],d:"泻热\n苦寒。凉心平肝，明目杀虫。治惊痫五痔（涂之取瘥）。通明者佳。性善辟尘。扑尘水上，投胆少许，则豁然而开。"},
  "燕脂":{o:[],src:["本草纲目"],d:"新五。\n婴孩鹅口，白浓如纸︰用坯子燕脂，以乳汁调涂之，一宿效。男用女乳，女用男乳。（《集简方》）\n漏疮肿痛︰猪胆七个，绵燕脂十个洗水，和匀，搽七次即可。（《救急方》）\n防痘入目︰燕脂嚼汁点之。（《集简方》）\n痘疮倒陷︰干燕脂三钱，胡桃（烧存性）一个，研末，用胡荽煎酒服一钱，再服取效。（《救急方》）"},
  "牛肉":{o:["牛肉"],src:["本草备要"],d:"补脾土\n甘温属土。安中补脾，益气止渴（倒仓法，用牡黄牛肉二十斤，洗净，煮为糜，滤去渣，熬成琥珀色。前一晚不食，至日，空腹坐密室，取汁每饮一钟。少时又饮，积数十钟，身体觉痛。如病在上则吐，在下则利，在中则吐而利，利后必渴，即饮已溺数碗，以涤余垢。饥倦先与米饮，二日与淡粥，次与浓粥软饭，将养一月沉 悉安矣。须断房事半年，牛肉五年。丹溪曰∶牛坤土，黄中色，肉、胃药，液、无形之物也！积聚既久，回薄肠胃曲折之处，岂铢两丸散所能窥犯乎！肉液充满流行，无处不到，如洪水泛涨，一切凝滞，皆顺流而去矣。此方传于西域异人，中年后行一二次，亦却疾养寿之一助也。王纶曰∶牛肉补中，非吐下药，借补为泻，因泻为补，亦奇方也。丹溪治林德方咳而咯血，调肺壅非吐不可，血耗非补不可，惟倒仓二法兼备，服之而愈。又治萧伯善便浊滑精，亦用倒仓法而愈。又治许文懿公病心痛，用燥药、灵丹、艾灸杂治，数年不效，自分为弃人。丹溪先以防风通圣散下其积滞，而病稍起，思食。然两足难移，次年行倒仓法，节节应手，复生子，活十四年。又临海林兄久嗽吐红，发热消瘦，众以为瘵，百方不应。丹溪脉之，两手弦数，日轻夜重，计无所出。时冬月也，以倒仓法而安，仍次年生子）。牛乳，味甘微寒。润肠胃，解热毒，补虚劳，治反胃噎膈（胃槁胃冷，脾不磨食，故气逆而成反胃。气血不足，其本也；曰痰饮，曰食积，其标也。胃槁者，滋血生津；胃冷者，温中调气。东垣曰∶上焦吐者由乎气，治在和中而降气；中焦吐者由乎积，治在行气而消积；下焦吐者由乎寒，治在温中而散寒。丹溪曰∶反胃噎膈，大便燥结，宜牛、羊乳时时咽之，兼服四物汤为上策。不可服人乳，人乳有五味之毒，七情之火也。昂按∶噎膈不通，服香燥药取快一时，破气而燥血，是速其死也。不如少服药，饮牛乳加韭汁、或姜汁、或陈酒为佳。江南臬司多患噤口痢，粒米不进，郑奠一令服牛乳，久之亦瘥）。白水牛喉，治反胃吐食，肠结不通（除两头，去脂膜，醋浸炙末，每服二钱，陈米饮下）。酥、酪、醍、醐，皆牛羊乳所作，滋润滑泽，宜于血热枯燥之人。牛胆，纳锻石于内，悬挂风处百日，治金疮良。"},
  "牛虱":{o:[],src:["本草纲目"],d:"新二。\n预解痘毒︰\n谈野翁方︰用白水牛虱一岁一枚，和米粉作饼，与儿空腹食之，取下恶粪，终身可免痘疮之患。\n一方︰用白牛虱四十九枚（焙），绿豆四十九粒，朱砂四分九厘，研末，炼蜜丸小豆大，以绿豆汤下。"},
  "牛黄":{o:["牛黄"],src:["本草备要"],d:"泻热，利痰，凉惊\n甘凉。牛有病，在心、肝、胆之间凝结成黄，故还以治心、肝、胆之病（《经疏》云∶牛食百草，其精华凝结成黄，犹人之有内丹。故能散火、消痰、解毒，为世神物。或云牛病乃生黄者，非也）。清心解热，利痰凉惊，通窍辟邪。治中风入脏，惊痫口噤（心热则火自生焰，肝热则木自生风，风火相搏，胶痰上壅，遂致中风不语。东垣曰∶中脏宜之。若中腑及血脉者用之，反能引风入骨，如油入面。按∶中风中脏者重，多滞九窍；中腑稍轻，多着四肢。若外无六经形证，内无便溺阻隔，为中经络，为又轻。初宜顺气开痰，次宜养血活血，不宜专用风药。大抵五脏皆有风，而犯肝者为多。肝属风木而主筋，肝病不能营筋，故有舌强口噤， 斜、瘫痪、不遂、不仁等症。若口开为心绝；手散为脾绝；眼合为肝绝；遗尿为肾绝；吐沫鼻衄为肺绝；发直头摇、面赤如妆、汗缀如珠者，皆不治。若只见一二症，犹有可治者），小儿百病（皆胎毒、痰热所生。儿初生时未食乳，用三五厘，合黄连、甘草末蜜调，令咂之良），发痘堕胎（善通窍）。牛有黄，必多吼唤，以盆水承之，伺其吐出迫喝即堕水，名生黄，如鸡子黄大，重叠可揭。轻虚、气香者良（观此则非病乃生黄矣）。杀死，角中得者名角黄，心中者名心黄，肝、胆中者名肝、胆黄。成块成粒，总不及生者。但磨指甲上，黄透指甲者为真（骆驼黄极易得，能乱真）。得牡丹、菖蒲良（聪耳明目），人参为使。恶龙骨、龙胆、地黄、常山。"},
  "牡丹":{o:[],src:["本草纲目"],d:"旧三，新三。\n疝偏坠，气胀不能动者。牡丹皮、防风等分。为末，酒服二钱，甚效。（《千金方》）\n妇人恶血，攻聚上面多怒。牡丹皮半两，干漆（烧烟尽）半两。水二钟，煎一钟服。（《诸证辨疑》）\n伤损瘀血︰牡丹皮二两，虻虫二十一枚（熬过同捣末。）每旦温酒服方寸匕，血当化为水下。（《贞元广利方》）\n金疮内漏，血不出。牡丹皮为末，水服三指撮，立尿出血也。（《千金方》）\n解中蛊毒︰牡丹根捣末，服一钱匕，日三服。（《外台秘要》）"},
  "牡蒿":{o:[],src:["本草纲目"],d:"新一。\n疟疾寒热︰齐头蒿根、滴滴金根各一把。擂生酒一钟，未发前服。以滓敷寸口，男左女右"},
  "牵牛":{o:["牵牛"],src:["本草备要"],d:"大泻气分湿热\n辛热有毒，属火善走。入肺经，泻气分之湿热（肺主气，火能平金而泄肺），能达右肾命门，走精隧，通下焦郁遏。及大肠风秘、气秘，利大小便，逐水消痰，杀虫堕胎。治水肿喘满 癖气块。若湿、热在血分、胃弱气虚人禁用（东垣曰∶牵牛苦寒误矣，其味辛辣，久嚼猛烈雄壮，所谓苦寒安在哉？乃泻气之药，比诸辛药泄气尤甚。若湿从下受，下焦主血，血中之湿，宜苦寒之味。而反用辛热之药，泄上焦之气，是血病泻气，使气血俱损也。王好古曰∶以气药引，则入气；以大黄引，则入血。时珍曰∶一妇肠结，年几六十，服养血润燥药，则泥结，服硝黄药，则若罔知。如此三十余年。其人体肥膏梁而多郁，日吐酸痰乃宽。此乃三焦气滞，有升无降，津液皆化为痰，不能下润肠腑，非血燥也。润剂留滞，硝、黄入血，不能入气，故无效。用牵牛为末，皂角膏丸，才服便通。外甥素多酒色病，二便不通，胀痛呻吟七昼夜，用通利药不效。予言此乃湿热之邪在精道，壅隧路，病在二阴之间。故前阻小便，后阻大便，病不在大肠、膀胱也。用楝实、茴香、穿山甲诸药，倍牵牛，三服而平。东垣补下焦阳虚天真丹，用牵牛盐水炒黑，佐沉香、杜仲、肉桂、破故纸诸药，深得补泻兼施之妙）。有黑、白二种，黑者（亦名黑丑）力速。取子淘去浮者，舂去皮用。得木香、干姜良（此药汉前未入本草，故仲景方中无此。《别录》始载之，宋后始多用者）。"},
  "犀角":{o:["犀角"],src:["本草备要"],d:"泻心、胃大热\n苦酸咸寒。凉心泻肝，清胃中大热，祛风利痰，辟邪解毒。治伤寒时疫，发黄发斑（伤寒下早，热乘虚入胃则发斑；下迟，热留胃中亦发斑），吐血下血，蓄血谵狂，痘疮黑陷，消痈化脓，定惊明目。妊妇忌之（能消胎气。时珍曰∶五脏六腑，皆禀气于胃。风邪热毒，必先干之，饮食药物，必先入胃。角，犀之精华所聚，足阳明胃药也。故能入阳明，解一切毒，疗一切血，及惊、狂、斑、痘之证。《抱朴子》云∶犀食百草之毒及棘，故能解毒。饮食有毒，以角搅之，则生白沫）。乌而光润者胜，角尖尤胜（鹿取茸，犀取尖，其精气尽在是也）。现成器物，多被蒸煮，不堪入药。入汤剂磨汁用，人丸散锉细。纸裹纳怀中，待热捣之立碎（《归田录》云∶人气粉犀）。升麻为使。忌盐。"},
  "犬肉":{o:["犬肉"],src:["本草备要"],d:"补虚寒\n酸而咸温。暖脾益胃，脾胃暖则腰肾受荫矣。补虚寒，助阳事（两肾、阴茎尤胜）。黄者补脾，黑者补肾。畏杏仁。忌蒜（道家以为地厌。黄犬血，酒服二碗，治肠痈）。"},
  "独活羌活":{o:[],src:["本草纲目"],d:"旧八，新七。\n中风口噤，通身冷，不知人。独活四两。好酒一升，煎半升服。（《千金方》）\n中风不语：独活一两。酒二升，煎一升，大豆五合，炒有声，以药酒热投，盖之良久，温服三合，未瘥再服。（陈延之《短剧方》）\n热风瘫痪，常举发者。羌活二斤，构子一升。为末。每酒服方寸匕，日三服。（《广济方》）\n产后中风语涩，四肢拘急。羌活三两。为末。每服五钱，酒、水各一盏，煎减半服。（《短剧方》）\n产后风虚：独活、白藓皮各三两，水三升，煮二升，分三服。耐酒者，入酒同煮。（\n《短剧方》）\n产后腹痛：羌活二两，煎酒服。（《必效方》）\n产肠脱出：方同上。（《子母秘录》）\n妊娠浮肿：羌活、萝卜子同炒香，只取羌活为末。每服二钱，温酒调下，一日一服，二日二服，三日三服。乃嘉兴主簿张昌明所传。（许学士《本事方》）\n风水浮肿：方同上。历节风痛：独活、羌活、松节等分。用酒煮过，每日空心饮一杯。（《外台秘要》）\n风牙肿痛：《肘后方》：用独活煮酒，热漱之。文潞公《药准》：用独活、地黄各三两，为末。每服三钱，水一盏煎，和滓温服，卧时再服。喉闭口噤：羌活三两，牛蒡子二两，水煎一钟，入白矾少许，灌之取效。（《圣济录》）\n睛垂至鼻：人睛忽垂至鼻，如黑角色，痛不可忍，或时时大便血出，名曰肝胀。用羌活煎汁，服数盏，自愈。（夏子益《奇疾方》）\n太阳头痛：羌活、防"},
  "独用将军":{o:[],src:["本草纲目"],d:"新一。\n下痢噤口︰独将军草根，有珠如豆者，取珠捣汁三匙，以白酒半杯和服。（《简便方》）"},
  "猪肉":{o:["猪肉"],src:["本草备要"],d:"脏腑引经\n水畜，咸寒。心血，用作补心药之向导，盖取以心归心、以血导血之意（《延寿丹书》曰∶猪临杀，惊气入心，绝气入肝，皆不可多食）。尾血，和龙脑（冰片），治痘疮倒 （能发之，时珍曰∶取其动而不息，亦有用心血者）。肝，主藏血，补血药用之，入肝明目（雄者良。同夜明砂作丸，治雀目。雀目者，夜不能睹，湿痰及肝火盛也）。肺，补肺，治肺虚咳嗽（咳血者，蘸薏仁末食）。肚，入胃健脾（仲景治消渴，有黄连猪肚丸。用雄猪肚一枚，入黄连末五两，栝蒌根、白粱米各四两，知母三两，麦冬二两，缝定蒸熟，丸如梧子大，每服三十丸，米饮下。《直指方》∶治小儿疳热，黄连五两，入猪肝蒸烂，饭丸，米饮下，仍服调血清心药佐之。且曰∶小儿之病，非疳即热，常须识此）。肾，咸冷而通肾。治腰痛耳聋（日华曰∶补水脏，暖腰膝。又曰∶久食令人少子。孟诜曰∶久食令人肾虚。李时珍韪之，谓其咸冷能泻肾气也。昂按∶枸杞、玄参、知母、黄柏，性皆寒而能补肾。猪肾乃肉食，何独泻肾若斯之酷也？古今补腰肾药，用猪肾者颇多，未见作害。大抵诸家食忌，不可尽信。《琐碎录》∶猪肾一对，童便二分，酒一分，瓦罐煨，五更食之，治劳瘵，一月愈。《经验后方》∶猪肾、枸杞叶、豉汁，入葱、椒、盐作羹，治阴痿羸瘦）。肠，入大肠，治肠风血痢（《奇效方》∶治脏毒，有脏连丸）。胆汁，苦入心、寒胜热、滑润燥。泻肝胆之疳，沐发光泽。醋和，灌谷道，治大便不通（仲景治阳明证内无热者，便虽秘，勿攻。故用胆汁外导之法，不欲以苦寒伤胃腑也。成无已曰∶仲景治厥逆无脉，用白通汤加猪胆汁。盖阳气大虚，阴气内胜，纯与阳药，恐阴气格拒不得入。故加猪胆汁，苦入心而通脉，寒补肝而和阴，不致格拒也。昂按∶此即热因寒用之义）。浴初生小儿，永无疮疥。猪脬（亦作胞），治遗溺疝气，用作引经。猪脂，甘寒。凉血润燥，行水散风，解毒（《千金方》∶凡中恶及牛肉毒、百兽肝毒，服猪脂一斤，佳）杀虫（故疮药多用之），利肠（能通大便，退诸黄）滑产。煎膏药，主诸疮（腊月者佳。古方用之最多，治咳嗽亦用之）。猪蹄，煮汤，通乳汁（加通草二两，佳），洗败疮。悬蹄甲，治寒热痰喘，痘疮入目，五痔肠痈（古人有用左甲者，有用后甲者）。猪肉反黄连、乌梅、桔梗，犯之泻痢（时珍曰∶方有脏连丸、黄连猪肚丸，岂忌肉而不忌脏腑乎？昂按∶《别录》云，猪肉闭血脉，弱筋骨，虚人肌，不可久食。陶弘景曰∶猪为用最多，唯肉不可食。孙思邈曰∶久食令人少子，发宿病、筋骨碎痛之气。孟诜曰∶久食杀药、动风、发疾。韩 曰∶凡肉皆补，惟猪肉无补。李时珍曰∶南猪味浓汁浓，其毒尤甚，若将为大禁者然。然今人终日食肉，内滋外腴，子孙蕃衍，未见为害若斯之甚也。又云∶合黄豆、荞麦、葵菜、生姜、胡荽、吴茱、牛肉、羊肝、龟、鳖、鲫鱼、鸡子食之，皆有忌。然肴馔中合食者多，未见丝毫作害也。大抵肉能补肉，其味隽永，食之润肠胃，生精液，丰肌体，泽皮肤，固其所也。惟多食，则助热生痰、动风作湿，伤风寒及病初愈人为大忌耳。先王教民，畜牧养彘为先，岂故为是以厉民欤？明太祖释家字之义，亦曰无豕不成家。诸家之说，稽之于古则无征，试之于人则不验，徒令食忌不足取信于后世而已。伤寒忌之者，以其补肌固表，油腻缠粘，风邪不能解散也。病初愈忌之者，以肠胃久枯，难受肥浓浓味也。又按∶猪肉生痰，惟风痰、湿痰、寒痰忌之。如老人燥痰干咳，更须肥浓以滋润之，不可执泥于猪肉生痰之说也）。"},
  "獭肝":{o:["獭肝"],src:["本草备要"],d:"补肝肾，杀传尸\n甘咸而温。益阴补虚，杀虫止嗽，治传尸鬼疰有神功（尸疰、鬼疰乃五疰之一，变动有三十三种，乃至九十九种。其症使人寒热，沉沉默默，不知病之所苦，而无处不恶，死后传入，乃至灭门。古方有獭肝丸。獭肝烘干，炙为末。水服二钱，日三次，以瘥为度）。诸肝皆有叶数，惟獭肝一月一叶，其间又有退叶，须于獭身取下，不尔多伪（吴鹤皋曰∶獭阴物，昼伏夜出，故治鬼疰。昂谓∶不然，缘其肝独异于他兽也）。"},
  "玄明粉":{o:[],src:["本草纲目"],d:"新三。\n热厥气痛︰玄明粉三钱，热童尿调下。（《集简方》）\n伤寒发狂︰玄明粉二钱，朱砂一钱。末之。冷水服。（《伤寒蕴要》）\n鼻血不止︰玄明粉二钱，水服。（《圣济》）"},
  "玄精石":{o:[],src:["本草纲目"],d:"旧一，新八。\n正阳丹︰治伤寒三日，头痛壮热，四肢不利。太阴玄精石、硝石、硫黄各二两， 砂一两。细研，入瓷瓶固济。以火半斤，周一寸 之，约近半日，候药青紫色，住火。待冷取出，用腊月雪水拌匀，入罐子中，屋后北阴下阴干。又入地埋二七日，取出细研，面糊和丸鸡头子大。先用热水浴后，以艾汤研下一丸。以衣盖汗出为瘥。（《图经本草》）\n小儿风热，挟风蕴热，体热。太阴玄精石一两，石膏七钱半，龙脑半两，为末。每服半钱，新汲水下。（《普济方》）\n肺热咳嗽︰方见不灰木下。冷热霍乱，分利阴阳︰玄精石、半夏各一两，硫黄三钱，为末，面糊丸梧子大。每米饮服三十丸。（《指南方》）\n头风脑痛︰玄精石末，入羊胆中阴干。水调一字，吹鼻中，立止。（《千金方》）\n目赤涩痛︰玄精石半两，黄柏（炙）一两。为末。点之，良。（《普济方》）\n赤目失明，内外障翳︰太阴玄精石（阴阳火 ）、石决明各一两，蕤仁、黄连各二两，羊子肝七个（竹刀切晒）。为末，粟米饭丸梧子大。每卧时茶服二十丸。服至七日，烙顶心以助药力，一月见效。宋丞相言︰黄典史病此，梦神传此方，愈。（《朱氏集验方》）\n目生赤脉︰玄精石一两，甘草半两。为末。每服一钱，小儿半钱，竹叶煎汤调下。（《总微论》）\n重舌涎出，水浆不入︰太阴玄精石二两，牛黄、朱砂、龙脑各一分。为末。以铍针舌上去血，盐汤漱口，掺末咽津，神效。（《圣惠方》）"},
  "玉":{o:[],src:["本草纲目"],d:"新三。\n小儿惊啼︰白玉二钱半，寒水石半两，为末，水调涂心下。（《圣惠方》）\n癖鬼气，往来疼痛，及心下不可忍者，不拘大人小儿。白玉、赤玉等分，为末，糊丸梧子大。每服三十丸，姜汤下。（《圣惠方》）\n面身瘢痕︰真玉日日磨之，久则自灭。（《圣济录》）"},
  "玉簪":{o:[],src:["本草纲目"],d:"新五。\n乳痈初起︰内消花（即玉簪花），取根擂酒服，以渣敷之。（《海上方》）\n妇人断产︰白鹤仙根、白凤仙子各一钱半，紫葳二钱半，辰砂二钱，捣末，蜜和丸梧子大。产内三十日，以酒半盏服之。不可著牙齿，能损牙齿也。（《摘玄方》）\n解斑蝥毒︰玉簪根擂水服之，即解。（赵真人《济急方》）\n下鱼骨哽︰玉簪花根、山里红果根，同捣自然汁，以竹筒灌入咽中，其骨自下。不可著牙齿。（刮骨取牙︰玉簪根（干者）一钱，白砒三分，白 七分，蓬砂二分，威灵仙三分，草乌头一分半，为末。以少许点疼处，即自落也。（余居士《选奇方》）\n叶"},
  "王瓜":{o:["王瓜"],src:["本草备要", "本草纲目"],d:"（即土瓜根）\n泻热，利水，行血苦寒。泻热利水。治天行热疾，黄胆消渴（捣汁饮），便数带下，月闭瘀血。利大、小肠，排脓消肿，下乳（通乳药多用之，单服亦可）堕胎。根如栝蒌之小者，味如山药，根、子通用（《经疏》曰∶主治略似栝蒌。伤寒发斑，用王瓜捣汁，和伏龙肝末服，甚效）。"},
  "珍珠":{o:["真珠"],src:["本草备要"],d:"泻热，定惊\n甘咸性寒。感月而胎（语云∶上巳有风梨有蠹，中秋无月蚌无胎），水精所孕。水能制火，入心、肝二经。镇心安魂（肝藏魂。昂按∶虽云泻热，亦借其宝气也。大抵宝物多能镇心安魂，如金箔、琥珀、真珠之类。龙齿安魂，亦假其神气也），坠痰拔毒，收口生肌。治惊热痘疗，下死胎胞衣（珠末一两，苦酒服），涂面好颜色，点目去翳膜，绵裹塞耳治聋。取新洁未经钻缀者，乳浸三日，研粉极细用（不细伤人脏腑。陆佃曰∶蛤蚌无阴阳牝牡，须雀化成，故能生珠，专一于阴阳也）。"},
  "琥珀":{o:["琥珀"],src:["本草备要"],d:"通，行水，散瘀，安神\n甘平。以脂入土而成实，故能通塞以宁心。安魂魄，疗癫邪（从镇坠药，则安心神）。色赤入手少阴、足厥阴（心、肝）血分，故能消瘀血，破症瘕，生肌肉，合金疮（从辛温药、则破血生肌）。其味甘淡上行，能使肺气下降而通膀胱（经曰∶饮食入胃，游溢精气。上输于脾，脾气散精，上归于肺，通调水道，下输膀胱。凡渗药皆上行而后下降），故能治五淋，利小便，燥脾土（从淡渗药，则利窍行水。然石药终燥，若血少而小便不利者，仅致燥急之苦），又能明目磨翳。松脂入土，年日久结成，或云枫脂结成。以摩热拾芥者真（市人多煮鸡子及青鱼枕伪之。摩呵亦能拾芥，宜辨）。用柏子仁末，入瓦锅同煮半日，捣末用。"},
  "甘松香":{o:["甘松香"],src:["本草备要", "本草纲目"],d:"宣，理气醒脾\n甘温芳香。理诸气，开脾郁。治腹卒然满痛，风疳齿 ，香港脚膝浮。煎汤淋洗。出凉州及黔蜀。叶如茅，用根（根极繁密）。"},
  "甘澜水":{o:["甘澜水"],src:["本草备要"],d:"补\n用流水以瓢扬万遍，亦曰劳水。水性咸而重，劳之则甘而轻。仲景用煎伤寒劳伤等药，取其不助肾气而益脾胃也。"},
  "甘蔗":{o:["甘蔗"],src:["本草备要"],d:"补脾，润燥\n甘寒。和中助脾，除热润燥，止渴（治消渴）消痰，解酒毒，利二便（《外台方》∶嚼咽或捣汁，治发热口干便涩）。治呕哕反胃（《梅师方》∶蔗汁、姜汁和服），大便燥结（蔗汁熬之，名石蜜，即白霜糖。唐大历间，有邹和尚始传造法，性味甘温，补脾缓肝，润肺和中，消痰治嗽，多食助热损齿生虫。紫沙糖功用略同）。"},
  "甘蕉":{o:[],src:["本草纲目"],d:"旧四，新六。\n发背欲死︰芭蕉根捣烂涂之。（《肘后方》）\n一切肿毒︰方同上。\n赤游风疹︰方同上。\n风热头痛︰方同上。\n风虫牙痛︰芭蕉自然汁一碗，煎热含嗽。（《普济方》）\n天行热狂︰芭蕉根捣汁饮之。（《日华子本草》）\n消渴饮水，骨节烦热︰用生芭蕉根捣汁，时饮一、二合。（《圣惠方》）\n血淋涩痛︰芭蕉根、旱莲草各等分。水煎服，日二。（《圣惠方》）\n产后血胀︰捣芭蕉根绞汁，温服二、三合。\n疮口不合︰芭蕉根取汁，抹之良。（《直指方》）\n\n新一。\n小儿截惊︰以芭蕉汁、薄荷汁煎匀，涂头顶，留囟门，涂四肢，留手足心勿涂，甚效。（《邓笔峰杂兴》）\n叶\n\n新一。\n消或破，皆无痕也。（《仁斋直指方》）\n花"},
  "甜瓜蒂":{o:["甜瓜蒂"],src:["本草备要"],d:"宣，涌，吐。与淡豆豉、赤小豆，并为吐药\n苦寒。阳明（胃）吐药，能吐风热痰涎，上隔宿食（吐去上焦之邪，经所谓其高者因而越之。在上者涌之，木郁达之是也。越以瓜蒂、淡豉之苦，涌以赤小豆之酸，吐去上焦有形之物，则木得舒畅，天地交而万物通矣。当吐而胃弱者，代以参芦。朱丹溪曰∶吐中就有发散之义。张子和曰∶诸汗法，古方多有之，惟以吐发汗，世罕知之。故予尝曰∶吐法兼汗以此夫。昂按∶汗、吐、下、和，乃治疗之四法。仲景瓜蒂散、栀豉汤，并是吐药。子和治病，用吐尤多。丹溪治许白云大吐二十余日，治小便不通，亦用吐法，甚至用四物、四君以引吐，成法具在。今人惟知汗、下、和，而吐法绝置不用。遇邪在上焦及当吐者，不行涌越，致结塞而成坏证。轻病致重，重病致死者多矣！时医皆弃古法，枉人性命，可痛也夫），治风眩头痛，懊 不眠，癫痫喉痹，头目湿气，水肿黄胆（或合赤小豆煎，或吹鼻中，取出黄水），湿热诸病。上部无实邪者禁用（能损胃耗气，语曰∶大吐亡阳，大下亡阴。凡取吐者，须天气清明，巳午以前，令病患隔夜勿食，卒病者不拘。《类编》云∶一女子病 喘不止，遇道人教取瓜蒂七枚为末，调服其汁，即吐痰如胶粘，三进而病如扫）。"},
  "田螺":{o:["田螺"],src:["本草备要"],d:"泻热\n味甘大寒。利湿清热，止渴（消渴）醒酒，利大、小便（能引热下行。熊彦诚病前后不通，腹胀如鼓，众医莫措。遇一异人曰∶此易耳，奉施一药。即脱靴入水，探得一大螺，曰∶事济矣。以盐和壳捣碎，帛系脐下一寸三分，曾未安席，砉然暴下。归访异人，无所见矣。董守约以香港脚攻注，或教捶数螺系两股，便觉冷气趋下至足，即而亦安）。治香港脚黄胆，噤口毒痢（用螺少加麝，捣饼烘热，贴脐下，引热下行，自然思食），目热赤痛（入盐花，取汁点之），搽痔疮狐臭。"},
  "番木鳖":{o:[],src:["本草纲目"],d:"新四。\n喉痹作痛︰番木鳖、青木香、山豆根等分，为末吹之。（杨拱《医方摘要》）\n缠喉风肿︰番木鳖仁一个，木香三分，同磨水，调熊胆三分，胆矾五分。以鸡毛扫患处取效。（唐瑶《经验方》）\n疮入目︰苦实把豆儿（即马钱子）半个，轻粉、水花、银朱各五分，片脑、麝香、枯矾病欲去胎︰苦实把豆儿研膏，纳入牝户三、四寸。（《集简方》）"},
  "番红花":{o:[],src:["本草纲目"],d:"新一。\n人所传。（王玺《集要》 )"},
  "白石英":{o:["白石英"],src:["本草备要", "本草纲目"],d:"重，润肺\n甘辛微温。肺、大肠经气分之药。润以去燥，利小便，实大肠。治肺痿吐脓，咳逆上气。但系石类，祗可暂用（《十剂》曰∶湿可去枯，白石英、紫石英之属是也。湿，即润也。按∶润药颇多，石药终燥，而徐之才取二石英为润剂，存其意可取）。白如水晶者良。"},
  "白矾":{o:["白矾"],src:["本草备要"],d:"涩，燥湿，坠痰\n酸咸而寒，性涩而收。燥湿追涎，化痰坠浊，解毒生津，除风杀虫，止血定痛，通大、小便，蚀恶肉，生好肉，除痼热在骨髓（髓为热所劫则空，故骨痿而齿浮）。治惊痫黄胆，血痛喉痹，齿痛风眼，鼻中息肉，崩带脱肛，阴蚀阴挺（阴肉挺出，肝经之火），疔肿痈疽，瘰疥癣，虎、犬、蛇、虫咬伤（时珍曰∶能吐风，热痰涎，取其酸苦涌泄也；治诸血痛、阴挺、脱肛、疮疡，取其酸涩而收也；治风眼、痰饮、泄痢、崩滞，取其收而燥湿也；治喉痹、痈蛊、蛇伤，取其解毒也）。多服损心、肺，伤骨（寇宗奭曰∶劫水故也。书纸上，水不能濡，故知其性劫水也。李迅曰∶凡发背，当服蜡矾丸以护膜，防毒瓦斯内攻。矾一两，黄蜡七钱，溶化和丸。每服十丸，渐加至二十丸，日服百丸则有力。此药护膜托里、解毒化脓功甚大。以白矾、芽茶捣末冷水服，解一切毒）。取洁白光莹者， 用。又法以火 地，酒水于上、取矾布地，以盘复之。四面灰拥一日夜，矾飞盘上，扫收之，为矾精。未尽者更如前法。再以陈苦酒（醋也）化之，名矾华。七日可用，百日弥佳。甘草为使。畏麻黄。恶牡蛎（生用解毒， 用生肌）。"},
  "白芥":{o:[],src:["本草纲目"],d:"新八。\n反胃上气：白芥子末，酒服一、二钱。（《普济方》）。\n热痰烦运：白芥子、黑芥子、大戟、甘遂、芒硝、朱砂等分为末，糊丸梧子大。每服二十丸，姜汤下。名白芥丸。（《普济》）\n冷痰痞满：黑芥子、白芥子、大戟、甘遂、胡椒、桂心等分，为末，糊丸梧子大。每服十丸，姜汤下。名黑芥丸。（《普济方》）。\n腹冷气起：白芥子一升。微炒研末，汤浸蒸饼丸小豆大。每姜汤吞十丸，甚妙。（《续传信方》）。\n脚气作痛：方见白芷。\n小儿乳癖：白芥子研末，水调摊膏贴之，以平为期。（《本草权度》）。\n防痘入目：白芥子末，水调涂足心，引毒归下，令疮疹不入目。（《全幼心鉴》）。\n肿毒初起：白芥子末，醋调涂之。（《濒湖集简方》）\n胸胁痰饮：白芥子五钱，白术一两。为末，枣肉和捣，丸梧子大，每白汤服五十丸。（《摘玄方》）。"},
  "白芨":{o:[],src:["本草纲目"],d:"旧一，新八。\n鼻衄不止︰津调白芨末，涂山根上，仍以水服一钱，立止。（《经验生编》）\n重舌鹅口︰白芨末，乳汁调涂足心。（《圣惠方》）\n妇人阴脱︰白芨、川乌头等分。为末，绢裹一钱，纳阴中，入三寸，腹内热即止，日用一次。（《广济方》）\n疔疮肿毒︰白芨末半钱，以水澄之，去水，摊于浓纸上贴之。（《袖珍方》）\n打跌骨折︰酒调白芨末二钱服，其功不减自然铜、古铢钱也。（《永类方》）\n刀斧伤损︰白芨、石膏（煅）等分。为末。掺之，亦可收口。（《济急方》）\n手足皲裂︰白芨末水调塞之。勿犯水。（《济急方》）\n汤火伤灼︰白芨末，油调敷之。（《赵真人方》）"},
  "白花蛇":{o:[],src:["本草纲目"],d:"新十三。\n驱风膏︰治风瘫疠风，遍身疥癣。用白花蛇肉四两（酒炙），天麻七钱半，薄荷、荆芥各二钱半，为末。好酒二升，蜜四两，石器熬成膏。每服一盏，温汤服，日三服。急于暖处出汗，十日效。（《医垒元戎》）\n涩。或筋脉挛急，肌肉顽痹，皮肤燥痒，骨节疼痛，或生恶疮、疥癞等疾。用白花蛇一条，温水洗净，各一钱，独活、白芷、天麻、赤芍药、甘草、升麻各五钱，锉碎，以绢袋盛贮。用糯米二斗蒸熟。如常造酒，以袋置缸中，待成，取酒同袋密封，煮熟，置阴地七日出毒。每温饮数杯，常令相续。此方乃蕲人板印，以侑蛇馈送者，不知所始也。（《濒湖集简方》）\n治诸风疠癣。用白花蛇一条，酒润，去皮骨，取肉绢袋盛之。蒸糯米一斗，安曲于缸底，置蛇于曲上，以饭安蛇上，用物密盖。三七日取酒，以蛇晒干为末。每服三五分，温以浊酒并糟作饼食之，尤佳。（《瑞竹堂经验方》）\n口目 斜，肤肉 痹，骨节疼痛，及年久疥癣、恶疮、风癞诸口，黑质白花，尾有佛指甲，目光不陷者为真。以酒洗润透，去骨刺二两，当归身二两，真天麻二两，真秦艽二两，五加皮二两，防风一两盛之，入金华酒坛内，悬胎安置。入糯米生酒醅五壶浸袋，箬叶密封。安坛于大锅内，水煮一日，取起，埋阴地七日取出。每饮一、二杯。仍以滓日干碾末，酒糊丸丸，用煮酒吞下。切忌见风犯欲，及鱼、羊、鹅、面发风之物。\n阳少阴多，手足举动不快。用白花蛇二两，为细末。以银盂盛无灰酒一升浸之，重汤煮稠瓶收。每服半匙头，用好酒或白汤化服，日二次神效极佳。（《备急方》）\n花蛇五寸（酒浸，去皮、骨，炙干），雄黄一两（水飞研匀），以白沙蜜一皮研烂，同炼为膏。每服一钱，温酒化下，日三。须先服通天再造散，下根。（《三因》）\n炙去皮骨）、天南每服一钱，茶下，日净肉二钱（酒炙），雄黄二钱，大黄五钱，为末。每服二钱，白汤下，三日一服。（《家珍》）\n三蛇愈风丹︰治疠风，手足麻木，眉毛脱落，皮肤瘙痒，及一切风疮。白花蛇、乌稍蛇、土蝮蛇各一条（并酒浸，取肉晒干），苦参（头末）四两，为末，以皂角一斤切，酒以水一碗， 取浓汁，石器熬膏和，丸梧子大。每服七十丸，煎通圣散下，以粥饭压之，日三服。三日一浴，取汗避风。《治例》无蝮蛇，，发项腋之间，痒痛，憎寒发热。白花蛇（酒浸，取肉）二两（焙），生犀角一两二钱五分（镑研），黑牵牛五钱（半生半炒），青皮五钱。为末。每服二钱，入腻粉五分，五更时，糯米饮调下，利下恶毒为度。十日一服，可绝病根，忌发物。\n药，后服钱，为末，红枣肉捣，丸梧子大。每服七丸，冷茶下，日三。忌鱼肉，服尽即愈，后服土茯苓药调之。方广《心法附余》︰治杨梅疮。用花蛇肉一钱，银朱二钱，铅二钱，汞二钱，为末，作纸捻九条。每用一条，于灯盏内香油浸，点灯安烘炉里，放被中，盖卧熏之，勿透风。一日三次。托痘花蛇散︰治痘疮黑陷。白花蛇（连骨炙，勿令焦）三钱，大丁香七枚，为末。\n每服五分，以水和淡酒下，神效。移时身上发热，其疮顿出红活也。（王氏《手集》）\n头\n\n新一。\n紫癜风︰除风散︰以白花蛇头二枚（酒浸，炙），蝎梢一两（炒），防风一两，上为末。\n每服一\n目睛"},
  "白芷香":{o:[],src:["本草纲目"],d:"旧一，新三十四。一切伤寒︰神白散，又名圣僧散︰治时行一切伤寒，不问阴阳轻重、老少男女孕妇，皆可服之。用白芷一两，生甘草半两，姜三片，葱白三寸，枣一枚，豉五十粒。水二碗，煎服取汗。不汗再服。病至十余日未得汗者，皆可服之。此药可卜人之好恶也。如煎得黑色，或误打翻，即难愈；如煎得黄色，无不愈者。煎时要至诚，忌妇人鸡犬见。（《卫生家宝方》）\n一切风邪︰方同上。风寒流涕︰香白芷一两，荆芥穗一钱。为末，蜡茶点服二钱。（《百一选方》）\n小儿流涕，是风寒也。白芷末、葱白。捣丸小豆大。每茶下二十丸。仍以白芷末，姜汁调，涂太阳穴，乃食热葱粥取汗。（《圣惠方》）\n小儿身热︰白芷煮汤浴之。取汗避风。（《子母秘录》）\n头面诸风︰香白芷切，以萝卜汁浸透，晒干为末。每服二钱，白汤下。或以搐鼻。（《直指方》）\n偏正头风，百药不治，一服便可，天下第一方也。香白芷（炒）二两五钱，川芎（炒）、甘草（炒）、川乌头（半生半熟）各一两，为末。每服一钱，细茶、薄荷汤调下。（《谈野翁试效方》）\n头风眩运︰都梁丸，见发明下。眉棱骨痛︰属风热与痰。白芷、片芩（酒炒）等分，为末。每服二钱，茶清调下。（《丹溪纂要》）\n风热牙痛︰香白芷一钱，朱砂五分。为末，蜜丸芡子大。频用擦牙。此乃濠州一村妇以医人者，庐州郭医云︰绝胜他药也。或以白芷、吴茱萸等分。浸水漱涎。（《医林集要》）\n一切眼疾︰白芷、雄黄为末，炼蜜丸龙眼大，朱砂为衣。每服一丸，食后茶下，日二服。名还睛丸。（《普济方》）\n口齿气臭︰《百一选方》︰用香白芷七钱。为末。食后井水服一钱。《济生方》︰用白芷、川芎等分。为末，蜜丸芡子大，日噙之。盗汗不止︰太平白芷一两，辰砂半两。为末。每服二钱，温酒下，屡验。（《朱氏集验方》）\n血风反胃︰香白芷一两（切片，瓦炒黄）。为末。用猪血七片，沸汤泡七次，蘸末食之，日一次。（《妇人良方》）\n脚气肿痛︰白芷、芥子等分，为末。姜汁和，涂之效。（《医方摘要》）\n妇人白带︰白芷四两，以锻石半斤，淹三宿，去灰切片，炒研末。酒服二钱，日二服。（《医学集成》）\n妇人难产︰白芷五钱，水煎服之。（唐瑶《经验》）\n胎前产后 乌金散︰治胎前产后虚损，月经不调，崩漏及横生逆产。用白芷、百草霜等分。为末。以沸汤入童子小便同醋调服二钱。丹溪加滑石，以芎归汤调之。（《普济方》）\n大便风秘︰香白芷。炒，为末。每服二钱，米饮入蜜少许，连进二服。（《十便良方》）\n小便气淋，结涩不通。白芷（醋浸焙干）二两，为末。煎木通、甘草，酒调下一钱，连进二服。（《普济方》）\n鼻衄不止︰就以所出血调白芷末，涂山根，立止。（《简便方》）\n小便出血︰白芷、当归等分，为末，米饮每服二钱。（《经验方》）\n肠风下血︰香白芷为末，每服二钱，米饮下，神效。（余居士《选奇方》）\n痔漏出血︰方同上，并煎汤熏洗。（《直指方》）\n痔疮肿痛︰先以皂角烟熏之，后以鹅胆汁调白芷末涂之，即消。（《医方摘要》）\n肿毒热痛︰醋调白芷末敷之。（《卫生易简方》）\n乳痈初起白芷、贝母各二钱。为末，温酒服之。（《秘传外科方》）\n疔疮初起︰白芷一钱，生姜一两。擂酒一盏，温服取汗，即散。此陈指挥方也。（《袖珍方》）\n痈疽赤肿︰白芷、大黄等分。为末，米饮服二钱。（《经验方》）\n小儿丹瘤，游走入腹必死。初发，急以截风散截之。白芷、寒水石为末，生葱汁调涂。（《全幼心鉴》）\n刀箭伤疮︰香白芷嚼烂涂之。（《集简方》）\n解砒石毒︰白芷末，井水服二钱。（《事林广记》）\n诸骨哽咽︰白芷、半夏等分。为末。水服一钱，即呕出。（《普济方》）\n毒蛇伤螫︰临川有人被蝮伤，即昏死，一臂如股，少顷遍身皮胀，黄黑色。一道人以新汲水调香白芷末一斤，灌之。觉脐中 然，黄水自口出，腥秽逆人，良久消缩如故云。以麦门冬汤调尤妙，仍以末搽之。又经山寺僧为蛇伤，一脚溃烂，百药不愈。一游僧以新水数洗净腐败，见白筋、挹干，以白芷末，入胆矾、麝香少许掺之，恶水涌出。日日如此，一月平复。（洪迈《夷坚志》）\n叶\n\n新一。\n小儿身热︰白芷苗、苦参等分。煎浆水，入盐少许洗之。（《卫生总微论》）"},
  "白苣":{o:[],src:["本草纲目"],d:"旧一。\n鱼脐疮，其头白似肿，痛不可忍︰先以针刺破头及四畔，以白苣取汁滴孔中，良。（《外台秘要》）"},
  "白英":{o:[],src:["本草纲目"],d:"新一。目赤头旋，眼花面肿，风热上攻︰用排风子（焙）、甘草（炙）、菊花（焙）各一两。为末。每服二钱，卧时温水下。（《圣济录》）"},
  "白茅":{o:[],src:["本草纲目"],d:"旧二，新一十三。山中辟谷：凡辟难无人之境，取白茅根冼净，咀嚼，或石上晒焦捣末，水服方寸匕，可辟谷不饥。（《肘后方》）\n温病冷 ：因热甚饮水成暴冷 者。茅根（切）、枇杷叶（拭去毛，炙香）各半斤。水四升，煎二升，去滓，稍热饮之。（庞安常《伤寒总病论》）\n温病热哕：乃伏热在胃，令人胸满则气逆，逆则哕，或大下后，胃中虚冷，亦致哕也。茅反胃上气，食入即吐。茅根、芦根二两。水四升，煮二升，顿服得下，良。（《圣济总录肺热气喘：生茅根一握。 咀，水二盏，煎一盏，食后温服。甚者三服止，名如神汤。（虚后水肿：因饮水多，小便不利。用白茅根一大把，小豆三升。水三升，煮干，去茅食豆，水随小便下也。（《肘后方》）\n五种黄病：黄胆、谷疸、酒疸、女疸、劳疸也。黄汗者，乃大汗出入水所致，身体微肿，汗出如黄柏汁。用生茅根一把，细切，以猪肉一斤，合作羹食。（《肘后》）\n解中酒毒，恐烂五脏。茅根汁，饮一升。（《千金方》）\n小便热淋：白茅根四升，水一斗五升，煮取五升，适冷暖饮之，日三服。（《肘后方》）\n小便出血：茅根煎汤，频饮为佳。（《谈野翁方》）\n劳伤溺血：茅根、干姜等分。入蜜一匙，水二钟，煎一钟，日一服。鼻衄不止：茅根为末，米泔水服二钱。（《圣惠方》）\n吐血不止：《千金翼》：用白茅根一握，水煎服之。《妇人良方》：用根洗捣汁，日饮一合。竹木入肉：白茅根烧末，猪脂和涂之。风入成肿者，亦良。（《肘后方》）\n茅针（即初生苗也。（《拾遗》）\n\n新三。\n妇人阴痒：墙头烂茅、荆芥、牙皂等分。煎水频熏洗之。（《摘玄方》）\n大便闭塞，服药不通者。沧盐三钱，屋檐烂草节七个。为末。每用一钱，竹筒吹入肛内一寸即通，名提金散。（《圣济录》）\n卒中五尸：其状腹痛胀急，不得气息，上冲心胸，旁攻两胁，或 涌起，或牵引腰脊，此乃身中尸鬼接引为害。取屋上四角茅，入铜器中，以三赤布覆腹，著器布上，烧茅令热，随痛追逐，跖下痒即瘥也。（《肘后方》）"},
  "白药子":{o:[],src:["本草纲目"],d:"旧三，新九。\n天行热病︰白药为末，浆水一盏，冷调二钱服，仰卧少顷，心闷或腹鸣 痛，当吐利数行。如不止，吃冷粥一碗止之。（崔元亮《海上方》）\n心痛解热︰白药根、野猪尾（二味，洗去粗皮，焙干）等分。捣筛。酒服一钱。甚效。黔人用之。（苏颂《图经》）\n为末），防风末三两。和匀。每茶服一钱。（《圣惠方》）\n喉中热塞肿痛，散血消痰︰白药、朴硝等分。为末。吹之，日四、五次。（《直指方》）\n咽喉肿痛︰白药末一两，龙脑一分，蜜和丸芡子大。每含咽一丸。（《圣惠方》）\n吐血不止︰白药烧存性糯米饮服三钱。（《圣惠方》）\n衄血不止︰红枣、白药各（烧存性）等分。为末。糯米饮服。或煎汤洗鼻，频频缩药令入。（《经验良方》）\n汤下。心烦热，入砂糖少许。（《圣惠方》）\n肝一具，批开掺末五钱，煮熟食之。（《直指方》）\n小儿疳泻吐利︰方同上。\n诸骨哽咽︰白药，煎米醋细咽。在上即吐出，在下即下出。（《普济方》）\n痈肿不散︰生白药根捣贴，干则易之。无生者，研末水和贴。（《图经》）"},
  "白蒿":{o:[],src:["本草纲目"],d:"旧一。恶疮癞疾，但是恶疾遍体，面目有疮者，皆可服之︰用白艾蒿十束如升大，煮取汁，以曲及米一如酿酒法，候熟稍服之。（《深师方》）\n子"},
  "白蔹":{o:["白蔹"],src:["本草备要", "本草纲目"],d:"泻火，散结\n苦能泄，辛能散，甘能缓，寒能除热。杀火毒，散结气，生肌止痛。治痈疽疮肿，面上 疮，金疮扑损（箭镞不出者，同丹皮或半夏为末，酒服），敛疮方多用之（故名，每与白芨相须），搽冻耳（同黄柏末油调）。蔓赤，枝有五叶，根如卵而长，三五枝同窠，皮乌肉白。一种赤蔹，功用皆用（郑奠一曰∶能治温疟血痢，肠风痔 ，赤白带下）。"},
  "白藓":{o:[],src:["本草纲目"],d:"旧一，新一。\n鼠 已破，出脓血者。白藓皮煮汁，服一升，当吐若鼠子也。（《肘后方》）\n产后中风，人虚不可服他药者。一物白藓皮汤，用新汲水三升，煮取一升，温服。（陈延之《短剧方》）"},
  "白藓皮":{o:["白藓皮"],src:["本草备要"],d:"通，祛风湿\n气寒善行，味苦性燥（行水故燥）。入脾、胃除湿热，兼入膀胱、小肠。行水道，通关节，利九窍。为诸黄、风痹之要药（一味白藓皮汤，治产后风。时珍曰∶世医止施之疮科，浅矣）。兼治风疮疥癣，女子阴中肿痛（湿热乘虚客肾与膀胱所致）。根黄白而心实。取皮用。恶桑螵蛸、桔梗、茯苓、萆 。"},
  "白蜡":{o:["白蜡"],src:["本草备要"],d:"外用生肌\n甘温属金。生肌止血（郑赞寰曰∶汪御章年十六，常患尿血，屡医不效。予以白蜡加入冲血滋肾药中，遂愈），定痛补虚，续筋接骨，外科要药。"},
  "白马溺":{o:["白马溺"],src:["本草备要"],d:"泻，杀虫，消症\n辛寒。杀虫，破症积，治反胃，（祖台之志怪云∶昔有人与奴皆患心腹痛病，奴死，剖之得一鳖，尚活。以诸药投口中，不死。有人乘白马观之，马溺坠鳖而鳖缩，遂以灌之，即化成水。主乃服马溺而愈）。"},
  "白龙须":{o:[],src:["本草纲目"],d:"新一。\n诸风瘫痪，筋骨不收︰用白龙须根皮一两，闹羊花（即老虎花）七分，好烧酒三斤，封固，煮一炷香，埋土中一夜。能饮者三杯，不能饮者一杯，卧时服。服至三、五杯，见效。但知痛者可治。（坦仙《皆效方》）"},
  "百棱藤":{o:[],src:["本草纲目"],d:"新三。\n头风脑痛︰百灵藤十斤，水一石，煎汁三斗，入糯米三斗作饭。候冷，拌神曲炒末九两，同入瓮中，如常酿酒。经三、五日，看沫尽，更炊一斗糯米饭冷投之，待熟澄清。每温饮一小盏，服后浑身汗出为效。（《圣惠方》）\n一切风痹，不拘久近︰百灵藤五斤，水三斗，煎一斗，滤汁再煎至三升，入牛膝、附子、仙灵脾、赤箭、何首乌、乳香、鹿角胶各二两，为末，同煎，别入白蜜五合，熬如饧状，瓷瓶收之。每服一匙，温酒下，一日二服。忌毒物、滑物。（《圣惠方》）\n大风疮疾︰百灵藤四两。水一斗，煮三升，去滓，入粳米四合煮粥。于密室中浴毕乃食，暧卧取汗。汗后，皮肤起如麸片。每隔日一作，五、六十日后渐愈，毛发即生。（《圣惠方》）"},
  "百沸汤":{o:["百沸汤"],src:["本草备要"],d:"宣，助阳气\n助阳气，行经络（汪颖曰∶汤须百沸者佳。寇宗奭曰∶患风冷气痹，人以汤淋脚至膝，浓复取汗，然别有药，特假阳气而行耳。四时暴泻痢，四肢、脐、腹冷，坐深汤中，浸至腹上，生阳之药，无速于此。张从正曰∶凡伤风寒、酒食，初起无病，便饮太和汤。或酸荠水揉肚探吐，汗出即已。昂按∶感冒风寒，而以热汤澡浴，亦发散之一法。故《内经》亦有可汤熨、可浴及摩之、浴之之文。《备急方》治心腹卒胀痛，欲死，煮热汤以渍手足，冷即易之）。"},
  "百草霜":{o:["百草霜"],src:["本草备要"],d:"轻，止血，消积\n辛温。止血（鼻衄者，水调涂之。红见黑则止，水克火也）消积。治诸血病，伤寒阳毒、发斑，疸膈疟痢，咽喉、口舌、白秃、诸疮（时珍曰∶皆兼取火化从治之法）。灶突上烟煤。"},
  "皂矾":{o:["皂矾"],src:["本草备要"],d:"（一名绿矾）\n涩，燥湿，化痰酸涌涩收。燥湿化痰、解毒杀虫之功与石矾同，而力差缓。主治略同白矾，利小便，消食积（同健脾消食药为丸），散喉痹（醋调咽汁。时珍曰∶胀满、黄肿、疟痢、疳疾方往往用之。其源则自仲景用矾石硝石治女劳黄胆方中变化而来）。深青莹净者良。 赤用（ 赤名绛矾，能入血分，伐肝木，燥脾湿。张三丰治肿满，有伐木丸。苍术二斤，米泔浸，黄酒，面曲四两炒，绛矾一斤，醋拌晒干，入瓶。火 为末，醋糊丸，酒下。或去皂矾乃铜之精液，用醋制以平肝，胜于针铁。不必忌盐，后亦不发。多服令人泻）。"},
  "皂角":{o:["皂角"],src:["本草备要"],d:"通关窍，搜风\n辛咸性燥，气浮而散。入肺、大肠经。金胜木，燥胜风，故兼入肝。搜风泄热，吹之导之，则通上、下关窍，而涌吐痰涎，搐鼻立作喷嚏。治中风口噤，胸痹喉痹（凡中风不省人事，口噤不能进药。急提头发，手掐人中，用皂角末或半夏末吹入鼻中，有嚏者生，无嚏者肺气已绝，死。或用稀涎散吐之，皂角末一两，白矾五钱，每用一钱，温水调灌。或加藜芦、少麝，鹅翎探喉，令微吐稀涎，再用药治。年老、气虚人忌用）。服之则除湿去垢（最去油腻，刮人肠胃），消痰破坚（取中段，汤泡服，治老人风秘），杀虫下胎。治风湿风癞，痰喘肿满，坚症囊结（厥阴肝脉络阴器。寒客肝经，则为囊结）。涂之则散肿消毒，煎膏贴一切痹痛。合苍术焚之，辟瘟疫湿气。一种小如猪牙，一种长而枯燥，一种肥浓多脂。多脂者良。去粗皮、子弦。或蜜炙、酥炙，绞汁烧灰用。柏实为使，恶麦冬。畏人参、苦参（性能消铁，不结荚者，凿树一孔，八铁封之，则结荚矣。锤碾见之，久则成孔，故此木不能烧爨）。皂角刺辛温。搜风杀虫，功同皂荚。但其锋锐，能直达患处，溃散痈疽。治痈毒妒乳，风厉恶疮（痈，同癞。疠乃营气热附，风寒客于脉而不去。经曰∶脉风成为疠。脉与营皆血也。蒸晒为末，大黄汤调下）胎衣不下。痈疽已溃者禁用，孕妇忌之。皂角子通大便燥结。 存性用（汪机曰∶其性得湿则滑。李时珍曰∶亦辛以润之之义，非得湿则滑也）。"},
  "皂角蕈":{o:[],src:["本草纲目"],d:"新一。\n肠风泻血︰皂角树上蕈，瓦焙为末。每服一钱，温酒下。（许学士《本事方》）"},
  "皮":{o:["皮"],src:["本草备要"],d:"泻，凉血\n苦平。治肠风泻血，五痔（烧末，油调敷，水服亦佳）阴肿。脂滴耳中治聋。胆点痘后风眼。似鼠而圆大，褐色，攒毛，外刺如栗房。 黑存性用。"},
  "益智子":{o:[],src:["本草纲目"],d:"新八。\n小便频数，脬气不足也。雷州益智子（盐炒，去盐）、天台乌药等分，为末，酒煮山药粉为糊，丸如梧子大。每服七十丸，空心盐汤下。名缩泉丸。（《朱氏集验方》）\n心虚尿滑，及赤白二浊。益智子仁、白茯苓、白术等分，为末。每服三钱，白汤调下。白浊腹满，不拘男妇。用益智仁（盐水浸炒）、浓朴（姜汁炒）等分，姜三片，枣一枚，水煎服。（《永类钤方》）\n小便赤浊︰益智子仁、茯神各二两，远志、甘草（水煮）各半斤，为末，酒糊丸梧子大，空心姜汤下五十丸。腹胀忽泻日夜不止，诸药不效，此气脱也。用益智子仁二两，浓煎饮之，立愈。（危氏《得效方》）\n妇人崩中︰益智子炒碾细。米饮入盐，服一钱。（《产宝》）\n香口辟臭︰益智子仁一两，甘草二钱。碾粉舐之。（《经验良方》）\n漏胎下血︰益智仁半两，缩砂仁一两。为末。每服三钱，空心白汤下，日二服。（胡氏\n《济阴方》）"},
  "省藤":{o:[],src:["本草纲目"],d:"新一。\n五淋涩痛︰赤藤（即做草鞋者）、白茯苓、苎麻根等分，为末。百沸汤下，每服一钱，如神"},
  "石":{o:["石"],src:["本草备要"],d:"重，燥，祛寒积\n辛热，有大毒。治坚癖痼冷，寒湿风痹（苏恭曰∶攻寒冷之病最良。《别录》曰∶不炼服，杀人。此石生于山无雪，入水不冰。时珍曰∶性气与砒石相近。《博物志》言∶鹳伏卵时，取此石暖足。谬也）。有疮、白数种，火烧但解散，不能脱其坚。置水不冻者真。恶羊血。"},
  "石南叶":{o:["石南叶"],src:["本草备要"],d:"宣，去风，补肾\n辛散风、苦坚肾。补内伤阴衰，利筋骨皮毛，为治肾虚、脚弱、风痹要药。妇人不可久服，令思男（时珍曰∶今人绝不知用，盖为《药性论》有令人阴痿之说也。不知此药能令肾强，人或借此纵欲，以致痿弱，归咎于药，良可慨也。昂按∶石南补阴祛风则有之，然味辛不热，不助相火，亦未闻淫邪方中用石南者，《别录》思男之说，殆不可信）。关中者佳。炙用。"},
  "石榴皮":{o:["石榴皮"],src:["本草备要"],d:"涩肠，外用染须\n酸涩而温。能涩肠，止泻痢下血（ 末服），崩带脱肛（泻痢至于脱肛者，以石榴皮、陈壁土加明矾少许，浓煎熏洗，再用五倍子炒研、敷托而止之）。浸水，汁黑如墨，乌须方绿云油中用之。勿犯铁器（《客座新闻》云∶一人患腹胀，夏成诊曰∶饮食如常，非水肿蛊胀，乃湿热生虫之象也。以石榴、椿树东引根皮、槟榔各五钱，空心服，腹大痛，泻虫长丈余，遂愈）。"},
  "石灰":{o:["石灰"],src:["本草备要"],d:"重，燥湿，止血，生肌\n辛温性烈。能坚物散血，定痛生肌，止金疮血（腊月用黄牛胆汁和，纳胆中，阴干用），杀疮虫（有人脚肚生一疮，久遂成漏，百药不效，自度必死。一村人见之曰∶此鳝漏也。以锻石温泡、熏洗、觉痒即是也。洗不数次，遂愈）蚀恶肉，无瘢疵（和药点痣）解酒酸（酒家多用之，然有灰之酒伤人），内用止泻痢、崩带，收阴挺（阴肉挺出，亦名阴菌，或产后玉门不闭。熬黄水泡，澄清暖洗）、脱肛，消积聚、结核。风化者良。圹灰，火毒已出，主顽疮、脓水淋漓，敛口尤妙。"},
  "石炭":{o:[],src:["本草纲目"],d:"新五。\n金疮出血︰急以石炭末浓敷之。疮深不宜速合者，加滑石。（《医学集成》）\n误吞金银及钱，在腹中不下者。光明石炭一杏核大，硫黄一皂子大。为末，酒下。（《普济方》）\n腹中积滞︰乌金石（即铁炭也）三两，自然铜（为末醋熬）一两，当归一两，大黄（童尿浸晒）一两。为末。每服二钱，红花酒一盏，童尿半盏，同调，食前服，日二服。（张子和\n《儒门事亲》）\n月经不通︰巴豆去油，如绿豆大三丸，以乌金石末一钱，调汤送下，即通。（《卫生易简方》）\n产后儿枕刺痛︰黑白散︰用乌金石（烧酒淬七次）、寒水石（ 为末）等分。每用粥饮服一钱半，即止，未止再服。（洁古《保命集》）"},
  "石燕":{o:[],src:["本草纲目"],d:"（《日华》）\n【释名】\n土燕（《纲目》）。\n【集解】\n诜曰︰石燕在乳穴石洞中者。冬月采之，堪食。余月，只可治病。\n炳曰︰石燕似蝙蝠，口方，食石乳汁。\n时珍曰︰此非石部之石燕也。《广志》云︰燕有三种，此则土燕乳于岩穴者是矣。\n肉\n【气味】\n甘，暖，无毒。\n【主治】\n壮阳，暖腰膝，添精补髓，益气，润皮肤，缩小便，御风寒、岚瘴、温疫气。（《日华》。诜曰︰治法︰取石燕二七枚，和五味炒熟，以酒一斗浸三日。每夜卧时饮一、二盏，甚能补益，令人健力能食）。"},
  "石硫赤":{o:[],src:["本草纲目"],d:"新二。赤鼻作痛︰紫色石亭脂，红色次之，黄色勿用。研末，冷水调搽，半月绝根。（《圣济录》）\n风湿脚气︰石亭脂（生用）一两，川乌头（生）一两，无名异二两。为末，葱白自然汁和丸梧子大。每服一钱，空心淡茶、生葱吞下，日一服。（《瑞竹堂方》）"},
  "石硫黄":{o:["石硫黄"],src:["本草备要", "本草纲目"],d:"燥，补阳，杀虫\n味酸有毒。大热纯阳（硫黄阳精极热，与大黄极寒，并号将军），补命门真火不足。性虽热而疏利大肠，与燥涩者不同（热药多秘，惟硫黄暖而能通；寒药多泄，惟黄连肥汤而止泻），若阳气暴绝，阳毒伤寒，久患寒泻，脾胃虚寒，命欲垂尽者用之，亦救危妙药也。治寒痹冷癖，足寒无力，老人虚秘（《局方》用半硫丸），妇人阴蚀，小儿慢惊。暖精壮阳，杀虫疗疮，辟鬼魅，化五金，能干汞（王好古曰∶太白丹、来复丹皆用硫黄佐以硝石∶至阳佐以至阳，与仲景白通汤佐以人尿、猪胆汁意同。所以治内伤生冷，外冒暑湿、霍乱诸病。能除扦格之寒，兼有伏阳，不得不尔。如无伏阳，只是阴虚，更不必以阴药佐之。《夷坚志》云∶唐与正亦知医，能以意治病。吴巡检病不得溲，卧则微通，立则不能涓滴，遍用通药不效。唐问其平日自制黑锡丹常服，因悟曰∶此必结砂时，硫飞去，铅不死，铅砂入膀胱，卧则偏重犹可溲，立则正塞水道故不通。取金液丹三百粒，分十服，瞿麦汤下，铅得硫则化，水道遂通。家母舅童时亦病溺涩，服通淋药罔效，老医黄五聚视之曰∶此乃外皮窍小，故溺时艰难，非淋症也。以牛骨作楔，塞于皮端，窍渐展开，勿药而愈。使重服通利药，得不更变他证乎？乃知医理非一端也。硫能化铅为水，修炼家尊之为金液丹）。番舶者良（难得）。取色黄坚如石者，以莱菔剜空，入硫合定，糠火煨熟，去其臭气，以紫背浮萍煮过，消其火毒，以皂荚汤淘其黑浆。一法绢袋盛，酒煮三日夜。一法入猪大肠烂煮三时用。畏细辛、诸血、醋。土硫黄辛热、腥臭，只可入疮药，不可服饵。"},
  "石耳":{o:[],src:["本草纲目"],d:"新一。\n泻血脱肛︰石耳五两（炒），白枯矾一两，密陀僧半两，为末，蒸饼丸梧子大，每米饮下二十丸。（《普济方》）\n互考诸菜\n香薷 紫苏 紫菀 錾菜 牛膝苗 防风苗 薄荷 荏苏 马兰 蒌蒿 泽兰根 地黄苗 诸葵 菜 酸模 菖蒲 牛蒡苗 青葙苗 龙葵 决明 甘蓝 萝 红花苗 车前苗 萱草 芦笋 茭笋 苹 海苔菜 独帚苗 羊蹄 蒲笋 菜 齐头蒿 昆布苗 昆布 地菘 蓼芽 海藻 王瓜 百部 藕丝 荷 头 芡茎 菱茎 豆藿 豆芽 豆荚 豆腐 罂粟苗 椿芽 槐芽 芜荑 枸杞 皂荚苗 榆芽 槿芽 棕笋 五加\n:蔬菜"},
  "石胆":{o:[],src:["本草纲目"],d:"旧五，新一十五。老小风痰︰胆矾末一钱。小儿一字，温醋汤调下，立吐出涎，便醒。（谭氏小儿方）女人头晕，天地转动，名曰心眩，非血风也。胆子矾一两。细研，用胡饼剂子一个，按平一指浓，以篦子勒成骰子，大块勿界断，于瓦上焙干。每服一骰子，为末，灯心竹茹汤调下。（许学士《本事方》）\n喉痹喉风︰二圣散︰用鸭嘴胆矾二钱半，白僵蚕（炒）五钱。研。每以少许吹之，吐涎。（《济生方》）\n齿痛及落︰研细石胆，以人乳和膏擦之，日三、四次。止痛，复生齿，百日后复故乃止。每日以新汲水漱净。（王焘《外台秘要》）\n口舌生疮，众疗不瘥︰胆矾半两，入银锅内火 赤，出毒一夜，细研。每以少许敷之，吐出酸涎水，二、三次瘥。（《胜金方》）\n走马牙疳︰北枣一枚（去核），入鸭觜胆矾。纸包 赤，出火毒，研末敷之，追涎。（杨起《简便方》）\n小儿齿疳︰鸭觜胆矾一钱（匙上 红），麝香少许。研匀。敷齿上，立效。（《活幼口议》）\n小儿鼻疳蚀烂︰胆矾烧烟尽，研末。掺之，一、二日愈。（《集简方》）\n风眼赤烂︰胆矾三钱。烧研。泡汤日洗。（《明目经验方》）\n百虫入耳︰胆矾末，和醋灌之，即出。（《千金方》）\n疯犬咬毒︰胆矾末敷之，立愈。（《济急方》）\n一切诸毒︰胆子矾末，糯米糊丸如鸡头子大，以朱砂为衣，仍以朱砂养之。冷水化一丸服，立愈。（《胜金方》）\n挑生蛊毒，胸口痛者︰胆矾二钱，茶清泡服，即吐出。（《岭南卫生方》）\n腋下狐臭︰胆矾半生半熟，入腻粉少许，为末。每用半钱，以自然姜汁调涂，十分热痛乃止。数日一用，以愈为度。（黎居士《简易方》）\n赤白癜风︰胆矾、牡蛎粉各半两。生研，醋调，摩之。（《圣济录》）\n甲疽肿痛︰石胆一两。烧烟尽，研末。敷之，不过四、五度瘥。（《梅师方》）\n痔疮热肿︰鸭觜青胆矾 研，蜜水调敷，可以消脱。（《直指方》）\n肿毒不破︰胆矾、雀屎各少许。点之。（《直指方》）\n杨梅毒疮︰醋调胆矾末搽之。痛甚者，加乳香、没药。出恶水，一、二上即干。又方︰胆矾、白矾、水银各三钱半。研不见星，入香油、津唾各少许，和匀。坐帐内，取药涂两足心，以两手心对足心摩擦，良久再涂再擦，尽即卧。汗出，或大便去垢，口出秽涎为验。每一次，强者用四钱，弱者二钱，连用三日。外服疏风散，并澡洗。（《刘氏经验方》）"},
  "石胡荽":{o:[],src:["本草纲目"],d:"新十。\n寒痰齁喘︰野园荽研汁，和酒服，即住。（《集简方》）。\n鼻去翳︰碧云散︰治目赤肿胀，羞明昏暗，隐涩疼痛，眵泪风痒，鼻塞头痛脑酸，外翳扳睛诸病。鹅不食草（晒干）二钱，青黛、川芎各一钱，为细末。噙水一口，每以米许入鼻内，泪出为度。\n一方︰去青黛。（倪氏《启微集》）。贴目取翳︰鹅不食草（捣汁熬膏）一两，炉甘石（火煅，童便淬三次）三钱，上等瓷器末一钱半，熊胆二钱，硇砂少许，为极细末，和作膏。贴在翳上，一夜取下。用黄连、黄柏煎汤洗净，看如有，再贴。（孙天仁《集效方》）\n塞鼻治翳︰诗见发明。\n牙疼㗜鼻︰鹅不食草绵裹怀干为末。含水一口，随左右㗜之。亦可挼塞。（《圣济》）。\n一切肿毒︰野园荽一把，穿山甲（烧存性）七分，当归尾三钱，擂烂，入酒一碗，绞汁服。\n湿毒胫疮︰砖缝中生出野园荽，夏月采取，晒收为末。每以五钱，汞粉五分，桐油调作隔纸膏，周遭缝定。以茶洗净，缚上膏药，黄水出，五、六日愈。此吴竹卿方也。（《简便方》）。\n脾寒疟疾︰石胡荽一把。杵汁半碗，入酒半碗和服，甚效。（《集简方》）。\n痔疮肿痛︰石胡荽捣，贴之。（同上）"},
  "石蒜":{o:[],src:["本草纲目"],d:"新三。\n便毒诸疮：一枝箭，捣烂涂之即消。若毒太甚者，冼净，以生白酒煎服，得微汗即愈。（王永辅《济世方》）\n产肠脱下：老鸦蒜（即酸头草）一把。以水三碗，煎一碗半，去滓熏洗，神效。（危氏《得效方》）\n小儿惊风：大叫一声就死者，名老鸦惊。以散麻缠住胁下及手心足心，以灯火爆之。用老鸦蒜（晒干）、车前子等分，为末，水调贴手足心。仍以灯心淬手足心，及肩膊、眉心、鼻"},
  "石蟹":{o:["石蟹"],src:["本草备要", "本草纲目"],d:"重，泻，明目\n咸寒。治青盲目翳，天行热疾，解一切金石药毒。醋磨，敷痈肿。出南海。身全是蟹，而质石也。细研，水飞用。"},
  "石钟乳":{o:[],src:["本草纲目"],d:"新十一。李补阙服乳法︰主五劳七伤，咳逆上气，治寒嗽，通音声，明目益精，安五脏，通百节，利九窍，下乳汁，益气补虚损，疗脚弱疼冷，下焦伤竭，强阴，久服延年益寿不老，令人有子。取韶州钟乳，无问浓薄，但颜色明净光泽者，即堪入炼；惟黄、赤二色，不任用。置于金、银器中，大铛著水，沉器煮之，令如鱼眼沸，水减即添。乳少，三日三夜；乳多，七日七夜。候干，色变黄白即熟。如疑生，更煮满十日最佳。取出去水，更以清水煮半日，其水色清不变即止，乳无毒矣。入瓷钵中，玉槌著水研之。觉干涩，即添水，常令如稀米泔状。研至四、五日，揩之光腻，如书中白鱼，便以水洗之，不随水落者即熟，落者更研，乃澄取曝干。每用一钱半，温酒空腹调下，兼和丸散用。其煮乳黄浊水，切勿服。服之损人咽喉，伤肺，令人头痛，或下利不止。其有犯者，但食猪肉解之。（孙真人《千金方》）\n钟乳煎︰治风虚劳损，腰脚无力，补益强壮。用钟乳粉炼成者三两，以夹练袋盛之，牛乳一大升，煎减三之一，去袋饮乳，分二服，日一作。不吐不利，虚冷人微溏无苦。一袋可煮三十度，即力尽，别作袋。每煎讫，须濯净，令通气。其滓和面喂鸡，生子食之。此崔尚书方也。（孙真人《千金翼》）\n钟乳酒︰安五脏，通百节，利九窍，主风虚，补下焦，益精明目。钟乳炼成粉五两，以夹练袋盛之，清酒六升，瓶封，汤内煮减三之二，取出添满，封七日，日饮三合。忌房事、葱、豉、生食、硬食。（《外台秘要》）\n钟乳丸︰治丈夫衰老，阳绝肢冷，少气减食，腰疼脚痹，下气消食，和中长肌。钟乳粉二两，菟丝子（酒浸焙）、石斛各一两，吴茱萸（汤泡七次，炒）半两。为末，炼蜜和丸梧子大。每服七丸，空心温酒或米汤下，日二服。服讫行数百步，觉胸口热，稍定即食干饭豆酱。忌食粗臭恶食，及闻尸秽等气。初服七日，勿为阳事，过七日乃可行，不宜伤多。服过半剂，觉有功，乃续服。此曹公卓方也。（《和剂局方》）\n元气虚寒︰方见阳起石下。一切劳嗽，胸膈痞满︰焚香透膈散︰用鹅管石、雄黄、佛耳草、款冬花等分。为末。每用一钱，安香炉上焚之，以筒吹烟入喉中，日二次。（《宣明》）\n肺虚喘急，连绵不息︰生钟乳粉（光明者）五钱，蜡三两（化和）。饭甑内蒸熟，研丸梧子大。每温水下一丸。（《圣济录》）\n吐血损肺︰炼成钟乳粉，每服二钱，糯米汤下，立止。（《十便良方》）\n大肠冷滑不止︰钟乳粉一两，肉豆寇（煨）半两。为末，煮枣肉丸梧子大。每服七十丸，空心米饮下。（《济生方》）\n乳汁不通︰气少血衰，脉涩不行，故乳少也。炼成钟乳粉二钱，浓煎漏芦汤调下。或与通草等分为末，米饮服方寸匕，日三次。（《外台秘要》）\n精滑不禁，大腑溏泄，手足厥冷。方见阳起石下。"},
  "石首鱼":{o:["石首鱼"],src:["本草备要", "本草纲目"],d:"补，调胃\n甘平。开胃消食，治暴痢腹胀（《菽园杂记》曰∶痢疾最忌油腻、生冷，惟白鲞相宜。以其无脂不腻，而能消宿食、理肠胃也）。即干白鱼鲞，首中有石，故名（石治石淋。昂按∶今人多以石首鱼鳔合破故纸等药为丸，名鱼鳔丸，云暖精种子。而《本草》全未之及，何也）。"},
  "石龙子":{o:[],src:["本草纲目"],d:"新二。\n小儿阴 ︰用蜥蜴一枚烧灰，酒服。（《外台秘要》）\n诸 不愈︰用蜥蜴（炙）三枚，地胆（炒）三十枚，斑蝥（炒）四十枚，为末，蜜丸小豆大。每服二丸，白汤下。治诸法不效者。（《刘涓子鬼遗方》）\n肝\n\n去生胎︰蜥蜴肝、蛇脱皮等分，以苦酒和匀，摩妊妇脐上及左右令温，胎即下也。（《圣惠》）"},
  "石龙芮":{o:[],src:["本草纲目"],d:"旧二，新一。\n结核气︰堇菜日干为末，油煎成膏。摩之，日三、五度，便瘥。（孟诜《食疗》）\n蛇咬伤疮︰生堇杵汁涂之。（《万毕术》）\n血疝初起︰胡椒菜叶， ，按揉之。（《集简方》）"},
  "矾石":{o:[],src:["本草纲目"],d:"旧二十五，新六十四。中风痰厥，四肢不收，气闭膈塞者︰白矾一两，牙皂角五钱。为末。每服一钱，温水调下，吐痰为度。（陈师古方）胸中痰 ，头痛不欲食︰矾石一两，水二升，煮一升，纳蜜半合，顿服。须臾大吐，未吐，饮少热汤引之。（《外台秘要》）\n风痰痫病︰化痰丸︰生白矾一两，细茶五钱，为末，炼蜜丸如梧子大。一岁十丸，茶汤下；大人，五十丸。久服，痰自大便中出，断病根。（邓笔峰《杂兴》）\n小儿胎寒， 啼发痫︰白矾 半日，枣肉丸黍米大。每乳下一丸，愈乃止，去痰良。（《保幼大全》）\n产后不语︰胡氏孤凤散︰用生白矾末一钱，熟水调下。（《妇人良方》）\n牙关紧急不开者︰白矾、盐花等分。搽之，涎出自开。（《集简方》）\n走马喉痹︰用生白矾末涂于绵针上，按于喉中，立破。绵针者，用榆条，上以绵缠作枣大也。（《儒门事亲方》）\n喉痈乳蛾︰《济生》帐带散︰用矾三钱，铁铫内熔化，入劈开巴豆三粒，煎干去豆，研矾用之，入喉立愈。甚者，以醋调灌之。亦名通关散。法制乌龙胆︰用白矾末盛入猪胆中，风干研末。每吹一钱入喉，取涎出妙。咽喉谷贼肿痛︰生矾石末少少点肿处，吐涎，以痒为度。（《圣惠方》）\n风热喉痛︰白矾半斤，研末化水，新砖一片，浸透取晒，又浸又晒，至水干，入粪厕中浸一月，取洗，安阴处，待霜出扫收。每服半钱，水下。（《普济方》）\n悬痈垂长 咽中烦闷︰白矾（烧灰）、盐花等分。为末。箸头频点药在上，去涎。（孙用和《秘宝方》）\n小儿舌膜︰初生小儿有白膜皮裹舌，或遍舌根。可以指甲刮破令血出，以烧矾末半绿豆许，敷之。若不摘去，其儿必哑。（姚和众《至宝方》）\n牙齿肿痛︰白矾一两（烧灰），大露蜂房一两（微炙）为散。每用二钱，水煎含漱去涎。（《简要济众方》）\n患齿碎坏欲尽者︰常以绵裹矾石含嚼，吐去汁。（《肘后方》）\n齿龈血出不止︰矾石一两（烧）。水三升，煮一升，含漱。（《千金方》）\n木舌肿强︰白矾、桂心等分，为末。安舌下。（《圣惠方》）\n太阴口疮︰生甘草二寸，白矾一粟大。噙之，咽津。（《活法机要》）\n口舌生疮，下虚上壅︰定斋方︰用白矾泡汤濯足。张子和方︰用白矾（末）、黄丹（水飞炒）等分研，擦之。小儿鹅口，满口白烂︰枯矾一钱，朱砂二分。为末。每以少许敷之，日三次，神验。（《普济方》）\n小儿舌疮，饮乳不得︰白矾和鸡子置醋中，涂儿足底，二七日愈。（《千金方》）\n口中气臭︰明矾，入麝香为末，擦牙上。（《生生编》）\n衄血不止︰枯矾末吹之，妙。（《圣济方》）\n鼻中息肉︰\n《千金》︰用矾烧末，猪脂和，绵裹塞之。数日息肉随药出。一方︰用明矾一两，蓖麻仁七个，盐梅肉五个，麝香一字杵丸。绵裹塞之，化水自下也。眉毛脱落︰白矾十两。烧研，蒸饼丸梧子大。每空心温水下七丸，日加一丸，至四十九日减一丸，周而复始，以愈为度。（《圣济录》）\n发斑怪证︰有人眼赤鼻张，大喘，浑身出斑，毛发如铜铁，乃热毒气结于下焦也。白矾、滑石各一两为末，作一服。水三碗，煎减半，不住服，尽即安。（夏子益《奇疾方》）\n目翳弩肉︰白矾石纳黍米大入目，令泪出。日日用之，恶汁去尽，其疾日减。（《外台秘要》）\n目生白膜︰矾石一升。水四合，铜器中煎半合，入少蜜调之，以绵滤过。每日点三、四度。（姚和众《延龄至宝方》）\n赤目风肿︰甘草水磨明矾敷眼胞上效。或用枯矾频擦眉心。（《集简方》）\n烂弦风眼︰白矾（烧）一两，铜青三钱。研末，汤泡澄清，点洗。（《永类方》）\n耳出汁︰枯矾一两，铅丹（炒）一钱。为末，日吹之。（《圣济录》）\n猝死壮热︰矾石半斤，水一斗半，煮汤浸脚及踝，即得苏也。（《肘后方》）\n脚气冲心︰白矾三两。水一斗五升，煎沸浸洗。（《千金方》）\n风湿膝痛，脚膝风湿，虚汗，少力多痛，及阴汗。烧矾末一匙头，投沸汤，淋洗痛处。（《御药院方》）\n黄肿水肿︰推车丸︰用明矾二两，青矾一两，白面半斤，同炒令赤，以醋煮米粉糊为丸。枣汤下三十丸。（《济急方》）\n女劳黄胆黄家，日晡发热而反恶寒，膀胱急，少腹满，身尽黄，额上黑，足下热，因作黑疸。其腹胀如水状，大便必黑，时溏，此女劳之病，非水也。自大劳大热，交接后入水所致。腹满者难治。用矾石（烧）、硝石（熬黄）等分，为散。以大麦粥汁和服方寸匕。日三服。病从大小便去，小便正黄，大便正黑，是其候也。（张仲景《金匮方》）\n妇人黄胆，经水不调，房事触犯所致。白矾、黄蜡各半两，陈橘皮三钱。为末，化蜡丸梧子大。每服五十丸，以滋血汤或调经汤下。（《济阴方》）\n妇人白沃，经水不利，子脏坚癖，中有干血，下白物。用矾石三分（烧）、杏仁一分，研匀，炼蜜丸枣核大，纳入脏中，日一易之。（张仲景《金匮方》）\n妇人阴脱作痒︰矾石烧研，空心酒服方寸匕，日三。（《千金翼》）\n男妇遗尿︰枯白矾、牡蛎粉等分。为末。每服方寸匕，温酒下，日三服。（《余居士选奇方》）\n二便不通︰白矾末填满脐中，以新汲水滴之，觉冷透腹内，即自然通。脐平者，以纸围环之。（《经验方》）\n霍乱吐泻︰枯白矾末一钱，百沸汤调下。（华陀危病方）\n伏暑泄泻︰玉华丹︰白矾 为末，醋糊为丸。量大小，用木瓜汤下。（《经验方》）\n老人泄泻不止︰枯白矾一两，诃黎勒（煨）七钱半。为末。米饮服二钱，取愈。（《太平圣惠方》）\n赤白痢下︰白矾飞过为末，好醋、飞罗面为丸梧子大。赤痢，甘草汤，白痢干姜汤下。（《生生方》）\n气痢不止︰巴石丸︰取白矾一大斤，以炭火净地烧令汁尽，其色如雪，谓之巴石。取一两研末，熟猪肝作丸梧子大。空腹，量人加减。水牛肝更佳。如素食人，以蒸饼为丸。或云白矾中青黑者，名巴石。（刘禹锡《传信方》）\n冷劳泄痢食少，诸药不效︰白矾三两（烧），羊肝一具（去脂），酽醋三升煮烂，擂泥和丸梧子大。每服二十丸，米饮下，早夜各一服。（《普济方》）\n泄泻下痢︰白龙丹︰用明矾枯过为末，飞罗面醋打糊丸梧子大。每服二、三十丸，白痢姜汤下；赤痢甘草汤下；泄泻米汤下。（《经验方》）\n疟疾寒热︰即上方，用东南桃心七个，煎汤下。反胃呕吐︰白矾、硫黄各二两，铫内烧过，入朱砂一分，为末，面糊丸小豆大。每姜汤下十五丸。又方︰白矾（枯）三两，蒸饼丸梧子大。每空心米饮服十五丸。（《普济方》）\n化痰治嗽︰明矾二两，生参末一两，苦醋二升。熬为膏子，以油纸包收，旋丸豌豆大。每用一丸，放舌下，其嗽立止，痰即消。《定西侯方》︰只用明矾末，醋糊丸梧子大。每睡时茶下二、三十丸。《摘要》︰用明矾（半生半烧）、山栀子（炒黑）等分。为末，姜汁糊为丸。如上服。《杂兴方》︰用白明矾、建茶等分为末，糊丸服。\n诸心气痛︰《儒门事亲》方︰生矾一皂子大，醋一盏，煎七分服，立止。邵真人方︰用明矾一两（烧），朱砂一钱，金箔三个，为末。每服一钱半，空心白汤下。中诸蛊毒︰晋矾、建茶等分。为末。新汲水调下二钱，泻吐即效。未吐再服。（《济生方》）\n蛇虫诸毒︰毒蛇、射工、沙虱等伤人，口噤目黑，手足直，毒气入腹。白矾、甘草等分。为末。冷水服二钱。（《瑞竹堂方》）\n驴马汗毒所伤疮痛︰白矾（飞过）、黄丹（炒紫）等分。贴之。（王氏《博济方》）\n虎犬伤人︰矾末，纳入裹之，止痛尤妙。（《肘后方》）\n蛇咬蝎螫︰烧刀矛头令赤，置白矾于上，汁出热滴之，立瘥。此神验之方也。真元十三年，有两僧流南方，到邓州，俱为蛇啮，令用此法便瘥，更无他苦。（刘禹锡《传信方》）\n壁镜毒人必死︰白矾涂之。（《太平广记》）\n刀斧金疮︰白矾、黄丹等分为末。敷之最妙。（《救急方》）\n折伤止痛︰白矾末一匙，泡汤一碗，帕蘸乘热熨伤处。少时痛止，然后排整筋骨，点药。（《灵苑方》）\n漆疮作痒︰白矾汤拭之。（《千金方》）\n牛皮癣疮︰石榴皮蘸明矾末，抹之。切勿用醋，即虫沉下。（《直指方》）\n小儿风疹作痒︰白矾（烧），投热酒中，马尾 酒涂之。（《子母秘录》）\n小儿脐肿，出汁不止︰白矾烧灰敷之。（《圣惠方》）\n干湿头疮︰白矾（半生半 ），酒调涂上。（《生生编》）\n身面瘊子︰白矾、地肤子等分，煎水。频洗之。（《多能鄙事》）\n腋下狐臭︰矾石绢袋盛之，常粉腋下，甚妙。（许尧臣方）鱼口疮毒︰白矾（枯）研，寒食面糊调敷上，即消。（《救急良方》）\n阴疮作臼︰取高昌白矾、麻仁等分。研末，猪脂和膏。先以槐白皮煎汤洗过，涂之。外以楸叶贴上。不过三度愈。（葛洪《肘后方》）\n足疮生虫︰南方地卑湿，人多患足疮，岁久生虫如蛭，乃风毒攻注而然。用牛或羊或猪肚，去粪不洗，研如泥，看疮大小，入 过泥矾半两。以上研匀，涂帛上贴之。须臾痒入心，徐徐连帛取下，火上炙之。虫出，丝发马尾千万，或青白赤黑，以汤洗之。三日一作，不过数次，虫尽疮愈。（南宫从《岣嵝神书》）\n嵌甲作疮︰足趾甲入肉作疮，不可履靴。矾石烧灰敷之。蚀恶肉，生好肉。细细割去甲角，旬日取愈，此方神效。（《肘后方》）\n鸡眼肉刺︰枯矾、黄丹、朴硝等分。为末，搽之。次日浴二、三次，即愈。（《多能鄙事》）\n冷疮成漏︰明矾（半生半飞，飞者生肉，生者追脓）、五灵脂（水飞）各半钱为末。以皮纸裁条，唾和末作小捻子，香油捏湿，于末拖过，剪作大小捻，安入漏，早安午换。候脓出尽后，有些小血出，方得干水住药，自然生肉痊好。（《普济方》）\n鱼睛疔疮︰枯矾末，寒食面糊调贴。消肿无脓。（崔氏方）疔疮肿毒︰雪白矾末五钱，葱白煨熟，捣和丸梧子大。每服二钱五分，以酒送下，未效再服。久病、孕妇不可服。（《卫生宝鉴》）\n痈疽肿毒︰方见前发明下。阴汗湿痒︰枯矾扑之。又泡汤沃洗。（《御药院方》）\n交接劳复︰卵肿或缩入，腹痛欲绝。矾石一分，硝三分。大麦粥清服方寸匕，日三服，热毒从二便出也。（《肘后方》）\n女人阴痛︰矾石三分（炒），甘草末半分。绵裹导之，取瘥。（《肘后百一方》）\n疔肿恶疮︰二仙散︰用生矾、黄丹临时等分。以三棱针刺血，待尽敷之。不过三上，决愈。乃太医李管勾方。（《卫生宝鉴》）\n虫蛇兽毒及蛊毒︰生明矾、明雄黄等分，于端午日研末，黄蜡和丸梧子大。每服七丸，念药王菩萨七遍，熟水送下。（东坡《良》）方"},
  "砂":{o:["砂"],src:["本草备要"],d:"泻，消肉积\n咸苦辛热，有毒。消食破瘀。治噎膈症瘕，去目翳 肉，暖子宫，助阳道（性大热，能烂五金。《本草》称其能化人心为血，亦甚言不可多服耳。凡煮硬肉，投少许即易烂，故治噎膈、症瘕、肉积有殊功。《鸡峰方》云∶人之脏腑，多因触冒成病，而脾胃最易受触。饮食过多，则停滞难化。冷热不调，则呕吐泻痢，而膏梁者为尤甚。口腹不节，须用消化药。或言饮食既伤于前，难以毒药反攻其后，不使 砂、巴豆等，只用曲、柏之类。不知古今立方用药，各有主对。曲、柏只能消化米谷，如伤肉食，则非 砂、阿魏不能治也；如伤鱼、蟹，须用橘叶、紫苏、生姜；伤菜果，须用丁香、桂心；伤水饮，须用牵牛、芫花，必审所伤之因，对用其药，则无不愈。其间多少，则随患人气血以增损之而已。又有虚人沉积，不可直取，当以蜡匮其药，盖蜡能久留肠胃，又不伤气，能消磨至尽也。又有脾虚饮食迟化者，正宜助养脾胃，自能消磨，更不须用消导药耳。病久积而成症瘕者，须用三棱、鳖甲之类。寒冷成积者，轻则附子、浓朴；重则矾石、硫黄。瘀血结块者，则用大黄、桃仁之类，用者详之）。出西戎。乃卤液结成，状如盐块，置冷湿处即化。白净者良。水飞过，醋煮，干如霜用（畏醋）。忌羊血。"},
  "砒石":{o:["砒石"],src:["本草备要", "本草纲目"],d:"大燥，劫痰\n辛苦而咸。大热大毒，砒霜尤烈。专能燥痰，可作吐药。疗风痰在胸膈，截疟除哮。外用蚀败肉，杀虫枯痔。出信州，故名信石，衡州次之。锡之苗也（故锡壶亦云有毒）。生者名砒黄，炼者名砒霜。畏绿豆、冷水、羊血。"},
  "硝石":{o:[],src:["本草纲目"],d:"旧四，新十。\n头痛欲死︰硝石末吹鼻内，即愈。（《炮炙论》）\n诸心腹痛︰焰硝、雄黄各一钱。研细末。每点少许入 内。名火龙丹。（《集玄方》）\n腰腹诸痛︰方同上。赤眼肿痛︰硝石末，卧时，以铜箸点黍米大入目 。至旦，以盐水洗去之。（《圣惠方》）眼目障翳︰男女内外障翳，或三、五个月不见效者，一点复明。好焰硝一两，铜器熔化，入飞过黄丹二分，片脑二分，铜匙急抄入罐内，收之。每点少许，其效如神。兖州朱秀才忽不见物，朝夕拜天，因梦神传此方，点之而愈。（《张三丰仙方》）\n风热喉痹及缠喉风病。玉钥匙︰用焰硝一两半，白僵蚕一钱，硼砂半两，脑子一字。为末。吹之。（《三因方》）\n重舌鹅口︰竹沥，同焰硝点之。（《普济》）\n伏暑泻痢及肠风下血，或酒毒下血，一服见效，远年者不过三服。硝石、舶上硫黄各一两，白矾、滑石半两，飞面四两，为末，滴水丸梧子大。每新汲水下三、五十丸。名甘露丸。（《普济方》）\n五种淋疾︰劳淋、血淋、热淋、气淋、石淋及小便不通至甚者。透格散︰用硝石一两，不夹泥土雪白者，生研为末。每服二钱，各依汤使。劳淋，劳倦虚损，小便不出，小腹急痛，葵子末煎汤下，通后便须服补虚丸散。血淋，小便不出时，下血疼痛满急；热淋，小便热，赤色，脐下急痛，并用冷水调下。气淋，小腹满急，尿后常有余沥，木通煎汤下。石淋，茎内痛，尿不能出，内引小腹膨胀急痛，尿下砂石，令人闷绝，将药末先入铫内，隔纸炒至纸焦为度，再研，用温水调下。小便不通，小麦汤下。猝患诸淋，只以冷水下。并空心，调药使硝如水，乃服之。（沈存中《灵苑方》）\n蛟龙症病︰方见雄黄发明下。服石发疮疼不可忍︰用纸圈围之，中心填硝石令满，以匙抄水淋之。觉不热痛，即止。（《兵部手集》）\n发背初起︰恶寒啬啬，或已生疮肿瘾疹。硝石三两，暖水一升，泡化，待冷，青布折三重，湿拓赤处，热即换，频易取瘥。（《外台秘要》）\n女劳黑疸︰仲景曰︰黄家日晡发热，反恶寒，此为女劳得之。膀胱急，小腹满，身尽黄，额上黑，足下热，因作黑疸。腹胀如水，大便黑，时溏，非水也。腹满者难治。硝石、矾石（烧）等分。为末。以大麦粥汁和服方寸匕，日三。病随大小便去，小便黄，大便黑，是其候也。（《金匮》）\n手足不遂大风，及丹石热风不遂。用硝石一两，生乌麻油二斤。置铛中，以土堑盖口，纸泥固济，火煎。初时气腥，熟则气香。更以生麻油二升，合煎得所，收不津器中。服时坐室中，重作小纸屋，燃火于内，服一大合，发汗，力壮者日二服。三七日，头面 疮皆减也，然必以火为使。（波罗门僧方）"},
  "硵砂":{o:[],src:["本草纲目"],d:"旧四，新二十三。服食法︰ 砂丸︰ 砂不计多少，入罐子内，上面更坐罐子一个，纸筋白土上下通泥了，晒干。上面罐子内盛水，以苍耳干叶为末，铺头盖底，以火烧之。火尽旋添火，水尽旋添水，从辰初起至戌一伏时，住火勿动。次日取出研，米醋面糊和丸梧子大。每服四、五丸，温酒或米饮下，并无忌。久服进食无痰。（《经验方》）\n元脏虚冷，气攻脐腹疼痛︰用 砂一两，以纤霞草末二两和匀，用小砂罐不固济，慢火烧赤，乃入 在罐内，不盖口，加顶火一秤，待火尽炉寒取出。用川乌头（去皮脐，生研末）二两，和匀，汤浸蒸饼丸梧子大。每服三丸，木香汤、醋汤任下，日一服。（陈巽方）\n肾脏积冷，气攻心腹疼痛，面青足冷︰ 砂二两，桃仁一两（去皮）。酒一小盏，煎十余沸，去砂石，入桃仁泥，旋旋煎成膏，蒸饼和丸梧子大。每热酒下二十丸。（《圣惠方》）\n积年气块，脐腹痛疼︰ 砂（醋煮）二两，木瓜三枚（切，须去瓤）。入 在内，碗盛，于日中晒至瓜烂，研匀，以米醋五升，煎如稀饧，密收。用时旋以附子末和丸梧子大。热酒化下一丸。（《圣惠方》）\n癖症块 砂丸︰治 癖症块，暖水脏，杀三虫，妇人血气，子宫冷。腊月收桑条灰，淋去苦汁，日干。每 砂一两，用灰三两，以水化 ，拌灰干湿得所。以瓶盛灰半寸，入于内，以灰填盖固济，文武火 赤，冷定取出，研。以箕铺纸三重，安药于上，以热水淋之，直待 味尽即止。以钵盛汁，于热灰火中养之，常令鱼眼沸，待汁干入瓶，再 一食顷，取出重研，以粟饭和丸绿豆大。每空心。酒下五丸，病去即止。（《圣惠方》）\n噎膈反胃 邓才清兴︰用北庭砂二钱，水和荞麦面包之， 焦，待冷，取中间湿者，焙干一钱，入槟榔二钱，丁香二个，研匀。每服七厘，烧酒送下，日三服，愈即止。后吃白粥半月，仍服助胃丸药。《孙天仁集效方》︰用北庭砂二两（一两，用人言末一两，同入罐内，文武火升三炷香，取出，灯盏上末；一两，以黄丹末一两，同入罐内，如上法升过，取末），用桑灰霜一两。研匀。每服三分，烧酒下，愈即止。又方︰平胃散各一钱，入 砂、生姜各五分，为末。沸汤点服二钱，当吐出黑物如石，屡验。一切积痢︰灵砂丹︰用 砂、朱砂各二钱半。为末。用黄蜡半两，巴豆仁三七粒（去膜），同入石器内，重汤煮一伏时，候豆紫色为度。去二七粒，只将一七粒同二砂研匀，溶蜡和收。每旋丸绿豆大。或三丸、五丸，淡姜汤下。（《本事方》）\n月水不通︰脐腹积聚疼痛。 砂一两，皂角五挺（去皮子）。锉为末，以头醋一大盏，熬膏，入陈橘皮末三两，捣三百杵，丸梧子大。每温酒下五丸。（《圣惠方》）\n死胎不下︰ 砂、当归各半两。为末。分作二服，温酒调下，如人行五里，再一服。（《瑞竹堂方》）\n喉痹口噤︰ 砂、马牙硝等分，研匀，点之。（《圣济方》）\n悬痈猝肿︰ 砂半两，绵裹含之，咽津即安。（《圣惠方》）\n牙齿肿痛︰老鼠一个去皮，以 砂淹擦，三日肉烂化尽，取骨，瓦上焙干，为末，入樟脑一钱，蟾酥二分。每以少许点牙根上，立止。（《孙氏集效方》）\n偏头风痛︰ 砂末一分，水润豉心一分。捣丸皂子大。绵包露出一头，随左右内鼻中，立效。（《圣惠方》）\n损目生瘀，赤肉弩出不退︰杏仁百个，蒸熟去皮尖研，滤取净汁，入砂末一钱，水煮化。日点一、二次，自落。（《普济方》）\n鼻中息肉︰ 砂点之，即落。（白飞霞方）鼻中毛出︰昼夜可长一、二尺，渐渐粗圆如绳，痛不可忍，摘去复生，此因食猪羊血过多致生。用乳香、 砂各一两，为末，饭丸梧子大。每空心临卧各服十丸，水下。自然退落。（夏子益《奇疾方》）\n鱼骨哽咽︰ 砂少许，嚼咽立下。（《外台秘要》）\n蚰蜒入耳︰砂、胆矾等分。为末。每吹一字，虫化为水。（《圣济录》）\n割甲侵肉久不瘥︰ 砂、矾石，为末。裹之，以瘥为度。（《外台秘要》）\n蝎虿叮螫︰水调 砂涂之，立愈。（《千金方》）\n代指肿痛︰唾和白 砂，以面作碗子，套指入内，一日瘥。（《千金方》）\n面上疣目︰ 砂、硼砂、铁锈、麝香等分研，搽三次自落。（《集效方》）\n疔疮肿毒︰好 砂、雄黄等分研。以银篦刺破疮口，挤去恶血，安药一豆入内，纸花贴住即效。毒气入腹呕吐者，服护心散。（《瑞竹堂方》）\n疝气卵肿，胀痛不可忍。念珠丸︰用 砂、乳香各二钱，黄蜡一两。研溶和丸，分作一百单八丸，以绵缝，露一夜，次日取出，蛤粉为衣。每用一丸，乳香汤吞下，日二服，取效。（《本事方》）\n诸劳久嗽︰方见兽部下。"},
  "硼砂":{o:["硼砂"],src:["本草备要", "本草纲目"],d:"润，生津，去痰热\n甘微咸凉。色白质轻，故除上焦胸膈之痰热，生津止嗽。治喉痹、口齿诸病（初觉喉中肿痛，含化咽津，则不成痹）。能金而去垢腻，故治噎膈积块，结核 肉，目翳骨哽（碱能软坚，含之咽汁）。出西番者，白如明矾，出南番者，黄如桃胶。能制汞、哑铜（硼砂、砂，并可作金银焊）。"},
  "碱":{o:["碱"],src:["本草备要"],d:"（一作碱）\n泻，磨积，去垢辛苦涩温。消食磨积，去垢除痰。治反胃噎膈，点痣、 、疣、赘（与矿灰等分，用小麦杆灰，煎干为末。挑破痣，三点即瘥）。发面，浣衣用之。取蓼蒿之属，浸晒烧灰，以原水淋汁，每百斤入粉面二三斤，则凝定如石。"},
  "礜石":{o:[],src:["本草纲目"],d:"新一。\n风冷脚气︰白礜石二斤，酒三斗，渍三日，稍稍饮之。（《肘后方》）"},
  "礞石":{o:["礞石"],src:["本草备要", "本草纲目"],d:"重，泻痰\n甘威有毒，体重沉坠。色青入肝，制以硝石，能平肝下气，为治惊利痰之圣药（吐痰在水上，以石末掺之，痰即随下。王隐君有礞石滚痰丸，能治百病。礞石、焰硝各二两， 研，水飞净一两，大黄酒蒸八两，黄芩酒洗八两，沉香五钱，为末，水丸，量虚实服。时珍曰∶风木太过，来制脾土，气不运化，积滞生痰，壅寒上、中二焦，变生诸证。礞石重坠，硝性疏快，使痰积通利，诸证自除）。气弱脾虚者禁用。坚细青黑，中有白星点。硝石、礞石等分，打碎拌匀，入坩锅 至硝尽、石色如金为度。如无金星者不入药。研末水飞，去硝毒用。"},
  "禹余粮":{o:["禹余粮"],src:["本草备要", "本草纲目"],d:"重，涩固下\n甘平性涩。手、足阳明（大肠、胃）血分重剂。治咳逆下痢，血闭（症瘕）血崩，能固下（李先知云∶下焦有病患难会，须用余粮、赤石脂），又能催生。石中黄粉，生于池泽。无砂者良。牡丹为使。"},
  "秋石":{o:["秋石"],src:["本草备要"],d:"补肾水，润三焦\n咸温。滋肾水，润三焦，养丹田，安五脏，退骨蒸，软坚块。治虚劳咳嗽，白浊遗精，为滋阴降火之圣药。若煎炼失道，多服误服，反生燥喝之患（咸能走血，且经 炼，中寓暖气，使虚阳妄作，则真水愈亏。）《蒙筌》曰∶每月取童便，每缸用石膏七钱，桑条搅澄，倾去清液，如此二三次，乃入秋露水搅澄（故名秋石）如此数次，滓秽净，咸味减，以重纸铺灰上晒干，刮去在下重浊，取轻清者为秋石。世医不取秋时，杂收人溺，以皂荚水澄晒为阴炼，火 为阳炼，尽失于道，安能应病？况经火炼，性却变温耶（秋石再研入罐，铁盏盖定，盐泥固济升打，升起盏上者名秋冰。味淡而香，乃秋石之精英也。《保寿堂方》∶用童男童女小便，各炼成秋石，其色如雪，和匀加乳汁，日晒夜露，取日精月华，干即加乳。待四十九日足，收贮配药。《摘玄》曰∶肿胀忌盐，只以秋石拌饮食佳）。"},
  "秦皮":{o:["秦皮"],src:["本草备要"],d:"涩而补，明目\n苦寒，色青，性涩。补肝胆而益肾。以能平木（能除肝热）故治目疾（洗目赤，退翳膜）惊痫。以其收涩而寒，故治崩带下痢（仲景白头翁汤用之）。以其涩而补下焦，故能益精有子（时珍曰∶天道贵啬，惟收涩故能补。今人只知治目一节，几于废弃，良为可婉）。出西土。皮有白点、渍水碧色、书纸不脱者真。大戟为使。恶吴茱萸。"},
  "积雪草":{o:[],src:["本草纲目"],d:"旧二，新二热毒痈肿︰秋后收连钱草。阴干为末。水调敷之。生捣亦可。（寇氏《衍义》）\n女子少腹痛︰颂曰︰《天宝单行方》云︰女子忽得小腹中痛，月经初来，便觉腰中切痛连脊间，如刀锥所刺，不可忍者。众医不别，谓是鬼疰，妄服诸药，终无所益，其疾转增。审察前状相当，即用此药。其药夏五月正放花时，即采曝干，捣筛为散。每服二方寸匕，和好醋二小合，搅匀，平旦空腹顿服之。每旦一服，以知为度。如女子阴冷者，即取前药五两，加桃仁二百枚（去皮尖），熬捣为散，以蜜为丸如梧子大。每旦空腹米饮及酒下三十丸，日再服，以愈为度。忌麻子、荞麦。（《图经本草》方）。男女血病︰九仙驱红散︰治呕吐诸血及便血、妇人崩中神效。用积雪草五钱，当归（酒洗）、栀子仁（酒炒）、蒲黄（炒）、黄连（炒）、条黄芩（酒炒）、生地黄（酒洗）、陈槐花（炒）各一钱。上部加藕节一钱五分，下部加地榆一钱五分，水二钟，煎一钟服，神效。此方得之甚秘，此草与本草主治不同，不可晓也。（董炳《集验方》）\n牙痛塞耳︰用连钱草（即积雪草），和水沟污泥同捣烂，随左右塞耳内。（《摘玄方》）"},
  "稷":{o:["稷"],src:["本草备要"],d:"补、和中\n甘平。益气和中，宣脾利胃（陶宏景曰∶稷米，人亦不识。书记多云黍与稷相似，又注∶黍米云 米。与黍米相似，而粒殊大，食之不宜，人发旧病。《诗》云∶黍稷稻粱，禾麻菽麦，此八谷也。俗犹不能辨证，况芝英乎？按∶黍、稷辨者颇多，皆无确义。李时珍曰∶稷、黍一类二种。粘者为黍，不粘者为稷。昂谓∶诗人既云八谷，何必取一类者强分二种？是仍为七谷矣。盖 、稷同音，故世妄谓 为稷，不知 乃黍类似粟，而粒大疏散，乃北方下谷，南土全无，北人亦不之重，安能度越粳、糯而高踞八谷之上乎？陶氏所说，因是 黍，所以疑也。若稷当属高硕如芦，世之所谓芦稷者，实既香美，性复中和，干又高硕，所以能为五谷之长，而先王以之名官也。况 黍所生不遍，而芦稷薄海蕃滋，《本草》乃指芦稷为蜀黍，其名义亦不伦矣。此实从来之误，敢为正之，以质明者。又芦稷最能和中，煎汤温服，治霍乱吐泻如神。昂尝病中啾唧，经两月，有友人见招，饮以芦稷烧酒一醉，而积病畅然，性之中和，又可见矣）。"},
  "空青":{o:["空青"],src:["本草备要", "本草纲目"],d:"重，明目\n甘酸而寒。益肝明目，通窍利水。产铜坑中。大块、中空有水者良。"},
  "穿山甲":{o:["穿山甲"],src:["本草备要"],d:"（一名鲛鲤）\n宣，通经络咸寒善窜（喜穿山），专能行散，通经络，达病所（某处病，用某处之甲，更良），入厥阴、阳明（肝、胃）。治风湿冷痹。通经下乳，消肿溃痈，止痛排脓，和伤发痘（元气虚者慎用）。风、疟、疮科为要药（以其穴山寓水，故能出入阴阳，贯穿经络，达于营分，以破邪结，故用为使），以其食蚁，又治蚁 （漏也，音闾，亦音漏。有妇人项下忽肿一块，渐延至颈，偶刺破，出水一碗，疮久不合。有道人曰∶此蚁漏也，缘饭中偶食蚁得之。用穿山甲烧，存性为末，敷之立愈。刘伯温《多能鄙事》云∶油笼渗漏，刮甲里肉 投入，自至漏处补住。《永州记》云∶不可于堤岸杀之。恐血入土，则岸堤渗漏。观此二说，其性之善窜可知矣）。痈疡已溃者忌服。如鳖而短，似鲤有足。尾甲力更胜。或生或烧，酥炙，醋炙。童便，油煎，土炒，随方用。"},
  "童便":{o:["童便"],src:["本草备要"],d:"（一名还元水。饮自己溺，名轮回酒）\n平，泻火，补阴，散瘀血咸寒（时珍曰温）。能引肺火下行从膀胱出，乃其旧路，降火滋阴甚速。润肺散瘀（咸走血），治肺痿失音，吐衄损伤（凡跌打损伤、血闷欲死者，擘开口以热尿灌之，下咽即醒。一切金疮受杖，并宜用之，不伤脏腑。若用他药，恐无瘀者，反致误人矣），胞胎不下（皆散瘀之功）。凡产后血晕，败血入肺，阴虚久嗽，火蒸如燎者，惟此可以治之（晋褚澄《劳极论》曰∶降火甚速，降血甚神。饮溲溺百无一死，服寒凉药百无一生）取十二岁以下童子（少知识，无相火），不食荤、腥、酸、咸者佳。去头尾，取中间一节清沏如水者，用当热饮。热则真气尚存，其行自速，冷则惟有咸寒之性。入姜汁（行痰）、韭汁（散痰）更好。冬月用汤温之（李士材曰∶炼成秋石，真元之气渐失，不及童便多矣。《普济方》∶治目赤肿痛，用自己小便，乘热抹洗，即闭目少顷。此以真气退其邪热也）。"},
  "竹沥":{o:["竹沥"],src:["本草备要"],d:"泻火，滑痰，润燥\n甘寒而滑。消风降火，润燥行痰，养血益阴（竹之有沥，犹人之有血也。故能补阴清火）。利窍明目。治中风口噤，痰迷大热，风痉癫狂，烦闷（《产乳》方∶妊娠苦烦名子烦，竹沥不限多少细服。梅师加茯苓煎）消渴，血虚自汗。然寒胃滑肠、有寒湿者勿服（《经疏》曰∶中风要药。凡中风未有不因阴虚火旺、痰热壅结所致，如果外来风邪，安得复用此寒滑之药治之哉！丹溪曰∶痰在经络、四肢、皮里、膜外者，非此不能达行。又曰∶味甘性缓，能除阴虚之有大热者。寒而能补，胎后不碍虚，胎前不损子。世人因本草大寒二字，弃而不用，然人食笋，至老未有因寒而病者。沥，即笋之液也，又假火而成，何寒如此之甚耶？治法云∶竹沥和米煮粥，能治反胃）。竹类甚多，淡行肉薄，节间有粉，多汁而甘，最良； 竹坚而节促，皮白如霜；苦竹本粗叶大，笋味苦。入药，惟此三种，功用略同。竹茹即刮取青皮。竹沥如取荆沥法。姜汁为使（姜能除痰，且济其寒）。笋尖发痘疮（《本草》未载。昂按∶笋蕨多食，皆能燥血，故笋有刮肠篦之名。惟同肉煮食，则无害也）。"},
  "竹虱":{o:[],src:["本草纲目"],d:"新一。\n中风偏痹，半身不遂者︰用麻孔，其病处不糊。以竹虱（焙为末）臾药行如风声，口吐出恶水，身出臭汗日，手足如故也。（《岣嵝神书》)"},
  "竹蠹虫":{o:[],src:["本草纲目"],d:"新六。\n耳出水︰苦竹蛀屑、野狼牙、白蔹等分，为末和匀，频掺之。（《圣惠》）。\n耳出臭脓︰用竹蛀虫末、胭脂坯子等分，麝香少许，为末吹之。（《朱氏集验》）\n耳脓作痛︰因水入耳内者︰如圣散︰用箭杆内蛀末一钱，腻粉一钱，麝香半钱，为末。以绵杖缴尽，送药入耳，以绵塞定，有恶物放令流出，甚者三度必愈。（《普济》）。\n汤火伤疮︰竹蠹蛀末，敷之。（《外台秘要》）\n湿毒 疮︰枯竹蛀屑、黄柏末等分。先以葱、椒、茶汤洗净，搽之，日一上。\n牙齿疼痛︰蛀竹屑、陈皮各一两，为末，乌梅肉同研如泥，敷之。（《救急方》）"},
  "箬":{o:[],src:["本草纲目"],d:"新一十二。\n一切眼疾︰笼 烧灰，淋汁洗之，久之自效。（《经验方》）\n咽喉闭痛︰辽叶、灯心草（烧灰）等分。吹之，甚妙。（《集简方》）\n耳忽作痛或红肿内胀︰将经霜青箬露在外，将朽者烧存性，为末。敷入耳中，其疼即止。（杨起《简便方》）\n肺壅鼻衄︰箬叶（烧灰）、白面三钱。研匀，井花水服二钱。（《圣济总录》）\n箬叶灰、蚕纸灰等分，为末。每服二钱，米饮下。（《圣济总录》）\n肠风便血︰茶篓内箬叶，烧存性。每服三匙，空心糯米汤下。或入麝香少许。（ 《百一选方》）\n男妇血淋，亦治五淋︰多年煮酒瓶头箬叶（三、五年至十年者，尤佳）。每用七个，烧存性，入麝香少许，陈米饮下，日三服。有人患此，二服愈。福建煮过夏月酒多有之。（《百一选方》）\n小便涩滞不通︰干箬叶一两（烧灰），滑石半两，为末，每米饮服三钱。（《普济方》）\n男妇转脬︰方同上。吹奶乳痈 五月五日粽箬烧灰，酒服二钱，即散，累效。（《济急仙方》）\n痘疮倒靥 箬叶灰一钱，麝香少许。酒服。（张德恭《痘疹便览方》）"},
  "粉铅":{o:[],src:["本草纲目"],d:"旧十四，新三十。\n劳复食复欲死者︰水服胡粉少许。（《肘后方》）\n小儿脾泄不止︰红枣二十个去核，将官粉入内，以阴阳瓦焙干，去枣研粉。每服三分，米汤下。（孙真人《集效方》）\n赤白痢下频数，肠痛︰定粉一两，鸡子清和，炙焦为末。冷水服一钱。（《肘后方》）\n小儿无辜疳，下痢赤白︰胡粉熟蒸，熬令色变，以饮服半钱。（《子母秘录》）\n小儿腹胀︰胡粉、盐熬色变，以摩腹上。（《子母秘录》）\n腹皮青色，不速治，须臾死。方同上。\n小儿夜啼︰水服胡粉三豆大，日三服。（《子母秘录》）\n身热多汗︰胡粉半斤，雷丸四两，为末粉身。（《千金方》）\n妇人心痛急者︰好官粉为末，葱汁和丸小豆大。每服七丸，黄酒送下即止。粉能杀虫，葱能透气故也。（邵真人方）\n寸白蛔虫︰胡粉炒燥，方寸匕，入肉 中，空心服，大效。（张文仲《备急方》）\n服药过剂闷乱者。水和胡粉服之。（《千金方》）\n鼻衄不止︰胡粉炒黑，醋服一钱，即止（《圣惠方》）\n齿缝出血︰胡粉半两，麝香半钱，为末。卧时揩牙。（《圣济录》）\n坠扑瘀血，从高落下，瘀血抢心，面青气短欲死。胡粉一钱，和水服即安。（《肘后方》）\n折伤接骨︰官粉、硼砂等分，为末。每服一钱，苏木汤调下，仍频饮苏木汤，大效。（《接骨方》）\n杖疮肿痛︰水粉一两，赤石脂（生）一钱，水银一分，以麻油杵成膏，摊油纸贴之。肉消者，填满紧缚。（《救急方》）\n抓伤面皮︰香油调铅粉搽之，一夕愈。（《集简方》）\n食梅牙 ︰韶粉揩之。（《相感志》）\n染白须发︰胡粉、锻石等分，水和涂之，以油纸包，烘令温暖，候未燥间洗去，以油润之，黑如漆也。（《博物志》）\n腋下胡臭︰胡粉常粉之。或以胡粉三合，和牛脂煎稠涂之。（《千金方》）\n阴股常湿︰胡粉粉之。（《备急方》）\n干湿癣疮︰方同上。\n黄水脓疮︰官粉（ 黄）、松香各三钱，黄丹一钱，飞矾二钱。为末，香油二两，熬膏敷之。（邵真人方）\n小儿耳疮月蚀︰胡粉，和土涂之。（《子母秘录》）\n小儿疳疮︰熬胡粉，猪脂和涂。（张文仲方）\n小儿舌疮︰胡粉，和猪 骨中髓，日三敷之。（《食医心镜》）\n燕口吻疮︰胡粉（炒）一分，黄连半两，为末，敷之。（《普济方》）\n痘疮瘢痕，或凸或凹。韶粉一两，轻粉一定，和研，猪脂调敷。（陈文中小儿方）\n妒精阴疮︰铅粉二钱，银杏仁七个，铜铫内炒至杏黄，去杏取粉，出火毒，研搽效。（《集简方》）\n反花恶疮︰胡粉一两，胭脂一两。为末。盐汤洗净敷之，日五次。（《圣惠方》）\n疮似蜂窠，愈而复发。胡粉、朱砂等分。为末，蜜和涂之。（《圣济录》）\n血风 疮︰《孙氏集效方》︰用官粉四两，水调入碗内，以蕲州艾叶烧烟熏干，入乳香少许同研，香油调作隔纸膏，反复贴之。《杨氏简便方》︰用官粉炒过，桐油调作隔纸贴之。\n小儿丹毒︰唾和胡粉，从外至内敷之良。（《千金方》）\n汤火烧疮︰胡粉，羊髓和，涂之。（孙真人方）\n疮伤水湿︰胡粉、炭灰等分，脂和涂孔上，水即出也。（《千金方》）\n蠷 尿疮︰酢和胡粉涂之。（《千金方》）\n诸蛇螫伤︰胡粉和大蒜捣涂。（《千金方》）\n误吞金银及钱︰胡粉一两，猪脂调，分再服，令消烊出也。（《外台秘要》）\n三年目翳︰胡粉涂之。（《圣惠方》）\n口中干燥，烦渴无津。雄猪胆五枚，酒煮皮烂，入定粉一两研匀，丸芡子大，每含化一丸咽汁。（《太平圣惠方》）\n腹中鳖症︰胡粉、黍米，淋汁温服，大效。（《卫生易简方》）\n接骨续筋，止痛活血。定粉、当归各一钱，硼砂一钱半。为末。每服一钱，苏木煎汤调下，仍频饮汤。（同上）发背恶疮，诸痈疽。好光粉二两，真麻油三两。慢火熬，以柳枝急搅，至滴水成珠，入白胶末少许，入器，水浸两日，油纸摊贴，名神应膏。（《直指方》）"},
  "粉霜":{o:[],src:["本草纲目"],d:"新六。\n小儿急惊，搐搦涎盛︰粉霜二钱，白牵牛（炒）、轻粉各一钱。为末。每服一字，薄荷汤下，吐涎为效。（《全婴方》）\n小儿躁渴︰粉霜一字，大儿半钱，莲花汤调下。冬月用莲肉。（《保幼大全》）\n风热惊狂︰神白丹︰治伤寒积热，及风生惊搐，或如狂病，诸药不效。粉霜一两，（以白面六钱，和作饼子，炙熟同研），轻粉半两，铅白霜二钱半。为末，滴水丸梧子大。每服十丸至十五丸，米饮下。（《宣明方》）\n疹生翳︰粉霜八分，朱砂一钱。为末。水调少许，倾入耳内。（《鸿飞集》）\n腋下狐臭︰粉霜、水银等分，以面脂和涂之。（《圣济录》）\n杨梅恶疮︰粉霜一味搽之。（《集简方》）"},
  "粟":{o:["粟"],src:["本草备要"],d:"补肾\n甘咸微寒。养肾益气。治胃热消渴，止霍乱，利二便（《千金方》粟米粉水丸，梧子大，煮七枚，纳醋中，细吞之，治反胃吐食）。即粱米。有青、黄、赤、白、黑诸色，陈者良。"},
  "粪清":{o:["粪清"],src:["本草备要"],d:"（一名金汁）\n泻火热主治同人中黄。用棕皮棉纸，上铺黄土，淋粪滤汁，入新瓮，碗复埋土中一年，清若泉水，全无秽气用。年久者弥佳（野间残粪下土，筛敷痈疽，如冰着背）。"},
  "粳米":{o:["粳米"],src:["本草备要"],d:"（粳，硬也）\n补脾清肺甘凉。得天地中和之气，和胃补中，色白入肺。除烦清热，煮汁止渴（仲景白虎汤、桃花汤、竹叶石膏汤，并用之以清热、补不足。张文潜《粥记》∶粥能畅胃气，生津液，每晨空腹食之，所补不细。昂按∶今人终日食粥，不知其妙。迨病中食之，觉与脏腑相宜，迥非他物之所能及也）。粳，乃稻之总名，有早、中、晚三收。晚者得金气多，性凉，尤能清热（北粳凉，南粳温，白粳凉，红粳温，新米食之动气）。陈廪米冲淡可以养胃，煮汁煎药，亦取其调肠胃、利小便、去湿热，除烦渴之功（《集成》云∶陈米饭扎作团，火 存性，麻油，腻粉调，敷一切恶疮、百药不效者）。"},
  "糯米":{o:["糯米"],src:["本草备要"],d:"（糯，懦也。《本草》名稻米。按∶《诗》，黍、稷、稻、粱、禾、麻、菽、麦，名八）（此稻与禾所以有异乎。）补温脾肺甘温。补脾、肺虚寒，坚大便，缩小便，收自汗（同龙骨、牡蛎为粉，能扑汗），发痘疮（解毒化脓）。然性粘滞，病患及小儿忌之（糯米酿酒则热，熬饧尤甚。饧即饴糖，润肺和脾，化痰止嗽。仲景建中汤用之，取其甘以补脾缓中。多食发湿热、动痰火、损齿）。"},
  "紫参":{o:[],src:["本草纲目"],d:"旧一，新三。\n紫参汤︰治痢下。紫参半斤。水五升，煎二升，入甘草二两，煎取半升，分三服。（张仲景《金匮玉函》）\n吐血不止︰紫参、人参、阿胶（炒）等分。为末。乌梅汤服一钱。一方去人参，加甘草，以面上酒刺︰五参丸︰用紫参、丹参、人参、苦参、沙参各一两。为末，胡桃仁杵和丸，梧"},
  "紫堇":{o:[],src:["本草纲目"],d:"旧一。\n脱肛，凡大人、小儿脱肛，每天冷及吃冷食，即暴痢不止，肛则下脱，久疗不瘥者：春间收紫堇花二斤，曝干为散，加磁毛末七两，相和研细。涂肛上纳入，即使人 冷水于面上，即吸入肠中。每日一涂药 面，不过六、七度即瘥矣。又以热酒半升，和散一方寸匕，空腹服之，日再服。渐加至二方寸匕，以瘥为度。若五岁以下小儿，即以半杏子许，和酒服之。忌生冷、陈仓米等物。（《天宝单方》）"},
  "紫檀":{o:["紫檀"],src:["本草备要"],d:"重，和血\n咸寒。血分之药。和荣气，消肿毒，敷金疮，止血定痛。"},
  "紫河车":{o:["紫河车"],src:["本草备要"],d:"（即胞衣，一名混沌皮）\n大补气血甘咸性温。本人之血气所生，故能大补气血，治一切虚劳损极（虚损∶一损肺，皮槁毛落；二损心，血脉衰少；三损脾，肌肉消脱；四损肝，筋缓不收；五损肾，骨痿不起。六极，曰气极、血极、筋极、肌极、骨极、精极），恍惚失志癫痫。以初胎及无病妇人者良。有胎毒者害人（以银器插入，焙煮，不黑则无毒）。长流水洗极净，酒蒸焙干研末。或煮烂捣碎入药（如新瓦炙者，反损其精汁），亦可调和煮食（李时珍曰∶崔行功《小儿方》云∶胞衣宜藏天德月德吉方，深埋紧筑。若为猪、狗食，令儿癫狂；蝼蚁食，令儿疮癣；鸟雀食，令儿恶死；弃火中，令儿疮烂；近社庙、井、灶、街巷，皆有所忌。此亦铜山西崩，洛钟东应，自然之理。今人以之炮炙入药，虽曰以人补人，然食其同类，独不犯崔氏之戒乎？以故本集如天灵盖等，概不入录）。"},
  "紫石英":{o:["紫石英"],src:["本草备要", "本草纲目"],d:"重，镇心，润，补肝\n甘平。性温而补，重以去怯，湿以去枯。入心、肝血分，故心神不安，肝血不足，女子血海虚寒不孕者宜之（冲为血海，任主胞胎。《经疏》云∶女子系胞于肾及心包络，虚则风寒乘之，故不孕。紫石英辛温，走二经，散风寒，镇下焦，为暖子宫之要药）。色深紫莹彻，五棱。火 、醋淬七次，研末水飞用。二英俱畏附子。恶黄连（石英五色，各入五脏）。"},
  "紫苏":{o:["紫苏"],src:["本草备要"],d:"宣，发表，散寒\n味辛入气分，色紫入血分。香温散寒，通心利肺，开胃益脾（气香入胃），发汗解肌，和血下气，宽中消痰，祛风定喘，止痛安胎，利大、小肠，解鱼、蟹毒。多服泄人真气（时珍曰∶同陈皮、砂仁，行气安胎；同霍香、乌药，温中止痛；同香附、麻黄，发热解肌；同芎、当归，和血散血；同桔梗、枳壳，利膈宽肠；同卜子、杏仁，消痰定喘；同木瓜、浓朴，散温解暑治霍乱香港脚）。气香者良。宜橘皮。忌鲤鱼。苏子与叶同功。润心肺，尤能下气定喘，止嗽消痰，利膈宽肠，温中开郁（有苏子降气汤）。苏梗下气稍缓，虚者宜之（叶发汗散寒、梗顺气安胎，子降气开郁、消痰定喘。表弱气虚者忌用叶，肠滑气虚者忌用子），炒、研用。"},
  "紫葳":{o:["凌霄花"],src:["本草备要", "本草纲目"],d:"（一名紫葳）\n泻血热甘酸而寒。入厥阴（心包、肝）血分。能去血中伏火，破血去瘀。生产乳余疾，崩带症瘕，肠结（不大便）血闭，淋 风痒，血热生风之证。女科多用，孕妇忌之（《本经》云∶养胎。《经疏》云∶破血之药，非所宜也。肺痈有用之为君药者。凌霄花为末，和密陀僧唾调，敷酒 甚验）。藤生，花开五瓣，黄赤有点，不可近鼻，嗅之伤脑。"},
  "紫金藤":{o:[],src:["本草纲目"],d:"新二。\n紫金藤丸，补肾脏，暖丹田，兴阳道，减小便，填精髓，驻颜色，润肌肉，治元气虚惫，面目黧黑，口干舌涩，梦想虚惊，耳鸣目泪，腰胯沉重，百节酸疼，项筋紧急，背胛劳倦，阴汗盗汗，及妇人子宫久冷，月水不调，或多或少，赤白带下，并宜服之︰用紫金藤十六两、巴戟天（去心）三两，吴茱萸、高良姜、肉桂、青盐各二两。为末，酒糊丸梧子大。每温酒下二十丸，日三服。（《和剂方》）\n死胎不下︰紫金藤、葵根各七钱，土牛膝三两，土当归四钱，肉桂二钱，麝香三分。为末，米糊丸梧子大，朱砂为衣。每服五十丸，乳香汤下，极验。（葛静观方）"},
  "紫铆":{o:[],src:["本草纲目"],d:"新三。\n齿缝出血︰紫矿、乳香、麝香产后血晕，狂言失志︰用紫矿一两。为末。酒服二钱匕。（《徐氏家传方》）\n经水不止，日渐黄瘦︰紫 末，每服二钱，空心白汤下。（《杨氏家藏方》）"},
  "红曲":{o:["红曲"],src:["本草备要"],d:"宣，破血，燥，消食\n甘温色赤。入营而破血，燥胃消食，活血和血。治赤白下痢，跌打损伤，产后恶露不尽（李时珍曰∶人之水谷入胃，中焦湿热熏蒸，游溢精气，化为营血，此造化自然之妙也。红曲以白米饭杂曲面母，湿热蒸 ，即变为真红，此人窥造化之巧者也。故治脾胃营血，得同气相求之理）。红入米心、陈久者良（昂按∶红曲温燥，能腐生物使熟。故鱼肉 用之，不特取其色也）。"},
  "红蓝花":{o:[],src:["本草纲目"],d:"旧四，新四。\n六十二种风，张仲景治六十二种风，兼腹内血气刺痛︰用红花一大两，分为四分。以酒一大升，煎钟半，顿服之。不止再服。（《图经本草》）\n一切肿疾︰红花，熟，捣，取汁，服。不过三服，便瘥。（《外台秘要》）\n喉痹壅塞不通者︰红蓝花捣，绞取汁一小升服之，以瘥为度。如冬月无生花，以干者浸湿绞汁，煎热病胎死︰红花，酒煮汁，饮二、三盏。（《熊氏补遗》）\n胎衣不下︰方同上。（《杨氏产乳》）\n产后血晕，心闷气绝︰红花一两，为末，分作二服，酒二盏，煎一盏，连服。如口噤，斡开灌之，或入小便尤妙。（《子母秘录》）\n耳出水 红蓝花三钱半，枯矾五钱。为方去矾。（《圣惠方》）\n噎膈拒食︰端午采头次红花（无灰酒拌，焙干）、血竭（瓜子样者）等分为末。无灰酒一盏，隔汤顿热，徐咽。初服二分；次日，四分；三日，五分。（杨起《简便方》）\n子\n\n旧二，新一。\n血气刺痛︰红蓝子一升。捣碎，以无灰酒一大升拌子，曝干，重捣筛，蜜丸梧子大，空心酒下四十丸。（张仲景方）\n疮疽不出︰红花子、紫草茸各半两，蝉蜕二钱半，水酒钟半，煎减半，量大小加减服。（庞安常《伤寒论》）\n女子中风，血热烦渴︰以红蓝子五合。熬捣，旦日取半大匙，以水一升渣，细细咽之。（《贞元广利方》）\n苗"},
  "线香":{o:[],src:["本草纲目"],d:"新一。\n杨梅毒疮︰龙挂香、孩儿茶、皂角子各一钱，银朱二钱，为末，纸卷作捻，点灯置桶中，以鼻吸烟，一日三次，三日止。内服解毒药，疮即干。（《集简方》）"},
  "络石":{o:[],src:["本草纲目"],d:"旧一，新二。\n小便白浊︰方同上。\n喉痹肿塞，喘息不通，须臾欲绝，神验︰方︰用络石草一两。水一升，煎一大盏。细细呷之，少顷即通。（《外台秘要》）\n痈疽 痛，止痛︰灵宝散︰用鬼系腰（生竹篱阴湿石岸间，络石而生者，好；络木者，无用。其藤柔细，两叶相对，形生三角，用茎叶）一两（洗晒，勿见火），皂荚刺一两（新瓦炒黄），甘草节半两，大栝蒌一个（取仁炒香），乳香、没药各三钱。每服二钱，水一盏，酒半盏，慢火煎至一盏，温服。（《外科精要》）"},
  "续随子":{o:["续随子"],src:["本草备要", "本草纲目"],d:"（一名千金子）\n泻，行水，破血，解毒辛温有毒，行水破血。治症瘕痰饮，冷气胀满，蛊毒鬼疰。利大、小肠，下恶滞物，涂疥癣疮（玉枢丹用之，治百病多效。《经疏》曰∶乃以毒治毒之功）。去壳，取色白者，压去油用（时珍曰∶续随子、大戟、泽漆、甘遂，茎叶相似，主疗亦相似，长于利水，用之得法，皆要药也）。"},
  "绿盐":{o:[],src:["本草纲目"],d:"新二。\n胎赤眼痛︰盐绿一分，蜜半两。于蚌蛤壳内相和。每夜卧时浆水洗目，炙热点之，能断根。（《圣济录》）\n目暗赤涩多泪︰盐绿一钱，蕤仁（去皮）一钱。研热，入好酥一钱，研匀。每夜点一麻子。（《圣惠方》）"},
  "绿矾":{o:[],src:["本草纲目"],d:"旧一，新三十四。重舌木舌︰皂矾二钱，铁上烧红，研，掺之。（陆氏《积德堂方》）\n喉风肿闭︰皂矾一斤，米醋三斤拌，晒干末，吹之。痰涎出尽，用良姜末少许，入茶内漱口，咽之即愈。（孙氏《集效方》）\n眼暴赤烂︰红枣五斤，入绿矾在内，火煨熟，以河水、井水各一碗，桃、柳心各七个，煎稠。每点少许入 上。（《摘玄方》）\n烂弦风眼︰青矾火出毒，细研。泡汤澄清，点洗。（《永类方》）\n倒睫拳毛︰方同上。疟疾寒热︰矾红、独蒜头（煨）等分。捣丸芡子大。每白汤嚼下一丸，端午日合之。（《普济方》）\n少阴疟疾呕吐︰绿矾一钱，干姜（泡）、半夏（姜制），各半两。为末。每服半钱，发日早以醋汤下。（《圣济录》）\n翻胃吐食︰白面二斤半，蒸作大馒头一个，头上开口，剜空，将皂矾填满，以新瓦围住，盐泥封固，挖土窑安放。文武火烧一日夜，取出研末，枣肉为丸梧子大。每服二十丸，空心酒、汤任下。忌酒色。（《医方摘要》）\n大便不通︰皂矾一钱，巴霜二个，同研，入鸡子内搅匀，封头，湿纸裹，煨熟食之，酒下，即通。（《集玄方》）\n肠风下血︰积年不止，虚弱甚者，一服取效。绿矾四两，入砂锅内，新瓦盖定，盐泥固济，赤取出，入青盐、生硫黄各一两、研匀。再入锅中固济， 赤取出，去火毒，研。入熟附子末一两，粟米粥糊丸梧子大。每空心米饮、温酒任下三十丸。（《永类方》）\n妇人血崩︰青矾二两，轻粉一钱，为末，水丸梧子大。每服二、三十丸，新汲水下。（《摘玄方》）\n血证黄肿︰绿矾四两，百草霜一升，炒面半升，为末，沙糖和丸梧子大。每服三、四十丸，食后姜汤下。郑时举所传。又方︰小麦淘净一斤，皂矾半斤，同炒黄为末，黑枣肉半斤捣匀，米醋打糊丸梧子大。每姜汤下八、九十丸，一日三服。（《简便方》）\n脾病黄肿︰青矾四两（ 成赤珠子），当归四两（酒 浸七日，焙），百草霜三两。为末，以浸药酒打糊丸梧子大。每服五丸至七丸，温水下。一月后黄去立效，此方祖传七世。又方︰绿矾四两，百草霜、五倍子各一两，木香一钱。为末，酒煎，飞面丸梧子大。每空心酒下五丸。又方︰平胃散四两、青矾二两。为末，醋糊丸，米饮下。或加乌沉汤四两，酒糊丸亦可。（洁古《活法机要》）\n酒黄水肿︰黄肿积病。青矾半斤（醋一大盏，和匀，瓦盆内 干为度）、平胃散、乌药顺气散各半两。为末，醋煮糊丸梧子大。每酒或姜汤下二、三十丸。不忌口，加锅灰。（赵原杨真人《济急方》）\n食劳黄病，身目俱黄︰青矾锅内安，炭 赤，米醋拌为末，枣肉和丸梧子大。每服二、三十丸，食后姜汤下。（《救急方》）\n腹中食积︰绿矾二两，研，米醋一大碗，瓷器煎之，柳条搅成膏，入赤脚乌一两（研），丸绿豆大。每空心温酒下五丸。（《圣惠方》）\n疳虫食土及生物︰研绿矾末，猪胆汁丸绿豆大。每米饮下五、七丸。（《保幼大全》）\n小儿疳气不可疗者︰绿矾 赤、醋淬三次，为末，枣肉和丸绿豆大。每服十丸，温水下，日三。（《集验方》）\n走马疳疮︰绿矾入锅内，炭火 红，以醋拌匀，如此三次，为末，入麝香少许。温浆水漱净，掺之。（谈野翁《试效方》）\n白秃头疮︰皂矾、楝树子，烧研，搽之。（《普济方》）\n小儿头疮︰绛矾一两，淡豉一两（炒黑），腻粉二钱。研匀。以桑灰汤洗净，掺之良。小儿甜疮︰大枣去核，填入绿矾，烧存性研，贴之。（《拔萃方》）\n耳生烂疮︰枣子去核，包青矾 研，香油调敷之。（《摘玄方》）\n蚰蜒入耳︰水调绿矾，灌之。（《普济方》）\n蛆入耳中︰绿矾掺之，即化为水。（《摘玄方》）\n疮中生蛆︰绿矾末掺贴，即化为水。（《摘玄方》）\n汤火伤灼︰皂矾和凉水浇之。其疼即止，肿亦消。（杨诚《经验方》）\n癣疮作痒︰螺蛳十四个，槿树皮末一两，入碗内蒸熟，入矾红三钱捣匀，搽之。（孙氏《集效方》）\n甲疽延烂︰崔氏方︰治甲疽，或因割甲伤肌，或因甲长侵肉，遂成疮肿，黄水浸淫相染，五指俱烂，渐上脚趺，泡浆四边起，如火烧疮，日夜倍增，医不能疗。绿矾石五两，烧至汁尽，研末，色如黄丹，收之。每以盐汤洗拭，用末浓敷之，以软帛缠裹，当日即汁断疮干。每日一遍，盐汤洗濯，有脓处使净敷，其痂干处不须近。但有急痛，即涂酥少许令润。五日即觉上痂起，依前洗敷。十日痂渐剥尽，软处或更生白脓泡，即擦破敷之，自然瘥也。张侍郎病此，卧经六十日，京医并处方无效，得此法如神。（王焘《外台秘要》）\n妇人甲疽︰妇人趾甲内生疮，恶肉突出，久不愈，名臭田螺。用皂矾日晒夜露。每以一两，煎汤浸洗。仍以矾末一两，加雄黄二钱，硫黄一钱，乳香、没药各一钱。研匀，搽之。（《医方摘要》）\n涂染白发︰绿矾、薄荷、乌头等分为末，以铁浆水浸。日染之。（《相感志》）\n腋下狐气︰绿矾（半生半 ）为末，入少轻粉。以半钱，浴后姜汁调搽，候十分热痛乃止。（《仁斋直指方》）"},
  "绿豆":{o:["绿豆"],src:["本草备要"],d:"泻热解毒\n甘寒。行十二经，清热解毒（一切草木、金石、砒霜毒皆治之），利小便，止消渴，治泻痢，连皮用（其凉在皮）。粉，扑痘疮溃烂良（一市民诵观音经甚诚，出行折一足，哀叫菩萨，梦僧授一方，绿豆粉新铫炒紫色，井水调，浓敷纸贴，杉木扎定，其效如神）。"},
  "绿青":{o:[],src:["本草纲目"],d:"新四。急惊昏迷，不省人事︰石绿四两，轻粉一钱。为末。薄荷汁入酒调一字服，取吐。（《全婴方》）\n风痰迷闷︰碧霞丹︰用石绿十两，乌头尖、附子尖、蝎梢各七十个。为末，糊丸芡子大。每服一丸，薄荷汁入酒半合化下，须臾吐出痰涎。（《和剂局方》）\n小儿疳疮，肾疳鼻疳、头疮耳疮、久不瘥者。石绿、白芷等分。为末。先以甘草水洗疮，拭净敷之，一日愈。（《集玄方》）\n腋下狐臭︰石绿三钱，轻粉一钱。浓醋调涂。五次断根。（《集玄方》）"},
  "缩砂蔤":{o:[],src:["本草纲目"],d:"旧三，新一十三。冷滑下痢，不禁虚羸。用缩砂仁熬为末，以羊子肝薄切掺之，瓦上焙干为末，入干姜末等分，饭丸梧子大。每服四十丸，白汤下，日二服。又方︰缩砂仁、炮附子、干姜、浓朴、陈橘皮等分。为末，饭丸梧子大。每服四十丸，米饮下，日二服。（并《药性论》）\n大便泻血，三代相传者。缩砂仁为末，米饮热服二钱，以愈为度。（《十便良方》）\n小儿脱肛︰缩砂（去皮）为末。以猪腰子一片，批开擦末在内，缚定，煮熟与儿食，次服白矾丸。如气逆肿喘者，不治。（《保幼大全》）\n遍身肿满，阴亦肿者。用缩砂仁、土狗一个，等分，研，和老酒服之。（《直指方》）\n痰气膈胀︰砂仁捣碎，以萝卜汁浸透，焙干为末。每服一、二钱，食远沸汤服。（《简便方》）\n上气咳逆︰砂仁（洗净，炒研）、生姜（连皮）等分。捣烂，热酒食远泡服。（《简便方》）\n子痫昏冒︰缩砂（和皮炒黑），热酒调下二钱。不饮者，米饮下。此方安胎止痛皆效，不可尽述。（陶隐居方）妊娠胎动，偶因所触，或跌坠伤损，致胎不安，痛不可忍者。缩砂（熨斗内炒熟，去皮用仁），捣碎。每服二钱，热酒调下。须臾觉腹中胎动处极热，即胎已安矣。神妇人血崩︰新缩砂仁，新瓦焙研末。米饮服三钱。（《妇人良方》）\n热拥咽痛︰缩砂壳为末，水服一钱。（戴原礼方）\n牙齿疼痛︰缩砂常嚼之良。（《直指方》）\n口吻生疮︰缩砂壳 研，擦之即愈。此蔡医博秘方也。（黎居士《简易方》）\n鱼骨入咽︰缩砂、甘草等分。为末，绵裹含之咽汁，当随痰出矣。（王璆《百一选方》）\n误吞诸物︰金银铜钱等物不化者，浓煎缩砂汤饮之，即下。（危氏《得效方》）\n一切食毒︰缩砂仁末，水服一、二钱。（《事林广记》）"},
  "罗勒":{o:[],src:["本草纲目"],d:"新二。\n鼻疳赤烂：兰香叶（烧灰）二钱，铜青五分，轻粉二字，为末，日敷三次。（钱乙《小儿方》）。\n反胃咳噫：生姜四两（捣烂），入兰香叶一两，椒末一钱，盐和面四两，裹作烧饼，煨熟，空心吃，不过两三度效。反胃，入甘蔗汁和之。（《普济方》）。\n子\n\n新二。\n目昏浮翳：兰香子每用七个，睡时水煎服之，久久有效也。（《海上名方》）。\n走马牙疳：小儿食肥甘，肾受虚热，口作臭息，次第齿黑，名曰崩砂；渐至龈烂，名曰溃槽；又或血出，名曰宣露；重则齿落，名曰腐根。用兰香子末、轻粉各一钱，密陀僧（醋淬，研末）半两，和匀。每以少许敷齿及龈上，立效。内服甘露饮。（《活幼口议》）"},
  "羊桃":{o:[],src:["本草纲目"],d:"旧一，新三。伤寒变 ，四肢烦疼，不食多睡︰羊桃十斤捣熟，浸热汤三斗，日正午时，入坐一炊久。不过三次愈。（《千金》）\n伤寒毒攻，手足肿痛︰羊桃煮汁，入少盐豉渍之。（《肘后》）\n水气鼓胀，大小便涩︰羊桃根、桑白皮、木通、大戟（炒）各半斤（锉）。水一斗，煮五升，熬如稀饧。每空心茶服一匙。二便利，食粥补之。（《圣惠方》）\n蜘蛛咬毒︰羊桃叶捣敷之，立愈。（《备急方》）"},
  "羊肉":{o:["羊肉"],src:["本草备要"],d:"补虚劳\n甘热属火。补虚劳，益气血，壮阳道，开胃健力，通气发疮（仲景治虚羸蓐劳，有当归羊血汤。《十剂》曰∶补可去弱，人参、羊肉之属是也。东垣曰∶人参补气，羊肉补形。凡味同羊肉者，皆补血虚，阳生则阴长也）。羊肝，苦寒（苏颂曰温）色青。补肝而明目（肝以泻为补。羊肝丸，治目疾加黄连）。胆，苦寒。点风泪眼，赤障白翳（腊月入蜜胆中，纸套笼住，悬檐下，待霜出，扫取点眼。又入蜜胆中蒸之，候干，研为膏，每含少许，或点之。名二百味草花膏，以羊食百草，蜂采百花也。时珍曰∶肝窍开于目，胆汁减则目暗。目者，肝之外候，胆之精华也，故诸胆皆治目病）。胫骨，入肾而补骨。烧灰擦牙良（时珍曰∶羊胫骨灰可以磨镜，羊头骨可以消铁。误吞铜钱者，胫骨三钱，米饮下）。"},
  "羊血":{o:["羊血"],src:["本草备要"],d:"解金银、丹石、砒硫一切诸毒。\n乳，甘温。补肺肾虚，润胃脘、大肠之燥。治反胃消渴，口疮舌肿（含漱），蜘蛛咬伤（有浑身生丝者，饮之瘥）。肉、肝，青 羊良；胆，青羯羊良；乳，白 羊良。骨 用。反半夏、菖蒲。忌铜器（牡羊曰 、曰羝，去势曰羯。子曰羔，羔五月曰 ）。"},
  "羊踯躅":{o:[],src:["本草纲目"],d:"新四。\n风痰注痛︰踯躅花、天南星，并生时同捣作饼，甑上蒸四五遍，以稀葛囊盛之。临时取焙为末，蒸饼丸梧子大。每服三丸，温酒下。腰脚骨痛，空心服；手臂痛，食后服，大良。（《续传信方》）\n痛风走注︰黄踯躅根一把，糯米一盏，黑豆半盏，酒、水各一碗，徐徐服。大吐大泄，一服风湿痹痛，手足身体收摄不遂，肢节疼痛，言语蹇涩︰踯躅花酒拌蒸一炊久，晒干为末。每以牛乳一合，酒二合，调服五分。（《圣惠方》）\n风虫牙痛︰踯躅一钱，草乌头二钱半，为末，化腊丸豆大。绵包一丸，咬之，追涎。（《海上仙方》）"},
  "羊蹄":{o:[],src:["本草纲目"],d:"旧六，新七。\n大便卒结︰羊蹄根一两，水一大盏，煎六分，温服。（《圣惠方》）\n肠风下血︰败毒菜根（洗切），用连皮老姜各半盏，同炒赤，以无灰酒淬之，碗盖少顷，去滓，任意饮。（《永类方》）。\n喉痹不语︰羊蹄独根者，勿见风日及妇人、鸡、犬，以三年醋研如泥，生布拭喉外令赤，涂之。（《千金方》）。\n面上紫块：如钱大，或满面俱有。野大黄四两（取汁），穿山甲十片（烧存性），川椒末五钱，生姜四两取汁和研，生绢包擦。如干，入醋润湿。数次如初，累效。（《陆氏积德堂方》）\n疬疡风驳︰羊蹄草根，于生铁上磨好醋，旋旋刮涂。入硫黄少许，更妙。日日用之。（《圣惠》）\n汗斑癜风︰羊蹄根二两，独科扫帚头一两，枯矾五钱，轻粉一钱，生姜半两，同杵如泥。以汤澡浴，用手抓患处起粗皮。以布包药，著力擦之。暖卧取汗，即愈也。乃盐山刘氏方，比用硫黄者更妙。（《蔺氏经验方》）\n头风白屑︰羊蹄草根曝干杵末，同羊胆汁涂之，永除。（《圣惠方》）\n头上白秃︰独根羊蹄，勿见妇女、鸡、犬、风日，以陈醋研如泥，生布擦赤敷之，日一次。（《肘后》）。\n癣久不瘥︰《简要济众方》︰用羊蹄根杵绞汁，入轻粉少许，和如膏，涂之。三、五次即愈。《永类方》︰治癣经年者。败毒菜根（独生者），即羊蹄根，捣三钱，入川百药煎二钱，白梅肉擂匀，以井华水一盏，滤汁澄清。天明空心服之。不宜食热物。其滓抓破擦之。三次即愈。《千金方》︰治细癣。用羊蹄根五升，桑柴灰汁煮四、五沸，取汁洗之。仍以羊蹄汁和矾末涂之。 疥，湿癣浸淫日广，痒不可忍，愈后复发，出黄水︰羊蹄根捣，和大醋，洗净涂上\n疥疮有虫︰羊蹄根捣，和猪脂，入盐少许，日涂之。（《外台秘要》）"},
  "羚羊角":{o:["羚羊角"],src:["本草备要"],d:"泻心、肝火\n苦咸微寒。羊属火，而羚羊属木，入足厥阴（肝）、手太阴、少阴（肺、心）经。目为肝窍，此能清肝，故明目去障。肝主风，其合在筋，此能祛风舒筋，故治惊痫搐搦，骨痛筋挛；肝藏魂，心主神明，此能泻心、肝邪热，故治狂越僻谬，梦魇惊骇；肝主血，此能散血，故治瘀滞恶血，血痢肿毒；相火寄于肝胆，在志为怒，（经曰∶大怒则形气绝，而血菀于上），此能下气降火，故治伤寒伏热，烦懑气逆，食噎不通；羚之性灵，而精在角，故又辟邪而解诸毒（昂按∶痘科多用以清肝火，而《本草》不言治痘）。似羊而大，角有节、最坚劲、能碎金刚石与貘骨（貘，音麦，能食铁）。夜宿防患，以角挂树而栖（角有挂纹者真。一边有节而疏，乃山驴、山羊，非羚也）。多两角。一角者胜。锉研极细，或磨用。"},
  "翘摇":{o:[],src:["本草纲目"],d:"新二。\n活血明目︰漂摇豆为末，甘草汤服二钱，日二钱。（《卫生易简方》）。\n热疟不止︰翘摇杵汁服之。（《广利方》）"},
  "翻白草":{o:[],src:["本草纲目"],d:"新七。\n崩中下血︰用湖鸡腿根一两捣碎，酒二盏，煎一盏服。（《濒湖集简方》）。\n吐血不止︰翻白草，每用五七科 咀，水二钟，煎一钟，空心服。\n疟疾寒热︰翻白草根五七个，煎酒服之。\n无名肿毒︰方同上。\n丁毒初起，不拘已成、未成︰用翻白草十科，酒煎服，出汗即愈。\n浑身疥癞︰端午日午时采翻白草，每用一握，煎水洗之。\n疮溃烂︰端午日午时采翻白草，洗收。每用一握，煎汤盆盛，围住熏洗，效。（刘松石《保寿堂方》）。"},
  "肥皂荚":{o:["肥皂荚"],src:["本草备要"],d:"泻热毒\n辛温。除风湿，去垢腻（故澡身，盥面用之），疗无名肿毒有奇功（不拘奇疡恶毒，用生肥皂去子、弦及筋捣烂，酽醋和敷立愈，不愈再敷奇验。此方方书未载，若贫人，僻地仓卒无药者，用之甚便，故特着之。《集成》曰∶生肥皂火 存性，生油，腻粉调敷诸恶疮）。"},
  "胆矾":{o:["胆矾"],src:["本草备要"],d:"（一名石胆）\n宣，吐风痰，涩，敛咳逆酸涩辛寒。入少阳胆经。性敛而能上行，涌吐风、热痰诞，发散风木相火。治喉痹（醋调咽，吐痰诞立效）咳逆，痉痫崩淋。能杀虫，治牙虫、疮毒、阴蚀。产铜坑中，乃铜之精液（故能入肝、胆治风木）。磨铁作铜色者真，形似空青鸭嘴色为上（市人多以醋揉青矾伪之）。畏桂、芫花、辛夷、白薇。"},
  "胡卢巴":{o:["胡卢巴"],src:["本草备要"],d:"燥，补肾命，除寒湿\n苦温纯阳。入右肾命门。暖丹田，壮元阳。治肾脏虚冷，阳气不能归元（同附子、硫黄），瘕疝冷气（同茴香、巴戟、川乌、川楝、吴茱萸），寒湿香港脚。出岭南番舶者良，云是番莱菔子。酒浸曝，或蒸，或炒。"},
  "胡桃":{o:["胡桃"],src:["本草备要"],d:"补命门，肉润，皮涩\n味甘气热。皮涩（皮敛肺定喘，固肾涩精。今药中罕用，昂谓若用之，当胜金樱、莲须也）肉润，皮汁青黑，属水入肾。通命门，利三焦，温肺润肠，补气养血。佐补骨脂，一木一火，大补下焦（胡桃属木，破故纸属火，有木火相生之妙。古云∶黄柏无知母，破故纸无胡桃，犹水母之无虾也。时珍曰∶三焦者，无气之别使；命门者，三焦之本原。命门指所居之府而言，为藏精、系胞之物；三焦指所治之部而名，为出纳、腐熟之司。一为体，一为用也。其体非脂非肉，白膜裹之，在脊骨第七节两肾中央，系着于脊，下通二肾，上通心、肺贯脑。为生命之源，相火之生，精气之府，人物皆有之。生人生物，皆由此出。《内经》所谓七节之旁，中有小心是也。《难经》误以右肾为命门。高阳生承谬脉诀，至朱肱、陈言、戴起宗始辟之。夫肾命相通，藏精而恶燥，胡桃颇类其状。汁青黑，故入北方，佐破故纸，润燥而调血，使精气内充，血脉通利，诸疾自除矣。男女交媾，皆禀此命火而结胎。人之穷通寿夭，皆根于此），三焦通利，故上而虚寒喘嗽（能温肺化痰。洪迈有痰疾，晚对上谕以胡桃三枚、姜三片，卧时嚼服，即饮汤，复嚼姜、桃如前数，静卧必愈。迈如旨服，旦而痰消嗽止。洪辑幼子病痰喘，梦观音令服人参胡桃汤，服之而愈。明日剥去皮，喘复作，仍连皮用，信宿而瘳。盖皮能敛肺也。胡桃、葱白、姜、茶等分，捣煎，能发汗散寒），下而腰脚虚痛（能补肾），内而心腹诸痛，外而疮肿诸毒（能调中和营），皆可除也。然动风痰，助肾火（连皮同烧细嚼三枚，能久战），有痰火积热者，少服。油者有毒，故杀虫治疮。壳外青皮，压油乌髭发。润燥养血去皮用，敛涩连皮用。"},
  "胡桐泪":{o:["胡桐泪"],src:["本草备要"],d:"泻热，杀虫\n苦能杀虫，咸能入胃软坚，大寒能除热。治咽喉热痛（磨扫取涎），齿 风疳，瘰 结核（苏颂曰∶古方稀用，今口齿家，多用为要药）。出凉肃。乃胡桐脂，入土得斥卤之气结成，如小石片，木泪状如膏油。"},
  "胡椒":{o:["胡椒"],src:["本草备要"],d:"燥，快膈，消痰\n辛热纯阳。暖胃快膈，下气消痰。治寒痰食积，肠滑冷痢，阴毒腹痛，胃寒吐水，牙齿浮热作痛（合荜茇散之）。杀一切鱼、肉、鳖、蕈（音寻，上声）毒。食料宜之，嗜之者众。多食损肺，走气动火，发疮、痔、脏毒，齿痛目昏。毕澄茄一类二种，主治略同。"},
  "胡瓜":{o:[],src:["本草纲目"],d:"旧一，新六。\n小儿热痢︰嫩黄瓜同蜜食十余枚，良。（《海上名方》）。\n水病肚胀，四肢浮肿︰用胡瓜一个破开，连子以醋煮一半，水煮一半至烂，空心俱食之，须臾下水也。（《千金髓》）。\n小儿出汗︰香瓜丸︰用黄连、胡黄连、黄柏、川大黄（煨熟）、鳖甲（醋炙）、柴胡、芦荟、青皮等分为末。用大黄瓜黄色者一个，割下头，填药至满，盖定签住，慢火煨熟，同捣烂，入面糊丸绿豆大。每服二、三丸，大者五、七丸至十丸，食后新水下。（钱乙《小儿方》）。\n咽喉肿痛︰老黄瓜一枚去子，入消填满，阴干为末。每以少许吹之。（《医林集要》）。\n杖疮 肿︰六月六日，取黄瓜入瓷瓶中，水浸之。每以水扫于疮上，立效。（《医林集要》）。\n火眼赤痛︰五月取老黄瓜一条，上开小孔，去瓤，入芒硝令满，悬阴处，待消透出刮下，留点眼甚效。（《寿域神方》）。\n汤火伤灼︰五月五日，掐黄瓜入瓶内封，挂檐下，取水刷之，良。（《医方摘要》）。\n叶"},
  "胡荽":{o:["胡荽"],src:["本草备要", "本草纲目"],d:"宣，发痘疹，辟恶气\n辛温香窜。内通心脾，外达四肢。辟一切不正之气，痧疹、痘疮不出。煎酒喷之（心脾之气，得芳香而营运，含喷遍身，勿 头面。痘疹家悬挂，辟邪恶，胡荽久食，令人多忘，病患不宜食胡荽、黄花菜）。"},
  "胡葱":{o:[],src:["本草纲目"],d:"新一。\n身面浮肿，小便不利，喘急：用胡葱十茎，赤小豆三合，硝石一两，以水五升，煮葱、豆至熟，候水干，入硝石，同擂成膏。每空心温酒服半匙。（《圣惠方》）\n子"},
  "胡麻":{o:["胡麻"],src:["本草备要"],d:"（即芝麻，一名巨胜子，种出大宛，故曰胡麻）\n补肝肾，润五脏，清肠甘平。补肺气、益肝肾，润五脏，填精髓，坚筋骨，明耳目，耐饥渴（可以辟谷，但滑肠，与白术并用为胜），乌髭发，利大小肠，逐风湿气（刘河间曰∶麻木谷而治风。又云∶治风先治血，血活则风散，胡麻入肝益血，故风药中不可阙也。郑奠一用鳖虱胡麻，佐苦参、蒺藜，治大疯疥癞，屡有愈者），凉血解毒。生嚼敷小儿头疮。麻油滑胎疗疮，熬膏多用之（凉血解毒，止痛生肌）。皮肉俱黑者良（入肾） 栗色者名鳖虱胡麻更佳，九蒸九晒，可以服食（陶宏景曰∶八谷之中，惟此为良。昂按∶若云自大宛来，则非八谷之麻，明矣。又按∶月令仲秋之月，天子以犬尝麻，则其为八谷之麻又可见矣。种出大宛之说，何以称焉，岂白者产中原、黑者产大宛乎？）"},
  "腊雪水":{o:["腊雪水"],src:["本草备要"],d:"泻热\n甘寒。治时行瘟疫，宜煎伤寒、火 （音谒，伤暑）之药，抹痱良。"},
  "自然铜":{o:["自然铜"],src:["本草备要", "本草纲目"],d:"重，续筋骨\n辛平。主折伤，续筋骨，散瘀止痛（折伤必有死血瘀滞经络，然须审虚实，佐以养血、补气、温经之药。铜非 不可用，火毒、金毒相煽，复挟香药，热毒内攻，虽有接骨之功，必多燥散之祸，用者慎之）。产铜坑中。火 、醋淬七次，细研，甘草水飞用（昔有饲折翅雁者，雁飞去，故治折伤）。"},
  "船底苔":{o:[],src:["本草纲目"],d:"旧二。小便五淋︰船底苔一团，鸡子大，水煮饮。（陈藏器）。\n乳石发动，小便淋沥，心神闷乱︰船底青苔半鸡子大，煎汁温服，日三、四次。（《圣惠"},
  "艾":{o:[],src:["本草纲目"],d:"旧二十三，新二十九。伤寒时气，温病头痛，壮热脉盛。以干艾叶三升。水一斗，煮一升，顿服取汗。（《肘后方》）\n妊娠伤寒壮热，赤斑变为黑斑，溺血︰用艾叶如鸡子大，酒三升，煮二升半，分为二服。（《伤寒类要》）\n妊娠风寒卒中，不省人事，状如中风︰用熟艾三两，米醋炒极热，以绢包熨脐下，良久即苏。（《妇人良方》）\n中风口 ︰以苇筒长五寸，一头刺入耳内，四面以面密封，不透风，一头以艾灸之七壮。患右灸左，患左灸右。（《胜金方》）\n中风口噤︰熟艾灸承浆一穴，颊车二穴，各五壮。（《千金方》）\n中风掣痛，不仁不随︰并以干艾斛许，揉团纳瓦甑中，并下塞诸孔，独留一目，以痛处著舌缩口噤︰以生艾捣敷之。干艾浸湿亦可。（《圣济录》）\n咽喉肿痛︰《医方大成》︰同嫩艾捣汁，细咽之。《经验方》︰用青艾和茎叶一握，同醋捣烂，敷于喉上。冬月取干艾亦得。李亚所传方也。癫痫诸风︰熟艾于阴囊下谷道正门当中间，随年岁灸之。（《斗门方》）\n鬼击中恶，卒然著人，如刀刺状，胸胁腹内 刺切痛不可按，或即吐血、鼻中出血、下血，一名鬼排︰以熟艾如鸡子大三枚，水五升，煎二升，顿服。（《肘后方》）\n小儿脐风撮口︰艾叶烧灰填脐中，以帛缚定效。或隔蒜灸之，候口中有艾气立愈。（《简便方》）\n狐惑虫 病患齿无色，舌上白，或喜睡不知痛痒处，或下痢，宜急治下部。不晓此者，但攻其上，而下部生虫，食其肛，烂见五脏，便死也。烧艾于管中，熏下部令烟入，或少加雄黄更妙。罂中烧烟亦可。（《肘后方》）\n头风久痛︰蕲艾揉为丸，时时嗅之，以黄水出为度。（《青囊杂纂》）\n头风面疮，痒出黄水︰艾叶二两，醋一斤，砂锅煎取汁，每薄纸上贴之。一日一、两上。（心腹恶气︰艾叶捣汁饮之。（《药性论》）\n脾胃冷痛︰白艾末，沸汤服二钱。（《卫生易简方》）\n蛔虫心痛如刺，口吐清水︰白熟艾一升。水三升，煮一升服，吐虫出。或取生艾捣汁，五更食香脯一片，乃饮一升，当下虫出。（《肘后方》）\n口吐清水︰干蕲艾煎汤啜之。（《怪证奇方》）。霍乱洞下不止︰以艾一把。水三升，煮一升，顿服。（《外台秘要》）\n老小白痢︰艾姜丸︰用陈北艾四两，干姜（炮）三两，为末，醋煮仓米糊丸梧子大。每服七诸痢久下︰艾叶、陈皮等分，煎汤服之。亦可为末，酒煮烂饭和丸，每盐汤下二、三十丸暴泄不止︰陈艾一把，生姜一块，水煎热服。（《生生编》）\n粪后下血︰艾叶、生姜煎浓汁，服三合。（《千金方》）\n野鸡痔病︰先以槐柳汤洗过，以艾灸上七壮，取效。郎中王及乘骡入西川，数日病痔大作五壮，忽觉一道热气入肠中，因大转泻，血秽并出，泻后遂失胡瓜所在矣。（《经验方》）\n妊娠下血︰张仲景曰︰妇人有漏下者，有半产后下血不绝者，有妊娠下血者，并宜胶艾汤清酒三升，煮取三升，乃纳胶令消尽，每温服一升，日三服。（《金匮要略》）\n妊娠胎动或腰痛，或抢心，或下血不止，或倒产子死腹中︰艾叶一鸡子大，酒四升，煮二升，分二服。（《肘后方》）\n胎动迫心作痛︰艾叶鸡子大。以头醋四升，煎二升，分温服。（《子母秘录》）\n妇人崩中连日不止︰熟艾鸡子大，阿胶（炒为末）半两，干姜一钱。水五盏，先煮艾姜至二盏半，倾出，入胶烊化，分三服，一日服尽。（初虞世《古今录验》）\n产后泻血不止︰干艾叶半两，炙熟老生姜半两，浓煎汤，一服止，妙。（孟诜《食疗本草》）\n产后腹痛欲死，因感寒起者︰陈蕲艾二斤。焙干，捣铺脐上，以绢复住，熨斗熨之，待口中艾气出，则痛自止矣。（《杨诚经验方》）\n忽然吐血一二口，或心衄，或内崩︰熟艾三团，水五升，煮二升服。一方︰烧灰水服鼻血不止︰艾灰吹之。亦可以艾叶煎服。（《圣惠方》）\n盗汗不止︰熟艾二钱，白茯神三钱，乌梅三个，水一钟，煎八分，临卧温服。（《通妙真人方》）\n火眼肿痛︰以艾烧烟起，用碗覆之，候烟尽，碗上刮煤下，以温水调化洗眼，即瘥。更入面上 ︰艾灰、桑灰各三升，以水淋汁，再淋至三遍，以五色布纳于中，同煎，令可丸妇人面疮，名粉花疮︰以定粉五钱，菜子油调泥碗内，用艾一、二团，烧烟熏之，候烟尽身面疣目︰艾火灸三壮即除。（《圣惠方》）\n鹅掌风病︰蕲艾（真者）四、五两，水四五碗，煮五、六滚，入大口瓶内盛之，用麻布二层缚之，将手心放瓶上熏之，如冷再热，如神。（陆氏《积德堂方》）\n疮疥熏法︰熟蕲艾一两，木鳖子三钱，雄黄二钱，硫黄一钱。为末，揉入艾中，分作四条。每以一条安阴阳瓦中，置被里烘熏，后服通圣散。（《医方摘要》）\n小儿疳疮︰艾叶一两，水一升，煮取四合，分三服。（《备急方》）\n小儿烂疮︰艾叶烧灰，敷之，良。（《子母秘录》）\n疮口冷不合︰熟艾烧烟熏之。（《经验方》）\n白癞风疮︰干艾随多少，以浸曲酿酒如常法，日饮之，觉痹即瘥。（《肘后方》）\n疔疮肿毒︰艾蒿一担烧灰，于竹筒中淋取汁，以一、二合，和锻石如糊。先以针刺疮至痛，乃点药三遍，其根自拔。玉山韩光以此治人神验。贞观初，衢州徐使君访得此方。予用治三十余人，得效。（孙真人《千金方》）\n发背初起未成，及诸热肿︰以湿纸拓上，先干处是头，著艾灸之。不论壮数，痛者灸至不痛；不痛者灸至痛乃止。其毒即散，不散亦免内攻，神方也。（李绛《兵部手集》）\n痈疽不合，疮口冷滞︰以北艾煎汤洗后，白胶熏之。（《直指方》）\n咽喉骨哽︰用生艾蒿数升，水、酒共一斗，煮四升，细细饮之，当下。（《外台秘要》）\n误吞铜钱︰艾蒿一把，水五升，煎一升，顿服便下。（钱相公《箧中方》）\n诸虫蛇伤︰艾灸数壮甚良。（《集简方》）\n风虫牙痛︰化蜡少许，摊纸上，铺艾，以箸卷成筒，烧烟，随左右熏鼻，吸烟令满口，呵\n实"},
  "芋":{o:[],src:["本草纲目"],d:"旧二，新二。\n腹中癖气︰生芋子一斤压破，酒五斤渍二七日。空腹每饮一升，神良。（韦宙《独行方》）。\n身上浮风︰芋煮汁浴之。慎风半日。（孟诜《食疗》）。\n疮冒风邪肿痛︰用白芋烧灰敷之。干即易。（《千金方》）。\n头上软疖︰用大芋捣敷之，即干。（《简便方》）。\n叶、茎\n\n新一。\n黄水疮︰芋苗晒干，烧存性研搽。（邵真人《经验方》）。"},
  "芍药":{o:[],src:["本草纲目"],d:"旧六，新一十。\n服食法︰颂曰︰安期生服炼芍药法云︰芍药有二种︰救病用金芍药，色白多脂肉；其木芍药，色紫瘦多脉。若取审看，勿令差错。凡采得，净洗去皮，以东流水煮百沸，阴干。停三日，又于木甑内蒸之，上覆以净黄土，一日夜熟，出阴干，捣末。以麦饮或酒服三钱匕，日三。服满三百日，可以登岭绝谷不饥。（《图经本草》）\n腹中虚痛︰白芍药三钱，炙甘草一钱。夏月，加黄芩五分；恶寒，加肉桂一钱；冬月大寒，再加桂一钱。水二盏，煎一半，温服。（《洁古用药法象》）\n风毒骨痛在髓中。芍药二分，虎骨一两（炙），为末，夹绢袋盛，酒三升，渍五日。每服三合，日三服。（《经验后方》）\n脚气肿痛︰白芍药六两，甘草一两。为末，白汤点服。（《事林广记》）\n消渴引饮︰白芍药、甘草等分。为末。每用一钱，水煎服，日三服。鄂渚辛 之患此九年，服药止而复作。苏朴授此方，服之七日顿愈。古人处方，殆不可晓，不可以平易而忽之也。（陈日华《经验方》）\n小便五淋︰赤芍药一两，槟榔一个（面裹煨）。为末。每服一钱，水一盏，煎七分，空心服。（《博济方》）\n衄血不止︰赤芍药为末，水服二钱匕。（《事林广记》）\n衄血咯血︰白芍药一两，犀角末二钱半。为末。新水服一钱匕，血止为限。（《古今录验》）\n崩中下血，小腹痛甚者。芍药一两（炒黄色），柏叶六两（微炒）。每服二两，水一升，煎六合，入酒五合，再煎七合，空心分为两服。亦可为末，酒服二钱。（《圣惠方》）\n经水不止︰白芍药、香附子、熟艾叶各一钱半。水煎服之。（《熊氏补遗》）\n血崩带下︰赤芍药、香附子等分。为末。每服二钱，盐一捻，水一盏，煎七分，温服，日二服。十服见效，名如神散。（《良方》）\n赤白带下，年深月久不瘥者。取白芍药三两，并干姜半两。锉熬令黄，捣末。空心水饮服二钱匕，日再服。《广济方》只用芍药炒黑，研末，酒服之。（《贞元广利方》）\n金疮血出︰白芍药一两。熬黄为末。酒或米饮服二钱，渐加之。仍以末敷疮上即止，良验。（《广利方》）\n痘疮胀痛︰白芍药为末，酒服半钱匕。（《痘疹方》）\n木舌肿满，塞口杀人。红芍药、甘草煎水热漱。（《圣济总录》）\n鱼骨哽咽︰白芍药嚼细咽汁。（《事林广记》）"},
  "芎䓖":{o:[],src:["本草纲目"],d:"旧七，新一十三。生犀丸︰宋真宗赐高相国，去痰清目，进饮食。生犀丸︰用川芎十两，紧小者，粟米泔浸二日换，切片子，晒干为末，分作两料。每料入麝、脑各一分，生犀半两，重汤煮，蜜和丸小弹子大。茶、酒嚼下一丸。痰，加朱砂半两；膈壅，加牛黄一分，水飞铁粉一分。头目昏眩，加细辛一分。口眼 斜，加炮天南星一分。（《御药院方》）\n气虚头痛︰真川芎 为末，腊茶调服二钱，甚捷。曾有妇人产后头痛，一服即愈。（《集简方》）\n气厥头痛︰妇人气盛头痛，及产后头痛。川芎 、天台乌药等分，为末。每服二钱，葱茶调下。《御药院方》︰加白术，水煎服。风热头痛︰川芎一钱，茶叶二钱，水一钟，煎五分，食前热服。（《简便方》）\n头风化痰︰川芎洗切，晒干为末，炼蜜丸如小弹子大。不拘时嚼一丸，茶清下。（《经验后方》）\n偏头风痛︰京芎细锉，浸酒日饮之。（《斗门方》）\n风热上冲︰头目运眩，或胸中不利。川芎、槐子各一两。为末。每服三钱，用茶清调下。胸中不利，以水煎服。（张洁古《保命集》）\n首风旋运及偏正头疼，多汗恶风，胸膈痰饮。川芎一斤，天麻四两，为末，炼蜜丸如弹子大。每嚼一丸，茶清下。（刘河间《宣明方》）\n失血眩晕︰方见当归下。一切心痛︰大芎一个，为末，烧酒服之。一个住一年，两个住二年。（《孙氏集效方》）\n经闭验胎︰经水三个月不行。验胎法︰川芎生为末，空心煎艾汤服一匙。腹内微动者是有胎不动者非也。（《灵苑方》）\n损动胎气︰因跌扑举重，损胎不安，或子死腹中者。芎 为末，酒服方寸匕，须臾一二服。立出。（《续十全方》）\n崩中下血，昼夜不止。《千金方》︰用芎 一两，清酒一大盏，煎取五分，徐徐进之。《圣惠》︰加生地黄汁二合，同煎。酒癖胁胀，时复呕吐，腹有水声。川芎、三棱（炮）各一两，为末。每服二钱，葱白汤下。（《圣济总录》）\n小儿脑热好闭目，或太阳痛，或目赤肿。川芎 、薄荷、朴硝各二钱，为末，以少许吹鼻中。（《全幼心鉴》）\n齿败口臭︰水煎芎 ，含之。（《广济方》）\n牙齿疼痛︰大川芎 一个，入旧糟内藏一月，取焙，入细辛同研末，揩牙。（《本事方》）\n诸疮肿痛︰抚芎 研，入轻粉，麻油调涂。（《普济方》）\n产后乳悬︰妇人产后，两乳忽长，细小如肠，垂过小肚，痛不可忍，危亡须臾，名曰乳悬。将芎 、当归各一斤。以半斤锉散，于瓦石器内，用水浓煎，不拘多少频服；仍以一斤半锉块，于病患桌下烧烟，令将口鼻吸烟。用尽未愈，再作一料。仍以蓖麻子一粒，贴其顶心。（夏子益《奇疾方》）"},
  "芙蓉花":{o:["芙蓉花"],src:["本草备要"],d:"泻，凉血，解毒\n辛平、性滑涎粘。清肺凉血，散热止痛，消肿排脓。治一切痈疽肿毒有殊功（用芙蓉花，或叶、或皮、或根，生捣或干研末，蜜调涂四围，中间留头，干则频换。初起者即觉清凉，痛止肿消。已成者即脓出，已溃者则易敛。疡科秘其名为清凉膏、清露散、铁箍散，皆此物也。或加赤小豆末，或苍耳烧存性为末，加入亦妙）。"},
  "芜夷":{o:["芜夷"],src:["本草备要"],d:"宣，散风湿，泻，消积，杀虫\n辛散满，苦杀虫，温燥湿化食（诸虫皆因湿而生，气食皆因寒而滞）。祛五脏、皮肤、肢节风湿，心腹积冷，症痛鳖瘕（《直指方》云∶嗜酒人，血入于酒为酒鳖；多气人，血入于气为气鳖；虚劳人，败血杂痰为血鳖。如虫之行，上侵人咽，下蚀人肛，或附胁背，或隐胸腹。惟用芜夷炒，兼暖胃、理气、益血之药，乃可杀之），痔 疮癣，小儿惊疳冷痢（得诃子、豆蔻良），胃中有虫，食即作痛（和面炒黄为末，米饮下）。形类榆荚。陈久、气膻者良。"},
  "芜菁":{o:[],src:["本草纲目"],d:"旧七，新七。\n预禳时疾：立春后遇庚子日，温蔓荆汁，合家大小并服之，不限多少，一年可免时疾。（《神仙教子法》）。\n鼻中衄血：诸葛菜，生捣汁饮。（《十便良方》）。\n大醉不堪，连日病困者：蔓荆菜，入少米煮熟，去滓，冷冻饮料之良。（《肘后方》）。\n饮酒辟气：干蔓荆根二七枚，蒸三遍，碾末。酒后水服二钱，即无酒气也。（《千金》）。\n一切肿毒：孙真人食忌：生蔓荆根一握，入盐花少许，同捣封之，日三易之。《肘后方》：用蔓荆叶不中水者，烧灰和腊猪脂封之。\n疔肿有根：用大针刺作孔，削蔓荆根如针大，染铁生衣刺入孔中。再以蔓荆根、铁生衣等分，捣涂于上。有脓出即易，须臾根出立瘥。忌油腻、生冷、五辛、粘滑、陈臭。（《肘后》）。\n乳痈寒热：蔓荆根并叶，去土，不用水洗，以盐和捣涂之。热即换，不过三、五次即瘥。\n冬月只用根。此方已救十数人。须避风。（李绛《兵部手集》）。\n女子妒乳：生蔓荆根捣，和盐、醋、浆水煮汁洗之，五、六度良。又捣：和鸡子白封之亦妙。（《食疗》）。\n阴肿如斗：生蔓荆根捣封之，治人所不能治者。（《集疗方》）\n豌豆斑疮：蔓荆根捣汁，挑疮研涂之。三食顷，根出矣。（《肘后方》）。\n犬咬伤疮重发者：用蔓荆根捣汁服之，佳。（《肘方》）。\n小儿头秃：芜菁叶烧灰，和脂敷之。（《千金》）。\n飞丝入眼：蔓荆菜揉烂帕包，滴汁三、两点，即出也。（《普济方》）\n子\n\n旧十二，新十。\n明目益气：芜菁子一升，水九升，煮汁尽，晒干。如此三度，研细。水服方寸匕，日三。\n亦可研水和米煮粥食。（《外台秘要》）\n常服明目，使人洞视充肥：用芜菁子三升，以苦酒三升，煮熟晒干，研筛末。以井华水服方寸匕，日三，无所忌。《抱朴子》云：服尽一斗，能夜视有所见物。（《千金方》）\n青盲眼障，但瞳子不坏者，十得九愈：用蔓荆子六升，蒸之气遍，合甑取下，以釜中热汤淋之，乃曝干，还淋，如是三遍，即收杵为末。食上清酒服方寸匕，日再服。（崔元亮《海上方》）。\n虚劳目暗：方同上法。（《普济方》）。\n补肝明目：芜菁子淘过一斤，黄精二斤同和，九蒸九晒为末。每空心米饮服二钱，日再服。又方：蔓荆子二升，决明子一升和匀，以酒五升煮干，曝为末。每服二钱，温水调下，日二。（并《圣惠》）。\n风邪攻目，视物不明，肝气虚者：用蔓荆子四两（入瓷瓶中烧黑，无声取出），入蛇蜕二两（又烧成灰）。为末。每服半钱，食后酒下，日三服。（《圣济总录》）。\n服食辟谷：芜菁子，熟时采之，水煮三过，令苦味尽，曝捣为末。每服二钱，温水下，日三次。久可辟谷。（苏颂《图经本草》）。\n黄汗染衣，涕唾皆黄：用蔓荆子捣末，平旦以井华水服一匙，日再服。\n加至两匙，以知为度。每夜以帛浸小便，逐日看之，渐白则瘥，不过服五升已来也。（《外台秘要》）。\n黄胆如金，睛黄，小便赤：用生蔓荆子末，熟水服方寸匕，日三服。（《孙真人食忌》）。\n急黄黄胆及内黄，腹结不通：用蔓荆子捣末，水绞汁服。当得嚏，鼻中出黄水，及下利则愈。以子压油，每服一盏更佳。（陈藏器《本草拾遗》）。\n热黄便结：用芜菁子捣末，水和绞汁服。少顷当泻一切恶物，沙、石、草、发并出。（孟诜《食疗本草》）。\n二便关格，胀闷欲绝：蔓荆子油一合，空腹服之即通。通后汗出勿怪。（《圣惠方》）。\n心腹作胀：蔓荆子一大合，拣净捣烂，水一升和研，滤汁一盏，顿服。少顷自利，或自吐，或得汗，即愈。（《外台秘要》）。\n霍乱胀痛：芜菁子，水煮汁，饮之。（《濒湖集简方》）。\n妊娠溺涩：芜菁子末，水服方寸匕，日二服。（《子母秘录》）。\n风疹入腹，身体强，舌干硬：用蔓荆子三两。为末。每温酒服一钱。（《圣惠方》）。\n瘭疽发热，疽著手、足、肩、背，累累如米起，色白，刮之汁出，复发热：用芜菁子熟捣帛裹，展转其上，日夜勿止。（《肘后方》）。\n骨疽不愈：愈而复发，骨从孔中出者。芜菁子，捣敷之，用帛裹定，日一易之。（《千金方》）。\n小儿头秃：蔓荆子末，和酢敷之。一日三上。（《千金方》）。\n眉毛脱落：蔓荆子四两。炒研，醋和涂之。（《圣惠》）。\n面 痣点：蔓荆子研末，入面脂中，夜夜涂之。亦去面皱。（《圣惠方》）。\n花"},
  "芝":{o:[],src:["本草纲目"],d:"新一。\n紫芝丸︰治虚劳短气，胸胁苦伤，手足逆冷，或时烦躁口干，目视 ，腹内时痛，不思饮食，此药安神保精也︰紫芝一两半，山芋（焙）、天雄（炮去皮）、柏子仁（炒）、巴戟天（去心）、白茯苓（去皮）、枳实（去瓤麸炒）各三钱五分，生地黄（焙）、麦门冬（去心焙）、五味子（炒）、半夏（制炒）、附子（炒去皮）、牡丹皮、人参各七钱五分，远志（去心）、蓼实各二钱五分，瓜子仁（炒）、泽泻各五钱，为末，炼蜜丸梧子大。每服十五丸，渐至三十丸，温酒下，日三服。（《圣济总录》）"},
  "芥":{o:[],src:["本草纲目"],d:"新四。\n牙龈肿烂，出臭水者：芥菜秆烧存性，研末，频敷之，即愈。\n飞丝入目：青菜汁点之如神。（《摘玄方》）。\n漆疮搔痒：芥菜煎汤，洗之。（《千金方》）。\n痔疮肿痛：芥叶捣饼，频坐之。（谈野翁《经效方》）。\n子\n\n旧八，新十六。\n感寒无汗：水调芥子末填脐内，以热物隔衣熨之，取汗出妙。（杨起《简便单方》）。\n身体麻木：芥菜子末，醋调涂之。（《济生秘览》）。\n中风口噤，舌本缩者：用芥菜子一升研，入醋二升，煎一升，敷颔颊下，效。（《圣惠方》）。\n小儿唇紧：用马芥子捣汁曝浓，揩破，频涂之。（崔氏《纂要方》）。\n喉痹肿痛：芥子末，水和敷喉下，干即易之。又用辣芥子研末，醋调取汁，点入喉内。\n待喉内鸣，却用陈麻骨烧烟吸入，立愈。（并《圣惠方》）。\n耳卒聋闭：芥子末，人乳汁和，以绵裹塞之。（《外台秘要》）。\n雀目不见：真紫芥菜子，炒黑为末，用羊肝一具，分作八服。每用芥末三钱，捻肝上，笋箨裹定，煮熟冷食，以汁送下。（《圣济总录》）。\n目中翳膜：芥子一粒，轻手 入眼中。少顷，以井华水、鸡子清洗之。（《总录》）。\n眉毛不生：芥菜子、半夏等分，为末，生姜自然汁调搽，数次即生。（孙氏《集效方》）。\n鬼疰劳气：芥子三升，研末，绢袋盛，入三斗酒中七日，温服，一日三次。（《广济方》）。\n热痰烦运：方见白芥。\n霍乱吐泻：芥子捣细，水和敷脐上。（《圣济总录》）。\n反胃吐食：芥子末，酒服方寸匕，日三服。（《千金方》）。\n上气呕吐：芥子末，蜜丸梧子大，井华水寅时下七丸，申时再服。（《千金方》）。\n脐下绞痛：方同上。\n腰脊胀痛：芥子末调酒，贴之立效。（《摘玄方》）。\n走注风毒作痛：用小芥子末，和鸡子白涂之。（《圣惠》）。\n一切痈肿：猪胆汁和芥子末贴之，日三上。猪脂亦可。（《千金翼》）。\n痈肿热毒：家芥子末同柏叶捣涂，无不愈者，大验。得山芥更妙。（《千金翼》）。\n热毒瘰疬：小芥子末，醋和贴之。看消即止，恐损肉。（《肘后》）。五种 疾：芥子末，以水、蜜和敷，干即易之。（《广济方》）。\n射工中人有疮：用芥子末和苦酒浓涂之。半日痛即止。（《千金方》）。\n妇人经闭不行，至一年者，脐腹痛，腰腿沉重，寒热往来：用芥子二两，为末。每服二钱，热酒食前服。（《仁存方》）。\n阴证伤寒，腹痛厥逆：芥菜子研末，水调贴脐上。（《生生编》）"},
  "芦":{o:[],src:["本草纲目"],d:"旧六，新六。\n生姜各十两，橘皮、茯苓各五两，水二斗，煮八升，去滓，分五服，取汗乃瘥。（《外台秘要》）\n水煮浓汁，频饮二升。必效。若以童子小便煮服，不过三服愈。（《肘后方》）\n膈气滞，烦闷不下食︰芦根五两（锉）。以水三大盏，煮取二盏，去滓温服。（《金匮玉函方》）\n反胃上气︰芦根、茅根各二两。水四升，煮二升，分服。（《千金方》）\n霍乱烦闷︰芦根三钱，麦门冬一钱。水煎服。（《千金方》）\n霍乱胀痛︰芦根一升，生姜一升，橘皮五两。水八升，煎三升，分服。（《太平圣惠方》）\n食狗肉毒，心下坚，或腹胀口干，忽发热妄语︰芦根煮汁服。（《梅师方》）\n中马肉毒︰方同上。（《圣惠》）\n鱼毒︰方同上。（《肘后方》）\n食蟹中毒︰方同上。（《千金》）\n中药箭毒︰方同上。（《千金》）\n茎、叶\n\n新七。\n霍乱烦渴腹胀︰芦叶一握，水煎服。又方︰芦叶五钱，糯米二钱半，竹茹一钱。水煎，入姜汁、蜜各半合，煎两沸，时时呷之。（《圣惠方》）\n吐血不止︰芦荻外皮烧灰，勿令白，为末，入蚌粉少许，研匀。麦门冬汤服一、二钱。三服可救一人。（《圣惠方》）\n肺痈咳嗽，烦满微热，心胸甲错︰苇茎汤︰用苇茎（切）二升，水二斗桃仁五十枚，薏苡仁、瓜瓣各半升，煮取二升，服。当吐出脓血而愈。（张发背溃烂︰陈芦叶为末，以葱椒汤洗净，敷之神效。（《乾坤秘韫》）\n痈疽恶肉︰白炭灰、荻灰等分。煎膏涂之。蚀尽恶肉，以生肉膏贴之。亦去黑子。此药只可留十日，久则不效。（葛洪《肘后方》）\n小儿秃疮︰以盐汤洗净，蒲苇灰敷之。（《圣济总录》）\n蓬\n\n新二。\n干霍乱病，心腹胀痛︰芦蓬茸一把，水煮浓汁，顿服二升。（《肘后方》）\n诸般血病︰水芦花、红花、槐花、白鸡冠花、茅花等分。水二钟，煎一钟服。（万表《积善堂方》)"},
  "芦荟":{o:["芦荟"],src:["本草备要"],d:"泻热，杀虫\n大苦大寒。功专清热杀虫，凉肝明目，镇心除烦。治小儿惊痫五疳，敷 齿湿癣（甘草末和敷），吹鼻杀脑疳，除鼻痒。小儿脾胃虚寒作泻者勿服。出波斯国。木脂也，味苦、色绿者真。"},
  "芭蕉根":{o:["芭蕉根"],src:["本草备要"],d:"泻热\n味甘大寒。治天行热狂，烦闷消渴，产后血胀（并捣汁服），涂痈肿结热（为末，油调敷。霜后者佳）。"},
  "花乳石":{o:[],src:["本草纲目"],d:"新五。\n花蕊石散︰治五内崩损，喷血出斗升，用此治之。花蕊石 存性，研如粉。以童子小便一钟，男，入酒一半；女，入醋一半，煎温，食后调服二钱，甚者五钱。能使瘀血化为黄水，后以独参汤补之。（葛可久《十药神书》）\n花蕊石散︰治一切金刃箭镞伤，及打扑伤损，狗咬至死者。急以药掺伤处，其血化为黄水，再掺便活，更不疼痛。如内损血入脏腑，煎童子小便，入酒少许，热调一钱服，立效。畜生抵伤，肠出不损者，急纳入，桑白皮线缝之，掺药，血止立活。妇人产后败血不尽，血晕，恶血奔心，胎死腹中，胎衣不下，至死，但心头温暖者。急以童子小便调服一钱，取下恶物如猪肝，终身不患血风血气。若膈上有血，化为黄水，即时吐出，或随小便出，甚效。硫黄四两，花蕊石一两。并为粗末拌匀，以胶泥固济，日干，瓦罐一个盛之，泥封口，焙干，安在四方砖上，砖上书八卦五行字。用炭一秤簇匝，从巳午时自下生火， 至炭消冷定，取出为细末，瓶收用。（《和剂局方》）\n金疮出血︰方见主治。多年障翳︰花蕊石（水飞焙）、防风、川芎 、甘菊花、白附子、牛蒡子各一两，甘草（炙）半两。为末。每服半钱，腊茶下。（《卫生家宝方》）\n脚缝出水︰好黄丹，入花蕊石末，掺之。（谈野翁《试效方》）"},
  "花蕊石":{o:["花蕊石"],src:["本草备要"],d:"涩，止血\n酸涩气平。专入肝经血分。能化瘀血为水，止金疮出血（刮末敷之即合，仍不作脓。《局方》治损伤诸血，胎产恶血、血晕，有花蕊石散），下死胎胞衣（恶血化则胞胎无阻）。出陕华代地。体坚色黄。 研，水飞用。"},
  "芸苔":{o:["芸薹"],src:["本草备要", "本草纲目"],d:"宣，散血，消肿\n辛温。散血消肿，捣贴乳痈丹毒（孙思邈曰∶捣贴丹毒，随手即消，其效如神），动疾发疮。即油菜（道家五荤之一）。子，与叶同功，治产难。"},
  "苋":{o:[],src:["本草纲目"],d:"旧二，新五。\n产后下痢，赤白者︰用紫苋菜一握切煮汁，入粳米三合，煮粥，食之立瘥也。（《寿亲养老书》）。\n小儿紧唇︰赤苋，捣汁洗之，良。（《圣惠》）。\n漆疮搔痒︰苋菜，煎汤洗之。\n蜈蚣螫伤︰取灰苋叶擦之，即止。（谈野翁方）。\n蜂虿螫伤︰野苋 擦之。\n诸蛇螫人︰紫苋，捣汁饮一升，以滓涂之。（《集验方》）。\n射工中人，状如伤寒，寒热，发疮偏在一处，有异于常者。取赤苋合茎、叶捣汁饮一升，日再服之。（《集验方》）。\n苋实\n\n</span>\n新一。利大小便︰苋实为末半两，分二服，新汲水下。（《圣惠》）。\n根\n\n</span>\n新一。\n牙痛︰苋根晒干，烧存性为末，揩之。再以红灯笼草根煎汤漱之。（孙氏《集效方》）。"},
  "苍耳蠹虫":{o:[],src:["本草纲目"],d:"新三。\n一切疔肿及无名肿毒恶疮︰刘松石《经验方》︰用苍耳草梗中虫一条，白梅肉三、四分，同捣如泥，贴之立愈。《圣济总录》等分为末，蜜调涂之。又用苍耳节内虫四少顷以手撮出根，即愈。"},
  "苎根":{o:["苎根"],src:["本草备要"],d:"泻热，散瘀\n甘寒而滑。补阴破瘀，解热润燥。治天行热疾，大渴大狂，胎动下血，诸淋血淋，捣贴赤游丹毒，痈疽发背，金疮折伤（止血易痂），鸡鱼骨哽（捣如龙眼。鸡骨，鸡汤下，鱼骨，鱼汤下）。汁能化血为水。苎皮与产妇作枕，止血运；安腹上，止产后腹痛（散瘀之功）沤苎汁，疗消渴。"},
  "苏":{o:[],src:["本草纲目"],d:"旧二，新一十三。感寒上气︰苏叶三两，橘皮四两，酒四升，煮一升半，分再服。（《肘后方》）\n伤寒气喘不止︰用赤苏一把，水三升，煮一升，稍稍饮之。（《肘后》）\n劳复食复欲死者。苏叶煮汁二升，饮之。亦可入生姜、豆豉同煮饮。（《肘后》）\n卒 不止 香苏浓煮，顿服三升，良。（《千金》）\n霍乱胀满，未得吐下。用生苏捣汁饮之，佳。干苏煮汁亦可。（《肘后方》）\n诸失血病︰紫苏不限多少，入大锅内，水煎令干，去滓熬膏，以炒熟赤豆为末，和丸梧子大。每酒下三、五十丸，常服之。（《斗门方》）\n金疮出血不止。以嫩紫苏叶、桑叶同捣贴之。（《永类钤方》）\n颠扑伤损︰紫苏捣敷之。疮口自合。（《谈野翁试验方》）\n伤损血出不止。以陈紫苏叶蘸所出血， 烂敷之。血不作脓，且愈后无瘢，甚妙也。（《永疯狗咬伤︰紫苏叶嚼敷之。（《千金方》）\n蛇虺伤人︰紫苏叶捣饮之。（《千金方》）\n食蟹中毒︰紫苏煮汁饮二升。（《金匮要略》）\n飞丝入目，令人舌上生泡。用紫苏叶嚼烂，白汤咽之。（危氏《得效方》）\n乳痈肿痛︰紫苏煎汤频服，并捣封之。（《海上仙方》）\n咳逆短气︰紫苏茎叶二钱，人参一钱。水一钟，煎服。（《普济》）\n子\n\n旧三，新六。\n顺气利肠︰紫苏子、麻子仁等分，研烂，水滤取汁，同米煮粥食之。（《济生方》）\n治风顺气，利肠宽中。用紫苏子一升，微炒杵，以生绢袋盛，于三斗清酒中浸三宿，少少饮之。（《圣惠》）\n一切冷气︰紫苏子、高良姜、橘皮等分，蜜丸梧子大。每服十丸，空心酒下。（《药性论》）\n风湿脚气︰方同上。风寒湿痹，四肢挛急，脚肿不可践地。用紫苏子二两，杵碎。以水三升，研取汁，煮粳米二合，作粥，和葱、椒、姜、豉食之。（《圣惠方》）\n消渴变水，服此令水从小便出。用紫苏子（炒）三两，萝卜子（炒）三两，为末。每服二钱，桑根白皮煎汤服，日三次。（《圣济总录》）\n梦中失精︰苏子一升。熬杵研末，酒服方寸匕，日再服。（《外台秘要》）\n食蟹中毒︰紫苏子煮汁饮之。（《金匮要略》）\n上气咳逆︰紫苏子入水研滤汁，同粳米煮粥食。（《简便方》）"},
  "苏木":{o:["苏木"],src:["本草备要"],d:"泻，行血，解表\n甘咸辛凉。入三阴血分。行血去瘀，发散表里风气（宜与防风同用）。治产后血晕（《肘后方》∶煮汁服。《海藏方》∶加乳香，酒服），胀满欲死，血痛血瘕，经闭气壅，痈肿朴伤，排脓止痛。多破血，少和血。出苏方国，交、爱亦有。忌铁。"},
  "苦楝子":{o:["苦楝子"],src:["本草备要"],d:"（一名金铃子）\n泻湿热，治疝，杀虫苦寒有小毒。能入肝舒筋，能导小肠、膀胱之热，因引心包相火下行，通利小便。为疝气要药。亦治伤寒热狂、热厥，腹痛心痛。杀三虫，疗疡疥（《夷坚志》∶消渴症有虫、耗其津液者，取根、皮浓煎，加少麝服，下其虫而渴自止）。脾胃虚寒忌之。川产良。酒蒸（寒因热用）。去皮取肉、去核用。用核则槌碎，浆水煮一伏时去肉用。茴香为使。"},
  "苦瓠":{o:[],src:["本草纲目"],d:"旧八，新十七。\n急黄病︰苦瓠一枚，开孔，以水煮之，搅取汁，滴入鼻中。去黄水。（陈藏器）。\n黄胆肿满︰苦壶卢瓤如大枣许，以童子小便二合，浸之一时，取两酸枣大，纳两鼻中，深吸气，待黄水出良。又方︰用瓠瓤熬黄为末，每服半钱，日一服，十日愈。然有吐者当详之。（《伤寒类要》）。\n大水胀满，头面洪大︰用莹净好苦瓠白瓤，捻如豆粒，以面裹煮一沸，空心服七枚。至午当出水一斗。二日水自出不止，大瘦乃瘥。二年内忌咸物。（《外台》）\n《圣惠》︰用苦壶卢瓤一两，微炒为末，每日粥饮服一钱。\n通身水肿︰苦瓠膜（炒）二两，苦葶苈五分，捣合丸小豆大。每服五丸，日三，水下止。\n又用苦瓠膜五分，大枣七枚。捣丸。一服三丸，如人行十里许，又服三丸，水出更服一丸，即止。（并《千金方》）。\n石水腹肿︰四肢皆瘦削。用苦瓠膜（炒）一两，杏仁半两（炒去皮尖），为末，糊丸小豆大。每饮下十丸，日三，水下止。（《圣济总录》）。\n水蛊洪肿︰苦瓠瓤一枚，水二升，煮至一升，煎至可丸，如小豆大，每米饮下十丸。待小便利，作小豆羹食。勿饮水。\n小便不通，胀急者︰用苦瓠子三十枚（炒），蝼蛄三个（焙），为末，每冷水服一钱。（并《圣济总录》）。\n小儿闪癖︰取苦瓠未破者，煮令热，解开熨之。（陈藏器《本草》）。\n风痰头痛︰苦瓠膜取汁，以苇管灌入鼻中，其气上冲脑门，须臾恶涎流下，其病立愈除根，勿以昏运为疑。干者浸汁亦效，其子为末吹入亦效。年久头风皆愈。（《普济方》）。\n鼻窒气塞︰苦壶卢子为末，醇酒浸之，夏一日，冬七日。日日少少点之。（《圣惠方》）。\n眼目昏暗︰七月七日，取苦瓠白瓤绞汁一合，以酢二升，古钱七文，同以微火煎减半。\n每日取沫纳 中，神效。（《千金》）。\n肉血翳︰秋间取小柄壶卢，或小药壶卢，阴干，于紧小处锯断，内挖一小孔如眼孔大。\n遇有此病，将眼皮上下用手挣开，将壶卢孔合定。初虽甚痛苦，然瘀肉、血翳皆渐下，不伤睛也。（刘松石《经验方》）。\n齿 口臭︰苦瓠子为末，蜜丸半枣大。每旦漱口了，含一丸，仍涂齿 上，涎出，吐去妙。（《圣惠方》）。\n风虫牙痛︰壶卢子半升。水五升，煎三升，含漱之。茎叶亦可。不过三度。（《圣惠方》）\n恶疮癣癞，十年不瘥者︰苦瓠一枚，煮汁搽之，日三度。（《肘后方》）\n九 有孔︰苦瓠四枚，大如盏者，各穿一孔如指大，汤煮十数沸，取一竹筒长一尺，一头插瓠孔中，一头注疮孔上，冷则易之，用遍乃止。（《千金方》）。\n痔疮肿痛︰苦壶卢、苦 菜煎汤，先熏后洗，乃贴熊胆、密陀僧、胆矾、片脑末，良。（《摘玄方》）。\n下部悬痈︰择人神不在日，空心用井华水调百药煎末一碗服之。微利后，却用秋壶卢（一名苦不老，生在架上而苦者）切片置疮上，灸二七壮。肃端式病此连年，一灸遂愈。（《永类钤方》）。\n卒中蛊毒，或吐血，或下血，皆如烂肝者︰苦瓠一枚。水二升，煮一升服，立吐即愈。\n又方︰用苦酒一升，煮令消，服之取吐，神验。（《肘后方》）。\n死胎不下︰苦壶卢烧存性，研末。每服一钱，空心热酒下。（《海上名方》）。\n耳出脓︰干瓠子一分，黄连半钱，为末。以绵先缴净，吹入半字，日二次。（《圣惠方》）。\n鼻中息肉︰苦壶卢子、苦丁香等分，入麝香少许，为末。纸捻点之。（《圣惠方》）。\n花\n\n新一。\n小儿白秃︰瓠藤同裹盐，荷叶煎浓汁洗，三、五次愈。（《总录》）"},
  "苦菜":{o:[],src:["本草纲目"],d:"新六。\n血淋尿血︰苦 菜一把，酒、水各半，煎服。（《资生经》）。\n血脉不调︰苦 菜晒干，为末。每服二钱，温酒下。（《卫生易简方》）。\n喉痹肿痛︰野苦 捣汁半盏，灯心以汤浸，捻汁半盏，和匀服。（《普济方》）。\n对口恶疮︰野苦 擂汁一钟，入姜汁一匙，和酒服，以渣敷，一、二次即愈。（唐瑶《经验方》）。\n中沙虱毒，沙虱在水中，人澡浴则著人身，钻入皮里。初得皮上正赤，如小豆、黍、粟，摩之痛如刺，三日后寒热发疮毒，若入骨杀人，岭南多此︰即以茅叶刮去，以苦菜汁涂之，佳。（《肘后方》）。\n壶蜂叮螫︰苦 汁涂之，良。（《摘玄方》）\n根"},
  "苧麻":{o:[],src:["本草纲目"],d:"旧四，新八。\n痰哮咳嗽︰苎根（煅存性），为末，生豆腐蘸三五钱，食即效。未全，可以肥猪肉二、三片蘸食，甚妙。（《医学正传》）\n小便不通︰《圣惠方》︰用麻根、蛤粉各半两，为末。每服二钱，空心新汲水下。《摘玄方》︰用苎根洗研，摊绢上，贴少腹连阴际，须臾即通。妙。亦治诸淋。（《圣惠方》）\n五种淋疾︰苎麻根两茎，打碎。以水一碗半，煎半碗，顿服即通，大妙。（《斗门方》）\n妊娠胎动，忽下黄汁如胶，或如小豆汁，腹痛不可忍者︰苎根（去黑皮，切）二升，银一斤，水九升，煎四升。每服以水一升，入酒半升，煎一升，分作二服。一方︰不用银。（《梅师方》）\n肛门肿痛︰生苎根捣烂，坐之良。（《濒湖集简方》）\n脱肛不收︰苎根捣烂，煎汤熏洗之。（《圣惠方》）\n痈疽发背，初起未成者。苎根（熟）捣敷上，日夜数易，肿消则瘥。（《图经本草》）\n五色丹毒︰苎根煮浓汁，日三浴之。（《外台秘要》）\n鸡鱼骨哽︰《谈野翁试验方》︰用苎麻根捣汁，以匙挑灌之，立效。《医方大成》︰用野苎麻根捣碎，丸如龙眼大，鱼骨鱼汤\n叶\n\n新三。\n五日采麻叶，阴干为末。每服二钱，冷水调下。勿吃热物，令人闷倒。只吃冷物。小儿半钱。（《杨子建护命方》）\n冷痢白冻︰方同上。蛇虺咬伤︰青麻嫩头捣汁，和酒等分，服三盏。以渣敷之，毒从窍中出，以渣弃水中即不发。看伤处有窍是雄蛇，无窍是雌蛇，以针挑破伤处成窍，敷药。（《摘玄方》）"},
  "茄":{o:[],src:["本草纲目"],d:"旧六，新十。\n妇人血黄︰黄茄子竹刀切，阴干为末。每服二钱，温酒调下。（《摘玄方》）。\n肠风下血︰经霜茄连蒂，烧存性，为末。每日空心温酒服二钱匕。（《灵苑方》）。\n久患下血︰大茄种三枚，每用一枚，湿纸包煨熟，安瓶内，以无灰酒一升半沃之，蜡纸封闭三日，去茄暖饮。（《普济方》）。\n腹内鳖症︰陈酱茄儿烧存性，入麝香、轻粉少许，脂调贴之。（《寿域方》）。\n卵 偏坠︰用双蒂茄子悬于房门上，出入用眼视之。茄蔫所患亦蔫，茄干亦干矣。又法︰用双茄悬门上，每日抱儿视之，二、三次钉针于上，十余日消矣。（刘松石《保寿堂方》）。\n大风热痰︰用黄老茄子大者不计多少，以新瓶盛，埋土中，经一年尽化为水，取出入苦参末，同丸梧子大。食已及卧时酒下三十丸，甚效。此方出江南人传。（苏颂《图经本草》）。\n腰脚拘挛，腰脚风血积冷，筋急拘挛疼痛者︰取茄子五十斤切洗，以水五斗煮取浓汁，滤去滓，更入小铛中，煎至一斗以来，即入生粟粉同煎，令稀稠得所，取出搜和，更入麝香、朱砂末，同丸如梧子大。每旦用秫米酒送下三十丸，近暮再服，一月乃瘥。男子、女人通用皆验。（《图经本草》）。\n磕扑青肿︰老黄茄极大者，切片如一指浓，新瓦焙研为末。欲卧时温酒调服二钱匕，一夜消尽，无痕迹也。（《胜金》）。\n坠损跌扑，散血止痛︰重阳日收老茄子百枚（去蒂四破切之），硝石十二两（捣碎）。以不津器先铺茄子一重，乃下硝石一重，如此间铺令尽，以纸数层密封，安置净处，上下以新砖承覆，勿犯地气。至正月后取出，去纸两重，日中曝之。逐日如此，至二、三月，度茄已烂，开瓶倾出，滤去滓，别入新器中，以薄绵盖头，又曝，至成膏乃可用。每以酒调半匙，空腹饮之，日再，恶血散则痛止而愈矣。若膏久干硬，即以饭饮化动用之。（《图经本草》）。\n发背恶疮︰用上方以酒服半匙，更以膏涂疮口四围，觉冷如冰雪，疮干便瘥。其有根本在肤腠者，亦可内消。（同上）。\n热毒疮肿︰生茄子一枚，割去二分，去瓤二分，似罐子形，合于疮上即消也。如已出脓，再用取瘥。（《圣济总录》）。\n牙齿肿痛︰隔年糟茄，烧灰频频干擦，立效。（《海上名方》）。\n虫牙疼痛︰黄茄种烧灰擦之，效。（《摘玄方》）。\n喉痹肿痛︰糟茄或酱茄，细嚼咽汁。（《德生堂方》）。\n妇人乳裂︰秋月冷茄子裂开者，阴干烧存性研末，水调涂。（《补遗》方）\n蒂\n\n新一。\n风蛀牙痛︰茄蒂烧灰掺之。或加细辛末等分，日用之。（《仁存方》）\n花\n\n新一。\n牙痛︰秋茄花干之，旋烧研涂痛处，立止。（《海上名方》）。\n根及枯茎叶\n\n新九。\n血淋疼痛︰茄叶熏干为末，每服二钱，温酒或盐汤下。隔年者尤佳。（《经验良方》）。\n肠风下血︰方同上，米饮下。\n久痢不止︰茄根烧灰、石榴皮等分。为末。以沙糖水服之。（《简便单方》）\n女阴挺出︰茄根烧存性，为末。油调在纸上，卷筒安入内，一日一上。（《乾坤生意》）\n口中生蕈︰用醋漱口，以茄母烧灰、飞盐等分，米醋调稀，时时擦之。（《摘玄方》）\n牙齿 痛︰茄根捣汁，频涂之。陈茄树烧灰敷之。先以露蜂房煎汤漱过。（《海上名方》）\n牙痛取牙︰茄科以马尿浸三日，晒炒为末。每用点牙即落，真妙。（鲍氏方）\n夏月趾肿，不能行走者︰九月收茄根悬檐下，逐日煎汤洗之。（《简便》）。"},
  "茄根":{o:["茄根"],src:["本草备要"],d:"泻，散血，消肿\n散血消肿。煮汁渍冻疮（史国公药酒，用白茄根为君。茄根以马尿浸三日，晒炒为末，点牙即落）。茄子甘寒，散血宽肠，动风发病。"},
  "茅香":{o:[],src:["本草纲目"],d:"︰新一。\n冷劳久病︰茅香花、艾叶四两，烧存性，研末，粟米饭丸梧子大。初以蛇床子汤下二十丸至三十丸，微吐不妨，后用枣汤下，立效。（《圣济总录》）\n苗、叶"},
  "茴香":{o:["茴香"],src:["本草备要", "本草纲目"],d:"（古作怀香）\n燥，补肾命门，治寒疝大茴辛热。入肾膀胱。暖丹田，补命门，开胃下食，调中止呕。疗小肠冷气， 疝阴肿（疝有七种，气、血、寒、水、筋、狐、 也。肝经病，不属肾经，以厥阴肝脉络阴器也。多因寒湿所致，亦有挟虚者，当加参、术于温散药中），干湿脚气。多食损目发疮。小茴辛平，理气开胃，亦治寒疝。食料宜之。大如麦粒，轻而有细棱者名大茴，出宁夏，他处小者名小茴。自番舶来，实八瓣者，名八角茴香。炒黄用，得酒良。得盐则入肾，发肾邪，故治阴疝（受病于肝，见证于肾。大、小茴各一两，为末，猪脬一个，连尿入药，酒煮烂，为丸服）。"},
  "茵芋":{o:["茵芋"],src:["本草备要", "本草纲目"],d:"宣，去风湿\n辛苦微温，有小毒。治风湿拘挛痹痛（时珍曰∶古方治风痫，有茵芋丸；治风痹，有茵芋酒；治产后风，有茵芋膏。风湿诸证多用之。茵芋、石南、莽草，皆治风妙品，近世罕知。莽草辛温有毒，治头风痈肿乳痈疝瘕。苏颂曰∶古方风湿诸酒多用之，今人取叶煎汤热含，治牙虫喉痹甚效。甄权曰∶不入汤）。茎赤，叶如石榴而短浓，茎炙用。"},
  "茵陈蒿":{o:[],src:["本草纲目"],d:"旧二，新六。\n茵陈羹︰除大热黄胆，伤寒头痛，风热瘴疟，利小便。以茵陈细切，煮羹食之。生食亦宜。（《食医心镜》）\n遍身风痒生疮疥︰用茵陈煮浓汁洗之，立瘥。（《千金方》）\n疡风病︰茵陈蒿两握，水一斗五升，煮取七升。先以皂荚汤洗，次以此汤洗之，冷更作。隔日一洗，不然恐痛也。（崔行功《纂要》）\n风疾挛急︰茵陈蒿一斤，秫米一石，曲三斤，和匀，如常法酿酒服之。（《圣济总录》）\n痫黄如金，好眠吐涎︰茵陈蒿、白藓皮等分，水二钟，煎服，日二服。（《三十六黄方》）\n遍身黄胆︰茵陈蒿一把，同生姜一块，捣烂，于胸前四肢，日日擦之。男子酒疸︰用茵陈蒿四根，栀子七个，大田螺一个（连壳捣烂）。以百沸白酒一大盏，冲汁饮之，秘方也。眼热赤肿︰山茵陈、车前子等分。煎汤调（茶调散），服数服。（《直指方》）"},
  "茶":{o:["茶"],src:["本草备要"],d:"泻热，清神，消食\n苦甘微寒。下气消食，去痰热，除烦渴，清头目（得春初生发之气，故多整肃上膈之功。《汤液》云∶茶苦寒下行，如何是清头目？《蒙鉴》曰∶热下降，则上自清矣），醒昏睡（清神），解酒食、油腻、烧炙之毒，利大、小便。多饮消脂（最能去油）、寒胃（故浓茶能引吐。《千金》疗卒头痛如破，非中冷、中风。由痰、厥气上冲所致，名厥头痛，单煮茶恣饮取吐，直吐出胆汁乃已，渴而即瘥）。酒后饮茶，引入膀胱、肾经，患瘕疝水肿，空心亦忌之（与姜等分浓煎，名姜茶饮，治赤白痢。茶助阴，姜助阳，使寒热平调。并能消暑、解酒、食毒）。陈、细者良，粗者损人。"},
  "茹":{o:["茹"],src:["本草备要", "本草纲目"],d:"泻，破血\n辛寒，有小毒。蚀恶肉，排脓血，杀疥虫，除热痹，破症瘕（《内经》同乌贼骨。治妇人血枯）。根如莱菔，皮黄肉白，叶长微阔，折之有汁，结实如豆，一颗三粒。甘草为使。"},
  "茺蔚":{o:[],src:["本草纲目"],d:"旧十三，新十。\n济阴返魂丹︰昝殷《产宝》曰︰此方，乃吉安文江高师禹，备礼求于名医所得者，其效神妙，活人甚多，能治妇人胎前、产后诸疾危证。用野天麻，又名益母，又名火 ，又名负担，即茺蔚子也。叶似艾叶，茎类火麻，方梗凹面，四、五、六月节节开花，红紫色如蓼花，南北随处皆有，白花者不是。于端午、小暑，或六月六日，花正开时，连根收采阴干，用叶及花子。忌铁器，以石器碾为细末，炼蜜丸如弹子大随证嚼服用汤使。其根烧存性为末，酒服，功与黑神散不相上下。其药不限丸数，以病愈为度。或丸如梧子大，每服五、七十丸。又可捣汁滤净，熬膏服之。胎前脐腹痛，或作声者，米饮下；胎前产后，脐腹刺痛，胎动不安，下血不止，当归汤下；产后，以童子小便化下一丸，能安魂定魄，血气自然调顺，诸病不生。又能破血痛，养脉息，调经络，并温酒下。胎衣不下，及横生不顺，死胎不下，经日胀满，心闷心痛，并用炒盐汤下。产后血晕，眼黑血热，口渴烦闷，如见鬼神，狂言不省人事，以童子小便和酒化下；产后结成血块，脐腹奔痛，时发寒热，有冷汗，或面垢颜赤，五心烦热，并用童子小便、酒下，或薄荷自然汁下。产后恶露不尽，结滞刺痛，上冲心胸满闷，童子小便、酒下。产后泻血水，以枣汤下。产后痢疾，米汤下。产后血崩漏下，糯米汤下。产后赤白带下，煎胶艾汤下；月水不调，温酒下。产后中风，牙关紧急，半身不遂，失音不语，童便、酒下；产后气喘咳嗽，胸膈不利，恶心吐酸水，面目浮肿，两胁疼痛，举动失力，温酒下。产后月内咳嗽，自汗发热，久则变为骨蒸，童便、酒下；产后鼻衄，舌黑口干，童便酒下。产后两太阳穴痛，呵欠心忪，气短羸瘦，不思饮食，血风身热，手足顽麻，百节疼痛，并米饮化下。产后大小便不通，烦躁口苦者，薄荷汤下。妇人久无子息，温酒下。益母膏︰《近效方》︰治产妇诸疾，及折伤内损有瘀血，每天阴则痛，神方也。三月采益母草一名负担，一名夏枯草，连根叶茎花洗择令净，于箔上摊曝水干，以竹刀切长五寸，勿用铁刀，置于大锅中，以水浸过二、三寸，煎煮，候草烂水减三之二，漉去草，取汁约五、六斗，入盆中澄半日，以绵滤去浊滓，以清汁入釜中，慢火煎取一斗，如稀饧状，瓷瓶封收。每取梨大，暖酒和服，日再服。或和羹粥亦可。如远行，即更炼至可丸收之。服至七日，则疼渐平复也。产妇恶露不尽及血晕，一二服便瘥。其药无忌。又能治风，益心力。（《外台秘要》）\n女人难产︰益母草捣汁七大合，煎减半，顿服立止。无新者，以干者一大握，水七合，煎服。（韦宙《独行方》）\n胎死腹中︰益母草捣熟，以暖水少许，和绞取汁，顿服之。（韦宙《独行方》）。产后血晕，心气欲绝︰益母草研汁，服一盏，绝妙。（《子母秘录》）\n产后血闭不下者︰益母草汁一小盏，入酒一合，温服。（《圣惠方》）\n带下赤白︰益母草花开时采，捣为末。每服二钱，食前温汤下。（《集验方》）\n小便尿血︰益母草捣汁，服一升立瘥。此苏澄方也。（《外台秘要》）\n赤白杂痢困重者︰益母草（日干）、陈盐梅（烧存性），等分为末。每服三钱，白痢干姜汤、赤痢甘草汤下。名二灵散。（《卫生家宝方》）\n小儿疳痢垂死者︰益母草嫩叶，同米煮粥食之，取足，以瘥为度，甚佳。饮汁亦可。（《广济方》）\n痔疾下血︰益母草叶，捣汁饮之。（《食医心镜》）\n一切痈疮︰妇人妒乳乳痈，小儿头疮，及浸淫黄烂热疮，疥疽阴蚀︰并用天麻草（切）五升急慢疔疮︰《圣惠方》︰用益母草捣封之，仍绞五合服，即消。《医方大成》︰用益母草四月连花采之，烧存性。先以小尖刀十字划开疔根，令血出。次绕根开破，捻出血，拭干。以稻草心蘸药捻入疮口，令到底。良久当有紫血出，捻令血净，再捻药入，见红血乃止。一日夜捻药三、五度。重者二日根烂出，轻者一日出。有疮根胀起，即是根出，以针挑之。出后仍敷药生肌易愈。忌风寒、房室、酒肉、一切毒物。疖毒己破︰益母草捣敷，甚妙。（《斗门方》）\n勒乳成痈︰益母为末。水调涂乳上，一宿自瘥。生捣亦得。（《圣惠方》）\n喉闭肿痛︰益母草捣烂，新汲水一碗，绞浓汁顿饮，随吐愈。冬月用根。（《卫生易简方》）\n粉刺黑斑︰《闺阁事宜》云︰五月五日收带根天麻紫花者，晒干烧灰。以商陆根捣自然汁，加酸醋和搜灰作饼，炭火 过收之。半年方用，入面药，甚能润肌。苏颂曰︰唐天后炼益母草泽面法︰五月五日采根苗具者，勿令著土，曝干捣罗，以面水和成团，如鸡子大，再曝干。仍作一炉，四旁开窍，上下置火，安药中央。大火烧一炊久，即去大火，留小火养之，勿令火绝。经一复时出之，瓷器中研治，筛再研，三日收用，如澡豆法，日用。一方︰每十两加滑石一两，胭脂一钱。马咬成疮︰苦低草，切细，和醋炒涂之。（《孙真人方》）\n新生小儿︰益母草五两，煎水浴之，不生疮疥。（《简要济众》）"},
  "荆三棱":{o:[],src:["本草纲目"],d:"旧三，新五。\n症瘕鼓胀︰三棱煎︰用三棱根（切）一石。水五石，煮三石，去滓更煎，取三斗汁入锅中，重汤煎如稠糖，密器收之。每旦酒服一匕，日二服。（《千金翼方》）\n癖气块︰草三棱、荆三棱、石三棱、青橘皮、陈橘皮、木香各半两，肉豆蔻、槟榔各一两， 砂二钱，为末，糊丸梧子大，每姜汤服三十丸。（《奇效方》）\n癖不瘥，胁下硬如石。京三棱一两（炮），川大黄一两，为末，醋熬成膏。每日空心生姜橘皮汤下一匙，以利下为度。（《圣惠方》）\n小儿气癖︰三棱煮汁作羹粥，与奶母食，日亦以枣许与儿食。小儿新生百日及十岁以下，无问痫热 癖等皆理之。秘妙不可具言，大效。（《子母秘录》）\n痞气胸满︰口干，肌瘦食减，或时壮热。石三棱、京三棱、鸡爪三棱（并炮），蓬莪术三枚，槟榔一枚，青橘皮五十片（醋浸去白），陈仓米一合（醋浸淘过），巴豆五十个（去皮，同青皮、仓米炒干，去豆）。为末，糊丸绿豆大。每米饮下三丸，日一服。（《圣济总录》）\n反胃恶心，药食不下。京三棱（炮）一两半，丁香三分，为末。每服一钱，沸汤点服。（《圣济总录》）\n乳汁不下︰京三棱三个，水二碗，煎汁一碗，洗奶取汁出为度，极妙。（《外台秘要》）\n浑身燎泡，如棠梨状，每个出水，有石一片，如指甲大，其泡复生，抽尽肌肤肉，即不可治。用荆三棱、蓬莪术各五两，为末，分三服，酒调连进愈。（危氏《得效方》）"},
  "荆沥":{o:["荆沥"],src:["本草备要"],d:"宣通经络，滑痰泻热\n甘平。除风热，化痰涎，开经络，行血气。治中风失音，惊痫痰迷，眩晕烦闷，消渴热痢，为去风化痰妙药。气虚、食少者忌之（《延年秘录》云∶热多用竹沥，寒多用荆沥。丹溪曰∶虚痰用竹沥，实痰用荆沥，并宜姜汁助送，则不凝滞）。牡荆俗名黄荆，截取尺余，架砖上，中间火炙，两头承取汁用。"},
  "草":{o:["草"],src:["本草备要"],d:"宣，去风湿\n苦辛。生寒，熟温。治肝肾风气，四肢麻痹，筋骨冷痛，腰膝无力，风湿疮疡。若痹痛由脾肾两虚、阴血不足，不由风湿而得者，忌服（风药能燥血）。江东人呼猪为 ，其草似猪咏臭，故名（唐·成讷有进 表。宋·张咏进 表云∶其草金棱银线，素茎紫 ，对节而生，颇同苍耳。臣吃百服，眼目清明，即至千服，须发乌黑，筋力轻健，效验多端）。以五月五日、六月六日、七月七日、九月九日采者尤佳。去粗茎，留枝叶花实，酒拌蒸晒九次，蜜丸，甚益元气（ 辛苦气寒，故必蒸晒九次加以酒蜜，则苦寒之阴浊尽去，而清香之美味见矣。数不至九，阴浊未尽，则不能透骨搜风而却病也）。捣汁熬膏，以甘草、生地煎膏，炼蜜三味收之，酒调服尤妙。"},
  "草乌头":{o:["草乌头"],src:["本草备要"],d:"大燥，开顽痰\n辛苦大热。搜风胜湿，开顽痰。治顽疮，以毒攻毒，颇胜川乌。然至毒，无所酿制，不可轻投。野生，状类川乌，亦名乌喙。姜汁炒，或豆腐煮用。熬膏，名射罔，敷箭射兽，见面立死。"},
  "草蜘蛛":{o:[],src:["本草纲目"],d:"新二。\n瘤疣︰用稻上花蜘蛛十余，安桃枝上，待丝垂下，取东边者捻为线系之，七日一换，自消落也。（《总微论》）\n截疟︰五月五日取花蜘蛛，晒干，绛囊盛之，临期，男左女右系臂上，勿令知之。（《普济方》）"},
  "草豆蔻":{o:["草豆蔻"],src:["本草备要"],d:"（一名草果）\n燥湿祛痰，除痰截疟辛热香散。暖胃健脾，破气开郁，燥湿祛寒，除痰化食。治瘴疠寒疟（佐常山能截疟。或与知母同用，取其一阴一阳，治寒热瘴疟。盖草果治太阴独胜之寒，知母治阳明独胜之火），寒客胃痛（散滞气，利膈痰，因滞因寒者多效），霍乱泻痢，噎膈反胃，痞满吐酸，痰饮积聚。解口臭气、酒毒、鱼肉毒（故食料用之）。过剂助脾热，耗气损目。闽产名草蔻，如龙眼而微长，皮黄白、薄而棱峭，仁如砂仁，而辛香气和。滇广所产名草果，如诃子，皮黑、浓而棱密，子粗而辛臭，虽是一物，微有不同。面裹，煨熟，取仁用。忌铁。"},
  "荏":{o:[],src:["本草纲目"],d:"（旧二）男女阴肿（男子︰荏叶生捣，和醋封之。女人︰绵裹内，三四易。孟诜食疗。）\n蛇虺中人（以荏叶烂杵，猪脂和，薄敷上。梅师方。）\n子"},
  "荛花":{o:["荛花"],src:["本草备要"],d:"大通，行水\n辛散结、苦泄热，行水捷药，主治略同芫花。"},
  "荜茇":{o:["荜茇"],src:["本草备要", "本草纲目"],d:"（茇、一作拨）\n燥，除胃冷，散浮热辛热除胃冷，温中下气，消食祛痰。治水泻气痢（牛乳点服），虚冷肠鸣（亦入大肠经），冷痰恶心，呕吐酸水， 癖阴疝。辛散阳明之浮热，治头痛（偏头痛者，口含温水，随左右以末吹一字入鼻效）、牙痛（寒痛宜干姜、荜茇、细辛，热痛宜石膏、牙硝，风痛宜皂角、僵蚕、蜂房、二乌，虫痛宜锻石、雄黄），鼻渊。多服泄真气，动脾肺之火，损目。出南番，岭南亦有。类椹子而长，青色，去挺用头。醋浸。刮净皮粟，免伤人肺。"},
  "荞麦":{o:["荞麦"],src:["本草备要"],d:"泻，利肠，下气\n甘寒。降气，宽肠胃沉积（孟诜曰∶能炼五脏垢秽。昂按∶亦解酒积），泄痢带浊，敷痘疮溃烂，汤火灼伤。脾胃虚寒人勿服。"},
  "荠":{o:["荠"],src:["本草备要", "本草纲目"],d:"补，和中，解毒\n寒利肺，甘解毒（能解百药及蛇虫毒，在诸药中，毒皆自解）。和中止嗽，治消渴强中（渴症下消，茎长兴盛，不交精出，名强中。消渴之后，发为痈疽），痈肿疔毒。似人参而体虚无心，似桔梗而味甘不苦（奸贾多用以乱人参。时珍曰∶荠 即甜桔梗）。"},
  "荠苨":{o:[],src:["本草纲目"],d:"旧四，新三。\n强中消渴︰猪肾荠 汤︰治强中之病，茎长兴盛，不交精液自出，消渴之后，即发痈疽。皆由恣意色欲，或饵金石所致，宜此以制肾中热也。用猪肾一具，荠、石膏各三两，人参、茯苓、磁石、知母、葛根、黄芩、栝蒌根、甘草各二两，黑大豆一升，水一斗半，先煮猪肾、大豆，取汁一斗，去滓下药，再煮三升，分三服。后人名为石子荠汤。又荠 丸︰用荠 、大豆、茯神、磁石、栝蒌根、熟地黄、地骨皮、玄参、石斛、鹿茸各一两，人参、沉香各半两。为末，以猪肚治净煮烂，杵和丸梧子大。每服七十丸，空心盐汤下。（并《千金方》）\n疔疮肿毒︰生荠 根捣汁，服一合，以滓敷之，不过三度。（《千金翼》）\n面上 ︰荠 、肉桂各一两。为末。每用方寸匕，酢浆服之，日一服。又灭瘢痣。（《圣济总录》）\n解诸蛊毒︰荠 根捣末，饮服方寸匕，立瘥。（陈延之《短剧方》）\n解钩吻毒︰钩吻叶与芹叶相似，误食之杀人。惟以荠 八两，水六升，煮取三升，每服五合，日五服。（仲景《金匮玉函》）\n解五石毒︰荠 生捣汁，多服之，立瘥。（苏颂《图经》）"},
  "荭草":{o:[],src:["本草纲目"],d:"旧一，新一。\n瘰疬︰水荭子不以多少，一半微炒，一半生用，同研末。食后好酒调服二钱，日三服。已破癖痞腹胀及坚硬如杯碗者︰用水荭花子一升，另研独颗蒜三十个（去皮），新狗脑一个，皮硝再贴二、三次。倘有脓溃，勿怪。仍看虚实，日逐间服钱氏白饼子、紫霜丸、塌气丸、消积丸，利之磨之。服至半月，甚者一月，无不瘥矣。以喘满者，为实；不喘者，为虚。（《蔺氏经验方》）\n花\n\n新三。\n胃脘血气作痛︰水荭花一大撮。水二钟，煎一钟服。百户毛菊庄屡验方也。（董炳避《水集验方》）\n心气 痛︰水荭花为末。热酒服二钱。又法︰男，用酒水各半煎服；女，用醋水各半煎服。一妇年三十病此，一服立效。（《摘玄方》）\n腹中痞积︰水荭花或子一碗。以水三碗，用桑柴文武火煎成膏，量痞大小摊贴，仍以酒调膏服。忌腥荤油腻之物。（刘松石《保寿堂方》）"},
  "荷叶":{o:["荷叶"],src:["本草备要"],d:"轻宣，升阳，散瘀\n苦平。其色青，其形仰，其中空，其象震（震仰盂），感少阳甲胆之气。烧饭合药，裨助脾，胃而升发阳气（洁古枳术丸，用荷叶烧饭为丸），痘疮倒 者，用此发之（僵蚕等分为末，胡荽汤下。闻人规曰∶胜于人牙、龙脑）。能散瘀血，留好血。治吐、衄、崩、淋，损伤产瘀（熬香末服），一切血证，洗肾囊风（东垣曰∶雷头风症，头面疙瘩肿痛，憎寒恶热，状如伤寒，病在三阳，不可过用寒药重剂，诛罚无过，处清震汤治之。荷叶一枚，升麻、苍术各五钱，煎服。郑奠一曰∶荷叶研末，酒服三钱，治遗精极验）。"},
  "荸荠":{o:["荸荠"],src:["本草备要"],d:"（一名凫茈，一名乌芋，一名地栗）\n补中，泻热，消食甘微寒滑。益气安中，开胃消食（饭后宜食之），除胸中实热。治五种噎膈（五膈，忧膈、恚膈、气膈、热膈、寒膈。噎亦五种，气噎、食噎、劳噎、忧噎、思噎），消渴黄胆，血证蛊毒（末服辟蛊），能毁铜（汪机曰∶食铜钱，食之则钱化。可见为消坚削积之物，故能开五膈，消宿食，治误吞铜也）。"},
  "莎根、香附子":{o:[],src:["本草纲目"],d:"旧一，新四十八。服食法︰颂曰︰唐玄宗《天宝单方图》云︰水香棱根名莎结，亦名草附子，说已见前。其根二大升，捣熬令香，以生绢袋盛，贮于三大斗无灰清酒中浸之。春三月后，浸一日即堪服；冬十月后，即七日，近暖处乃佳。每空腹温饮一盏，日夜三、四次，常令酒气相续，以知为度。若不饮酒，即取根十两，加桂心五两，芜荑三两。和捣为散，以蜜和为丸，捣一千杵，丸交感丹︰凡人中年精耗神衰。盖由心血少，火不下降；肾气惫，水不上升。致心肾隔绝，营卫不和。上则多惊；中则塞痞，饮食不下；下则虚冷遗精。愚医徒知峻补下田，非惟不能生水滋阴，而反见衰悴。但服此方半年，屏去一切暖药，绝嗜欲，然后习秘固溯流之术，其效不可殚述。俞通奉年五十一，遇铁瓮城申先生授此，服之老犹如少，年至八十五乃终也。因普示群生，同登寿域。香附子一斤（新水浸一宿，石上擦去毛，炒黄），茯神（去皮木）四两，为末，炼蜜丸弹子大。每服一丸，侵早细嚼，以降气汤下。降气汤用香附子（如上法）半两，茯神二两，炙甘草一两半，为末，点沸汤服前药。（萨谦斋《瑞竹堂经验方》）\n一品丸︰治气热上攻，头目昏眩，及治偏正头痛。大香附子去皮，水煮一时，捣晒焙研为末，炼蜜丸弹子大。每服一丸，水一盏，煎八分服。女人，醋汤煎之。（《奇效良方》）\n升降诸气︰治一切气病，痞胀喘哕，噫酸烦闷，虚痛走注。常服开胃消痰，散壅思食。早行山行，尤宜服之，去邪辟瘴。香附子（炒）四百两，沉香十八两，缩砂仁四十八两，炙甘草一百二十两，为末。每服一钱，入盐少许，白汤点服。（《和剂局方》）\n一切气疾︰心腹胀满，胸膈噎塞，噫气吞酸，痰逆呕恶，及宿酒不解。香附子一斤，缩砂仁八两，甘草（炙）四两，为末，每白汤入盐点服。为粗末煎服亦可。名快气汤。（《和剂局方》）\n调中快气，心腹刺痛。小乌沉汤︰香附子（擦去毛，焙）二十两，乌药十两，甘草（炒）一两心脾气痛︰白飞霞《方外奇方》云︰凡人胸膛软处一点痛者，多因气及寒起，或致终身，或子母相传。俗名心气痛，非也，乃胃脘有滞尔。惟此独步散，治之甚妙。香附（米醋浸，略炒为末），高良姜（酒洗七次，略炒为末）。俱各封收。因寒者，姜二钱，附一钱；因气者，附二钱，姜一钱；因气与寒者，各等分，和匀。以热米汤入姜汁一匙，盐一捻，调下立止。不过七八次除根。王璆《百一方》云︰内翰吴开夫人，心痛欲死，服此即愈。《类编》云︰梁混心脾痛数年不愈，供事秽迹佛，梦传此方，一服而愈，因名神授一匕散。心腹诸病︰艾附丸︰治男女心气痛、腹痛、少腹痛、血气痛，不可忍者。香附子二两，蕲》）\n停痰宿饮，风气上攻，胸膈不利。香附（皂荚水浸）、半夏各一两，白矾末半两，姜汁面糊丸梧子大。每服三四十丸，姜汤随时下。（《仁存方》）\n元脏腹冷及开胃。香附子炒为末，每用二钱，姜、盐同煎服。（《普济方》）\n酒肿虚肿︰香附子去皮，米醋煮干，焙研为末，米醋糊丸服。久之败水从小便出，神效。（《经验良方》）\n气虚浮肿︰香附子一斤，童子小便浸三日，焙为末，糊丸。每米饮下四、五十丸，日二。（《丹溪心法》）\n老小 癖，往来疼痛。香附、南星等分，为末，姜汁糊丸梧子大，每姜汤下三、三十丸。（《圣惠》）\n疝胀痛及小肠气。香附末二钱，以海藻一钱煎酒，空心调下，并、食海藻。（《濒湖集腰痛揩牙︰香附子五两，生姜二两，取自然汁浸一宿，炒黄为末，入青盐二钱，擦牙数次血气刺痛︰香附子（炒）一两，荔枝核（烧存性）五钱，为末。每服二钱，米饮调下。（《妇女人诸病︰《瑞竹堂方》︰四制香附丸︰治妇人女子经候不调，兼诸病。大香附子（擦去毛）一斤，分作四分︰四两醇酒浸，四两醇醋浸，四两盐水浸，四两童子小便浸。春三、秋五、夏一、冬七日。淘洗净，晒干捣烂，微焙为末，醋煮面糊丸梧子大，每酒下七十丸。瘦人加泽兰、赤茯苓末二两，气虚加四君子料，血虚加四物料。《法生堂方》︰煮附济阴丸︰治妇人月经不调，久成症积，一切风气。用香附子一斤（分作四分，以童溲、盐水、酒、醋各浸三日），艾叶一斤（浆水浸过，醋糊和作饼，晒干），晚蚕砂半斤（炒），莪术四两（酒浸），当归四两（酒浸）。各焙为末，醋糊丸梧子大。每服七十丸，米饮下，日二。醋附丸︰治妇人室女一切经候不调，血气刺痛，腹胁膨胀，心怔乏力，面色痿黄，头晕恶心，崩漏带下，便血，症瘕积聚，及妇人数堕胎，由气不升降，服此尤妙。香附子米醋浸半日，砂锅煮干，捣焙，石臼为末，醋糊为丸，醋汤下。《澹寮方》艾附丸︰治同上。香附子一斤，熟艾四两（醋煮），当归（酒浸）二两，为末，如上丸服。妇人气盛血衰，变生诸症，头晕腹满，皆宜抑气散主之。香附子四两（炒），茯苓、甘草（炙）各一两，橘红二两，为末。每服二钱，沸汤下。（《济生方》）\n下血血崩，血如山崩，或五色漏带，并宜常服，滋血调气，乃妇人之仙药也。香附子去毛炒焦为末，极热酒服二钱立愈。昏迷甚者，三钱，米饮下。亦可加棕灰。（许学士《本事方》）\n赤白带下及血崩不止。香附子、赤芍药等分，为末，盐一捻，水二盏，煎一盏，食前温安胎顺气︰铁罩散︰香附子炒为末，浓煎紫苏汤服一二钱。一加砂仁。（《中藏经》）\n妊娠恶阻，胎气不安，气不升降，呕吐酸水，起坐不便，饮食不进。二香散︰用香附子一两，藿香叶、甘草各二钱，为末。每服二钱，沸汤入盐调下。（《圣惠方》）\n临产顺胎︰九月、十月服此，永无惊恐。福胎饮︰用香附子四两，缩砂仁（炒）三两，甘草（炙）一两，为末。每服二钱，米饮下。（《朱氏集验方》）\n产后狂言，血晕，烦渴不止。生香附子去毛为末，每服二钱，姜、枣水煎服。（同上）气郁吐血︰丹溪︰用童子小便调香附末二钱服。《澹寮方》︰治吐血不止。莎草根一两，白茯苓半两，为末。每服二钱，陈粟米饮下。肺破咯血︰香附末一钱。米饮下，日二服。（《百一选方》）\n小便尿血︰香附子、新地榆等分各煎汤。先服香附汤三、五呷，后服地榆汤至尽。未效再服。（《指迷方》）\n小便血淋，痛不可忍。香附子、陈皮、赤茯苓等分水煎服。（《十便良方》）\n诸般下血︰香附，童子小便浸一日，捣碎，米醋拌焙为末。每服二钱，米饮下。《直指方》︰用香附以醋、酒各半煮熟，焙研为末，黄秫米糊丸梧子大。每服四十丸，米饮下，日二服。戴原礼云︰只以香附子末二钱，入百草霜、麝香各少许，同服，效尤速也。老小脱肛︰香附子、荆芥穗等分，为末。每用三匙，水一大碗，煎十数沸淋洗。（《三因偏正头风︰香附子（炒）一斤，乌头（炒）一两，甘草二两，为末，炼蜜丸弹子大。每服一丸，葱茶嚼下。（《本事方》）\n气郁头痛︰《澹寮方》︰用香附子（炒）四两，川芎 二两。为末。每服二钱，腊茶清调下头风睛痛︰方同妊娠恶阻。女人头痛︰香附子末，茶服三钱，日三五服。（《经验良方》）\n肝虚睛痛，冷泪羞明。补肝散︰用香附子一两，夏枯草半两，为末。每服一钱，茶清下。耳卒聋闭︰香附子瓦炒研末，萝卜子煎汤，早夜各服二钱。忌铁器。（《卫生易简方》）\n耳出汁︰香附末，以绵杖送入。蔡邦度知府常用，有效。（《经验良方》）\n诸般牙痛︰香附、艾叶煎汤漱之，仍以香附末擦之，去涎。（《普济方》）\n牢牙去风，益气乌髭，治牙疼牙宣，乃铁瓮先生妙方也。香附子（炒存性）三两，青盐、生姜各半两，为末，日擦。（《济生方》）\n消渴累年不愈。莎草根一两，白茯苓半两，为末。每陈粟米饮服三钱，日二。痈疽疮疡︰曾孚先云︰凡痈疽疮疡，皆因气滞血凝而致，宜服诸香药，引气通血。常器之云︰凡气血闻香即行，闻臭即逆。疮疡皆由气涩而血聚，最忌臭秽不洁，触之毒必引蔓。陈正节公云︰大凡疽疾，多因怒气而得，但服香附子药，进食宽气，大有效也。独胜散︰用香附子去毛，以生姜汁腌一宿，焙干碾为细末，无时以白汤服二钱。如疮初作，以此代茶。疮溃后，亦宜服之。或只以《局方》小乌沉汤，少用甘草，愈后服至半年，尤妙。（陈自明\n《外科精要》）\n蜈蚣咬伤︰嚼香附涂之，立效。（《袖珍方》）"},
  "莕菜":{o:[],src:["本草纲目"],d:"新四。\n一切痈疽及疮疖。用荇丝菜或根，马蹄草茎或子（即 也），各取半碗，同苎麻根五寸去皮，以石器捣烂，敷毒四围。春夏秋日换四、五次，冬换二、三次，换时以荠水洗之，甚效。（《保生余录》）\n谷道生疮︰荇叶捣烂，绵裹纳之下部，日三次。（《范汪方》）\n毒蛇螫伤，牙入肉中，痛不可堪者。勿令人知，私以荇叶覆其上穿，以物包之，一时折牙\n点眼去翳︰荇丝菜根一钱半（捣烂。即叶如马蹄开黄花者），川楝子十五个，胆矾七分，石次，七日见效也。（孙氏《集效方》）"},
  "莨菪":{o:[],src:["本草纲目"],d:"旧二，新二十一。\n卒发颠狂︰莨菪三升为末，以酒一升渍数日，绞去滓，煎令可丸，如小豆三丸，日三服。当觉口面急，头中如有虫行，额及手足有赤色处，如此，并是瘥候也。未知再服，取尽神良。（陈延之《短剧方》）\n风痹厥痛︰天仙子三钱（炒），大草乌头、甘草半两，五灵脂一两。为末，糊丸梧子大，以螺青为衣。每服十丸，男子菖蒲酒下，女子芫花汤下。（《圣济录》）\n久嗽不止有脓血︰莨菪子五钱（淘去浮者，煮令芽出，炒研），真酥一鸡子大，大枣七枚，同煎令酥尽，取枣日食三枚。\n又方︰莨菪子三撮，吞之，日五六度。光禄李丞服之，神验。（孟诜《必效方》）\n年久呷嗽，至三十年者︰莨菪子、木香、熏黄等分，为末。以羊脂涂青纸上，撒末于上，卷作筒，烧烟熏吸之。（《崔行功纂要方》）\n水肿蛊胀︰方见兽部羚羊下。\n积冷 癖，不思饮食，羸困者︰莨菪子三分（水淘去浮者），大枣四十九个。水三升，煮干，只取枣去皮核。每空心食一个，米饮下，觉热即止。（《圣济录》）\n水泻日久︰青州干枣十个（去核），入莨菪子填满扎定，烧存性。每粟（《圣惠方》）\n冷疳痢下︰莨菪子为末，腊猪脂和丸，绵裹枣许，导下部。因痢出，更纳新者。不过三度瘥。（孟诜《必效方》）\n末。每服一钱，米饮下。（《普济方》）\n久痢不止，变种种痢，兼脱肛︰莨菪丸︰用莨菪子一升（淘去浮者，煮令芽出，晒干，炒黄黑色），青州枣一升（去皮核），酽醋二升，同煮，捣膏丸梧子大。每服二十丸，食前米饮下。（《圣惠方》）\n肠风下血︰莨菪煎︰用莨菪实一升（曝干捣筛），生姜半斤（取汁）。银锅中更以无灰酒二升投之，上火煎如稠饧，即旋投酒，度用酒可及五升即止。慢火煎令可丸，大如梧子。每旦酒饮通下三丸，增至五、七丸止。若丸时粘手，则以菟丝粉衬隔之。火候忌紧，药焦则失力也。初服微热，勿怪。疾甚者，服过三日，当下利。疾去，利亦止。绝有效。（《箧中方》）\n脱肛不收︰莨菪子炒研敷之。（《圣惠方》）\n风牙虫牙︰《瑞竹堂方》︰用天仙子一撮，入小口瓶内烧烟，竹筒引烟，入虫孔内，熏之即死，永不发。《普济方》︰用莨菪子入瓶内，以热汤淋下，口含瓶口，令气熏之。冷更作，尽三合乃止。有涎津可去，甚效。《备急方》︰用莨菪子数粒纳孔中，以蜡封之，亦效。牙齿宣落风痛︰莨菪子末，绵裹咬之，有汁勿咽。（《必效方》）\n风毒咽肿，咽水不下，及瘰疬咽肿︰水服莨菪子末两钱匕，神良。（《外台秘要》）\n乳痈坚硬︰新莨菪子半匙。清水一盏，服之。不得嚼破。（《外台秘要》）\n石痈坚硬不作脓者。莨菪子为末，醋和，敷疮头，根即拔出。（《千金方》）\n恶疮似癞，十年不愈者︰莨菪子烧研敷之。（《千金方》）\n打扑折伤︰羊脂调莨菪子末，敷之。（《千金方》）\n恶犬咬伤︰莨菪子七枚，吞之，日三服。（《千金方》）\n根\n\n新六。\n疟疾不止︰莨菪根烧炭，水服一合。量人强弱用。（《千金方》）\n恶癣有虫︰莨菪根捣烂，蜜和敷之。（《千金翼》）\n趾间肉刺︰莨菪根捣汁涂之。《雷公炮炙论》序云︰脚生肉刺， 系菪根。谓系于 带上也\n狂犬咬人︰莨菪根和盐捣敷，日三上。（《外台秘要》）\n恶刺伤人︰莨菪根，水煮汁浸之，冷即易。神方也。（《千金方》）\n箭头不出︰万圣神应丹︰端午前一日，不语，寻见莨菪科，根本枝叶花实全好者。道云︰先生﹗你却在这里。道罢，用柴灰自东南起围了，以木 子掘取根下周回土。次日日未出时，依前不语，用 头取出，洗净。勿令鸡犬妇人见，于净室中，以石臼捣如泥，丸弹子大，黄丹为衣，以纸袋封，悬高处阴干。遇有箭头不出者，先以象牙末贴疮口，后用绯帛袋盛此药，放脐中，绵兜肚系了，当便出也。（张子和《儒门事亲》方）"},
  "莱菔":{o:["莱菔"],src:["本草备要", "本草纲目"],d:"（俗作萝卜）\n宣，行气，化痰，消食辛甘属土。生食升气，熟食降气。宽中化痰，散瘀消食（丹溪曰∶气升则食自降）。治吐血衄血，咳嗽吞酸，利二便，解酒毒，制面毒、豆腐积（昔有人病，梦红裳女子引入宫殿，小姑歌云∶五灵楼阁晓玲珑，天府由来是此中，惆怅闷怀言不尽，一丸莱菔火吾宫。一道士云∶此犯大麦毒也。女子心神，小姑脾神。《医经》∶莱菔制面毒，遂以药并莱菔治之，果愈。腐浆见莱菔则难收）。生捣治噤口痢，止消渴，涂跌打汤火伤。多食渗血，故白人髭发（服何首乌、地黄者忌之，生姜能制其毒。夏月食其菜数斤，秋不患痢，冬月以菜叶摊屋瓦上，任霜雪打压，至春收之，煎汤饮，治痢得效。有人避难入石洞中，贼烧烟熏之，口含莱菔一块，烟不能毒。嚼汁濡水饮之亦可。王荆公患偏头痛，捣莱菔汁，仰卧，左痛注右鼻，右痛注左鼻，或两鼻齐注，数十年之患。二注而愈）。莱菔子辛入肺，甘走脾，长于利气。生能升，熟能降。升则吐风痰，散风寒，宽胸膈，发疮疹；降则定痰喘咳嗽，调下痢后重，止内痛（皆利气之功。丹溪曰∶莱菔子治痰，有冲墙倒壁之功。《食医心境》研汤煎服，治气嗽痰喘吐脓血）。炒用。"},
  "莲蕊须":{o:["莲蕊须"],src:["本草备要"],d:"涩精\n甘温而涩。精心通肾，益血固精，乌须黑发，止梦泄遗精，吐崩诸血。略与莲子同功。"},
  "莳萝":{o:[],src:["本草纲目"],d:"新二。\n闪挫腰痛：莳萝作末，酒服二钱匕。（《永类钤方》）。\n牙齿疼痛：舶上莳萝、芸苔子、白芥子等分。研末。口中含水，随左右 鼻，神效。（《圣惠方》）"},
  "莴苣":{o:[],src:["本草纲目"],d:"旧一，新五。\n乳汁不通︰莴苣菜煎酒服。（《海上方》）。\n小便不通︰莴苣菜，捣敷脐上即通。（《卫生易简方》）。\n小便尿血︰同上方，甚效。（杨氏方）。\n沙虱水毒︰莴苣菜捣汁涂之，良。（《肘后方》）。\n蚰蜒入耳︰莴苣叶（干者）一分，雄黄一分，为末，糊丸枣核大。蘸生油塞耳中，引出。（《圣惠方》）。\n百虫入耳︰莴苣捣汁滴入，自出也。（《圣济总录》）。\n子\n入药炒用。\n\n旧一，新六。\n乳汁不行︰莴苣子三十枚，研细酒服。又方︰莴苣子一合，生甘草三钱，糯米、粳米各半合，煮粥频食之。\n小便不通︰莴苣子捣饼，贴脐中，即通。（《海上仙方》）。\n肾黄如金︰莴苣子一合。细研。水一盏，煎五分服。（《外台秘要》）。\n阴囊 肿︰莴苣子一合捣末，水一盏，煎五沸，温服。\n闪损腰痛，趁痛丸︰用白莴苣子（炒）三两，白粟米（炒）一撮，乳香、没药、乌梅肉各半两，为末，炼蜜丸弹子大。每嚼一丸，热酒下。（《玉机微义》）。\n髭发不生，疖疮疤上不生髭发︰先以竹刀刮损，以莴苣子拗猢狲姜末，频擦之。（《摘玄方》）。"},
  "莼":{o:[],src:["本草纲目"],d:"新三。\n一切痈疽︰马蹄草即 菜，春夏用茎，冬月用子，就于根侧寻取，捣烂敷之。未成即消，已成即毒散。用叶亦可。（《保生余录》）。\n头上恶疮︰以黄泥包豆豉煨熟，取出为末，以 菜汁调敷之。（《保幼大全》）\n数种疔疮︰马蹄草（又名缺盆草）、大青叶、臭紫草各等分，擂烂，以酒一碗浸之，去滓温"},
  "莽草":{o:[],src:["本草纲目"],d:"旧四，新十。\n贼风肿痹，风入五藏恍惚，宜莽草膏主之︰莽草一斤，乌头、附子、踯躅各二两，切，以水和醋一升，渍一宿。猪脂一斤，煎三上三下，绞去滓。向火，以手摩病上三百度，应手即瘥。若耳鼻疾，可以绵裹塞之。疥癣杂疮，并宜摩之。（《肘后》）\n小儿风痫，掣 戴眼，极者日数十发，又治大人贼风︰莽草、雷丸各一鸡子黄大，化猪脂一斤，煎七沸，去滓，摩痛处，勿近目及阴，日凡三、四次。（《外台秘要》）\n头风久痛︰莽草煎汤沐之，勿令入目。（《圣惠方》）\n风虫牙痛︰《肘后方》︰用莽草煎汤，热漱冷吐。一加山椒师方》）\n；一加芫花； 一加川椒、细辛各等分。煎汤热漱冷吐。《圣惠》︰用莽草半两，皂角三挺（去皮子），汉椒七粒。为末，枣肉丸芥子大。每以一丸塞孔中，吐涎取效。瘰疬结核︰ 草一两为末鸡子白调涂帛上，贴之，日二易，取效止。（《圣惠方》）\n痈疮未溃︰方同上，得痛为良。（《肘后方》）\n乳肿不消︰莽草、小豆等分。为末。苦酒和，敷之。（《卫生易简》）\n狗咬昏闷︰浸椒水，调莽草末敷之。（《便民图纂》）"},
  "菊":{o:[],src:["本草纲目"],d:"旧五，新六。\n服食甘菊︰《玉函方》云︰王子乔变白增年方︰用甘菊，三月上寅日采苗，名曰玉英；六月上寅日采叶，名曰容成；九月上寅日采花，名曰金精；十二月上寅日采根茎，名曰长生。四味并阴干，百日取等分，以成日合捣千杵为末，每酒服一钱匕。或以蜜丸梧子大。酒服七丸，一日三服。百日，身轻润泽；一年，发白变黑；服之二年，齿落再生；五年，八十岁老翁，变为儿童也。孟诜云︰正月采叶，五月五日采茎，九月九日采花。服食白菊︰《太清灵宝方》引︰九月九日白菊花二斤，茯苓一斤。并捣罗为末。每服二钱，温酒调下，日三服。或以炼过松脂和丸鸡子大，每服一丸。主头眩，久服令人好颜色不老。藏器曰︰《抱朴子》言刘生丹法，用白菊汁、莲花汁、地血汁、樗汁，和丹蒸服也。白菊花酒︰《天宝单方》︰治丈夫、妇人久患头风眩闷，头发干落，胸中痰壅，每发即头旋眼昏，不觉欲倒者，是其候也。先灸两风池各二七壮，并服此酒及散，永瘥。其法︰春末夏初，收白菊软苗，阴干捣末，空腹取一方寸匕和无灰酒服之，日再服，渐加三方寸匕。若不饮酒者，但和羹粥汁服，亦得。秋八月合花收曝干，切取三大斤，以生绢袋盛，贮三大斗酒中，经七日服之，日三次，常令酒气相续为佳。（苏颂《图经》）\n风热头痛︰菊花、石膏、川芎各三钱，为末。每服一钱半，茶调下。（《简便方》）\n痘入目生翳障︰用白菊花、谷精草、绿豆皮等分，为末。每用一钱，以干柿饼一枚，粟米泔一盏，同煮候泔尽，食柿，日食三枚。浅者五七日，远者半月，见效。（《仁斋直指方》）\n病后生翳︰白菊花、蝉蜕等分，为散。每用二三钱，入蜜少许，水煎服。大人小儿皆宜，屡验。（《救急方》）\n疔肿垂死︰菊花一握，捣汁一升，入口即活，此神验方也。冬月采根。（《肘后方》）\n女人阴肿︰甘菊苗捣烂煎汤，先熏后洗。（危氏《得效方》）\n酒醉不醒︰九月九日真菊花为末，饮服方寸匕。（《外台秘要》）\n眼目昏花︰双美丸︰用甘菊花一斤，红椒（去目）六两，为末，用新地黄汁和丸梧子大。每\n花上水"},
  "菖蒲":{o:[],src:["本草纲目"],d:"旧十，新一十七。\n服食法︰甲子日，取菖蒲一寸九节者，阴干百日，为末。每酒服方寸匕，日三服。久服耳健忘益智︰七月七日，取菖蒲为末，酒服方寸匕，饮酒不醉，好事者服而验之。久服聪明三十六风有不治者，服之悉效菖蒲（薄切日干）三斤，盛以绢袋，玄水一斛，即清酒也，悬浸之，密封一百日，视之如菜绿色，以一斗熟黍米纳中，封十四日，取出日饮。（夏禹《神仙经》）\n癫痫风疾︰九节菖蒲不闻鸡犬声者，去毛，木臼捣末。以黑 猪心一个批开，砂罐煮汤。调服三钱，日一服。（《医学正传》）\n尸厥魇死，尸厥之病，卒死脉犹动，听其耳中如微语声，股间暖者，是也。魇死之病，卧忽不寤。勿以火照，但痛啮其踵及足拇趾甲际，唾其面即苏。仍以菖蒲末吹鼻中，桂末纳舌下，并以菖蒲根汁灌之。（《肘后方》）。\n卒中客忤︰菖蒲生根捣汁灌之，立瘥。（《肘后方》）。\n除一切恶︰端午日，切菖蒲渍酒饮之。或加雄黄少许。（《洞天保生录》）。\n喉痹肿痛︰菖蒲根嚼汁，烧铁秤锤淬酒一杯，饮之。（《圣济总录》）。\n霍乱胀痛︰生菖蒲（锉）四两，水和捣汁，分温四服。（《圣惠方》）。诸积鼓胀，食积、气积、血积之类︰石菖蒲八两（锉），斑蝥四两（去翅足），同炒黄，去斑蝥不用。以布袋盛，拽去蝥末，为末，醋糊丸梧子大。每服三、五十丸，温白汤下。治肿胀尤妙。或入香附末二钱。（《奇效方》）。\n肺损吐血︰九节菖蒲末、白面等分。每服三钱，新汲水下，一日一服。（《圣济录》）。\n解一切毒︰石菖蒲、白矾等分，为末，新汲水下。（《事林广记》）。\n赤白带下︰石菖蒲、破故纸等分，炒为末。每服二钱，更以菖蒲浸酒调服，日一。（《妇人良方》）。\n胎动半产卒动不安，或腰痛胎转抢心，下血不止，或日月未足而欲产。并以菖蒲根捣汁一、二升，服之。（《千金》）。\n产后崩中，下血不止。菖蒲一两半，酒二盏，煎取一盏，去滓分三服，食前温服。（《千金方》）。\n耳卒聋闭︰菖蒲根一寸，巴豆一粒（去心），同捣作七丸。绵裹一丸，塞耳，日一换。\n一方不用巴豆，用蓖麻仁。（《肘后方》）。\n病后耳聋︰生菖蒲汁，滴之。（《圣惠方》）\n蚤虱入耳︰菖蒲末炒热，袋盛，枕之即愈。（《圣济录》）。\n诸般赤眼，攀睛云翳。菖蒲擂自然汁，文武火熬作膏，日点之效。（《圣济录》）。\n眼睑挑针︰独生菖蒲根，同盐研敷。（《寿域神方》）。\n飞丝入目︰石菖蒲捶碎。左目塞右鼻，右目塞左鼻。百发百中。（危氏《得效方》）。\n头疮不瘥︰菖蒲末，油调敷之，日三、夜二次。（《法天生意》）。\n痈疽发背︰生菖蒲，捣贴之。疮干者，为末，水调涂之。（孙用和《秘宝方》）。\n露岐便毒︰生菖蒲根捣敷之。（《证治要诀》）。\n热毒湿疮︰宗奭曰︰有人遍身生疮，痛而不痒，手足尤甚，粘著衣被，晓夕不得睡。有人教以菖蒲三斗，日干为末，布席上卧之，仍以衣被覆之。既不粘衣，又复得睡，不五、七日，其疮如失。后以治人，应手神验。（《本草衍义》）。\n风癣有虫︰菖蒲末五斤。以酒三升渍，釜中蒸之，使味出。先绝酒一日，每服一升或半升\n阴汗湿痒︰石菖蒲、蛇床子等分。为末。日搽二、三次。（《济急仙方》）。"},
  "菘":{o:[],src:["本草纲目"],d:"旧一，新二。\n小儿赤游，行于上下，至心即死：菘菜捣敷之，即止。（张杰《子母秘录》）。\n漆毒生疮：白菘菜捣烂涂之。\n飞丝入目：白菜揉烂帕包，滴汁三、二点入目，即出。（《普济方》）。\n子\n\n旧一。\n酒醉不醒：菘菜子二合细研，井华水一盏调，为二服。（《圣惠方》）"},
  "菝葜":{o:[],src:["本草纲目"],d:"新五。\n小便滑数︰金刚骨为末。每服三钱，温酒下，睡时。（《儒门事亲》方）\n取去根本︰用菝 二两，为末。每米饮服二钱。后以地椒煎汤浴腰腹，须臾即通也。（《圣济录》）\n消渴不止︰菝谷即菝 ， 咀半两，水三盏，乌梅一个，煎一盏，温服。（《普济方》）\n下痢赤白︰金刚根、蜡茶等分。为末，白梅肉捣丸芡子大。每服五、七丸，小儿三丸，白痢甘草汤下；赤痢乌梅汤下。（《卫\n风毒脚弱，痹满上气，田舍贫家用此最良︰菝 （洗锉）一斛。以水三斛渍曲去滓，取一斛渍饮，如常酿酒。任意日饮之。（《肘后方》）"},
  "菠薐":{o:[],src:["本草纲目"],d:"（新一）\n消渴引饮，日至一石者︰菠薐根、鸡内金等分，为末。米饮服一钱，日三。（《经验方》）"},
  "菥蓂":{o:[],src:["本草纲目"],d:"旧一，新一。\n眼目热痛，泪出不止︰菥 子，捣筛为末。卧时铜簪点少许入目，当有热泪及恶物出，甚佳。\n眼中 肉︰方同上，夜夜点之。（崔元亮《海上方》）"},
  "菰":{o:[],src:["本草纲目"],d:"旧二。\n小儿风疮︰久不愈者。用菰蒋节烧研，敷之。（《子母秘录》）。\n毒蛇伤啮︰菰蒋草根烧灰，敷之。（《广济方》）。\n叶"},
  "菱":{o:["菱"],src:["本草备要"],d:"（俗名菱角，一名芰）\n泻，解暑，止渴甘寒。安中消暑，止渴解酒。有两角、三角、四角、老嫩之殊（《武陵记》以三角、四角者为芰，两角者为菱。菱花随月而转，犹葵花之向日）。"},
  "菾菜":{o:[],src:["本草纲目"],d:"新一。\n痔 下血︰ 子、芸苔子、荆芥子、芫荽子、莴苣子、蔓荆子、萝卜子、葱子等分，以大鲫鱼一个去鳞、肠，装药在内，缝合，入银、石器内，上下用火炼熟，放冷为末。每服二钱，米饮下，日二服。"},
  "萆":{o:["萆"],src:["本草备要"],d:"通，祛风湿，补下焦\n甘苦性平。入足阳明、厥阴（胃、肝）。祛风去湿，以固下焦（阳明主肉，属湿。厥阴主筋，属风），补肝虚（去风），坚筋骨（风湿去，则筋骨坚），益精明目。治风寒湿痹，腰痛久冷，关节老血，膀胱宿水，阴痿失溺，茎痛遗浊，痔 恶疮（诸病皆阳明湿热流入下焦，萆 能除浊厘清，古方有萆 厘清饮。史国信云∶若欲兴阳，先滋筋力。若欲便清，先分肝火。《万金护命方》云∶凡人小便频数、便时痛不可忍者，此疾必因大肠秘热不通，水液只就小肠，大肠愈加干竭，甚则身热心躁，思水，即重证也。此疾本因贪酒色，或过食辛热、荤腻之物，积有热毒，腐物、瘀血，乘虚流入小肠，故便时作痛也。此便数而痛，与淋证涩而痛不同，宜用萆 一两，盐水炒，为末，每服二三钱，使水道转入大肠，仍以葱汤频洗谷道，令气得通，则便数及痛自减也。肾有二窍，淋证出于溺窍，浊证出于精窍）。有黄、白二种，黄长、 （音硬），白虚、软，软者良。薏苡为使。畏大黄、柴胡、前胡。忌茗、醋（时珍曰∶萆 、菝 、土茯苓，形不同而主治不甚相远，岂一类数种乎？萆根细长、浅白，菝 根作块而黄）。"},
  "萎蕤":{o:[],src:["本草纲目"],d:"旧一，新六。\n服食法︰二月、九月采葳蕤根，切碎一石，以水二石煮之，从旦至夕，以手 烂，布囊榨取汁，熬稠。其渣晒为末，同熬至可丸，丸如鸡头子大。每服一丸，白汤下，日三服。导气脉，强筋骨，治中风湿毒，去面皱颜色，久服延年。（ 仙《神隐书》）\n赤眼涩痛︰葳蕤、赤芍药、当归、黄连等分。煎汤，薰洗。（《卫生家宝方》）\n眼见黑花，赤痛昏暗︰甘露汤︰用葳蕤（焙）四两。每服二钱，水一盏，入薄荷二叶，生姜一片，蜜少许，同煎七分，卧时温服，日一服。（《圣济总录》）\n小便猝淋︰葳蕤一两，芭蕉根四两。水二大碗，煎一碗半，入滑石二钱，分三服。（《太平圣惠方》）\n发热口干，小便涩︰用葳蕤五两，煎汁饮之。（《外台秘要》）\n乳石发热︰葳蕤三两，炙甘草二两，生犀角一两。水四升，煮一升半，分三服。（《圣惠方》）\n痫后虚肿︰小儿痫病瘥后，血气上虚，热在皮肤，身面俱肿。葳蕤、葵子、龙胆、茯苓、前胡等分，为末。每服一钱，水煎服。（《圣济总录》）"},
  "萤火":{o:[],src:["本草纲目"],d:"新二。\n黑发︰七月七日夜，取萤火虫二七枚，捻发自黑也。（《便民图纂》方）\n明目︰劳伤肝气目暗方︰用萤极妙。一方用白犬胆。（《圣惠方"},
  "营实、墙蘼":{o:[],src:["本草纲目"],d:"新一。\n眼热昏暗︰营实、枸杞子、地肤子各二两，为末。每服三钱，温酒下。（《圣惠方》）\n根\n\n旧七，新六。\n消渴尿多︰蔷薇根一把，水煎，日服之。（《千金方》）\n小便失禁︰蔷薇根煮汁饮，或为末酒服。野生白花者更良。（《圣惠方》）\n少小尿床︰蔷薇根五钱，煎酒夜饮。（《外台秘要》）\n小儿疳痢频数︰用生蔷薇根洗切，煎浓汁细饮，以愈为度。（《千金方》）\n尸咽痛痒，语声不出︰蔷薇根皮、射干一两，甘草（炙）半两。每服二钱，水煎服之。（《普\n口舌糜烂︰蔷薇根，避风打去土，煮浓汁，温含冷吐。冬用根皮，夏用枝叶。口疮日久，延及胸中生疮，三年以上不瘥者，皆效。（《千金方》）\n小儿月蚀︰蔷薇根四两，地榆二钱，为末。先以盐汤洗过，敷之。（《全幼心鉴》）\n痈肿疖毒，溃烂疼痛︰用蔷薇皮更炙熨之。（《千金方》）\n筋骨毒痛，因患杨梅疮服轻粉毒药成者︰野蔷薇根白皮（洗）三斤，水酒十斤，煮一炷香。每日任饮，以愈为度。《邓笔峰杂兴方》︰用刺蔷薇根三钱，五加皮、木瓜、当归、茯苓各二钱。以酒二盏，煎一盏，日服一次。\n金疮肿痛︰蔷薇根烧灰。每白汤服方寸匕，一日三服。（《抱朴子》）\n箭刺入肉，脓囊不出︰以蔷薇根末掺之，服鼠扑，十日即穿皮出也。（《外台秘要》）\n骨哽不出︰蔷薇根末。水服方寸匕，日三。（同上）\n叶"},
  "萱草":{o:[],src:["本草纲目"],d:"新四。\n通身水肿︰鹿葱根叶，晒干为末。每服二钱，入席下尘半钱，食前米饮小便不通︰萱草根煎水频饮。（《杏林摘要》）\n大便后血︰萱草根和生姜，油炒，酒冲服。（《圣济总录》）\n食丹药毒︰萱草根，研汁服之。（《事林广记》）"},
  "落花生":{o:["落花生"],src:["本草备要"],d:"补脾润肺\n辛能润肺，香能舒脾。果中佳品，出闽广。藤生花，落地而结实，故名（按∶落花生《本草》未收，本无当医药之用，然能益脾润肺，实佳果也。因世人谤之者多，附见于此，明其有利无害也）。炒食。"},
  "葈耳":{o:[],src:["本草纲目"],d:"旧三，新四。\n酒服三十丸，日二服。生者捣汁服亦可。（《朱氏集验方》）\n葶苈（末）等分。每服二钱，水下，日二服。（《千金方》）\n两（炒）。为末，以水一升半，煎取七合，去滓呷之。（《食医心镜》）\n水一斗，煮取五升，热含之。冷即吐去，吐后（孙真人《千金翼》）\n钱。（《证治要诀》）\n嗜酒不已︰毡中苍耳子七枚，烧灰投酒中饮之，即不嗜。（陈藏器《\n\n旧十二，新十七。\n疮杖疮，牙疼喉痹︰五月五日采苍耳根叶数担，洗净晒萎细锉，以大锅五口，入水煮烂，以筛滤去粗滓，布绢再滤。复入净锅，武火煎滚，文火煎稠，搅成膏，以新罐贮封。每以敷贴，即愈。牙疼即敷牙上，喉痹敷舌上或噙化，二、三次即效。每日用酒服一匙，极有效。（《集简方》）\n五日午时附地刈取 耳叶，洗暴燥，捣下筛，每服方寸匕，酒或浆水下，日二、夜三。若觉吐逆，则以蜜丸服，准计方寸匕数也。风轻者，日二服。若身体作粟或麻豆出，此为风毒出也。可以针刺溃去黄汁，乃止。七月七、九月九，亦可采用。（《千金方》）\n一切风气︰苍耳嫩叶一石（切），和麦 五升作块，于蒿艾中 二十日成曲。取米一斗，炊作饭，看冷暖，入曲三升酿之，封二七日得令密，密则溢出。忌马肉、猪肉。（孟诜《食疗本草》）\n每服一钱，酒调下，日三服。若吐，则以蜜丸梧子大，每服二十丸。十日全好矣。（《杨氏经验方》）\n血风脑晕︰方见发明下。毒攻手足，肿痛欲断︰苍耳捣汁渍之，并以滓敷之，立效。春，用心；冬，用子。（《千金翼》）\n卒中水毒，初觉头目微痛，恶寒，骨节强急，日醒暮剧，手足逆冷，三日则虫蚀下部；六、七日脓溃，食至五脏，杀人也。捣常思草，绞汁服一、二升，并以绵染，导其下部。（《肘后方》）\n毒蛇溪毒，沙虱、射工等所伤，口噤眼黑，手足强直，毒攻腹内成块，逡巡不救︰苍耳嫩苗一握。取汁，和酒温灌之，以滓浓敷伤处。（《胜金方》）\n疫病不染︰五月五日午时多采苍耳嫩叶，阴干收之。临时为末，冷水服二钱，或水煎举家皆服，能辟邪恶。（《千金方》）\n风瘙瘾疹，身痒不止︰用苍耳茎、叶、子等分，为末。每服二钱，豆淋酒调下。（《圣惠方》）\n面上黑斑︰苍耳叶焙为末，食后米饮调服一钱，一月愈。（《摘玄方》）\n赤白汗斑︰苍耳嫩叶尖，和青盐擂烂，五、六月间擦之，五、七次效。（《摘玄方》）\n大风疠疾︰《袖珍方》︰用嫩苍耳、荷叶等分，为末。每服二钱，温酒下，日二服。《乾坤生意》︰用苍耳叶为末，以大枫子油和丸梧子大。每服三、四十丸，以茶汤下，日二服。又方︰五月五日或六月六日，五更带露采苍耳草，捣取汁，熬作锭子。取半斤鳢鱼一尾，剖开不去肚肠，入药一锭，线缝，以酒二碗，慢火煮熟令吃，不过三五个鱼即愈也。忌盐一百日。卒得恶疮︰苍耳、桃皮作屑，纳疮中。（《百一方》）\n反花恶疮，有肉如饭粒，破之血出，随生反出︰用苍耳叶捣汁，服三合，并涂之，日二上。（《圣济总录》）\n日三服，拔根甚验。《养生方》︰用苍耳根、苗烧灰，和醋淀涂之，干再上。不十次，即拔根出。齿风动痛︰苍耳一握，以浆水煮，入盐含漱。（《外台秘要》）\n缠喉风病︰苍耳根一把，老姜一块。研汁，入酒服。（《圣济总录》）\n赤目生疮作痛︰道人头末二两，乳香一钱，每用一钱，烧烟搐鼻。（《圣济总录》）\n鼻衄不止︰苍耳茎叶捣汁一小盏服。（《圣惠方》）\n五痔下血︰五月五日采苍耳茎、叶为末。水服方寸匕，甚效。（《千金翼》）\n赤白下痢︰苍耳草（不拘多少）洗净，用水煮烂去滓，入蜜用武火熬成膏。每服一、二匙，产后诸痢︰苍耳叶捣绞汁，温服半中盏，日三、四服。（《圣惠方》）\n误吞铜钱︰苍耳头一把，以水一升，浸水中十余度，饮水愈。（《肘后方》）\n花蜘蛛毒咬人，与毒蛇无异︰用野缣丝（即道人头）。捣汁一盏服，仍以渣敷之。（《摘玄方"},
  "葛":{o:[],src:["本草纲目"],d:"旧十七，新四。痛，内热脉洪者︰葛根四两。水二升，入豉一升，煮取半升服。捣生根汁尤佳。（《伤寒类要》）\n时气头痛壮热︰生葛根洗净，捣汁一大盏，豉一合，煎六分，去滓分服，汗出即瘥。未汗再服。若心热，加栀子仁十枚。（《圣惠方》）\n伤寒头痛二、三日发热者︰葛根五两，香豉一升，以童子小便八升，煎取二升，分三服。食葱豉粥取汗。（《梅师方》）\n妊娠热病︰葛根汁二升，分三服。（《伤寒类要》）\n预防热病，急黄贼风︰葛粉二升，生地黄一升，香豉半升。为散。每食后米饮服方寸匕，日三服。有病五服。（庞安常《伤寒论》）\n辟瘴不染︰生葛捣汁一小盏服，去热毒气也。（《圣惠方》）\n烦躁热渴︰葛粉四两，先以水浸粟米半升，一夜漉出，拌匀，煮粥食之。（《圣惠方》）\n小儿热渴久不止︰葛根半两，水煎服。（《圣惠方》）\n干呕不息︰葛根捣汁，服一升，瘥。（《肘后方》）\n小儿呕吐，壮热食痫︰葛粉二钱。水二合，调匀，倾入锡锣中，重汤烫熟，以糜饮和食。（昝殷《食医心镜》）\n心热吐血不止︰生葛捣汁半升，顿服，立瘥。（《广利方》）\n衄血不止︰生葛根捣汁，服一小盏。三服即止。（《圣惠方》）\n热毒下血，因食热物发者︰生葛根二斤，捣汁一升，入藕汁一升，和服。（《梅师方》）\n伤筋出血︰葛根，捣汁饮。干者，煎服。仍熬屑敷之。（《外台秘要》）\n腰疼痛︰生葛根嚼之咽汁，取效乃止。（《肘后方》）\n金创中风，痉强欲死︰生葛根四大两，以水三升，煮取一升，去滓，分温四服。口噤者灌之。若干者，捣末调三指撮。仍以此及竹沥多服，取效。（《贞元广\n服药过剂苦烦︰生葛汁饮之。干者煎汁服。（《肘后方》）\n酒醉不醒︰生葛根汁，饮二升，便愈。（《千金方》）\n诸菜中毒，发狂烦闷，吐下欲死︰葛根，煮汁服。（《肘后方》）\n解中鸩毒，气欲绝者︰葛粉三合，水三盏，调服。口噤者灌之。（《圣惠方》）\n虎伤人疮︰生葛根，煮浓汁洗之。仍捣末，水服方寸匕，日夜五、六服。（《梅师方》）\n葛谷\n\n新三。\n妇人吹乳︰葛蔓烧灰。酒服二钱。三服效。（《卫生易简方》）\n疖子初起︰葛蔓烧灰。水调敷之，即消。（《千金方》）\n小儿口噤，病在咽中，如麻豆许，令儿吐沫，不能乳食︰葛蔓（烧灰）一字，和乳汁点之，即瘥。（《圣惠方》）"},
  "葛上亭长":{o:[],src:["本草纲目"],d:"新二。\n经脉不通︰妇人经脉不通，症块胀满，腹有鬼胎。用葛上亭长五枚，以糙米和炒，去翅、足，研末。分三服肺风白癞︰葛上亭长四七枚（去翅、足，与糯米同炒，米熟为度，不用米），干蝮蛇一枚（头尾全者，炙黄，去鳞及腹中物），共捣罗，生绢袋贮。以酒五升，瓷瓶中慢火 煮。酒及一升以下，将绵囊蘸药汁，摩涂癞上，日二夜一。如不急痛，日夜可五七次涂之。（《圣济总录》）"},
  "葫":{o:[],src:["本草纲目"],d:"旧十五，新三十二。\n背疮灸法：凡觉背上肿硬疼痛，用湿纸贴寻疮头。用大蒜十颗，淡豉半合，乳香一钱，细研。随疮头大小，用竹片作圈围定，填药于内，二分浓，著艾灸之。痛灸至痒，痒灸至痛，以百壮为率。与蒜钱灸法同功。（《外科精要》）\n疔肿恶毒：用门臼灰一撮罗细，以独蒜或新蒜苔染灰擦疮口，候疮自然出少汁，再擦，少顷即消散也。虽发背痈肿，亦可擦之。\n五色丹毒无常色，及发足踝者：捣蒜浓敷，干即易之。（《肘后方》）。\n关格胀满，大小便不通：独头蒜烧熟去皮，绵裹纳下部，气立通也。（《外台秘要》）。\n干湿霍乱转筋：用大蒜捣涂足心，立愈。（《永类钤方》）。\n水气肿满：大蒜、田螺、车前子等分。熬膏。摊贴脐中，水从便漩而下，数日即愈。象山民人患水肿，一卜者传此，用之有效。（仇远《稗史》）。\n山岚瘴气：生、熟大蒜各七片，共食之。少顷腹鸣，或吐血，或大便泄，即愈。（《摄生众妙方》）\n疟疾寒热《肘后》：用独头蒜炭上烧之，酒服方寸匕。《简便》：用桃仁半片，放内关穴上，将独蒜捣烂罨之，缚住（男左女右），即止。邻妪用此治人屡效。\n《普济方》：端午日，取独头蒜煨熟，入矾红等分，捣丸芡子大，每白汤嚼下一丸。\n寒疟冷痢：端午日，以独头蒜十个，黄丹二钱，捣丸梧子大。每服九丸，长流水下，甚妙。（《普济方》）。\n泄泻暴痢：大蒜捣贴两足心。亦可贴脐中。（《千金方》）。\n下痢禁口及小儿泄痢方：并同上。\n肠毒下血：蒜连丸：用独蒜煨捣，和黄连末为丸，日日米汤服之。（《济生方》）。\n暴下血病：用葫五、七枚，去皮研膏，入豆豉捣，丸梧子大。每米饮下五、六十丸，无不愈者。（寇宗奭《本草衍义》）。鼻血不止，服药不应：用蒜一枚，去皮，研如泥，作钱大饼子，浓一豆许。左鼻血出，贴左足心；右鼻血出，贴右足心；两鼻俱出，俱贴之，立瘥。（《简要济众方》）。\n血逆心痛：生蒜捣汁，服二升即愈。（《千金》）。\n鬼疰腹痛，不可忍者：独头蒜一枚，香墨如枣大，捣和酱汁一合，顿服。（《永类钤方》）。\n心腹冷痛：法醋浸至二、三年蒜，食至数颗，其效如神。（李时珍《濒湖集简方》）。\n夜啼腹痛面青，冷证也：用大蒜一枚（煨研，日干），乳香五分，捣丸芥子大。每服七丸，乳汁下。（危氏《得效方》）。\n寒湿气痛：端午日收独蒜，同辰粉捣，涂之。（唐瑶《经验方》）。\n鬼毒风气：独头蒜一枚，和雄黄、杏仁研为丸，空腹饮下三丸。静坐少时，当下毛出即安。（孟诜《食疗本草》）。\n狗咽气塞，喘息不通，须臾欲绝：用独头蒜一枚，削去两头，塞鼻中。\n左患塞右，右患塞左。候口中脓血出，立效。（《圣济》）。\n喉痹肿痛：大蒜塞耳、鼻中，日二易之。（《肘后方》）。\n鱼骨哽咽：独头蒜塞鼻中，自出。（《十便良方》）。\n牙齿疼痛：独头蒜煨乘热切熨痛处，转易之。亦主虫痛。（《外台秘要》）。\n眉毛动摇，目不能交睫，唤之不应，但能饮食：用蒜三两杵汁，调酒饮，即愈。（夏子益《奇疾方》）。\n脑泻鼻渊：大蒜切片贴足心，取效止。（《摘玄方》）。\n头风苦痛《易简方》：用大蒜研汁 鼻中。《圣济录》：用大蒜七个去皮，先烧红地，以蒜逐个于地上磨成膏子。却以僵蚕一两，去头足，安蒜上，碗覆一夜，勿令透气。只取蚕研末， 入鼻内，口中含水，甚效。\n小儿惊风《总录》：方同上。\n小儿脐风：独头蒜切片，安脐上，以艾灸之。口中有蒜气，即止。（黎居士《简易方论》）。\n小儿气淋：宋宁宗为郡王时病淋，日夜凡三百起。国医罔措。或举孙琳治之。琳用大蒜、淡豆豉、蒸饼三物捣丸，令以温水下三十丸。曰：今日进三服，病当减三之一，明日亦然，三日病除。已而果然，赐以千缗。或问其说。琳曰：小儿何缘有淋？只是水道不利，三物皆能通利故也。（爱竹翁《谈薮》）。\n产后中风，角弓反张，不语：用大蒜三十瓣，以水三升，煮一升，灌之即苏。（张杰《子母秘录》）。\n金疮中风，角弓反张：取蒜一升去心，无灰酒四升煮极烂，并滓服之。须臾得汗即瘥。（《外台秘要》）。\n妇人阴肿作痒：蒜汤洗之，效乃止。（《永类钤方》）。\n阴汗作痒：大蒜、淡豉。捣丸梧子大，朱砂为衣，每空腹灯心汤下三十丸。\n小便淋沥，或有或无：用大蒜一个，纸包煨熟，露一夜，空心新水送下。（《朱氏集验方》）。\n小儿白秃团团然：切蒜日日揩之。（《秘录》）\n闭口椒毒，气闭欲绝者：煮蒜食之。（张仲景方）\n射工溪毒：独头蒜切三分浓，贴上灸之，令蒜气射入即瘥。（《梅师方》）。\n蜈蝎螫伤：独头蒜摩之，即止。（《梅师》）\n蛇虺螫伤：孟诜曰：即时嚼蒜封之，六、七易。仍以蒜一升去皮，以乳二升煮熟，空心顿服。明日又进。外以去皮蒜一升捣细，小便一升煮三、四沸，浸损处。\n《梅师》：用独头蒜、酸草捣绞敷咬处。\n脚肚转筋：大蒜擦足心令热，即安。仍以冷水食一瓣。（《摄生方》）\n食蟹中毒：干蒜煮汁饮之。（《集验方》）。\n蛇瘕面光，发热，如火炙人：饮蒜汁一碗，吐出如蛇状，即安。（危氏方）"},
  "葫芦巴":{o:[],src:["本草纲目"],d:"新六。\n小肠气痛︰葫芦巴（炒）研末，每服二钱，茴香酒下。（《直指方》）\n肾脏虚冷，腹胁胀满︰葫芦巴（炒）二两，熟附子、硫黄各七钱五分。为末，酒煮曲糊丸梧桐子大，每盐汤下三、四十丸。（《圣济总录》）\n冷气疝瘕︰葫芦巴（酒浸晒干）、荞麦（炒，研面）各四两，小茴香一两。为末，酒糊丸梧子大。每服五十丸，空心盐汤或盐酒下。服至两月，大便出白脓，则除根。（方广《心法附余》）\n阴 肿痛偏坠，或小肠疝气，下元虚冷，久不愈者，沉香内消丸主之︰沉香、木香各半两，葫芦巴（酒浸炒）、小茴香（炒）各二两。为末，酒糊丸梧子大。每服五、七十丸，盐酒下。气攻头痛︰葫芦巴（炒）、三棱（酒浸焙）各半两，干姜（炮）二钱半，为末，姜汤或温酒每服二钱。（《济生方》）\n寒湿脚气，腿膝疼痛，行步无力︰胡芦巴（酒浸一宿，焙）、破故纸（炒香）各四两。为末。以木瓜切顶去瓤，安药在内令满，用顶合住签定，烂蒸，捣丸梧子大。每服七十丸，空心温酒下。（《杨氏家藏方》）"},
  "葱":{o:["葱"],src:["本草备要"],d:"轻，发表和里，宣，通阳活血\n生辛散，熟甘温（陶宏景曰∶白冷青热，伤寒汤中不得用青），外实中空，肺之菜也。肺主皮毛，其合阳明（大肠）。故发汗解肌，以通上下阳气（仲景白通汤、通脉四逆汤并加之，以通脉回阳），益目睛（白睛属肺），利耳鸣，通二便（时珍曰∶葱管吹盐入玉茎中，治小便不通，及转脬危急者极效）。治伤寒头痛，时疾热狂，阴毒腹痛（阴证厥逆，用葱白安脐上熨之）。气通则血活（气为血帅），故治吐血衄血，便血痢血（《食医心镜》∶葱煮粥食，治赤白痢，薤粥亦良），折伤血出（火煨研封，止痛无瘢），乳痈风痹，通乳安胎（妇人妊娠伤寒，葱白一物汤，发汗而安胎，加生姜亦佳。《删繁方》∶合香豉、阿胶，治胎动）。通气故能解毒，杀药毒、鱼肉毒、蚯蚓毒、 犬毒。诸物皆宜，故曰菜伯，又曰和事草。取白连须用，亦有用青者。同蜜食杀人，同枣食令人病（《百一方》∶患外痔者，先用木鳖煎汤熏洗，以青葱涎对蜜调敷，其凉如冰。《独行方》∶水病足肿，煮汤渍之，日三五度佳）。"},
  "葱茎白":{o:[],src:["本草纲目"],d:"旧十二，新三十六。\n感冒风寒初起：即用葱白一握，淡豆豉半合，泡汤服之，取汗。（《濒湖集简方》）\n伤寒头痛如破者：连须葱白半斤，生姜二两，水煮温服。（《活人书》）。\n时疾头痛，发热者：以连根葱白二十根，和米煮粥，入醋少许，热食取汗即解。（《济生秘览》）。\n数种伤寒，初起一、二日，不能分别者：用上法取汗。\n伤寒劳复，因交接者，腹痛卵肿：用葱白捣烂，苦酒一盏，和服之。（《千金方》）。\n风湿身痛：生葱擂烂，入香油数点，水煎，调川芎 、郁金末一钱服，取吐。（《丹溪心法》）。\n妊娠伤寒，赤斑变为黑斑，尿血者：以葱白一把，水三升，煮热服汁，食葱令尽，取汗。（《伤寒类要》）。\n六月孕动，困笃难救者：葱白一大握，水三升，煎一升，去滓顿服。（杨氏《产乳》）。\n胎动下血，腰痛抢心：杨氏产乳方：用葱白煮浓汁饮之。未死即安，已死即出。未效再服。\n一方：加川芎。一方：用银器同米煮粥及羹食。（《梅师方》）。\n卒中恶死或先病，或平居寝卧，奄忽而死，皆是中恶（《肘后方》）\n急取葱心黄刺入鼻孔中，男左女右，入七、八寸，鼻、目血出即苏。又法：用葱刺入耳中五寸，以鼻中血出即活也。如无血出，即不可治矣。相传此扁鹊秘方也。（崔氏《纂要》）。\n小儿卒死无故者：取葱白纳入下部，及两鼻孔中，气通或嚏即活。（《陈氏经验方》）。\n小儿盘肠，内钓腹痛：用葱汤洗儿腹，仍以炒葱捣贴脐上。良久，尿出痛止。（汤氏《婴孩宝书》）。\n阴毒腹痛，厥逆唇青卵缩，六脉欲绝者：用葱一束，去根及青，留白二寸，烘热安脐上，以熨斗火熨之，葱坏则易。良久热气透入，手足温有汗即瘥，乃服四逆汤。若熨而手足不温，不可治。（朱肱《南阳活人书》）。\n脱阳危症：凡人大吐大泄之后，四肢厥冷，不省人事，或与女子交后，小腹肾痛，外肾搐缩，冷汗出厥逆，须臾不救：先以葱白炒热熨脐，后以葱白三七茎擂烂，用酒煮灌之，阳气即回。（此华佗救卒病方也）。\n卒心急痛，牙关紧闭欲绝：以老葱白五茎去皮须，捣膏，以匙送入咽中，灌以麻油四两，但得下咽即苏。少顷，虫积皆化黄水而下，永不再发。累得救人。（《瑞竹堂方》）。\n霍乱烦躁，坐卧不安：葱白二十茎，大枣二十枚，水三升，煎二升，分服。（《梅师方》）。\n蛔虫心痛：用葱茎白二寸，铅粉二钱，捣丸服之，即止。葱能通气，粉能杀虫也。（杨氏《经验方》）。\n腹皮麻痹，不仁者：多煮葱白食之，即自愈。（危氏方）。\n小便闭胀，不治杀人：葱白三斤，锉炒，帕盛，二个更互熨小腹，气透即通也。（许学士《本事方》）。\n大小便闭：捣葱白和酢，封小腹上。仍灸七壮。（《外台秘要》）。\n大肠虚闭匀气散：用连须葱一根，姜一块，盐一捻，淡豉三七粒，捣作饼，烘掩脐中，扎定。良久，气通即通。不通再作。（杨氏《直指方》）。\n小儿虚闭：葱白三根煎汤，调生蜜、阿胶末服。仍以葱头染蜜，插入肛门，少顷即通。（《全幼心鉴》）。\n急淋阴肿：泥葱半斤，煨热杵烂，贴脐上。（《外台》）。\n小便淋涩或有血者：以赤根楼葱近根截一寸许，安脐中，以艾灸七壮。（《经验方》）。\n小儿不尿，乃胎热也：用大葱白切四片，用乳汁半盏，同煎片时，分作四服即通。不饮乳者，服之即饮乳。若脐四旁有青黑色及口撮者，不可救也。（《全幼心鉴》）。\n肿毒尿闭，因肿毒未溃，小便不通：用葱切，入麻油煎至黑色，去葱取油，时涂肿处，即通。（《普济》）。\n水 病肿：葱根白皮煮汁，服一盏，当下水出。病已困者，取根捣烂，坐之取气，水自下。（《圣济录》）。\n阴囊肿痛：葱白、乳香捣涂，即时痛止肿消。又方：用煨葱入盐，杵如泥，涂之。\n小便溺血：葱白一握，郁金一两，水一升，煎二合，温服。一日三次。（《普济方》）。\n肠痔有血：葱白三斤，煮汤熏洗立效。（《外台》）。\n赤白下痢：葱白一握细切，和米煮粥，日日食之。（《食医心镜》）。\n便毒初起：葱白炒热，布包熨数次，乃用敷药，即消。《永类方》：用葱根和蜜捣敷，以纸密护之。外服通气药，即愈。\n痈疽肿硬：乌金散：治痈疖肿硬无头，不变色者。米粉四两，葱白一两，同炒黑，研末，醋调，贴一伏时又换，以消为度。（《外科精义》）。\n一切肿毒：葱汁渍之，日四、五度。\n乳痈初起：葱汁一升，顿服即散。（并《千金》）。\n疔疮恶肿刺破：以老葱、生蜜杵贴。两时疔出，以醋汤洗之，神效。（《圣济录》）。\n小儿秃疮：冷泔洗净，以羊角葱捣泥，入蜜和涂之，神效。（杨氏）。\n刺疮金疮，百治不效：葱煎浓汁渍之，甚良。\n金疮瘀血，在腹者：大葱白二十枚，麻子三升，杵碎，水九升，煮一升半，顿服。当吐出脓血而愈。未尽再服。（并《千金方》）。\n血壅怪病，人遍身忽然肉出如锥，既痒且痛，不能饮食，名血壅。不速治，必溃脓血：以赤皮葱烧灰淋洗，饮豉汤数盏自安。（夏子益《怪病奇方》）\n解金银毒：葱白煮汁饮之。（《外台秘要》）。\n脑破骨折：蜜和葱白捣匀，浓封立效。（《肘后方》）。\n自缢垂死：葱心刺耳，鼻中有血出，即苏。（《肘后方》）\n叶\n\n旧三，新二。\n水病足肿：葱茎叶煮汤渍之，日三、五次妙。（韦宙《独行方》）。\n小便不通：葱白连叶捣烂，入蜜，合外肾上，即通。（《永类钤方》）\n疮伤风水肿疼。取葱青叶和干姜、黄柏等分，煮汤浸洗，立愈。（《食疗》）。\n蜘蛛咬疮，遍身生疮：青葱叶一茎去尖，入蚯蚓一条在内，待化成水，取点咬处即愈。（李绛《兵部手集》）。\n代指毒痛：取萎黄葱叶煮汁，热渍之。（《千金方》）。\n汁\n\n旧二，新三。\n衄血不止：方见上。\n金疮出血不止：取葱炙热， 汁涂之即止。（《梅师方》）\n火焰丹毒，从头起者：生葱汁涂之。\n痔 作痛：葱涎、白蜜和涂之，先以木鳖子煎汤熏洗，其冷如冰即效。一人苦此，早间用之，午刻即安也。（《唐仲举方》）。\n解钩吻毒，面青口噤欲死：以葱涕啖之，即解。（《千金》）。\n须\n\n旧一。\n喉中肿塞，气不通者：葱须阴干为末，每用二钱，入蒲州胆矾末一钱，和匀。每用一字，吹之。（杜壬方）\n花\n\n旧一。\n眼暗补中：葱子半斤、为末，每取一匙，水二升，煎汤一升半，去滓，入米煮粥食之。亦可为末，蜜丸梧子大，食后米汤服一、二十丸，日三服。（《食医心镜》）"},
  "葵":{o:[],src:["本草纲目"],d:"旧三，新四。\n天行斑疮︰方见上。\n肉锥怪疾︰有人手足甲忽长，倒生刺肉，如锥痛不可忍者，但食葵菜即愈。（夏子益《奇疾方》）\n诸 不合︰先以泔清温洗，拭净，取葵菜微火烘暖贴之。不过二三百叶，引脓尽，即肉生也。忌诸鱼、蒜、房事。（《必效方》）\n汤火伤疮︰葵菜为末敷之。（《食物本草》）\n蛇蝎螫伤︰葵菜捣汁服之。（《千金方》）\n误吞铜钱︰葵菜捣汁冷冻饮料。（《普济方》）\n丹石发动，口干咳嗽者︰每食后饮冬月葵齑汁一盏，便卧少时。（《食疗本草》）\n根\n\n旧五，新七。二便不通胀急者︰生冬葵根二斤（捣汁三合），生姜四两（取汁一合）。和匀，分二服。连用即通也。消渴引饮，小便不利︰葵根五两，水三大盏，煮汁，平旦服，日一服。（并《圣惠方》）\n每日平旦服二升。（《外台秘要》）\n漏胎下血，血尽子死︰葵根茎烧灰。酒服方寸匕，日三。（《千金方》）\n瘭疽恶毒，肉中忽生一 子，大如豆粟，或如梅李，或赤或黑，或白或青，其 有核，核有深根，应心，能烂筋骨，毒入脏腑即杀人︰但饮葵根汁，可折其热毒。（姚僧坦《集验方》）。\n妒乳乳痈︰葵茎及子为末。酒服方寸匕，日二。（昝殷《产宝》）\n身面疳疮，出黄汁者︰葵根烧灰，和猪脂涂之。（《食疗本草》）\n小儿蓐疮︰葵根烧末敷之。（《子母秘录》）\n小儿紧唇︰葵根烧灰，酥调涂之。（《圣惠方》）\n口吻生疮︰用经年葵根，烧灰敷之。（《外台秘要》）\n蛇虺螫伤︰葵根捣涂之。（《古今录验》）\n解防葵毒︰葵根捣汁饮之。（《千金方》）\n冬葵子\n《别录》曰︰十二月采之。机曰︰子乃春生，不应十二月可采也。\n\n旧九，新一十四。煮取一升服。不瘥更作。\n《圣惠》︰用葵子（末）、人乳汁等分。和服立通。\n《肘后方》︰用葵子二升。水四升，煮取一升，纳猪脂一丸如鸡子，顿服。《千金》︰用葵子为末，猪脂和丸梧子小便血淋︰葵子一升，水三升，煮汁，日三服。（《千金方》）\n妊娠患淋︰冬葵子一升，水三升，煮二升，分服。（《千金方》）\n妊娠下血︰方同上。\n产后淋沥不通︰用葵子一合，朴硝八分，水二升，煎八合，下硝服之。（《集验方》）\n妊娠水肿身重，小便不利，洒淅恶寒，起即头眩︰用葵子、茯苓各三两。为散。饮服方寸匕，日三服，小便利则愈。若转胞者，加发灰，神效。（《金匮要略》）\n生产困闷︰冬葵子一合，捣破。水二升，煮汁半升，顿服，少时便产。昔有人如此服之，登\n倒生口噤︰冬葵子炒黄为末。酒服二钱匕，效。（《产书》）\n乳汁不通︰方见发明。\n胎死腹中︰葵子为末，酒服方寸匕。若口噤不开者，灌之，药下即苏。（《千金方》）\n胞衣不下︰冬葵子一合，牛膝一两，水二升，煎一升服。（《千金方》）\n血痢产痢︰冬葵子为末。每服二钱，入蜡茶一钱，沸汤调服，日三。（《圣惠方》）\n疟邪热︰冬葵子阴干为末，酒服二钱。午日取花 手，亦去疟。（《圣惠方》）\n痈肿无头︰孟诜曰︰三日后，取葵子二百粒，水吞之，当日即开也。《经验后方》云︰只吞一粒即破。如吞两粒，则有两头也。\n便毒初起︰冬葵子末，酒服二钱。（《儒门事亲》）\n面上 疮︰冬葵子、柏子仁、茯苓、瓜瓣各一两。为末。食后酒服方寸匕，日三服。（陶隐\n解蜀椒毒︰冬葵子煮汁饮之。（《千金方》）\n伤寒劳复︰葵子二升，粱米一升，煮粥食，取汗立安。（《圣惠》）"},
  "葶苈":{o:["葶苈"],src:["本草备要", "本草纲目"],d:"大泻气秘，通，行水\n辛苦大寒。属火性急，大能下气，行膀胱水。肿中水气 急者，非此不能除。破积聚症结，伏留热气，消肿除痰，止嗽定喘（水湿泛溢，为肿胀，为痰嗽，为喘满）通经利便。久服令人虚（《十剂》曰∶泄可去闭，葶苈、大黄之属是也。大黄泄阴分血闭，葶苈泄阳分气闭，气味俱浓，不减大黄。然有甜、苦二种，甜者性缓，苦者性急，泄肺而伤胃，宜大枣辅之。仲景有葶苈大枣泻肺汤，治肺气喘急不得卧。昂按∶辅以大枣，补土所以制水）。子如黍米，微长色黄。合糯米微炒，去米用。得酒良。榆皮为使。"},
  "蒜":{o:[],src:["本草纲目"],d:"旧七，新七。\n时气温病，初得头痛，壮热脉大：即以小蒜一升，杵汁三合，顿服。不过再作便愈。（《肘后方》）。\n霍乱胀满，不得吐下，名干霍乱：小蒜一升，水三升，煮一升，顿服。（《肘后方》）。\n霍乱转筋，入腹杀人：以小蒜、盐各一两，捣敷脐中，灸七壮，立止。（《圣济录》）。\n积年心痛不可忍，不拘十年、五年者，随手见效：浓醋煮小蒜食饱，勿著盐。曾用之有效，再不发也。（《兵部手集》）。\n水毒中人：一名中溪，一名中湿，一名水病，似射工而无物。初得恶寒，头目微疼，旦醒暮剧，手足逆冷。三日则生虫，食人下部，肛中有疮，不痒不痛。过六、七日虫食五脏，注下不禁：以小蒜三升，煮微热（大热即无力）以浴身。若身发赤斑纹者，毋以他病治之也。（《肘后方》）。\n射工中人成疮者：取蒜切片，贴疮上，灸七壮。（《千金》）。\n止截疟疾：小蒜不拘多少，研泥，入黄丹少许，丸如芡子大。每服一丸，面东新汲水下，至妙。（唐慎微）。\n阴肿如刺汗出者：小蒜一升，韭根一升，杨柳根二斤，酒三升，煎沸乘热熏之。（《永类方》）。\n恶核肿结：小蒜、吴茱萸等分，捣敷即散。（《肘后》）。\n丹毒五色无常，及发足踝者：杵蒜浓敷，频易。（葛氏）。\n小儿白秃，头上团团白色：以蒜（切）口揩之。（《子母秘录》）。\n蛇蝎螫人：小蒜捣汁服，以滓敷之。（《肘后》）。\n蜈蚣咬疮：嚼小蒜涂之，良。（《肘后方》）。\n蚰蜒入耳：小蒜洗净，捣汁滴之。未出再滴。（李绛《兵部手集》）"},
  "蒟酱":{o:[],src:["本草纲目"],d:"新一。\n牙疼︰ 酱、细辛各半两，大皂荚五铤（去子，每孔入青盐烧存性）。同研末。频掺吐涎。（《御药院方》）"},
  "蒴藋":{o:[],src:["本草纲目"],d:"旧十二，新七。\n手足偏风︰蒴 叶，火燎，浓铺床上，趁热眠于上，冷复易之。冬月取根，舂碎熬热用。（《外台秘要》）\n风湿冷痹︰方同上。\n寒湿腰痛︰方同上。\n脚气胫肿骨疼︰蒴 根研碎，和酒糟三分，根一分，合蒸热，封裹肿上，日二即消。亦治不仁。（《千金方》）\n浑身水肿，坐卧不得︰取蒴 根去皮，捣汁一合，和酒一合，暖服，当微吐利。（《梅师方》）\n头风作痛︰蒴 根二升，酒二升，煮服，汗出止。（《千金方》）\n头风旋晕，起倒无定︰蒴 、独活、白石膏各一两，枳实（炒）七钱半。每服三钱，酒一盏，煎六分服。（《圣惠方》）\n煎半升，分二服。或小便\n产后恶露不除︰续骨木二十两（锉）。水一斗，煮三升，分三服，即下。（《千金方》）\n疟疾不止︰蒴 一大握，炙令黄色，以水浓煎一盏，欲发前服。（《斗门方》）\n卒暴症块坚如石，作痛欲死︰取蒴 根一小束，洗净细擘，以酒二升，渍三宿，温服五合至一升，日三服。若欲速用，于热灰中温出药味服之。此方无毒，已愈十六人矣，神验。药尽再作之。（《古今录验》）\n鳖瘕坚硬，肿起如盆，眠卧不得︰蒴 根白皮一握。捣汁和水服。（《千金方下部闭塞︰蒴 根一把。捣汁水和，绞去滓。强人每服一升。（《外台秘一切风疹︰蒴 煮汤，和少酒涂之，无不瘥。（《梅师方》）\n小儿赤游，上下游行，至心即死︰蒴 ，煎汁洗之。（《子母秘录》）\n五色丹毒︰蒴 叶，捣敷之。（《千金方》）\n痈肿恶肉不消者︰蒴 灰、锻石各淋取汁，合煎如膏。敷之，能蚀恶肉，亦去痣疵。此药过十日即不中用也。（《千金方》）\n手足疣目︰蒴 赤子，揉烂，涂目上。（《圣惠方》）\n熊罴伤人︰蒴 一大把。以水一升渍，须臾，取汁饮，以滓封之。（张文仲《备急方》）"},
  "蒺藜":{o:[],src:["本草纲目"],d:"旧九，新八。\n服食法︰蒺藜子一石（七、八月熟时收取）。日干，舂去刺，杵为末。每服二钱，新汲水调下，日三服，勿令中绝，断谷长生。服之一年以后，冬不寒，夏不热；二年，老者复少，发白复黑，齿落更生。服之三年，身轻长生。（《神仙秘旨》）\n腰脊引痛︰蒺藜子捣末，蜜和丸胡豆大。酒服二丸，日三服。（《外台秘要》）\n通身浮肿︰杜蒺藜日日煎汤洗之。（《圣惠方》）\n卒中五尸︰蒺藜子捣末，蜜丸胡豆大。每服二丸，日三服。（《肘后方》）\n大便风秘︰蒺藜子（炒）一两，猪牙皂荚（去皮，酥炙）五钱。为末。每服一钱，盐茶汤下。（《普济方》）\n月经不通︰杜蒺藜、当归等分，为末，米饮每服三钱。（《儒门事亲》）\n催生下衣，难产，胎在腹中，并包衣不下及胎死者︰蒺藜子、贝母各四两。为末，米汤服三钱。少顷不下，再服。（《梅师方》）\n蛔虫心痛吐清水︰七月七日采蒺藜子阴干，烧作灰，先食服方寸匕，日三服。（《外台秘要》）其汁煎如饴，服之。三十年失明︰补肝散︰用蒺藜子（七月七日收），阴干捣散。食后水服方寸匕，日二。（《外台秘要》）\n牙齿动摇，疼痛及打动者︰土蒺藜（去角生研）五钱，淡浆水半碗。蘸水入盐温漱，甚效。或以根烧灰，贴牙即牢固也。（《御药院方》）\n牙齿出血不止，动摇︰白蒺藜末，旦旦擦之。（《道藏经》）\n打动牙疼︰蒺藜子或根为末，日日揩之。（《瑞竹堂方》）\n鼻塞出水，多年不闻香臭︰蒺藜二握，当道车碾过，以水一大盏，煮取半盏。仰卧，先满口含饭，以汁一合灌鼻中。不过再灌，嚏出一两个息肉，似赤蛹虫，即愈。（《圣惠方》）\n面上瘢痕︰蒺藜子、山栀子各一合。为末。醋和，夜涂旦洗。（《救急方》）\n白癜风疾︰白蒺藜子六两，生捣为末。每汤服二钱，日二钱。一月绝根。服至半月，白处见红点，神效。（《孙真人食忌》）\n一切疔肿︰蒺藜子一升，作灰，以醋和封头上，拔根。（《外台秘要》）\n花\n\n旧二，新一。\n鼻流清涕︰蒺藜苗二握，黄连二两，水五升，煎一升，少少灌鼻中取嚏，不过再灌。（《圣济录》）\n诸疮肿毒︰蒺藜蔓洗，三寸截之，取得一斗。以水五升，煮取二升，去滓，纳铜器中，又煮取一升，纳小器中，煮如饴状，以涂肿处。（《千金方》）\n蠷 尿疮，绕身匝即死︰以蒺藜叶捣敷之。无叶用子。（《备急方》）"},
  "蓄":{o:[],src:["本草纲目"],d:"旧七，新二。\n热淋涩痛︰扁竹煎汤频饮。（《生生编》）\n热黄胆疾︰扁竹捣汁，顿服一升。多年者，日再服之。（《药性论》）\n霍乱吐利︰扁竹入豉汁中，下五味，煮羹食。（《食医心镜》）\n丹石冲眼，服丹石人毒发，冲眼肿痛︰扁竹根一握，洗，捣汁服之。（《食疗本草》）\n蛔咬心痛︰《食疗》︰治小儿蛔咬心痛，面青，口中沫出临死者︰取扁竹十斤（锉）。以水一石，煎至一斗，去滓煎如饧。隔宿勿食，空心服一升，虫即下也。仍常煮汁作饭食。《海上歌》云︰心头急痛不能当，我有仙人海上方。 蓄醋煎通口咽，管教时刻便安康。\n虫食下部，虫状如蜗牛，食下部作痒︰取扁竹一把。水二升，煮熟。五岁儿，空腹服三、五合。（《杨氏产乳》）\n痔发肿痛︰扁竹捣汁，服一升。一、二服未瘥，再服。亦取汁和面作 煮食，日三次。（《药性论》）\n恶疮痂痒作痛︰扁竹捣封，痂落即瘥。（《肘后方》）"},
  "蓍":{o:[],src:["本草纲目"],d:"新一。\n腹中痞块︰蓍叶、独蒜、穿山甲（末）、食盐。同以好醋捣成饼，量痞大小贴之，两炷香为度。其痞化为脓血，从大便出。（刘松石《保寿堂方》）"},
  "蓖麻":{o:[],src:["本草纲目"],d:"旧九，新三十二。半身不遂，失音不语︰取蓖麻子油一升，酒一斗，铜锅盛油，著酒中一日，煮之令熟。细细服之。（《外台秘要》）\n口目 斜︰蓖麻子仁捣膏，左贴右，右贴左，即正。《妇人良方》︰用蓖麻子仁七七粒，研作饼，右 安在左手心；左 ，安在右手心，却以铜盂盛热水坐药上，冷即换，五一方︰用蓖麻子仁七七粒，巴豆十九粒，麝香五分，作饼如上用。风气头痛不可忍者︰乳香、蓖麻仁等分，捣饼随左右贴太阳穴，解发出气，甚验。《德生堂方》︰用蓖麻油纸剪花，贴太阳亦效。又方︰蓖麻仁半两，枣肉十五枚，捣涂纸上，卷筒插入鼻中，下清涕即止。八种头风︰蓖麻子、刚子各四十九粒（去壳），雀脑芎一大块。捣如泥，糊丸弹子大，线穿挂风处阴干。用时先将好末茶调成膏子涂盏内，后将炭火烧前药烟起，以盏覆之。待烟尽，以百沸葱汤点盏内茶药服之。后以绵被裹头卧，汗出避风。（《袖珍方》）\n鼻窒不通︰蓖麻子仁（去皮）三百粒，大枣（去皮核）十五枚。捣匀，绵裹塞之。一日一易，三十余日闻香臭也。（《普济方》）\n天柱骨倒，小儿疳疾及诸病后，天柱骨倒，乃体虚所致，宜生筋散贴之︰木鳖子六个（去壳），蓖麻子六十粒（去壳）。研匀。先包头擦项上令热，以津调药贴之。（《郑氏小儿方》）\n五种风痫，不问年月远近︰用蓖麻子仁二两，黄连一两，用银石器纳水一大碗，文武火煮之。干即添水，三日两夜取出黄连，只用蓖麻风干，勿令见日，以竹刀每个切作四段。每服二十段，食后荆芥汤下，日二服。终身忌食豆，犯之必腹胀死。（《卫生宝鉴》）\n舌上出血︰蓖麻子油纸燃，烧烟熏鼻中，自止。（《摘玄方》）\n舌胀塞口︰蓖麻仁四十粒，去壳研油涂纸上，作燃烧烟熏之。未退再熏，以愈为度。有人舌肿退场门外，一村人用此法而愈。（《经验良方》）\n急喉痹塞，牙关紧急不通，用此即破︰以蓖麻子仁研烂，纸卷作筒，烧烟熏吸即通。或只取油作捻尤妙。名圣烟筒。咽中疮肿︰《杜壬方》︰用蓖麻子仁一枚，朴硝一钱，同研，新汲水服之，连进二、三服效。\n《三因方》︰用蓖麻仁、荆芥穗等分。为末，蜜丸。绵包噙，咽之。水气胀满︰蓖麻子仁研，水解得三合。清旦一顿服尽，日中当下青黄水也。或云壮人止可服五粒。（《外台秘要》）\n脚气作痛︰蓖麻子七粒，去壳研烂，同苏合香丸贴足心，痛即止也。（《外台秘要》）\n小便不通︰蓖麻仁三粒，研细，入纸捻内，插入茎中即通。（《摘玄方》）\n喘咳嗽︰蓖麻子去壳炒熟，拣甜者食之。须多服见效。终身不可食炒豆。（《卫生易简方》）\n催生下胞︰崔元亮《海上集验方》︰取蓖麻子七粒，去壳研膏，涂脚心。若胎及衣下，便速洗去。不尔则子肠出，即以此膏涂顶，则肠自入也。《肘后方》云︰产难，取蓖麻子十四枚，每手各把七枚，须臾立下也。子宫脱下︰蓖麻子仁、枯矾等分，为末，安纸上托入。仍以蓖麻子仁十四枚，研膏涂顶心即入。（《摘玄》）\n盘肠生产︰涂顶方同上。催生下胎，不拘生胎死胎︰蓖麻二个，巴豆一个，麝香一分，研贴脐中并足心。又下生胎，一月一粒，温酒吞下。（《集简方》）\n一切毒肿，痛不可忍︰蓖麻子仁捣敷，即止也。（《肘后方》）\n疠风鼻塌，手指挛曲，节间痛不可忍，渐至断落︰用蓖麻子一两（去皮），黄连一两（锉豆大）。以小瓶子入水一升，同浸。春夏三日，秋冬五日后，取蓖麻子一枚劈破，面东以浸药水吞之。渐加至四、五枚，微利不妨。瓶中水尽更添。两月后吃大蒜、猪肉试之，如不发是小儿丹瘤︰蓖麻子五个，去皮研。入面一匙，水调涂之，甚效。（《修真秘旨》）\n瘰疬结核︰蓖麻子炒去皮，每睡时服二三枚，取效。一生不可吃炒豆。（《阮氏经验方》）\n瘰疬恶疮及软疖︰用白胶香一两，瓦器溶化，去滓，以蓖麻子六十四个，去壳研膏，溶胶投之，搅匀，入油半匙头，柱点水中试软硬，添减胶油得所，以绯帛量疮大小摊贴，一膏可治三五疖也肺风面疮起白屑，或微有赤疮︰用蓖麻子仁四十九粒，白果、胶枣各三粒，瓦松三钱，肥皂一个，捣为丸。洗面用之良。（吴 《面上雀斑︰蓖麻子仁、密陀僧、硫黄各一钱，为末。用羊髓和匀，夜夜敷之。（《摘玄方》）\n发黄不黑︰蓖麻子仁，香油煎焦，去滓。三日后频刷之。（《摘玄方》）\n耳卒聋闭︰蓖麻子一百个（去壳），与大枣十五枚捣烂，入乳小儿乳汁，和丸作铤。每以绵裹一枚塞之，觉耳中热为度。一日一易，二十日瘥。（《千金方》）\n汤火灼伤︰蓖麻子仁、蛤粉等分。研膏。汤伤，以油调；火灼，以水调，涂之。（《古今录验》）\n针刺入肉︰蓖麻子（去壳烂研），先以帛衬伤处，敷之。频看，若见刺出，即拔去，恐药紧弩出好肉。或加白梅肉同研尤好。（《卫生易简方》）\n竹木骨哽︰蓖麻子仁一两，凝水石二两。研匀。每以一捻置舌根，噙咽，自然不见。又方︰蓖麻油、红曲等分。研细，沙糖丸皂子大，绵裹含咽，痰出大良。鸡鱼骨哽︰蓖麻子仁研烂，入百药煎研，丸弹子大。井花水化下半丸，即下。恶犬咬伤︰蓖麻子五十粒（去壳）。以井花研膏。先以盐水洗、吹痛处，乃贴此膏。（《袖珍方》）\n叶\n\n新二。\n喘痰嗽︰《儒门事亲》方︰用九尖蓖麻叶三钱，入飞过白矾二钱。以猪肉四两薄批，掺药在内，荷叶裹之，文武火煨熟。细嚼，以白汤送下。名九仙散。《普济方》︰治咳嗽涎喘，不问年深日近。用经霜蓖麻叶、经霜桑叶、御米壳（蜜炒）各一两。为末，蜜丸弹子大。每服一丸，白汤化下，日一服，名无忧丸。"},
  "蓖麻子":{o:["蓖麻子"],src:["本草备要"],d:"泻，通窍，拔毒，出有形滞物\n辛苦有毒。性善收，亦善走，能开通诸窍、经络。治偏风不遂， 斜（捣饼。左贴右，右贴左，即止）口噤，鼻窒耳聋（捣烂绵裹，塞耳塞鼻），喉痹舌胀（油作纸，燃烟熏）。能利水气，治水症浮肿（研服。当下青黄水，壮人只可五粒）能出有形滞物。治针刺入肉（捣敷伤处，频看，刺出即去药，恐努出好肉），竹木骨哽（蓖麻子一两，凝水石二两，研匀。以一捻置舌根，噙咽，自然不见），胞胎不下（蓖麻一粒，巴豆一粒，麝香一分，贴脐中并足心，胎下即去之。若子肠挺出者，捣膏涂顶心，即收）。能追脓拔毒，敷瘰 恶疮，外用屡奏奇功（鹈鹕油，能引药气入内。蓖麻油，能拔气出外，故诸膏多用之）。然有热毒，气味颇近巴豆，内服不可轻率（去皮，黄连水浸，每晨用浸水吞一粒至三四粒，治大风疥癞）。形如牛蜱，黄褐有斑。盐水煮，去皮研，或用油。忌铁（食蓖麻，一生不得食炒豆，犯之胀死）。"},
  "蓝淀":{o:[],src:["本草纲目"],d:"旧三，新一。\n时行热毒，心神烦躁︰用蓝淀一匙。新汲水一盏服。（《圣惠方》）\n小儿热丹︰蓝淀，敷之。（《子母秘录方》）\n口鼻急疳，数日欲死︰以蓝淀敷之，令遍，日十度，夜四度。（《千金翼》）\n误吞水蛭︰青靛调水饮，即泻出。（《普济方》）"},
  "蓬莪荗":{o:[],src:["本草纲目"],d:"旧二，新六。\n一切冷气，抢心切痛，发即欲死。久患心腹痛时发者，此可绝根。蓬莪术二两（醋煮），木香一两（煨）。为末。每服半钱，淡醋汤下。（《卫生家宝方》）\n小肠脏气，非时痛不可忍。蓬莪术研末，空心葱酒服一钱。（杨子建《护命方》）\n妇人血气，游走作痛，及腰痛。蓬莪术、干漆二两，为末，酒服二钱。腰痛，核桃酒下。（《普济方》）\n小儿盘肠内钓痛。以莪术半两，用阿魏一钱，化水浸一日夜，焙研。每服一字，紫苏汤下。（《保小儿气痛︰蓬莪术炮熟为末。热酒服一大钱。（《十全博救方》）\n上气喘急︰蓬莪术五钱，酒一盏半，煎八分服。（《保生方》）\n气短不接︰正元散︰治气不接续，兼治滑泄，及小便数。王丞相服之有验。用蓬莪术一两，金铃子（去核）一两，为末，入蓬砂一钱，炼过研细。每服二钱，温酒或盐汤空心服。（孙用和《秘宝方》）\n去滓，入牛黄两粟大，服之，甚效也。（《保幼大全》）\n浑身燎泡︰方见荆三棱。"},
  "蓬蘽":{o:[],src:["本草纲目"],d:"（音累，《本经》上品）\n【校正】自果部移入此。\n【释名】复盆（《本经》）、陵蘽（《别录》）、阴蘽（《别录》）、寒莓（《会编》）、割田藨（音包）\n时珍曰︰蓬蘽与复盆同类，故《本经》谓一名复盆。此种生于丘陵之间，藤叶繁衍，蓬蓬累累，异于复盆，故曰蓬蘽 、陵蘽，即藤也。其实八月始熟，俚人名割田藨。\n【集解】《别录》曰︰蓬蘽，生荆山平泽及冤句。\n弘景曰︰蓬蘽是根名，方家不用，乃昌容所服，以易颜者也。复盆是实名。李当之云︰是人所食莓子。以津汁\n恭曰︰复盆、蓬蘽，乃一物异名，本谓实，非根也。李云莓子者，近之矣。然生处不同，沃地则子大而甘，瘠地则子细而酸。此乃子有酸味，根无酸味。陶以根酸子甘，列入果部，重出二条，殊为孟浪。\n志曰︰蓬蘽乃复盆之苗茎，复盆乃蓬蘽之子也。按《切韵》︰莓音茂，其子复盆也。蘽者，藤也，则蓬蘽明是藤蔓矣。\n颂曰︰蓬蘽是复盆苗，处处有之，秦吴尤多。苗短不过尺，茎叶皆有刺，花白，子赤黄，如半弹丸大，而下有蒂承之，如柿蒂，小儿多食之。五月采实，其苗叶采无时。江南谓之莓，然其地所生差晚，三月始有苗，八、九月花开，十月实用则同。\n士良曰︰今观采取之家说，蓬蘽似蚕莓子，红色而大，其味酸甘，叶似野蔷薇，有刺。复盆子小，其苗各别。诸家本草不识，故皆说蓬蘽是复盆子之根。\n大明曰︰莓子是蓬蘽子也。树莓是复盆子也。\n宗奭曰︰蓬蘽非复盆也，别是一种，虽枯败而枝梗不散，今人不见用此。\n藏器曰︰其类有三种，惟四月熟，状如复盆子，而味甘美者，为是。余不堪入药。机曰︰蓬蘽，徽人谓之寒莓。沿堑作丛蔓生，茎小叶密多刺。其实四、五十颗作一朵，一朵大如盏面，霜后始红。苏颂《图经》以此注复盆，误矣。江南复盆，亦四五月熟，何尝差晚耶？复盆茎粗叶疏，结实大而疏散，不似寒莓，茎细叶密，结实小而成朵。一则夏熟，一则秋熟，岂得同哉？\n时珍曰︰此类凡五种。予尝亲采，以《尔雅》所列者校之，始得其的。诸家所说，皆未可信也。一种藤蔓繁衍，茎有倒刺，逐节生叶，叶大如掌，状类小葵叶，面青背白，浓而有毛，六、七月开小白花，就蒂结实，三、四十颗成簇，生则青黄，熟则紫黯，微有黑毛，状如熟椹而扁，冬月苗叶不凋者，俗名割田 ，即本草所谓蓬蘽也。一种蔓小于蓬蘽，亦有钩刺，一枝五叶，叶小而面背皆青，光薄而无毛，开白花，四、五月实成，子亦小于蓬蘽而稀疏，生则青黄，熟则乌赤，冬月苗凋者，俗名插田 ，即本草所谓复盆子，《尔雅》所谓 ，缺盆也。此二者俱可入药。一种蔓小于蓬蘽，一枝三叶，叶面青，背淡白而微有毛，开小白花，四月实熟，其色红如樱桃者，俗名 田 ，即《尔雅》所谓 者也。故郭璞注云︰ 即莓也。子似复盆而大，赤色，酢甜可食。此种不入药用。一种树生者，树高四五尺，叶似樱桃叶而狭长，四月开小白花，结实与复盆子一样，但色红为异，俗亦名，即《尔雅》所谓山莓，陈藏器《本草》所谓悬钩子者也。详见本条。一种就地生蔓，长数寸，开黄花，结实如覆盆而鲜红，不可食者，本草所谓蛇莓也。见本条。如此辨析，则蓬、复盆自定矣。李当之、陈士良、陈藏器、寇宗奭、汪机五说近是，而欠明悉。陶弘景以蓬为根，复盆为子；马志、苏颂以蓬蘽为苗，复盆为子；苏恭以为一物；大明以树生者为复盆。皆臆说，不可据。\n【气味】酸，平，无毒。《别录》曰︰咸。士良曰︰甘、酸，微热。\n【主治】安五脏，益精气，长阴令坚，强志倍力，有子。久服轻身不老（《本经》）。疗暴中风，身热大惊（《别录》）。益颜色，长发，耐寒湿（恭）。\n【发明】见复盆子下。\n【附方】新一。"},
  "蓼":{o:[],src:["本草纲目"],d:"旧二，新二。\n伤寒劳复，因交后卵肿，或缩入腹痛︰蓼子一把。水 汁，饮一升。（《肘后方》）\n霍乱烦渴︰蓼子一两，香薷二两。每服二钱，水煎服。（《圣济录》）\n小儿头疮︰蓼子为末，蜜和鸡子白同涂之，虫出不作痕。（《药性论》）\n蜗牛咬毒，毒行遍身者︰蓼子煎水浸之，立愈。不可近阴，令弱也。（陈藏器《本草》）\n苗叶\n\n旧四，新三。\n蓼汁酒，治胃脘冷，不能饮食，耳目不聪明，四肢有气，冬卧足冷︰八月三日取蓼日干，如五升大，六十把，水六石，煮取一石，去滓，拌米饭，如造酒法，待熟，日饮之。十日后，目明气壮也。（《千金方》）\n肝虚转筋吐泻︰赤蓼茎叶（切）三合。水一盏，酒三合，煎至四合，分二服。（《圣惠方》）\n霍乱转筋︰蓼叶一升。水三升，煮取汁二升，入香豉一升，更煮一升半，分三服。（《药性论》）\n夏月 死︰浓煮蓼汁一盏服。（《外台》）\n小儿冷痢︰蓼叶，捣汁服。（《千金》）\n血气攻心，痛不可忍︰蓼根洗锉，浸酒饮。（《斗门》）\n恶犬咬伤︰蓼叶，捣泥敷。（《肘后》）\n水蓼（《唐本草》）"},
  "蓼实":{o:["蓼实"],src:["本草备要"],d:"宣，温中\n辛温。温中明目，耐风寒，下水气（时珍曰∶古人种蓼为蔬，收子入药，今为酒曲用其汁耳。以香蓼、青蓼、紫蓼为良）。有香蓼、青蓼、紫蓼、赤蓼、木蓼、水蓼、马蓼。"},
  "蔓菁子":{o:["蔓菁子"],src:["本草备要"],d:"（即芜菁）\n泻热，利水，明目苦辛。泻热解毒，利水明目（古方治目，用之最多）。治黄胆（捣服）腹胀（捣研滤汁饮，或吐或利，腹中自宽，得汗愈），症瘕积聚，小儿血痢（蜜和汁服），一切疮疽（凡痈疽捣敷皆良。醋调敷秃疮，盐捣敷乳痈。冬取根用），敷蜘蛛咬毒（陈藏器曰∶蔓菁园中无蜘蛛。李时珍曰∶蔓菁子可升可降，能汗能吐能下，能利小便，明目解毒，其功甚伟，世罕知用，何哉？）。根，捣敷阴囊肿大如斗；末服解酒毒；和芸苔（油菜也）根捣汁，鸡子清调，涂诸热毒（单盐捣，不用芸苔亦可）。"},
  "蔷薇根":{o:["蔷薇根"],src:["本草备要"],d:"泻湿热\n苦涩而冷。入胃、大肠经。除风热、湿热，生肌杀虫。治泄痢消渴，牙痛口糜（煎汁含漱），遗尿好眠，痈疽疮癣。花有黄、白、红、紫数色，以黄心、白色、粉红者入药。子，名营实，酸温。主治略同（《千金》曰∶蔷薇根，角蒿，口疮之神药。角蒿所在多有，开淡红紫花，角微弯，长二寸许，辛苦有小毒。治恶疮有虫，及口齿疮）。"},
  "蕤仁":{o:["蕤仁"],src:["本草备要"],d:"（亦名白）\n补，明目甘温（《别录》微寒）。入心、肝、脾三经。消风散热，益水生光（三经皆血脏也。血得其养，则目疾平。凡目病在表，当疏风清热。在里属肾虚、血少、神劳，宜补肾养血安神。远视为肾水亏，近视为火不足）。治目赤肿痛， 烂泪出，亦治心腹邪热，结气痰痞（今人惟用疗眼。陈藏器曰∶生治足睡，熟治不眠）。丛生有刺，实如五味，圆扁有纹，紫赤可食。取仁浸，去皮、尖，研用。"},
  "蕨":{o:[],src:["本草纲目"],d:"新一。\n肠风热毒︰蕨菜花焙，为末。每服二钱，米饮下。（《圣惠》）"},
  "蕺菜":{o:[],src:["本草纲目"],d:"旧一，新七。\n背疮热肿︰蕺菜捣汁涂之，留孔以泄热毒，冷即易之。（《经验方》）。\n痔疮肿痛︰鱼腥草一握，煎汤熏洗，仍以草挹痔即愈。一方︰洗后以枯矾入片脑少许，敷之。（《救急方》）。疔疮作痛︰鱼腥草捣烂敷之。痛一、二时，不可去草，痛后一、二日即愈。徽人所传方也。（陆氏《积德堂方》）\n小儿脱肛︰鱼腥草擂如泥，先以朴硝水洗过，用芭蕉叶托住药坐之，自入也。（《永类方》）\n虫牙作痛︰鱼腥草、花椒、菜子油等分，捣匀，入泥少许，和作小丸如豆大。随牙左右塞耳内，两边轮换，不可一齐用，恐闭耳气。塞一日夜，取看有细虫为效。（《简便方》）\n断截疟疾︰紫蕺一握。捣烂绢包，周身摩擦，得睡有汗即愈。临发前一时作之。（《救急易方》）\n恶蛇虫伤︰鱼腥草、皱面草、槐树叶、草决明，一处杵烂，敷之甚效。（同上）"},
  "薇衔":{o:[],src:["本草纲目"],d:"新二。\n年深恶疮︰无心草根、钓苓根、野狼毒、白丁香各五钱，麝香一字，为末掺之。又方︰无心小儿破伤风病，拘急口噤︰没心草半两，白附子（炮）二钱半，为末。每服一字，薄荷酒灌下。（《圣济录》）"},
  "薤":{o:["薤"],src:["本草备要", "本草纲目"],d:"（一名 子， 音叫）\n滑，利窍，助阳辛苦滑温。调中助阳，散血生肌，泄下焦大肠气滞。治泄痢下重（王好古曰∶下重者，气滞也，四逆散加此以泄滞。按∶下重亦有气虚、血虚、火热、风燥之不同），胸痹刺痛（仲景用栝蒌薤白白酒汤），肺气喘急。安胎利产，涂汤、火伤（和蜜捣用。《肘后方》∶中恶卒死者，用薤汁灌鼻中，韭汁亦可）。叶似韭而中空，根如蒜。取白用。忌牛肉（其叶光滑，露亦难贮，故云薤露）。"},
  "薯蓣":{o:[],src:["本草纲目"],d:"旧一，新十。\n补益虚损，益颜色，补下焦虚冷，小便频数，瘦损无力︰用薯蓣于沙盆中研细，入铫中，以酥一大匙熬令香，旋添酒一盏煎搅令匀，空心饮之。每旦一服。（《圣惠方》）。\n心腹虚胀，手足厥逆，或饮苦寒之剂多，未食先呕，不思饮食︰山药半生半炒，为末。米饮服二钱，一日二服，大有功效。忌铁器、生冷。（《普济方》）。\n小便数多︰山药（以矾水煮过）、白茯苓等分，为末。每水饮服二钱。（《儒门事亲》）。\n下痢禁口︰山药半生半炒，为末。每服二钱，米饮下。（《卫生易简方》）。\n痰风喘急︰生山药捣烂半碗，入甘蔗汁半碗，和匀。顿热饮之，立止。（《简便单方》）。\n脾胃虚弱，不思饮食︰山芋、白术各一两，人参七钱半，为末，水糊丸小豆大，每米饮下四、五十丸。（《普济方》）\n湿热虚泄︰山药、苍术等分。饭丸。米饮服。大人、小儿皆宜。（《濒湖经验方》）\n肿毒初起︰带泥山药、蓖麻子、糯米等分，水浸研，敷之即散也。（《普济方》）\n胯眼脊疡︰山药、沙糖同捣，涂上即消。先以面涂四围，乃上此。（《简便单方》）\n项后结核，或赤肿硬痛︰以生山药一挺（去皮），蓖麻子二个同研，贴之如神。（《救急易方》）\n手足冻疮︰山药一截，磨泥，敷之。（《儒门事亲》）"},
  "薰草":{o:[],src:["本草纲目"],d:"新十。\n伤寒下痢︰蕙草汤︰用蕙草、当归各二两，黄连四两，水六升，煮二升服，日三服。（《范汪方》）\n伤寒狐惑，食肛者。蕙草、黄连各四两。 咀，以白酸浆一斗，渍一宿，煮取二升，分三服。（《短剧方》）\n头风旋运，痰逆恶心懒食。真零陵香、霍香叶、莎草根（炒）等分，为末。每服二钱，茶下，日三服。（《本事方》）\n小儿鼻塞头热。用薰草一两，羊髓三两。铫内慢火熬成膏，去滓，日摩背上三、四次。（《圣惠方》）\n头风白屑︰零陵香、白芷等分，水煎汁，入鸡子白搅匀，敷数十次，终身不生。（《圣惠方》）。牙齿疼痛︰零陵香梗叶煎水，含漱之。（《普济方》）\n风牙疳牙︰零陵香（洗炙）、荜茇（炒）等分，为末掺之。（《普济方》）\n梦遗失精︰薰草汤︰用薰草、人参、白术、白芍药、生地黄各二两，茯神、桂心、甘草（炙）各二两，大枣十二枚，水八升，煮三升，分二服。（《外台秘要》）\n妇人断产︰零陵香为末，酒服二钱。每服至一两，即一年绝孕。盖血闻香即散也。（《医林集要》）\n五色诸痢︰返魂丹︰用零陵香草去根，以盐酒浸半月，炒干。每两入广木香一钱半，为末。里急腹痛者，用冷水服一钱半，通了三、四次，用热米汤服一钱半，止痢。只忌生梨一味。（《集简方》）"},
  "藕":{o:["藕"],src:["本草备要"],d:"凉血散瘀\n涩平。解热毒，消瘀血，止吐、衄、淋、痢一切血证（和生地汁、童便服良）。藕生甘寒，凉血散瘀（宋大官作血 ，误落藕皮，血遂涣散不凝。一人病血淋，痛胀欲死，李时珍以发灰二钱，藕汁调服，三日而愈。《梅师方》∶产后余血上冲，煮汁服），止渴除烦（《圣惠方》∶藕汁，蜜和服，治时气烦渴），解酒毒、蟹毒（捣烂，热酒调服）。煮熟甘温，益胃补心（多孔象心），止泻（能实大肠）止怒，久服令人欢（益心之效）。生捣，罨金疮伤折；熟捣，涂坼裂冻疮（《肘后方》∶卒中毒箭者，藕汁饮，多多益善。孟诜曰∶产后忌生冷，独藕不忌，为能散瘀血也）澄粉亦佳，安神益胃。"},
  "藜":{o:[],src:["本草纲目"],d:"新一。\n白癜风︰红灰 五斤，茄子根、茎三斤，苍耳根、茎五斤，并晒干烧灰，以水一斗煎汤淋汁熬成膏，别以好乳香半两，铅霜一分，腻粉一分，炼成牛脂二两，和匀，每日涂三次。（《圣惠》）\n茎"},
  "藜芦":{o:["藜芦"],src:["本草备要", "本草纲目"],d:"宣，引吐\n辛寒至苦，有毒。入口即吐，善通顶，令人嚏，风痫证多用之（张子和曰∶一妇病风痫，初一、二年一作，后渐日作，甚至一日数作，求死而已。值岁大饥，采百草食，见野草若葱，采蒸饱食，觉不安，吐胶涎数日，约一二斗，汗出如洗，甚昏困，后遂轻健如常人。以所食葱访人，乃憨葱苗，即藜芦是矣。时珍曰∶和王妃年七十，中风不省，牙关紧闭。先考太医吏目月池翁诊视，药不得入。不获已，打去一齿，浓煎藜芦汤灌之，少顷噫气，遂吐痰而苏。药不瞑眩，厥疾不瘳，诚然）。取根去头。用黄连为使。反细辛、芍药、诸参。恶大黄。畏葱白（吐者、服葱汤即止）。"},
  "藿香":{o:["藿香"],src:["本草备要", "本草纲目"],d:"宣，去恶气\n辛甘微温。入手足太阴（肺、脾）。快气和中，开胃止呕（胃弱、胃热而呕者忌用），去恶气，进饮食。治霍乱吐泻，心腹绞痛，肺虚有寒，上焦壅热（能理脾、肺之气。古方有藿香正气散，正气通畅，则邪逆自除）。出交广，方茎有节，叶微似茄汁。古惟用叶，今枝、茎亦用之，因叶多伪也。"},
  "蘘荷":{o:[],src:["本草纲目"],d:"旧八，新一。\n密置病患席下，勿令知之，必自呼蛊主姓名也。（《梅师方》）\n取白 荷根捣汁服，蛊立出也。（《梅师方》）\n喉舌疮烂︰酒渍 荷根半日，含漱其汁，瘥乃止。（《外台秘要》方）\n吐血痔血︰向东 荷根一把，捣汁三升服之。（《肘后方》）\n妇人腰痛︰方同上。\n月信涩滞︰ 荷根细切，水煎取二升，空心入酒和服。（《经验方》）\n风冷失声，咽喉不利︰ 荷根二两，捣绞汁，入酒一大盏，和匀，细细服，取瘥。（《肘后方》）\n伤寒时气，温病初得，头痛壮热，脉盛者︰用生 荷根、叶合捣，绞汁服三、四升。（《肘后方》）"},
  "蘩缕":{o:[],src:["本草纲目"],d:"旧二，新二。\n食治乌髭︰繁缕为齑，久久食之，能乌髭发。（《圣惠方》）。\n小便卒淋︰繁缕草满两手，水煮，常常饮之。（《范汪东阳方》）。\n产妇有块作痛︰繁缕方见上。\n丈夫阴疮，茎及头溃烂，痛不可忍，久不瘥者。以五月五日繁缕烧焦五分，入新出蚯蚓屎二分，入少水，和研作饼，贴之。干即易。禁酒、面、五辛及热食等物。\n甚效。（《扁鹊方》）"},
  "虎掌":{o:[],src:["本草纲目"],d:"旧八，新三十二。中风口噤目瞑，无门下药者︰开关散︰用天南星为末，入白龙脑等分，五月五日午时合之。每用中指点末，揩齿诸风口噤︰天南星（炮锉）大人三钱、小儿三字，生姜五片，苏叶一钱，水煎减半，入雄猪胆汁少许，温服。（《仁斋直指方》）\n纸裹斜包，剪一小孔，透气于口中，牙关自开也。一方︰用生南星，同姜汁擦之，自开。小儿惊风︰坠涎散︰用天南星（一两重）一个，（换酒浸七伏时，取出安新瓦上，周回炭火炙裂，合湿地出火毒，为末），入朱砂一分。每服半钱，荆芥汤调下。每日空心一服，午时一服。（《经验方》）\n吐泻慢惊︰天王散︰治小儿吐泻，或误服冷药，脾虚生风痰慢惊︰天南星（一个）重八九钱者，去脐。黄土坑深三寸，炭火五斤， 赤，入好酒半盏。安南星在内，仍架炭三条在上，候发裂取锉，再炒熟为末，用五钱。天麻（煨熟研末）一钱，麝香一字，和匀。三岁小儿用半钱，以生姜、防风煎汤调下。亦治久嗽恶心。（钱乙小儿方）\n风痫痰迷︰坠痰丸︰用天南星九蒸九晒，为末，姜汁面糊丸梧子大。每服二十丸，人参汤下。石菖蒲、麦门冬汤亦可。（《卫生宝鉴》）\n小儿痫喑，痫后喑不能言︰以天南星湿纸包煨，为末。雄猪胆汁调服二字。（《全幼心鉴》）\n治痫利痰︰天南星（煨香）一两，朱砂一钱，为末，猪心血丸梧子大。每防风汤化下一丸。（《普济方》）\n口眼 斜︰天南星生研末，自然姜汁调之，左贴右，右贴左。（《仁存方》）\n角弓反张︰南星、半夏等分，为末。姜汁、竹沥灌下一钱。仍灸印堂。（《摘玄方》）\n破伤中风︰胡氏夺命散，又名玉真散︰治打扑金刃伤，及破伤风伤湿，发病强直如痫状者︰天南星、防风等分，为末。水调敷疮，出水为妙。仍以温酒调服一钱。已死心尚温者，热童便调灌二钱。斗殴内伤坠压者，酒和童便连灌三服，即苏。亦可煎服。（《三因方》）\n破伤风疮︰生南星末，水调涂疮四围，水出有效。（《普济方》）\n妇人头风，攻目作痛︰天南星一个，掘地坑烧赤，安药于中，以醋一盏沃之，盖定勿令透气，候冷研末。每服一字，以酒调下。重者半钱。（《经验方》）\n风痰头痛，不可忍︰天南星一两，荆芥叶一两，为末，姜汁糊丸梧子大。每食后姜汤下二十丸。又上清丸︰用天南星、茴香等分，生研末，盐醋煮面糊丸。如上法服。（并出《经效济世方》）\n风痰头晕目眩，吐逆烦懑，饮食不下︰玉壶丸︰用生南星、生半夏各一两，天麻半两，白面三两。为末，水丸梧子大。每服三十丸，以水先煎沸，入药煮五七沸，漉出放温，以姜汤吞之。（《惠民和剂局方》）\n脑风流涕，邪风入脑，鼻内结硬，遂流髓涕︰大白南星切片，沸汤泡二次，焙干。每用二钱，枣七个，甘草五分，同煎服。三、四服，其硬物自出，脑气流转，髓涕自收。以大蒜、荜茇末作饼，隔纱贴卤前，熨斗熨之。或以香附、荜茇末频吹鼻中。（《直指方》）\n毒壅滞，凉心压惊︰抱龙丸︰用牛胆南星一两，入金钱薄荷十片，丹砂一钱半，龙脑、麝香各一字，研末，炼蜜丸芡子大。每服一丸，竹叶汤化下。（《全幼心鉴》）\n壮人风痰及中风，中气初起︰星香饮︰用南星四钱，木香一钱。水二盏，生姜十四片，煎六分，温服。（王硕《易简方》）\n痰迷心窍︰寿星丸︰治心胆被惊，神不守舍，或痰迷心窍，恍惚健忘，妄言妄见︰天南星一斤（先掘土坑一尺，以炭火三十斤烧赤，入酒五升，渗干。乃安南星在内，盆覆定，以灰塞之，勿令走气。次日取出为末）。琥珀一两，朱砂二两，为末。生姜汁打面糊丸梧子大。每服三十丸至五十丸，煎人参、石菖蒲汤下。一日三服。（《和剂局方》）\n风痰注痛︰方见羊踯躅下。痰湿臂痛，右边者︰南星制、苍术等分，生姜三片，水煎服之。（《摘玄方》）\n风痰咳嗽︰大天南星一枚，炮裂研末。每服一钱，水一盏，姜三片，煎五分，温服。每日早、午、晚各一服。（《十全博救》）\n气痰咳嗽︰玉粉丸︰南星曲、半夏曲、陈橘皮各一两，为末，自然姜汁打糊丸如梧子大。每服四十丸，姜汤下。寒痰，去橘皮，加官桂。（东垣《兰室秘藏》）\n清气化痰︰三仙丸︰治中脘气滞，痰涎烦闷，头目不清︰生南星（去皮）、半夏各五两（并汤泡七次，为末，自然姜汁和作饼，铺竹筛内，以楮叶包覆，待生黄成曲，晒干）。每用二两，入香附末一两，糊丸梧子大。每服四十丸，食后姜汤下。（王璆《百一选方》）\n温中散滞，消导饮食︰天南星（炮）、高良姜（炮）各一两，砂仁二钱半，为末，姜汁糊丸梧子大。每姜汤下五十丸。（《和剂方》）\n酒积酒毒，服此即解︰天南星丸︰用正端天南星一斤。土坑烧赤，沃酒一斗入坑，放南星，盆覆，泥固济，一夜取出，酒和水洗净，切片，焙干为末，入朱砂末一两，姜汁面糊丸梧子大。每服五十丸，姜汤下。蔡丞相、吕丞相尝用有验。（《杨氏家藏方》）\n吐泄不止︰《集效方》︰四肢厥逆，虚风不省人事。服此则阳回，名回阳散︰天南星为末，每服三钱，京枣三枚，水二钟，煎八分，温服。未省再服。又方︰醋调南星末，贴足心。（《普济方》）\n肠风泻血，诸药不效︰天南星（锻石炒焦黄色），为末，酒糊丸梧子大。每酒下二十丸。（《普济方》）\n以自然铜磨酒调下。（《胜金方》）\n初生贴囟︰头热鼻塞者。天南星炮为末，水调贴囟上，炙手熨之。（危氏《得效方》）\n小儿解颅，囟开不合，鼻塞不通︰天南星炮去皮，为末，淡醋调绯帛上，贴囟门，炙手频熨之，立效。（钱乙《小儿直诀》）\n解颐脱臼，不能收上︰用南星末，姜汁调涂两颊，一夜即上。（《医说》）\n小儿口疮，白屑如鹅口，不须服药︰以生天南星去皮脐，研末。醋调涂足心，男左女右。（走马疳蚀，透骨穿腮︰生南星一个，当心剜空，入雄黄一块，面裹烧，候雄黄作汁，以盏子合定，出火毒，去面为末，入麝香少许，拂疮数日，甚效。（《经验方》）\n风虫牙痛︰南星末塞孔，以霜梅 住，去涎。（《摘玄方》）\n喉风喉痹︰天南星一个，剜心，入白僵蚕七枚，纸包煨熟，研末。姜汁调服一钱，甚者灌之痰瘤结核︰南星膏︰治人皮肌头面上生瘤及结核，大者如拳，小者如栗，或软或硬，不疼不痒，宜用此药，不可辄用针灸︰生天南星大者一枚，研烂，滴好醋五七点。如无生者，以干者为末，醋调。先用针刺令气透，乃贴之。觉痒则频贴，取效。（严子礼《济生方》）\n身面疣子︰醋调南星末涂之。（《简易方》）"},
  "虎骨":{o:["虎骨"],src:["本草备要"],d:"宣，去风，健骨\n味辛微热。虎属金而制木，故啸则风生。追风健骨，定痛辟邪。治风痹拘挛疼痛，惊悸颠痫，犬咬骨哽（为末，水服，犬咬敷患处）。以头骨、胫骨良（虎虽死，犹立不仆，其气力皆在前胫。时珍曰∶凡辟邪疰，治惊痫，瘟疟、头风，当用头骨。治手足风，当用胫骨。治腰脊风，当用脊骨，各从其类也）。虎肚，治反胃（取生者，存滓秽勿洗，新瓦固 存性，为末。入平胃散一两，每服三钱，效。昂按∶虎肚丸宜于食膈，若寒膈、气膈、血膈、痰膈，恐难见功）。虎睛为散，竹沥下，治小儿惊痫夜啼。"},
  "虫白蜡":{o:[],src:["本草纲目"],d:"新一。\n头上秃疮︰蜡烛频涂，勿令日晒，久则自然生发。（《集玄方》）"},
  "虾":{o:["虾"],src:["本草备要"],d:"补阳\n甘温。托痘疮。下浮汁，吐风痰（中风症，以虾半斤，入姜、葱、酱料水煮，先吃虾，次吃汁，以鹅翎探引，吐出痰涎，随证用药），壮阳道。"},
  "蚕":{o:[],src:["本草纲目"],d:"旧十五，新十九。\n一切风痰︰白僵蚕七个（直者），细研，姜汁一茶脚，温水调灌之。（《胜金方》）\n小儿惊风︰白僵蚕、蝎梢等分，天雄尖、附子尖共一钱。微炮为末。每服一字，或半钱，以风痰喘嗽，夜不能卧︰白僵蚕（炒研）、好茶末各一两，为末。每用五钱，卧时泡沸汤服。（《瑞竹堂方》）\n酒后咳嗽︰白僵蚕焙研末，每茶服一钱。（《怪证奇方》）\n喉风喉痹︰《仁存》︰开关散︰用白僵蚕（炒）、白矾（半生半烧）等分，为末。每以一钱，用自然姜汁调灌，得吐顽痰，立效。小儿加薄荷、生姜少许，同调。一方用白梅肉和丸，绵裹含之，咽汁也。《朱氏集验》︰用白僵蚕立愈。《圣惠》︰用白僵蚕三七枚，乳香一分急喉风痹︰王氏《博济》如圣散︰用白僵蚕、天南星（刮皮）等分，生研为末。每服一字，姜汁调灌，涎出即愈。后以生姜炙过，含之，《百一选方》无南星。\n撮口噤风︰面黄赤，气喘，啼声不出。由胎气挟热，流毒心脾，故令舌强唇青，聚口发噤。用直僵蚕二枚去嘴，略炒为末。蜜调敷大头风、小儿惊风︰并用大蒜七个，先烧红地，以蒜逐个于地上磨成膏。却以僵蚕一两（去头、足）安蒜上，碗覆一夜，勿令泄气，只取蚕研末。每用 鼻，口内含水，有效。（《普济偏正头风并夹脑风，连两太阳穴痛︰《圣惠方》︰用白僵蚕为末，葱茶调服方寸匕。\n叶椿治头风︰用白僵蚕、高良姜等分，为末。每服一钱，临卧时茶服，日二服。\n猝然头痛︰白僵蚕为末去丝。每用熟水下二钱，立瘥。（《斗门方》）\n牙齿疼痛︰白僵蚕（直者）、生姜同炒赤黄色，去姜为末。以皂角水调擦之，即止。（《普济》）\n风虫牙痛︰白直僵蚕（炒）、蚕蜕纸（烧）等分。为末。擦之。良久，以盐汤漱口。（《直指方》）\n疟疾不止︰白僵蚕（直者）一个。切作七段，绵裹为丸，朱砂为衣，作一服。日未出时，面向东，用桃、李枝七寸煎汤，吞下。（《院方》）\n腹内龟病︰《普济方》诗云︰人间龟病不堪言，肚里生成硬似砖。自死僵不过时刻软如绵。神效。\n面上黑黯︰白僵蚕末，水和搽之。（《圣惠方》）\n粉滓面 ︰令人面色好，用白僵蚕、黑牵牛、细辛等分，为末。如澡豆，日用之。（《斗门方》）\n瘾疹风疮︰疼痛。白僵蚕焙研，酒服一钱，立瘥。（《圣惠》）\n野火丹毒从背上两胁起者︰僵蚕二七枚，和慎火草捣涂。（杨氏《产乳》）\n小儿鳞体︰皮肤如蛇皮鳞甲之状，由气血否涩，亦曰胎垢，又曰蛇体。白僵蚕，去嘴，为末，煎汤浴之。一加蛇蜕。（《保幼大全》）\n小儿久疳体虚不食︰诸病后，天柱骨倒，医者不识，谓之五软者。用白僵蚕（直者），炒研。每服半钱，薄荷酒下。名金灵散。（《郑氏方》）\n小儿口疮通白者︰白僵蚕，炒黄。拭去黄肉、毛，研末，蜜和敷之，立效。（《小儿宫气方》）\n风疳蚀疮︰同上方。\n项上瘰疬︰白僵蚕为末。水服五分，日三服。十日瘥。（《外台》）\n风痔肿痛︰发、歇不定者，是也。白僵蚕二两。洗锉，炒黄为末，乌梅肉和丸梧桐子大。\n每姜蜜汤空心下五丸，妙。（《胜金方》）\n一切金疮及刀斧伤︰白僵蚕炒黄研末，敷之立愈。（《斗门》）\n乳汁不通︰白僵蚕末二钱，酒服。少顷，以脂麻茶一盏热投之，梳头数十遍，奶汁如泉也。（《经验后方》）\n崩中下血不止︰用白僵蚕、衣中白鱼等分。为末。井华水服之，日二。（《千金》）\n重舌木舌︰僵蚕，为末，吹之，吐痰甚妙。一方︰僵蚕一钱，黄连（蜜炒）二钱，为末。\n掺之，涎出为妙。（陆氏《积德方》）\n肠风下血︰僵蚕（炒，去嘴、足）、乌梅肉（焙）各一两，为末，米糊丸梧子大。每服"},
  "蚕茧（含蚕蜕、蚕连）":{o:[],src:["本草纲目"],d:"新五。\n痘疮疳蚀脓水不绝︰用出了蚕蛾茧，以生白矾末填满。 枯为末，擦之甚效。（陈文中《小儿方》）\n口舌生疮︰蚕茧五个，包硼砂，瓦上焙焦为末，抹之。\n大小便血︰茧黄散︰治肠风，大小便血，淋沥疼痛。用茧黄、蚕蜕纸（并烧存性）、晚蚕砂、白僵蚕（并炒）等分为末，入麝香少许。每服二钱，用米饮惠方》）\n妇人血崩︰方法同上。\n反胃吐食︰蚕茧十个煮汁，烹鸡子三枚食之，以无灰酒下，日二服，神效。或以缲丝汤煮粟米粥食之。（《普济方》）\n蚕蜕\n\n旧四，新十五。\n吐血不止︰蚕蜕纸烧存性，蜜和，丸如芡实大。含化咽津。（《集验》）\n牙宣牙痈及口疮︰并用蚕蜕纸烧灰，干敷之。（《集验》）\n风虫牙痛︰蚕纸烧灰擦之。良久，盐汤漱口。（《直指方》）\n走马牙疳︰《集验》︰用蚕蜕纸灰，入麝香少许，贴之。《直指》︰加白僵蚕等分。\n一切疳疮︰马明蜕（烧灰）三钱，轻粉、乳香少许。先以温浆水洗净，敷之。（《儒门事亲》）\n小儿头疮︰蚕蜕纸烧存性，入轻粉少许，麻油调敷。（《圣惠》）\n缠喉风疾︰用蚕蜕纸烧存性，炼蜜和，丸如芡实大。含化咽津。（《集验》）\n熏耳治聋︰蚕蜕纸作捻，入麝香二钱，入笔筒烧烟熏之。三次即开。\n癫狂邪祟︰凡狂发欲走，或自高贵称神，或悲泣呻吟，此为邪祟。以蚕纸烧灰，酒、水任下方寸匕。亦治风癫。（《肘后方》）\n沙证壮热︰江南有沙证，状如伤寒，头痛壮热呕恶，手足指末微厥。或腹痛闷乱，须臾杀人。先用蚕蜕纸剪碎，安于瓶中，以碟盖之，滚汤沃之，封固良久。乘热服，暖卧取汗。（《活人书》）\n中蛊药毒︰虽面青脉绝，腹胀吐血者，服之即活。用蚕蜕纸烧存性，为末。新汲水服一钱。（《岭南卫生方》）\n中诸药毒︰用蚕纸数张，烧灰，冷水服。（《卫生易简方》）\n小便涩痛不通︰用蚕蜕纸，烧存性，入麝香少许，米饮每服二钱。（王氏《博济方》）\n热淋如血︰蚕种烧灰，入麝香少许，水服二钱，极效方也。（《卫生家宝》）\n崩中不止︰蚕故纸一张（剪碎炒焦）、槐子（炒黄）各等分，为末。酒服立愈。（《卫生易简方》）\n吹奶疼痛︰马明蜕（烧灰）一钱五分，轻粉五分，麝香少许。酒服。（《儒门事亲》）\n妇人难产︰蚕布袋一张，蛇蜕一条。入新瓦中，以盐泥固， 为末，以榆白皮（《集成》）\n妇人断产︰蚕子故纸一尺，烧为末，酒服。终身不产。（《千金》）\n痔漏下血︰蚕纸半张，碗内烧灰，酒服自除。（《奚囊备急方》）\n缫丝汤"},
  "蚤休":{o:[],src:["本草纲目"],d:"新五服食法︰紫河车根以竹刀刮去皮，切作骰子大块，面裹入瓷瓶中，水煮候浮漉出，凝冷入新布袋中，悬风处待干。每服三丸，五更初面东念咒，井水下。连进三服，即能休粮。若要饮食，先以黑豆煎汤饮之。次以药丸煮稀粥，渐渐食之。咒曰︰天朗气清金鸡鸣，吾今服药欲长生。吾今不饥复不渴，赖得神仙草有灵。小儿胎风，手足搐搦︰用蚤休（即紫河车）为末。每服半钱，冷水下。（《卫生易简方》）\n慢惊发搐，带有阳证者︰白甘遂末（即蚤休）一钱，栝蒌根末二钱，同于慢火上炒焦黄，研匀。每服一字，煎麝香薄荷汤调下。（钱乙《小儿》方）\n中鼠莽毒︰金线重楼根，磨水服，即愈。（《集简方》）\n咽喉谷贼肿痛︰用重台（赤色者）、川大黄（炒）、木鳖子仁、马牙硝各半两，半夏（泡）一分，"},
  "蚯蚓":{o:[],src:["本草纲目"],d:"旧九，新三十四。\n伤寒热结︰六、七日狂乱，见鬼欲走。以大蚓半斤去泥，用人溺煮汁饮。或生绞汁亦可。（《肘后方》）。阳毒结胸︰按之极痛，或通而复结，喘促，大躁狂乱。取生地龙四条，洗净，研如泥，入生姜汁少许，蜜一匙，薄荷汁少许，新汲水调服。若热炽者，加片脑少许。即与揉心下，片时自然汗出而解。不应，再服一次，神效。（《伤寒蕴要》）\n诸疟烦热太躁︰用上方服之，甚效。亦治瘴疟。（《直指》）\n小便不通︰蚯蚓，捣烂，浸水。滤取浓汁半碗服，立通。（《斗门》）\n老人尿闭︰白颈蚯蚓、茴香等分，杵汁，饮之即愈。（《朱氏集验方》）\n小儿尿闭︰乃热结也。用大地龙数条去泥，入蜜少许，研敷茎卵。仍烧蚕蜕纸、朱砂、龙脑、麝香同研少许，以麦门冬、灯心煎汤调服。（《全幼》）。小儿急惊︰五福丸︰用生蚯蚓一条，研烂，入五福化毒丹一丸，同研，以薄荷汤少许化下。《普济方》云︰梁国材言︰扬州进士李彦直家，专货此药，一服千金，以糊十口。梁传其方，亲试屡验，不可不笔于册，以救婴儿。\n惊风闷乱︰乳香丸︰治小儿慢惊风，心神闷乱，烦懊不安，筋脉拘急，胃虚虫动，反折啼叫。用乳香半钱，胡粉一钱，研匀，以白颈蚯蚓（生，捏去土），捣烂和，丸麻子大。每服七丸至十五丸，葱白煎汤下。（《普济方》）\n慢惊虚风︰用平正附子去皮脐，生研为末，以白颈蚯蚓于末内滚之，候定，刮蚓上附末，丸黄米大。每服十丸，米饮下。（《百一方》）。\n急慢惊风︰五月五日取蚯蚓，竹刀截作两段，急跳者作一处，慢跳者作一处，各研烂，入朱砂末和作丸，记明急惊用急跳者，慢惊用慢跳者。每服五七丸，薄荷汤下。（《小儿卵肿︰用地龙，连土为末，津调敷之。（钱氏方）。劳复卵肿或缩入腹︰腹中绞痛，身体重，头不能举。小腹里急，热上冲胸四支拘急欲死。用蚯蚓二十四枚，水一斗，煮取三升，顿服取汗。或以蚯蚓数升绞汁服之，并良。（《肘后方》）\n手足肿痛欲断︰取蚓三升，以水五升，绞汁二升半，服之。（《肘后》）。\n代指疼痛︰蚯蚓杵，敷之。（《圣惠》）\n风热头痛︰地龙（炒研）、姜汁、半夏饼、赤茯苓等分。为末。每服一字至半钱，生姜、荆芥汤下。（《普济》）\n头风疼痛︰龙珠丸︰用五月五日取蚯蚓，和脑、麝杵，丸麻子大。每以一丸纳鼻中，随左右。先涂姜汁在鼻，立愈。（《总录》）\n偏正头痛不可忍者︰《普济》龙香散︰用地龙（去土，焙）、乳香等分。为末。每以一字作纸捻，灯上烧烟，以鼻嗅之。《澹寮方》︰加人指甲等分，云徐介翁方也。每用一捻，香炉内慢火烧之，以纸筒引烟入鼻熏之。口噙冷风赤眼痛︰地龙十条，炙为末，茶服三钱。（《圣惠》）\n风虫牙痛︰盐化地龙水，和面纳齿上，又以皂荚，去皮，研末涂上，虫即出。又同玄胡索、荜茇末塞耳。（《普济》）\n牙齿裂痛︰死曲 ，为末，敷之即止。（《千金翼》）\n齿缝出血不止︰用地龙末、枯矾各一钱，麝香少许，研匀擦之。（《圣惠方》）\n牙齿动摇及外物伤动欲落，诸药不效者︰干地龙（炒）、五倍子（炒）等分为末。先以生姜揩牙，后敷擦之。（《御药院方》）\n木舌肿满，不治杀人︰蚯蚓一条，以盐化水涂之，良久渐消。（《普济方》）\n咽喉卒肿不下食︰地龙十四条，捣涂喉外。又以一条，著盐化水，入蜜少许，服之。（《圣惠方》）\n喉痹塞口︰《普济》︰用韭地红小蚯蚓数条，醋擂取汁食之，并噙在喉内，即吐出痰血二、三碗，饮食即进，神效。《圣惠》鼻中息肉︰地龙（炒）一分，牙皂一挺，为末。蜜调涂之，清水滴尽即除。（《圣惠》）\n耳卒聋闭︰蚯蚓入盐，安葱内，化水点之，立效。（《胜金》）\n耳出脓︰生地龙、釜上墨、生猪脂等分。研匀，葱汁和，捻作挺子，绵裹塞之。《圣惠方》︰用地龙为末，吹之。耳中耵聍干结不出︰用白蚯蚓，入葱叶中化为水，滴耳令满。\n不过数度，即易挑出。\n蚰蜒入耳︰地龙，为末，入葱叶内，化水点入，则蚰蜒亦化为水。（《圣惠方白秃头疮︰干地龙为末，入轻粉，麻油调搽。（《普济方》）\n瘰疬溃烂流串者︰用荆芥根下段，煎汤温洗，良久，著疮破紫黑处，以针刺去血，再洗三、四次。用韭菜地上蚯蚓一把，五更时收取，炭火上烧红，为末。每一匙，入乳香、没轻粉各半钱，穿山甲九片，炙为末，油调敷之，如神。此武进朱守仁所传有验方。（《保命集》）\n龙缠疮毒︰水缸底蚯蚓一条，连泥捣敷，即愈。\n蜘蛛咬疮遍身皆有︰以葱一枚，去尖头，将蚯蚓入叶中，紧捏两头，勿令泄气，频摇动，即化为水，以点咬处，甚效。（《谭氏小儿方》）\n阳证脱肛︰以荆芥、生姜煎汤洗之；用地龙（蟠如钱样者，去土）一两，朴硝二钱，为末，油调敷之。（《全幼心鉴》）\n中蛊下血如烂肝者︰以蚯蚓十四枚，苦酒三升渍至蚓死，服水。已死者皆可活。（《肘后方》）\n疠风痛痒︰白颈蚯蚓，去土，以枣肉同捣，丸梧子大。每美酒下六十丸。忌姜、蒜。（《活人心统》）\n对口毒疮，已溃出脓，取韭地蚯蚓，捣细，凉水调敷，日换三、四次。（《扶寿精方》）\n耳聋气闭︰蚯蚓、川芎 各两半，为末。每服二钱，麦门冬汤下。服后低头伏睡。一夜一服，三夜立效。（《圣济总录》）\n口舌糜疮︰地龙、吴茱萸，研末，醋调生面和，涂足心，立效。（《摘玄方》）\n蚯蚓泥见土部。"},
  "蚱蝉":{o:[],src:["本草纲目"],d:"新三。\n百日发惊︰蚱蝉（去翅、足，炙）三分，赤芍药三分，黄芩二分，水二盏，煎一盏，温服。（《圣惠方》）。\n破伤风病无问表里，角弓反张︰秋蝉一个，地肤子（炒）八分，麝香少许，为末。酒服二钱。（同上）头风疼痛︰蚱蝉二枚生研，入乳香、朱砂各半分，丸小豆大。每用一丸，随左右纳鼻中，出黄水为效。（《圣济总录》）"},
  "蚺蛇":{o:[],src:["本草纲目"],d:"旧二，新二。\n小儿急疳疮︰水调蚺蛇胆，敷之。（《圣惠》）\n小儿疳痢︰羸瘦多睡，坐则闭目，食不下。用蚺蛇胆豆许二枚，煮通草汁研化，随意饮之。\n仁四十七枚，研匀。以布揩龈，嗍令血尽。日三掺之，愈乃止。（《圣惠》）\n蛇胆研，香油调涂，立效。（《医方摘要》）\n肉\n\n新三。\n蚺蛇酒︰治诸风瘫痪，筋挛骨痛，痹木瘙痒，杀虫辟瘴，及疠风疥癣恶疮。用蚺蛇肉一斤，羌活一两，绢袋盛之，用糯米二斗蒸熟，安曲于缸底，置蛇于曲上，乃下饭密盖，待熟取酒。以蛇焙研和药。其酒每随量温饮数杯。忌风及欲事。亦可袋盛浸酒饮。（《集简方》）\n急疳蚀烂︰蚺蛇肉作脍食之。（《圣惠方》）\n蛇，他蛇亦可。（《外台秘要》）\n子也。"},
  "蚺蛇胆":{o:["蚺蛇胆"],src:["本草备要"],d:"泻热、明目、护心\n蚺（音髯）禀己土之气，胆属甲乙风木，气寒有小毒，其味苦而带甘。凉血明目，疗疳杀虫，主厥阴、太阴（肝木、脾土）之病。肉，极腴美，主治略同。取胆粟许，置水上，旋行极速者真（胆上旬近头，中旬近心，下旬近尾。能护心止痛，受杖时噙之，杖多不死）。"},
  "蛆":{o:[],src:["本草纲目"],d:"新十。\n一切疳疾︰《圣济总录》︰六月取粪坑中蛆淘净，入竹筒中封之，待干研末。每服一、二钱，入麝香，米饮服之。又方︰用蛆分，以 猪胆汁和丸黍米大。每服三四十丸，米饮下，神效。\n小儿热疳︰尿如米泔，大便不调。粪蛆，烧灰，杂物与食之。\n小儿痹积︰用粪中蛆，洗浸，晒干为末，入甘草末少许，米糊丸梧子大。每服五、七丸，米饮下，甚妙。（《总微论》）\n小儿诸疳，疳积及无辜疳︰一服退热，二服烦渴止，三服泻痢住。用端午午时取蛤蟆（金眼大腹，不跳不鸣者），槌死，置尿桶新瓦焙干，入麝香少许，为末。每空心，三十丸。（《直指》）\n齿鼻疳疮︰粪蛆（有尾者）烧灰一钱，褐衣灰五分。和匀，频吹，神效无比。\n热痢吐食︰眼目赤瞎︰青泥中蛆，淘净，日干为末。令患人仰卧合目，每次用一钱，散目上臾药行，待少时去药，赤瞎亦无。（《保命集》）\n利骨取牙︰《普济》如神散︰取牙，用肥赤马肉一斤，入 砂二两，拌和，候生蛆，取日干为末。每一两入粉霜\n利骨散︰用白马脑上肉一二斤，待生蛆，与乌骨白鸡一只食之，取粪阴干。每一钱，入砂一钱研匀，用少许擦疼处，片时取之即落。"},
  "蛇含":{o:[],src:["本草纲目"],d:"旧三，新一。\n产后泻痢︰小龙牙根一握，浓煎服之甚效，即蛇含是也。（《斗门方》）\n金疮出血︰蛇含草捣敷之。（《肘后方》）\n身面恶癣︰紫背草，入生矾研。敷二、三次断根。（《直指方》）\n蜈蚣蝎伤︰蛇衔， 敷之。（《古今录验》）"},
  "蛇床":{o:[],src:["本草纲目"],d:"旧四，新十二。\n阳事不起︰蛇床子、五味子、菟丝子等分，为末，蜜丸梧子大。每服三十丸，温酒下，日三服。（《千金方》）\n赤白带下，月水不来。用蛇床子、枯白矾等分，为末，醋面糊丸弹子大，胭脂为衣，绵裹纳入阴户。如热极，再换，日一次。（《儒门事亲方》）\n子宫寒冷，温阴中坐药。蛇床子散︰取蛇床子仁为末，入粉少许，和匀如枣大，绵裹纳之，自然温也。（《金匮玉函方》）\n妇人阴痒︰蛇床子一两，白矾二钱。煎汤频洗。（《集简方》）\n产后阴脱︰绢盛蛇床子，蒸热熨之。又法︰蛇床子五两，乌梅十四个。煎水，日洗五六次。（《经验方》）\n妇人阴痛︰方同上。（《经验方》）\n大肠脱肛︰蛇床子、甘草各一两，为末。每服一钱，白汤下，日三服。并以蛇床末敷之。（《经验方》）\n小儿癣疮︰蛇床子杵末，和猪脂涂之。（《千金方》）\n小儿甜疮，头面耳边连引，流水极痒，久久不愈者。蛇床子一两，轻粉三钱。为细末，油调搽之。（《普济方》）\n耳内湿疮︰蛇床子、黄连各一钱，轻粉一字。为末吹之。（《全幼心鉴》）\n风虫牙痛︰用蛇床子、烛烬。同研，涂之。（《千金方》）用蛇床子煎汤，乘热漱数次，立止。（《集简方》）\n冬月喉痹肿痛，不可下药者。蛇床子烧烟于瓶中，口含瓶嘴吸烟，其痰自出。（《圣惠方》）"},
  "蛇蜕":{o:["蛇蜕"],src:["本草备要", "本草纲目"],d:"轻，宣，去风毒\n甘咸无毒（甄权∶有毒）。性灵而能辟恶，故治鬼魅蛊毒；性窜而善去风，故治惊痫风疟，重舌（《圣惠方》∶烧末敷）喉风；性毒而能杀虫，故治疥癣恶疮，疔肿痔漏；属皮而性善蜕，故治皮肤疮疡，产难目翳。用白色如银者，皂荚水洗净。或酒、或醋、或蜜浸，炙黄用，或烧存性，或盐泥固 ，各随本方。"},
  "蛇黄":{o:[],src:["本草纲目"],d:"新六。\n暗风痫疾︰忽然仆地，不知人事，良久方醒。蛇黄，火 醋淬七次，为末。每调酒服二钱，数服愈。年深者亦效。（危氏《得效方》）\n惊风痫疳︰神穴丹︰治急惊风、痫疾、天吊、疳热等证。用紫色蛇黄四两（ 过），猪屎二两（小者泥固 过），铁粉一两，朱砂半两，麝香一钱。为末，糯粉糊丸芡子大，漆盘晒干。看之每丸有一小穴，故名神穴丹。每服一丸，薄荷酒化下，立苏。疳热，冷水化下。（《灵苑方》）\n小儿项软因风虚者︰蛇含石一块（ 七次，醋淬七次研），郁金等分。为末，入麝香少许，白米饭丸龙眼大。每服一丸，薄荷汤化服，一日一服。（《活幼全书》）\n瘴疟鬼疟食疟。蛇含石末一两，信石（末）一两。研匀，入水火鼎内，上以盏盖，六一泥固济， 至药升在盏，刮下为末，米糕糊丸绿豆大，雄黄为衣。每服一丸，黑豆研水，五更送下。（《摘玄方》）\n血痢不止︰蛇含石二枚。火 醋淬，研末。每服三钱，米饮下。（《普济方》）\n肠风下血脱肛︰蛇黄二颗。火 醋淬七次，为末。每服三钱，陈米饮下。（《普济方》）"},
  "蛔虫":{o:[],src:["本草纲目"],d:"新三。\n玉箸煎︰治小儿胎赤眼、风赤眼。用小儿吐出蛔虫二条，瓷盒盛之，纸封埋湿地，五日取出，化为水，瓷瓶收。每日以铜干为末），腻粉一钱，石胆半钱，为蛔虫，烧灰。先以甘草汤洗净，涂之，无不瘥者。慎口味。（《千金方》）"},
  "蛙":{o:[],src:["本草纲目"],d:"新六。\n蛤馔︰治水肿。用活蛙三个，每个口内安铜钱一个，上著胡黄连末少许。以雄猪肚一个，茶油洗净，包蛙扎定，煮一宿，取出，去皮、肠，食肉并猪肚，以酒送下。忌酸、咸、鱼、面、鸡、鹅、羊肉，宜食猪、鸭。（《寿域神方》）\n水蛊腹大︰动摇有水声，皮肤黑色。用干青蛙二枚（以酥炒），干蝼蛄七枚（炒），苦壶芦半两（炒）。上为末。每空心温酒服二钱，不过三服。（《圣惠\n毒痢噤口︰水蛙一个，并肠肚捣碎，瓦烘热，入麝香五分，作饼，贴脐上，气通即能进食也。\n诸痔疼痛︰青蛙丸︰用青色蛙长脚者一个，烧存性，为末，雪糕和，丸如梧子大。每空心先吃饭二匙，次以枳壳汤下十五丸。（《直指方》）。\n虫蚀肛门，虫蚀肾腑，肛尽肠穿︰用青蛙一枚，鸡骨一分，烧灰吹入，数用大效。（《外台》）\n癌疮如眼︰上高下深，颗颗累垂，裂如瞽眼，其中带青，头上各露一舌，毒孔透里者，是也。用生井蛙皮，烧存性为末掺，或蜜水调敷之。（《"},
  "蛞蝓":{o:[],src:["本草纲目"],d:"新一。\n脚胫烂疮︰臭秽不可近。用蜒蚰十条，瓦焙研末，油调敷之，立效。（《救急方》）"},
  "蛤粉":{o:["蛤粉"],src:["本草备要"],d:"涩\n蛤蜊壳 为粉。与牡蛎同功（海藏曰∶肾经血分药。宋徽宗宠妃病痰嗽，面肿不寐，李防御治之，三日不效，当诛，李技穷忧泣，忽闻市人卖嗽药，一文一帖，吃了今夜得睡，色淡碧，李市之。恐药猛悍，先自试，觉无害，共并三帖为一以进，妃服之，是夕寝安嗽止，面肿亦消。帝大悦，赐直万金。李不知其方，惧得罪。伺得市人，重价求之，乃蚌壳研粉，少加青黛也。以淡荠水，加麻油数滴，调服。《圣惠方》∶白蚬壳研粉，米饮调，治咳嗽不止）。肉，咸冷，止渴解酒（牡蛎、蛤蜊、海蛤、文蛤，并出海中，大抵海物咸寒，功用略同。江湖蛤蚌，无咸水浸渍，但能清热利湿，不能软坚）。文蛤。背有花纹，兼能除烦渴，利小便。"},
  "蛤蟆":{o:[],src:["本草纲目"],d:"旧三，新三。\n风邪为病︰蛤蟆（烧灰）、朱砂等分，为末。每服一钱，水调下，日三四服，甚有神验。（《圣惠方》）。\n狂言鬼语猝死︰用蛤蟆烧末，酒服方寸匕，日三。（《外台秘要》）。\n噎膈吐食︰用蛇含蛤蟆，泥包， 存性，研末。每服一钱，酒下。（《寿域方》）\n瘰疬溃烂︰用黑色蛤蟆一枚，去肠焙研，油调敷之。忌铁器。\n头上软疖︰蛤蟆，剥皮，贴之，收毒即愈。（《活幼全书》）\n蝮蛇螫伤︰生蛤蟆一枚，捣烂敷之。（《圣惠方》）\n肝"},
  "蛴螬":{o:[],src:["本草纲目"],d:"旧五，新四。\n小儿脐疮︰蛴螬研末敷之，不过数次。（《千金方》）\n小儿唇紧︰蛴螬研末，猪脂和，敷之。（《千金方》）\n赤白口疮︰蛴螬研汁，频搽取效。（《政和本草》）\n丹毒浸淫︰走串皮中，名火丹。以蛴螬捣烂，涂之。（《删繁方》）\n痈疽痔漏︰蛴螬研末，敷之，日一上。（《子母秘录》）\n虎伤人疮︰蛴螬捣烂，涂之，日上。（唐瑶《经验方》）\n竹木入肉︰蛴螬捣涂之，立出。（《肘后》）\n麦芒入眼︰以新布覆目上，持生蛴螬从布上摩之，芒著布上出也。（《千金方》）\n断酒不饮︰蛴螬研末，酒服，永不饮。（《千金方》）"},
  "蜀羊泉":{o:[],src:["本草纲目"],d:"新一。\n黄胆疾︰漆草一把，捣汁和酒服。不过三、五次，即愈。（《摘玄方》）。"},
  "蜀葵":{o:[],src:["本草纲目"],d:"</span>新七。\n小便淋痛︰葵花根洗锉，水煎五七沸，服之如神。（《卫生宝鉴》）\n小便血淋︰葵花根二钱，车前子一钱，水煮，日服之。（《简便单方》）\n小便尿血︰葵茎，无灰酒服方寸匕，日三。（《千金》）\n肠胃生痈︰怀忠丹︰治内痈有败血，腥秽殊甚，脐腹冷痛，用此排脓下血︰单叶红蜀葵根、白芷各一两，白枯矾、白芍药各五钱。为末，黄蜡溶化，和丸梧子大，每空心米饮下二十丸。待脓血出尽，服十宣散补之。（《坦仙皆效方》）\n不可忍者︰葵花根（去黑皮），捣烂，入井华水调稠贴之。（《普济方》）。\n小儿吻疮，经年欲腐︰葵根烧研敷之。（《圣惠方》）\n小儿口疮︰赤葵茎（炙干）为末，蜜和含之。（《圣惠方》）\n吴葵华（《别录》）\n\n旧三，新四。\n二、三日则杀人︰蜀葵花一两（捣烂），麝香半钱。水一大盏，煎服。根亦可用。疟邪热︰蜀葵花白者，阴干为末，服之。午日取花 手，亦能去疟。（苏颂《图经本草》）\n妇人带下，脐腹冷痛，面色痿黄，日渐虚困︰用葵花一两，阴干为末，每空心温酒服二钱匕。赤带用赤葵，白带用白葵。（《圣惠方》）\n横生倒产︰葵花为末，酒服方寸匕。（《千金方》）\n酒渣赤鼻︰蜀葵花研末，腊猪脂和匀，夜敷旦洗。（《仁存方》）\n误吞针钱︰葵花煮汁服之。（《普济方》）\n蜂蝎螫毒︰五月五日午时，收蜀葵花、石榴花、艾心等分，阴干为末，水调涂之。（《肘后\n子\n\n旧一，新二。\n大小便闭不通者︰用白花胡葵子为末，煮浓汁服之。（《千金方》）\n石淋破血︰五月五日，收葵子炒研，食前温酒下一钱，当下石出。（《圣惠方》）\n痈肿无头︰蜀葵子为末，水调敷之。（《经验后方》）"},
  "蜗牛":{o:[],src:["本草纲目"],d:"旧三，新二十。\n小便不通︰蜗牛，捣贴脐下，以手摩之。加麝香少许更妙。（《简易》）\n大肠脱肛︰《圣惠》︰治大肠久积虚冷，每因大便脱肛。用蜗牛一两，烧灰，猪脂和敷，立缩。又治上证及痢后脱肛。用干蜗水一盏，煎半盏调服。日三。\n蜗牛一枚，盏，汤瓶中封一夜，取涎水，入真蛤粉旋调，扫敷疮上。日十余度，热痛止则疮便愈。（《集验方》）\n瘰疬未溃︰连壳蜗牛七个，丁香七粒，同烧研，纸花贴之。（危氏）瘰疬已溃︰蜗牛烧研，轻粉少许，用猪脊髓调，敷之。（危氏方）。喉痹肿塞︰用蜗牛绵裹，水浸含咽，须臾立通。又用蜗牛七枚，白梅肉三枚，研烂。绵裹含咽，立效。（《圣惠方》）\n喉风肿痛︰端午日午时，取蜒蚰十余条，同盐三、四个，小瓶内封固，俟化成水，收水点之。（唐氏）喉塞口噤︰蜒蚰（炙）二七枚，白梅肉（炒）二七枚，白矾（半生半烧）二钱。研为末。每水调半钱服，得吐立通。（《圣济总录》）\n耳腮 肿及喉下诸肿︰用蜗牛同面研，敷之。面上毒疮初起者︰急寻水蜒蚰一、二条，用酱少许共捣，涂纸上贴之，即退。纸上留一小孔出气。此乃凌汉章秘传极效方也。（谈野翁《试验方》）。赤白翳膜︰生蜗牛一枚，捣丹砂末于内，火上炙沸，以绵染汁敷 中，日二。（《圣惠方》）\n鼻血不止︰蜗牛（爆干）一枚，乌贼骨半钱，研末吹之。（《圣济总录》）\n撮口脐风︰乃胎热也。用蜗牛五枚去壳，研汁涂口，取效乃止。又方︰用蜗牛十枚，（去壳，研烂），入莳萝末半分，研匀，涂之，取效，甚良。滴耳聋闭︰蜗牛膏︰用蜗牛一两，石胆、钟乳粉各二钱半。为末，瓷盒盛之，火 赤，研末，入片脑一字。每以油调一字，滴入耳中。无不愈者。（并《圣惠方》）\n蚰蜒入耳︰蜗牛椎烂，置于耳边，即出也。（《瑞竹堂方》）\n染须方︰用蜒蚰四十九条，以京墨水养之三日，埋马屎中一月，取出，以白丝头试之，如即黑到尾，再入马屎中埋七日，再取试之，性缓乃以捻须，庶不致黑皮肤也。（《普济方》）\n消渴引饮不止︰崔元亮《海上方》︰用蜗牛十四枚（形圆而大者），以水三合，密器浸一宿。取水饮之，不过三剂愈。《圣济总录》︰用蜗牛（焙）半两，蛤粉、龙胆草、桑根白\n蜗壳\n\n旧二，新一。\n一切疳疾︰用自死蜗壳七枚（皮薄，色黄白者）洗净，不得少有尘滓，日干，内酥蜜于壳中。\n以瓷盏盛之，纸糊盏面，置炊饭上蒸之。下 时，即坐甑中，仍装饭又蒸，饭熟取出，研如水淀。渐渐与吃，一日令尽，取效止。（韦丹方）\n之，良。（《圣惠》）"},
  "蜘蛛":{o:[],src:["本草纲目"],d:"旧七，新十五。\n中风口 ︰向火取蜘蛛摩偏急颊车上，候正即止。（《千金方》）\n小儿口噤︰《直指》立圣散︰用干蜘蛛一枚（去足，竹沥浸一宿，炙焦），蝎梢七个，腻粉少许。为末。每用一字，乳汁调，时时灌入口中。《圣惠方》︰治小儿十日内，口噤不能吮乳。蜘蛛一枚，去足，炙焦研末。入猪乳一合，和匀。分作三服，徐徐灌之，神效无比。\n止截疟疾︰葛洪方︰用蜘蛛一枚，同饭捣丸，吞之。《杨氏家藏》︰用蜘蛛一枚，著芦管中，密塞，绾项上。勿令患人知之。《海上》︰用蜘蛛三五枚，绵包，系寸口上。《宣明方大蜘蛛三枚，信砒一钱，雄黑豆四十九粒，为末，滴水为丸豌豆大。先夜以一丸献于次早纸裹插耳内，立见神圣。一丸可医二人。\n泄痢脱肛︰疼痛已久者，黑圣散主之。大蜘蛛一个，瓠叶两重包扎定，合子内烧存性，入黄丹少许，为末。先以白矾、葱、椒煎汤洗，拭干，以前药末置软帛上，托入收之，甚是有效也。（《乘闲方》）\n走马牙疳，出血作臭︰用蜘蛛一枚，铜绿半钱，麝香少许，杵匀擦之。无蛛用壳。（《直指》）\n齿 断烂︰用大蜘蛛一个，以湿纸重裹，荷叶包之，灰火煨焦为末，入（《永类钤方》）\n耳出脓︰蜘蛛一个，胭脂坯子半钱，麝香一字，为末。用鹅翎吹之。\n吹奶疼痛︰蜘蛛一枚，面裹烧存性，为末。酒服即止，神效。\n颏下结核︰大蜘蛛不计多少，好酒浸过，同研烂，澄去滓。临卧时服之，最效。（《医林集要》）\n瘰疬结核，无问有头、无头。用大蜘蛛五枚，日干，去足细研，酥调涂之，日再上。（《圣惠方》）\n鼠 肿核已破出脓水者︰蜘蛛二七枚，烧研，敷之。（《千金方》）\n便毒初起︰大黑蜘蛛一枚，研烂，热酒一碗，搅服，随左右侧卧取利。不退再服，必效。（疔肿拔根︰取户边蜘蛛，杵烂，醋和，先挑四畔血出，根稍露，敷之，干即易。一日夜根拔出，大有神效。（《千金方》）\n腋下狐臭︰大蜘蛛一枚，以黄泥入少赤石脂末，及盐少许，和匀裹蛛， 之为末，入轻粉一字，醋调成膏。临卧敷腋下，明早登厕，必泄下黑汁也。（《三因方》）\n蜂蝎螫伤︰蜘蛛研汁涂之，并以生者安咬处吸其毒。（《广利方》）\n蜈蚣咬伤︰同上（《孙真人》）。\n蛇虺咬伤︰蜘蛛捣烂敷之，甚效。\n一切恶疮︰蜘蛛晒，研末，入轻粉，麻油涂之。（《直指方》）\n蜕壳\n\n旧一，新一。\n虫牙有孔︰蜘蛛壳一枚，绵裹塞之。（《备急》）\n牙疳出血︰蜘蛛壳，为末，入胭脂、麝香少许，敷之。（《直指方》）\n网\n\n新四。\n积年诸疮︰蜘蛛膜贴之，数易。（《千金方》）\n反花疮疾︰同上。\n肛门鼠痔︰蜘蛛丝，缠之，即落。\n疣瘤初起︰柳树上花蜘蛛丝缠之，久则自消。（《简便方》）"},
  "蜚虻":{o:[],src:["本草纲目"],d:"旧二，新一。\n蛇螫血出，九窍皆有者病笃去胎︰虻虫十枚，炙，捣为末。酒服，胎即下。（《产乳》）\n扑坠瘀血︰虻虫二十枚，牡丹皮一两，为末。酒服方寸匕，血化为水也。若久宿血在骨节中者，二味等分。（《备急方》）"},
  "蜜蜂":{o:[],src:["本草纲目"],d:"新一。\n大风疠疾，须眉堕落，皮肉已烂成疮者︰用蜜蜂子、胡蜂子、黄蜂子（并炒）各一分，白花蛇、乌蛇（并酒浸，去皮、骨，炙干）、全蝎（去土，炒）、白僵蚕（炒）各一两，地龙（去土，炒）半两，蝎虎（全者，炒）、赤足蜈蚣（全者，炒）各十五枚，丹砂一两，雄黄（醋熬）一分，龙脑半钱，上为末。每服一钱匕，温蜜汤调下，日三五服。（《总录》）"},
  "蜜蜡":{o:[],src:["本草纲目"],d:"旧十一，新十。\n仲景调气饮︰治赤白痢，少腹 痛不可忍，下重，或面青手足俱变者。用黄蜡三钱，阿胶三钱，同熔化，入黄连末\n《千金》胶蜡汤︰治热痢，及妇人产后下痢。用蜡二棋子大，阿胶二钱，当归二钱半，黄连三钱，黄柏一钱，陈廪米半升，水三升，煮米至一升，去米入药，煎至一钟，温服神效。（《千金方》）\n急心疼痛︰用黄蜡灯上烧化，丸芡子大，百草霜为衣。井水下三丸。\n肺虚咳嗽︰立效丸，治肺虚膈热，咳嗽气急烦满，咽干燥渴，欲饮冷水，体倦肌瘦，发热减食，喉音嘶不出。黄蜡（熔滤令净，浆水煮过）八两，再化作一百二十丸，以蛤粉四两为衣养药。每服一丸，胡桃半个，细嚼温水下，即卧，闭口不语，日二。（《普济方》）\n肝虚雀目︰黄蜡不以多少，熔汁取出，入蛤粉相和得所。每用刀子切下二钱，以猪肝二两批开，掺药在内，麻绳扎定。水一碗，同入铫子内煮熟，取出乘热蒸眼。至温，并肝食之，日二，以平安为度，其效如神。（《集验方》）\n头风掣疼︰湖南押衙颜思退传方︰用蜡二斤，盐半斤相和，于 罗中熔令相入，捏作一兜鍪，势可合脑大小。搭头至额，其痛立止也。（《经验方》）\n脚上转筋︰刘禹锡《传信方》︰用蜡半斤销之，涂旧绢帛上，随患大小阔狭，乘热缠脚，须当脚心，便著袜裹之，冷即易。仍贴两手心。（《图经》）\n暴风身冷︰暴风，通身冰冷如瘫痪者。用上方法，随所患大小阔狭摊贴，并裹手足心。\n风毒惊悸︰同上方法。\n破伤风湿如疟者︰以黄蜡一块，热酒化开服，立效。与玉方》）\n代指疼痛︰以蜡、松胶相和，火炙笼指，即瘥。（《千金翼》）\n脚上冻疮︰浓煎黄蜡涂之。（姚和众）\n狐尿刺人肿痛︰用热蜡著疮，并烟熏之，令汁出即愈。（《肘后方》）\n犬咬疮发︰以蜡炙熔，灌入疮中。（《葛氏方》）\n蛇毒螫伤︰以竹筒合疮上，熔蜡灌之，效。（《徐王方》）\n汤火伤疮︰ 赤疼痛，毒腐成脓。用此拔热毒，止疼痛，敛疮口。用麻油四两，当归一两，煎焦去滓。入黄蜡一两，搅化放冷，摊帛贴之，神效。（《医林集要》）\n胫烂疮︰用桃、柳、槐、椿、楝五枝，同荆芥煎汤，洗拭净。以生黄蜡摊油纸上，随疮大小贴十层，以帛拴定。三日一洗，除去一层不用，一月痊愈。（《医林集要》）\n妊娠胎漏︰黄蜡一两，老酒一碗，熔化热服，顷刻即止。（《药性论》）\n呃逆不止︰黄蜡烧烟熏，二三次即止。（《医方摘要》）\n霍乱吐利︰蜡一弹丸，热酒一升化服，即止。（《肘后方》）\n诸般疮毒︰ 疮、金疮、汤火等疮。用黄蜡一两，香油二两，黄丹半两，同化开，顿冷，瓶"},
  "蜣螂":{o:[],src:["本草纲目"],d:"旧七，新十七。\n小儿惊风︰不拘急慢。用蜣螂一枚杵烂，以水一小盏，于百沸汤中荡热，去滓饮之。\n小儿疳疾︰土裹蜣螂，煨熟，与食之。（《韩氏医通》）\n小儿重舌︰蜣螂，烧末，唾和，敷舌上。（《子母秘录》）\n膈气吐食︰用地牛儿二个，推屎虫一公一母，同入罐中，待虫食尽牛儿，以泥裹煨存性；用去白陈皮二钱，以巴豆同炒过，去豆，将陈皮及虫为末。每用一、二分，吹入咽中。吐痰三、四次，即愈。（《孙氏集效方》）\n赤白下痢︰黑牛散︰治赤白痢、噤口痢及泄泻。用黑牛儿（即蜣螂，一名铁甲将军），烧研。每服半大肠脱肛︰蜣螂，烧存性，为末，入冰片研匀。掺肛上，托之即入。（《医学集成》）\n大小便闭，经月欲死者︰《本事》推车散︰用推车客七个（男用头，女用身），土狗七个（男用身，女用头），新瓦焙，研末。用虎目树南向皮，煎汁调服。只一服即通。《杨氏经验方》︰治大砖上，四取井华水服之（二便不通，全用），即解。\n大肠秘塞︰蜣螂（炒，去翅、足）为末，热酒服一钱。（《圣惠》）\n小便转胞不通︰用死蜣螂二枚，烧末，井华水一盏调服。（《千金》）。\n小便血淋︰蜣螂研水服。（鲍氏）。\n痔漏出水︰唐氏方︰用蜣螂一枚阴干，入冰片少许，为细末，纸捻蘸末入孔内。渐渐生肉，药自退出，一切漏疮不拘蜂 、鼠 。蜣螂烧末，醋和敷。（《千金》）。\n附骨疽漏︰蜣螂七枚，同大麦捣敷。（《刘涓子方》）\n一切恶疮及沙虱、水弩、恶疽︰五月五日取蜣螂蒸过，阴干为末，油和敷之。（《圣惠》）\n疔肿恶疮︰杨柳上大乌壳硬虫（或地上新粪内及泥堆中者），生取，以蜜汤浸死，新瓦焙焦，为末。先以烧过针拨开，好醋调，敷无名恶疮︰忽得不识者。用死蜣螂杵汁涂之。（《子母秘录》）\n灸疮血出不止︰用死蜣螂，烧研，猪脂和涂。（《千金方》）\n大赫疮疾，急防毒瓦斯入心︰先灸，后用干蜣螂为末，和盐水敷四围，如韭叶阔、日一上之。（《肘后》）\n疡风病︰取涂中死蜣螂杵烂，揩疮令热，封之。\n鼻中息肉︰蜣螂十枚，纳青竹筒中，油纸密封，少许，为末涂之。当化为水也。（《圣惠》）\n沙尘入目︰取生蜣螂一枚，手持其背，于眼上影之，自出。（《图经本草》）。\n下部 虫︰痛痒脓血，旁生孔窍。蜣螂七枚（五月五日收者），新牛粪半两，肥羊肉一两（炒黄），同捣成膏，丸莲子大，炙热，绵裹纳肛中。半日即大便中虫出，三度永瘥。（董炳《集验\n心"},
  "蝎":{o:["蝎"],src:["本草备要", "本草纲目"],d:"宣，去风\n辛甘有毒。色青属木，故治诸风眩掉（皆属肝木），惊痫搐掣，口眼 斜（白附、僵蚕、全蝎等分为末，名牵正散。酒服二钱，甚效），疟疾风疮，耳聋带疝，厥阴风木之病（东垣曰∶凡疝气带下，皆属于风。蝎乃治风要药，俱宜加而用之。汪机曰∶破伤风，宜以全蝎、防风为主）。类中风、慢脾惊属虚者忌用。全用去足，焙，或用尾，尾力尤紧。形紧小者良（人被螫者，涂蜗牛即解）。"},
  "蝮蛇":{o:[],src:["本草纲目"],d:"旧一。\n白癞︰大蝮蛇一条，勿令伤，以酒一斗渍之，糠火温令稍热。取蛇一寸，和腊月猪脂捣敷。（《肘后方》）\n脂\n藏器曰︰摩著物皆透也。"},
  "蝼蛄":{o:[],src:["本草纲目"],d:"旧四，新二十。\n十种水病︰肿满喘促不得卧。《圣惠方》︰以蝼蛄五枚，焙干为末。食前白汤服一钱，小便利为效。杨氏︰加甘惠》︰用蝼蛄下截焙研，水服露一夜，日干研末，酒服。《乾坤秘头末七个，治中用腹末七个，治下用尾末七大腹水病︰《肘后》︰用蝼蛄，炙熟，日食十个。《普济》半边散，治水病。用大戟、芫花、甘遂、大黄各三钱，为末。以土狗七枚（五月能飞者），捣葱铺新瓦上焙之，待干去翅、足。每个剪作两半边，分左右记收。欲退左即以左边七片焙研，门冬煎汤，五更调服。候左退三日后，服右边如前法。\n鼻消水，面浮甚者︰用土妙小便不通︰葛洪方︰用大蝼蛄二枚，取下体，以水一升渍饮，须臾即通。《寿域方》︰用土狗下截焙研，调生研亦可。谈野翁方︰加车前草，同捣汁服。《唐氏经验方》︰用土狗后截，和麝捣，纳脐中，缚定，即通。《医方摘要》︰用土狗一个炙研，入冰片、麝香少许，翎管吹入茎内。\n大小便闭，经月欲死︰《普济方》︰用土狗、推车客各七枚，并男用头，女用身以向南樗皮煎汁饮，一服神效。\n灌入，下喉即出也。（《延年方》）\n脐风出汁︰蝼蛄、甘草等分，并炙为末。敷之。（《总录》）\n牙齿疼痛︰土狗一个，旧糟裹定，湿纸包，煨焦，去糟研末，敷之立止。（《本事》）。\n紧唇裂痛︰蝼蛄烧灰，敷之。（《千金方》）。\n塞耳治聋︰蝼蛄五钱，穿山甲（炮）五钱，麝香少许，为末，葱汁和丸，塞之。外用鼻药，即通。（《普济》）\n颈项瘰疬︰用带壳蝼蛄七枚，生取肉，入丁香七粒于壳内，烧过，与肉同研，用纸花贴之。（《救急方》）\n箭镞入肉︰以蝼蛄杵汁滴上，三、五度，自出。（《千金方》）\n针刺不出︰同上。\n误吞钩线︰蝼蛄，去身，吞其头数枚。勿令本人知。（《圣惠方》）"},
  "螳螂、桑螵蛸":{o:[],src:["本草纲目"],d:"新二。\n惊风定搐︰中分散︰用螳螂一个，蜥蜴一条，赤足蜈蚣一条，各中分之，随左右研末。\n记定男用左，女用右。每以一字吹鼻内，搐之。吹左即左定，吹右即右定也。（《普济》）\n箭镞入肉不可拔者︰用螳螂一个，巴豆半个，同研，敷伤处。微痒且忍，极痒乃撼拔之。\n以黄连、贯众汤洗拭，锻石敷之。\n桑螵蛸\n\n旧三，新七。\n遗精白浊下。（《外台小便不通︰桑螵蛸（炙黄）三十枚，黄芩二两，水煎。分二服。（《圣惠》）\n妇人胞转，小便不通︰用桑螵蛸炙为末，饮服方寸匕，日三。（《产书》）\n妇人遗尿︰桑螵蛸酒炒为末，姜汤服二钱。（《千金翼》）\n妊娠遗尿产后遗尿方》）\n咽喉肿塞︰桑上螳螂窠一两（烧灰），马屁勃半两，研匀，蜜丸梧子大。煎犀角汤，每服三五丸。（《总病论》）\n咽喉骨哽︰桑螵蛸醋煎，呷之。（《经验良方》）\n底耳疼痛︰桑螵蛸一个（烧存性），麝香一字。研末。每用半字，掺入神效。有脓先缴净。（《经验方》）\n小儿软疖 桑螵蛸烧存性，研末，油调敷之。（《危氏方》）"},
  "螺厣草":{o:[],src:["本草纲目"],d:"新七。\n吐血衄血︰镜面草水洗，擂酒服。（《朱氏集验方》）。\n牙齿虫痛︰《乾坤生意》︰用镜面草不拘多少，以水缸下泥同捣成膏，入香油二、三点，研匀。贴于痛处腮上。《杨氏家藏方》︰用镜面草半握，入麻油二点，盐半捻，挼碎。左疼右耳，右疼塞左耳。以薄泥饼贴耳门闭其气，仍仄卧。泥耳一、二时，去泥取草放水中，看有虫浮出，久者黑，次者褐，新者白。须于午前用之。徐克安一乳婢，苦此不能食，用之，出数虫而安。\n小儿头疮︰镜面草晒干为末，和轻粉、麻油敷之，立效。（《杨氏家藏方》）。\n手指肿毒，又指恶疮，消毒止痛︰镜面草捣烂，敷之。（《寿域神方》）。\n蛇缠恶疮︰镜面草，入盐杵烂，敷之妙。\n解鼠莽毒︰镜面草自然汁、清油各一杯和服，即下毒三、五次。以肉粥补之，不可迟。（张杲《医说》）。"},
  "蟅虫":{o:[],src:["本草纲目"],d:"新七。\n下瘀血汤︰治产妇腹痛有干血。\n用 虫二十枚（熬，去足），桃仁二十枚，大黄二两，为末，炼蜜杵和，分为四丸。每以一丸，酒一升，煮取八合，温服，当下血也。（张仲景方）\n木舌肿强︰塞口，不治杀人。 虫（炙）五枚，食盐半两，为末。水二盏，煎十沸，时时热含吐涎。瘥乃止。（重舌塞痛︰地鳖虫和生薄荷研汁，帛包捻舌下肿处。一名地蜱虫也。（鲍氏方）\n腹痛夜啼︰ 虫（炙）、芍药、芎 各二钱。为末。每用一字，乳汁调下。（《圣惠方》）\n折伤接骨︰杨拱《摘要方》︰用土鳖焙存性，为末。每服二、三钱，接骨神效。一方︰生者擂汁酒服。《袖珍方》︰用蚵 （即土鳖）六钱（隔，醋淬七次），为末。每服二钱，温酒调下。病在上食后，病在下食前，神效。董炳《集验方》︰用土鳖（阴干）一个麝香少许为末。每传秘方，慎之。又可代杖。"},
  "蟹":{o:["蟹"],src:["本草备要"],d:"泻，散血\n咸寒。除热解结，散血通经，续筋骨（筋绝伤者，取蟹黄、足髓，熬纳疮中，筋即续生。骨节脱离者，生捣，热酒调服，渣涂半日，骨内谷谷有声即好），涂漆疮（能败漆）。然寒胃动风。蟹爪堕胎（产难及子死腹中者，服蟹爪汤即出。其螯烧烟，能集鼠于庭。中蟹毒者，捣藕节，热酒调服。腌蟹，中入蒜则不沙）。"},
  "蟾蜍":{o:["蟾蜍"],src:["本草备要", "本草纲目"],d:"（即癞虾蟆）\n泻，疗疳，拔毒蟾，土精而应月魄，辛凉微毒，入阳明胃。发汗退热，除湿杀虫，治疮疽发背（未成者，用活蟾蜍系疮上。半日，蟾必昏愦，置水中救其命。再易一个，三易则毒散矣。势重者，剖蟾蜍合疮上，不久必臭不可闻，如此二三易，其肿自愈），小儿劳瘦疳疾。蟾酥，辛温大毒。助阳气，治疔肿发背，小儿疳疾脑疳（即蟾蜍眉间白汁，能烂人肌肉，惟疔疳或合他药服一二厘，取其以毒攻毒。脑疳乳和滴鼻中。外科多用之。蟾蜍肪涂玉，刻之如蜡。肪音方，脂也）。"},
  "蠡实":{o:[],src:["本草纲目"],d:"旧二，新六。\n诸冷极病，医所不治者︰马蔺子九升洗净，空腹服一合，酒下，日三服寒疝诸疾，寒疝不能食，及腹内一切诸疾，消食肥肌。马蔺子一升，每日取一把，以面拌煮吞之，服尽愈。（姚僧坦《集验方》）\n喉痹肿痛︰《卫生易简方》︰用蠡实一合，升麻五分，水一升，煎三合，入少蜜搅匀，细呷，大验。《圣惠方》︰用马蔺子二升，升麻一两。为末，蜜丸。水服一钱。又方︰马蔺子八钱，牛蒡子六钱。为末，空心温水服方寸匕。水痢百病︰张文仲《备急方》︰用马蔺子，以六月六日面熬，各等分，为末，空心米饮服方寸匕。如无六月六日面，常面亦可，牛骨灰亦可。又方︰马蔺子、干姜、黄连各等分，为散，熟汤服二方寸匕，入腹即断也。冷、热皆治，常用神效，不得轻之。忌猪肉、冷水。肠风下血，有疙瘩疮，破者不治︰马蔺子一斤（研破酒浸，夏三、冬七日，晒干），何首乌半斤，雄黄、雌黄各四两，为末，以浸药酒打糊丸梧子大。每服三十丸，温酒下，日三服，见效。（《普济方》）\n花、茎及根、叶\n\n旧三，新七。\n睡死不寤︰蠡实根一握，杵烂，以水绞汁，稍稍灌之。（《外台秘要》）\n喉痹口噤︰马蔺花二两，蔓荆子一两，为末，温水服一钱。喉痹肿痛，喘息欲死者︰《外台秘要》︰用马蔺根、叶二两，水一升半，煮一盏，细饮之，立瘥。《圣惠方》︰用根捣汁三合，蜜一合，慢火熬成，徐徐点之，日五七度。一方︰单汁饮之，口噤者灌下。无生者，以刷煎汁。沙石热淋︰马蔺花七枚（烧），故笔头二七枚（烧），粟米一合（炒）。为末。每服三钱，酒下，日二服。名通神散。小便不通︰马蔺花（炒）、茴香（炒）、葶苈（炒），为末，每酒服二钱。（《十便良方》）\n一切痈疽，发背恶疮︰用铁扫帚，同松毛、牛膝，以水煎服。（《乾坤生意》）\n面上瘢 ︰取铁扫帚，地上自落叶，并子，煎汤频洗，数次自消。（《寿域神方》）\n面 鼻渣︰马蔺子花，杵敷之佳。（《肘后方》）"},
  "血竭":{o:["血竭"],src:["本草备要"],d:"补，和血，敛疮\n甘咸。色赤入血分。补心包、肝血不足，专除血痛，散瘀生新，为和血之圣药。治内伤血聚，金疮折跌，疮口不合，止痛生肌。性急，不可多使，引脓（血竭单入血分、乳香、没药兼入气分，皆木脂也）。出南番。色赤，以染透指甲者为真（假者是海母血，味大咸，有腥气）。单碾用（同众药捣，则作尘飞）。"},
  "衣鱼":{o:[],src:["本草纲目"],d:"旧五，新七。\n小儿胎寒，腹痛汗出︰用衣中白鱼二七枚，绢包，于儿腹上回转摩之，以愈为度。（《圣惠小儿撮口︰壁鱼儿研末。每以少许涂乳，令儿吮之。（《圣惠》）。\n小儿客忤，项强欲死︰衣鱼十枚，研敷乳上，吮之入咽，立愈。或以二枚涂母手中，掩儿脐，得吐下愈，外仍以摩儿顶及项强处。《食医心镜》。\n小儿天吊，目睛上视︰并口手掣动用壁鱼儿干者十个，湿者五个，用乳汁和研，灌之。（《圣惠方》）\n小儿痫疾︰白鱼酒︰用衣中白鱼七枚，竹茹一握，酒一升，煎二合，温服之。（《外台》）\n偏风口 ︰取白鱼摩耳下，左 摩右，右 摩左，正乃已。（《孙真人》）。\n小儿重舌︰衣鱼烧灰，敷舌上。（《千金翼》）\n目中浮翳︰书中白鱼末，注少许于翳上，日二。（《外台》）\n沙尘入目不出者︰杵白鱼，以乳汁和，滴目中，即出。或为末，点之。（《千金》）\n小便不通︰滑石白鱼散︰用白鱼、滑石、乱发（烧）等分，为散。饮服半钱匕，日三。（《金匮要略》）\n小便转胞不出︰纳衣鱼一枚于茎中。（《千金方》）\n妇人尿血︰衣中白鱼三十枚，纳入阴中。（《子母秘录》）"},
  "西瓜":{o:["西瓜"],src:["本草备要"],d:"泻暑\n甘寒。解暑除烦，利便醒酒，名天生白虎汤（西瓜、甜瓜，皆属生冷，多食伤脾助湿。《卫生歌》云∶瓜、桃生冷宜少食，免致成疟痢。瓜性寒，曝之尤寒。《稽食赋》云∶瓜、曝则寒，油煎则冷，物性之异也）。"},
  "见肿消":{o:[],src:["本草纲目"],d:"新一。\n一切肿毒及伤寒遗毒，发于耳之前后，及项下肿硬︰用见肿消草、生白芨、生白蔹、土大黄、生大蓟根、野苎麻根捣成饼，入芒硝一钱，和贴留头，干即易之。若加金线重楼及山慈菇尤妙。（《伤寒蕴要》）"},
  "角蒿":{o:[],src:["本草纲目"],d:"旧二，新一。\n齿龈宣露，多是疳也。角蒿烧灰，夜涂上。切忌油腻、沙糖、干枣。（《外台秘要》）\n口疮不瘥，入胸中并生者。不拘大人、小儿，以角蒿灰涂之，有汁吐去，一宿效。（《千金方》）\n月蚀耳疮用蒿灰掺之，良。（《集简方》）"},
  "解毒子":{o:[],src:["本草纲目"],d:"新二。咽喉肿痛，水浆不下︰苦药、山豆根、甘草、硝石各一分，射干、柑皮、升麻各半两。为末，蜜丸。噙之。（《圣惠方》）\n眉棱骨痛，热毒攻眼，头痛眉痛，壮热不止︰解毒子、木香、川大黄各三分，为末，浆水调膏摊贴，干即易之。（《普济方》）"},
  "诸铁器":{o:[],src:["本草纲目"],d:"新四。\n喉痹肿痛︰菖蒲根嚼汁，烧秤锤淬一杯，饮之。（《普济方》）\n舌肿咽痛，咽生息肉，舌肿。秤锤烧赤，淬醋一盏，咽之。（《圣惠方》）\n误吞竹木︰秤锤烧红，淬酒饮之。（《集玄方》）\n便毒初起，极力提起，令有声。以铁秤锤摩压一夜，即散。（《集简方》）\n\n新一。\n眼生偷针︰布针一个，对井睨视，已而折为两段，投井中，勿令人见。（张杲《医说》）\n\n新三。\n小儿伤寒，百日内患壮热。用铁铧一斤，烧赤，水二斗，淬三七次，煎一半，入柳叶七片，浴之。（《圣济录》）\n积年齿 ︰旧铁铧头一枚，炭火烧赤，捻硫黄一分，猪脂一分，于上熬沸。以绵包柳杖 药，热烙齿缝，数次愈。（《普济方》）\n灌顶油法︰治脑中热毒风，除目中翳障，镇心明目。生油二斤，故铁铧五两（打碎），硝石半两，寒水石一两，马牙硝半两，曾青一两，绵裹入油中浸七日。每以一钱顶上摩之，及滴少许入鼻内，甚妙。此大食国胡商方。（《圣惠方》）\n铁犁 尖（《日华》）\n\n旧二，新一。\n小儿下血︰方见上。\n妊娠咳嗽︰车缸一枚，烧赤投酒中，冷冻饮料。（《圣惠方》）\n走注气痛︰车缸烧赤，湿布裹熨病上。（《千金方》）\n马衔 （即马勒口铁也。大明曰︰古旧者好，亦可作医工针也。（《开宝》）"},
  "谷精草":{o:["谷精草"],src:["本草备要", "本草纲目"],d:"轻，明目\n辛温轻浮。上行阳明（胃），兼入厥阴（肝）。明目退翳之功在菊花之上。亦治喉痹齿痛，阳明风热。收谷后，荒田中生。叶似嫩秧，花如白星（小儿雀盲者，羯羊肝一具，不洗，竹刀割开，入谷精煮熟食之。或作丸，茶下）。"},
  "谷芽":{o:["谷芽"],src:["本草备要"],d:"健脾消食\n甘温。开胃快脾，下气和中，消食化积。炒用。"},
  "豆蔻":{o:[],src:["本草纲目"],d:"旧一，新九。\n心腹胀满短气。用草豆蔻一两，去皮为末，以木瓜生姜汤，调服半钱。（《千金方》）\n胃弱呕逆不食。用草豆蔻仁二枚，高良姜半两，水一盏，煮取汁，入生姜汁半合，和白面作拨刀，以羊肉 汁煮熟，空心食之。（《普济》霍乱烦渴︰草豆蔻、黄连各一钱半，乌豆五十粒，生姜三片。水煎服之。（《圣济总录》）\n虚疟自汗不止。用草果一枚（面裹煨熟，连面研），入平胃散二钱。水煎服。（《经效济世方》）\n气虚瘴疟，热少寒多，或单寒不热，或虚热不寒。用草果仁、熟附子等分，水一盏，姜七片，枣一枚，煎半盏服。名果附汤。（《济生方》）\n脾寒疟疾，寒多热少，或单寒不热，或大便泄而小便多，不能食。用草果仁、熟附子各二钱半，生姜七片，枣肉二枚。水三盏，煎一盏，温服。（《医方大成》）\n脾肾不足︰草果仁一两（以舶茴香一两炒香，去茴不用），吴茱萸（汤泡七次，以破故纸一两炒香，去故纸不用），葫芦巴一两（以山茱萸一两炒香，去茱萸不用）。上三味为散，酒糊丸梧子大。每服六十丸，盐汤下。（《百一选方》）\n赤白带下︰连皮草果一枚，乳香一小块。面裹煨焦黄，同面研细。每米饮服二钱，日二服。（《卫生易简方》）\n香口辟臭︰豆蔻、细辛为末，含之。（《肘后方》）\n脾痛胀满︰草果仁二个。酒煎服之。（《直指方》）\n花"},
  "象皮":{o:["象皮"],src:["本草备要"],d:"外用，敛金疮\n象肉壅肿，以刀刺之，半日即合。治金疮不合者，用其皮灰，亦可以熬膏入散。象胆亦能辟尘，与熊胆同功。"},
  "豨莶":{o:[],src:["本草纲目"],d:"新五。\n风寒泄泻︰火 丸︰治风气行于肠胃，泄泻。火 草为末，醋糊丸梧子大。每服三十丸，白汤下。（《圣济总录》）\n痈疽肿毒，一切恶疮。 草（端午采者）一两，乳香一两，白矾（烧）半两。为末。每服二钱，热酒调下。毒重者连进三服，得汗妙。（《乾坤秘韫》）\n发背疔疮︰ 草、五叶草（即五爪龙）、野红花（即小蓟）、大蒜等分。擂烂，入热酒一碗，绞汁服，得汗立效。（《乾坤生意》）\n调下。汗出即愈，极有效验。（《集下五十丸。（《百一选方》）"},
  "贝母":{o:["贝母"],src:["本草备要", "本草纲目"],d:"宣，散结，泻热，润肺，清火\n微寒，苦泻心火，辛散肺郁（入肺经气分，心火降则肺气宁。《诗》曰∶言采其虻。虻即贝母也。取其解郁）。润心肺，清虚痰。治虚劳烦热，咳嗽上气，吐血咯血，肺痿肺痈，喉痹（君相之火）目眩（火热上攻），淋沥（小肠邪热，心与小肠相表里，肺为气化之源）瘿瘤（化痰），乳闭产难。功专散结除热，敷恶疮（唐时有人膊上生疮如人面，能饮酒食物，亦无他苦。遍投诸药悉受之，至贝母。疮乃颦眉，灌之数日，成痂而愈），敛疮口（火降邪散，疮口自敛，非贝母性收敛也。俗以半夏燥毒，代以贝母，不知贝母寒润，主肺家燥痰，半夏温燥，主脾家湿痰，设或误用，贻误非浅。故凡风、寒、湿、食诸痰，贝母非所宜也，宜用半夏、南星）。川产开瓣者良，独颗无瓣者不堪用。去心，糯米拌炒黄，捣用。浓朴、白薇为使。畏秦艽。反乌头。"},
  "败瓢":{o:[],src:["本草纲目"],d:"新六。\n中满鼓胀︰用三、五年陈壶卢瓢一个，以糯米一斗作酒，待熟，以瓢于炭火上炙热，入酒浸之，如此三、五次，将瓢烧存性，研末。每服三钱，酒下，神效。（余居士《选奇方》）。\n大便下血︰败瓢（烧存性）、黄连等分。研末。每空心温酒服二钱。（《简便方》）。\n赤白崩中︰旧壶卢瓢（炒存性）、莲房（煅存性）等分。研末。每服二钱，热水调服。\n三服，有汗为度，即止。甚者五服止，最妙。忌房事、发物、生冷。（《海上方》）。\n脑漏流脓︰破瓢、白鸡冠花、白螺蛳壳（各烧存性）等分，血竭、麝香各五分，为末。\n以好酒洒湿熟艾，连药揉成饼，贴在顶门上，以熨斗熨之，以愈为度。（孙氏《集效方》）。\n腋下瘤瘿︰用长柄茶壶卢烧存性，研末搽之，以消为度。一府校老妪右腋生一瘤，渐长至尺许，其状如长瓠子，久而溃烂。一方士教以此法用之，遂出水，消尽而愈。（《濒湖集简方》）。\n汤火伤灼︰旧壶卢瓢，烧灰敷之。（同上）"},
  "败酱":{o:[],src:["本草纲目"],d:"旧二，新三。\n肠痈有脓︰薏苡仁附子败酱散︰用薏苡仁十分，附子二分，败酱五分。捣为末。每以方寸匕，水二升，煎一升，顿服。小便当下，即愈。（张仲景《金匮玉函》）\n产后恶露七、八日不止︰败酱、当归各六分，续断、芍药各八分，芎 、竹茹各四分，生地黄（炒）十二分，水二升，煮取八合，空心服。（《外台秘要》）\n产后腰痛，乃血气流入腰腿，痛不可转者︰败酱、当归各八分，芎 、芍药、桂心各六分，水二升，煮八合，分二服。忌葱。（《广济方》）\n产后腹痛如锥刺者︰败酱草五两，水四升，煮二升。每服二合，日三服，良。（《卫生易简方》）\n蠷 尿疮绕腰者︰败酱煎汁涂之，良。（《杨氏产乳》）"},
  "贯众":{o:["贯众"],src:["本草备要", "本草纲目"],d:"泻热，解毒\n味苦微寒，有毒，而能解邪热之毒。治崩中带下，产后血气胀痛，破症瘕，发斑痘（王海藏快斑散用之），化骨哽（能软坚），杀三虫。根似狗脊而大。汁能制三黄，化五金，伏钟乳、结砂、制汞，解毒软坚（以此浸水缸中，日饮其水，能辟时疾）。"},
  "赤地利":{o:[],src:["本草纲目"],d:"旧二。小儿热疮，身面皆有，如火烧者︰赤地利末，粉之。（外台）火疮灭瘢︰赤地利末，油调涂。（《圣惠》）"},
  "赤柽柳":{o:["赤柽柳"],src:["本草备要"],d:"（一名西河柳）\n宣，解毒能使疹毒外出。末服四钱，治痧疹不出，喘嗽闷乱。沙糖调服，治疹后痢。"},
  "赤箭":{o:[],src:["本草纲目"],d:"新二。\n天麻丸︰消风化痰，清利头目，宽胸利膈。治心忪烦闷，头晕欲倒，项急，肩背拘倦，神二两。为末，炼蜜丸如芡子大。每食后嚼一丸，茶、酒任下。（《普济方》）\n腰脚疼痛︰天麻、半夏、细辛各二两。绢袋二个，各盛药令匀，蒸热，交互熨痛处。汗出则愈。数日再熨。（《卫生易简方》）\n还筒子\n\n新一。\n益气固精︰补血，黑发，益寿，有奇效。还筒子半两，芡实半两，金银花二两，破故纸（酒浸，春三、夏一、秋二，冬五日，焙，研末）二两。各研末，蜜糊丸梧子大。每服五十丸，空心盐汤"},
  "赤铜屑":{o:[],src:["本草纲目"],d:"旧一。\n腋下狐臭︰崔氏方︰用清水洗净，又用清酢浆洗净，微揩破，取铜屑和酢热揩之，甚验。（《外台》）"},
  "车前":{o:[],src:["本草纲目"],d:"旧六，新六。\n小便血淋作痛︰车前子晒干为末，每服二钱，车前叶煎汤下。（《普济方》）\n石淋作痛︰车前子二升，以绢袋盛，水八升，煮取三升，服之，须臾石下。（《肘后方》）。\n老人淋病，身体热甚︰车前子五合，绵裹煮汁，入青粱米四合，煮粥食。（《奉亲养老书》）\n孕妇热淋︰车前子五两，葵根（切）一升，以水五升，煎取一升半，分三服，以利为度。（《梅师方》）\n滑胎易产︰车前子为末。酒服方寸匕。不饮酒者，水调服。《诗》云︰采采 苡，能令妇人乐有子也。陆玑注云︰治妇人产难\n横产不出︰车前子末，酒服二钱。（《子母秘录》）\n阴冷闷疼，渐入囊内，肿满杀人︰车前子末，饮服方寸匕，日二服。（《千金方》）\n隐疹入腹，体肿舌强︰车前子末粉之，良。（《千金方》）\n阴下痒痛︰车前子煮汁频洗。（《外台秘要》）\n久患内障︰车前子、干地黄、麦门冬等分，为末，蜜丸如梧子大。服之。累试有效。（《圣惠方》）\n补虚明目︰驻景丸︰治肝肾俱虚，眼昏黑花，或生障翳，迎风有泪，久服补肝肾，增目力︰车前子、熟地黄（酒蒸焙）各三两，菟丝子（酒浸）五两，为末，炼蜜丸梧子大。每温酒下三十丸，日二服。（《和剂局方》）\n风热目暗涩痛︰车前子、宣州黄连各一两，为末。食后温酒服一钱，日二服。（《圣惠\n草及根\n\n旧四，新七。\n小便不通︰车前草一斤，水三升，煎取一升半，分三服。一方︰入冬瓜汁。一方︰入桑叶汁。（《百一方》）\n初生尿涩不通︰车前捣汁，入蜜少许，灌之。（《全幼心鉴》）\n小便尿血︰车前草（捣汁）五合，空心服。（《外台秘要》）\n鼻衄不止︰生车前叶，捣汁饮之甚善。（《图经本草》）\n金疮血出︰车前叶捣敷之。（《千金方》）\n热痢不止︰车前叶捣汁一盏，入蜜一合，煎温服。（《圣惠方》）\n产后血渗，入大小肠︰车前草（汁）一升，入蜜一合，和煎一沸，分二服。（崔氏方）\n湿气腰痛︰蛤蟆草（连根）七科，葱白（连须）七科，枣七枚，煮酒一瓶，常服，终身不发。（《简便方》）\n喉痹乳蛾︰蛤蟆衣、凤尾草擂烂，入霜梅肉、煮酒各少许，再研绞汁，以鹅翎刷患处，随手目赤作痛︰车前草自然汁，调朴硝末，卧时涂眼胞上，次早洗去。小儿目痛，车前草汁，和竹沥点之。（《圣济总录》）\n目中微翳︰车前叶、枸杞叶等分，手中揉汁出，以桑叶两重裹之，悬阴处一夜，破桑叶取点，不过三、五度。（《十便良方》）"},
  "轻粉":{o:["轻粉"],src:["本草备要"],d:"燥，劫痰涎，外用杀虫\n辛冷（时珍曰∶燥有毒）。杀虫治疮，劫痰消积（能消涎积。十枣汤加大黄、牵牛、轻粉，名三化神 散），善入经络，螈 药多用之。不可过服常用（时珍曰∶水银阴毒，用火丹砂而出。再加盐、矾，炼为轻粉。轻扬燥烈，走而不守，今人用治杨梅毒疮。虽能劫风痰湿热从牙龈出，邪郁暂解，然毒瓦斯窜入经络，筋骨血液耗亡，筋失所养，变为筋挛骨痛。痈肿疳漏，遂成废痼，贻害无穷。上下齿龈，属手足阳明肠胃经。毒瓦斯循经上行，至齿龈薄嫩之处而出）。土茯苓、黄连、黑铅、铁浆、陈酱能制其毒。"},
  "逆流回澜水":{o:["逆流回澜水"],src:["本草备要"],d:"宣\n性逆而倒上，中风、卒厥宣痰饮之药宜之。"},
  "通脱木":{o:[],src:["本草纲目"],d:"新一。\n洗头风痛︰新通草瓦上烧存性，研末二钱，热酒下。牙关紧者，斡口灌之。（王璆《百一选方》）"},
  "酒":{o:["酒"],src:["本草备要"],d:"宣，行药势\n辛者能散，苦者能降，甘者居中而缓，浓者热而毒，淡者利小便。用为响导，可以通行一身之表，引药至极高之分。热饮伤肺，温饮和中。少饮则和血行气，壮神御寒，遣兴消愁，辟邪逐秽，暖水藏，行药势。过饮则伤神耗血（亦能乱血，故饮之身面俱赤），损胃灼精，动火生痰，发怒助欲（酒是色媒人），致生湿热诸病（过饮则相火昌炎，肺金受灼，致生痰嗽。脾因火而困怠，胃因火而呕吐，心因火而昏狂，肝因火而善怒，胆因火而忘惧，肾因火而精枯，以致吐血、消渴、劳伤、蛊膈、痈疽、失明，为害无穷。汪颖曰∶人知戒早饮，而不知夜饮更甚。醉饱就床，热壅三焦，伤心损目，夜气收敛，酒以发之，乱其清明，劳其脾胃，停湿动火，因而致病者多矣。朱子云∶以醉为节可也）。醇而无灰，陈久者良。畏枳 、葛花、赤豆花、绿豆粉、咸卤（得咸则解，水制火也）。"},
  "酢浆草":{o:[],src:["本草纲目"],d:"旧二，新六。\n小便血淋︰酸草捣汁，煎五苓散服之。俗名醋啾啾是也。（王璆《百一选方》）。\n诸淋赤痛︰三叶酸浆草洗，研取自然汁一合，酒一合和匀。空心温服，立通。（沈存中《灵苑方》）。\n二便不通︰酸草一大把，车前草一握，捣汁，入砂糖一钱，调服一盏。不通再服。（《摘玄方》）。\n赤白带下︰三叶酸草，阴干为末。空心温酒服三钱匕。（《千金方》）。\n痔疮出血︰雀林草一大握，水二升，煮一升服。日三次，见效。（《外台秘要》）。癣疮作痒︰雀儿草（即酸母草），擦之。数次愈。（《永类方》）\n蛇虺螫伤︰酸草，捣敷。（崔氏方）。\n牙齿肿痛︰酸浆草一把（洗净），川椒四十九粒（去目），同捣烂，绢片裹定如箸大，切成豆"},
  "酸模":{o:[],src:["本草纲目"],d:"新一。\n瘭疽毒疮，肉中忽生黯子如粟豆，大者如梅李，或赤或黑，或青或白，其中有核，核有深根，应心。肿泡紫黑色，能烂筋骨，毒入脏腑杀人︰宜灸黯上百壮。以酸模叶薄其四面，防其长也。内服葵根汁，其毒自愈。（《千金方》）"},
  "酸浆":{o:[],src:["本草纲目"],d:"新三。\n热咳咽痛 灯笼草为末，白汤服，名清心丸。仍以醋调敷喉外。（《丹溪纂要》）\n痛︰灯笼草，炒焦研末，酒调呷之。（《医学正传》）\n灸疮不发︰酸浆叶贴之。\n子\n\n新二。\n马蔺子（炒）、大盐梧子大。每服三十丸，木香汤下。（《圣济总录》）\n天泡湿疮︰天泡草铃儿生捣敷之。亦可为末，油调敷。（《邓才杂兴方》）"},
  "醋":{o:["醋"],src:["本草备要"],d:"（一名苦酒）\n散瘀，敛气，消痈肿酸温。散瘀解毒，下气消食（食敛缩则消矣），开胃气（令人嗜食，《本草》未载），散水气。治心腹血气痛（磨木香服），产后血晕（以火淬醋，使闻其气），症结痰癖，疸黄痈肿（外科敷药多用之，取其敛壅热、散瘀解毒。昂按∶贝母性散而敛疮口，盖能散，所以能敛。醋性酸收而散痈肿，盖消则内散，溃则外散，收处即是散处，两者一义也）口舌生疮（含漱），损伤积血（面和，涂能散之），谷、鱼、肉、菜、蕈、诸虫毒。多食伤筋（收缩太过。酒、醋无所不入，故制药多用之）。米造、陈久者良（寇宗奭曰∶食酸则齿软者，齿属肾，酸属肝，木气强水气弱故也）。"},
  "醍醐菜":{o:[],src:["本草纲目"],d:"旧一。\n伤中崩赤︰醍醐杵汁，拌酒煎沸，空心服一盏。（《千金方》）。"},
  "野狼毒":{o:[],src:["本草纲目"],d:"旧四，新六。\n心腹连痛作胀︰用野狼毒二两附子半两，捣筛，蜜丸梧子大。一日服一丸，二日二丸，三日三丸，止；又从一丸起，至三丸止，以瘥为度。（《肘后方》）\n九种心痛，一虫，二蛀，三风，四悸，五食，六饮，七冷，八热，九气也。又治连年积冷，流注心胸，及落马堕车，瘀血中恶等证︰九痛丸︰用野狼毒（炙香）、吴茱萸（汤泡）、巴豆（去心，炒取霜）、干姜（炮）、人参各一两，附子（泡去皮）三两，为末，炼蜜丸梧子大。每空腹温酒下一丸。（《千金方》）\n食︰用野狼毒三两，附子一两，旋复花三两，捣末，蜜丸梧子大。每服三丸，食前白汤下，日三服。（《肘后方》）\n以蜜丸梧子大。每两胁气结︰方同腹中冷痛方。\n一切虫病︰用野狼毒杵末，每服一钱，用饧一皂子大，沙糖少许，以水化开，卧时空腹服之，次早即下虫也。（《集效方》）\n以猪油、马油调搽患处。方睡勿以被蒙头，恐药气伤面。此维扬潘氏所传方。（《蔺氏经验方》）\n瓦器内，以津液擦化为末，同以清油浸药，高一寸，三日，待药沉油清，遇夜不见灯火，蘸油涂疮上，仍以口鼻于药盏上吸气，取效。（《永类方》）\n积年干癣\n恶疾风疮︰野狼毒、秦艽等分。为末。每服方寸匕，温酒下，日一、二服。（《千金方》）"},
  "野狼牙":{o:[],src:["本草纲目"],d:"旧六，新四。\n金疮出血︰野狼牙草茎叶，熟捣贴之。（《肘后方》）\n小便溺血︰金粟野狼牙草（焙干，入蚌粉炒）、槐花、百药煎等分。为末。每服三钱，米泔空心调服。亦治酒病。（《卫生易简方》）\n寸白诸虫︰野狼牙五两。捣末，蜜丸麻子大。隔宿不食，明旦以浆水下一合，服尽即瘥。（《虫疮瘙痒︰六月以前采野狼牙叶，以后用根，生 咀，以木叶裹之， 火之，冷即止。（杨炎《南行方》）\n小儿阴疮︰野狼牙草，浓煮汁洗之。（《千金方》）\n妇人阴痒︰野狼牙二两，蛇床子三两，煎水热洗。（《外台秘要》）\n妇人阴蚀疮烂者︰野狼牙汤︰用野狼牙三两，水四升，煎取半升，以箸缠绵浸汤沥洗，日四、五遍。（张仲景《金匮玉函》）\n耳出汁︰野狼牙研末，绵裹，日塞之。（《圣惠方》）\n毒蛇伤螫︰独茎野狼牙根或叶，捣烂，腊猪脂和涂，立瘥。（崔氏方）\n射工中人有疮︰野狼牙，冬取根，夏取叶，捣汁饮四五合，并敷之。（《千金方》）"},
  "野菊":{o:[],src:["本草纲目"],d:"新四。痈疽疔肿︰一切无名肿毒。《孙氏集效方》︰用野菊花连茎捣烂，酒煎热服取汗，以渣敷之即愈。《卫生易简方》︰用野菊花茎叶、苍耳草各一握，共捣，入酒一碗，绞汁服，以渣敷之，取汗即愈。或六月六日采苍耳叶，九月九日采野菊花，为末。每酒服三钱，亦可。天泡湿疮︰野菊花根、枣木，煎汤洗之。（《医学集成》）\n瘰疬未破︰野菊花根捣烂，煎酒服，以渣敷之。自消，不消亦自破也。（《瑞竹堂经验方"},
  "金":{o:["金"],src:["本草备要", "本草纲目"],d:"重，镇心肝，定郁悸\n辛平有毒（生金屑，服之杀人。昂按∶金性至刚重坠，与血肉之体不相宜，故服之致死，非其性有毒也。人被金银灼者，并不溃烂，无毒可知矣。精金粹玉，世之宝器，岂有毒瓦斯哉？）。金制木，重镇怯，故镇心肝，安魂魄（虽云重坠，亦借其宝气也。古方有红雪、紫雪，皆并金银煮汁，亦假其气耳）。治惊痫风热，肝胆之病（肝经风热，则为惊痫失志，魂魄飞扬。肝属木而畏金，与心为子母之脏，故其病同源一治）。丸散用箔为衣，煎剂加入药煮。畏铅、水银（遇铅则碎，五金皆畏水银）。"},
  "金丝草":{o:[],src:["本草纲目"],d:"新三。\n妇人血崩：金丝草、海柏枝、砂仁、花椒、蚕退纸、旧锦灰，等分，为末，煮酒空心服。陈光述传。（《谈埜翁方》）\n痈疽疔肿：一切恶疮。金丝草、忍冬藤、五叶藤、天荞麦等分。煎汤温洗。黑色者，加醋。　又铁箍散：用金丝草灰二两（醋拌晒干），贝母五两（去心），白芷二两，为末，以凉水调贴疮上，香油亦可。或加龙骨少许。\n天蛇头毒：落苏（即金丝草）、金银花藤、五叶紫葛、天荞麦，等分。切碎，用绝好醋浓煎，先熏后洗。（《救急方》）"},
  "金星石":{o:[],src:["本草纲目"],d:"新二。吐血嗽血肺损者︰金星石、银星石、玄精石、不灰木、阳起石、云母石等分。用坩锅一个，铺冬月水牛粪一、二寸，铺药一层，铺灰二寸，又药一层，重重如此，以灰盖之，盐泥固济。用炭一秤，火 一日夜，埋土中一夜，取出药块，去灰为末。每一两，入龙脑、麝香各半钱，阿胶二钱半（炒）。每服一钱，糯米汤下，日三服。（《圣惠方》）\n大风虫疮，有五色虫取下︰诸石丸︰用金星 石、银星 石、云母石、禹余粮石、滑石、阳起石、磁石、凝水石、蜜陀僧、自然铜、龙涎石等分。捣碎瓶盛，盐泥固济之。炭火十斤，过为末，醋糊丸小豆大。每服十五丸，白花蛇酒下，一日三服，以愈为度。（《太平圣惠方》）"},
  "金星草":{o:[],src:["本草纲目"],d:"旧一，新二。\n五毒发背︰金星草和根净洗，慢火焙干。每四两入生甘草一钱，捣末，分作四服。每服用酒一升，煎二、三沸，更以温酒三、二升相和，入瓶器内封固，时时饮之。忌生冷油肥毒物。（《经验方》）。\n热毒下血︰金星草、陈干姜各三两，为末。每服一钱，新汲水下。（《本事方》）。\n脚膝烂疮︰金星草背上星，刮下敷之，即干。（《集简方》）。"},
  "金鱼":{o:[],src:["本草纲目"],d:"新一。\n久痢噤口，病势欲死︰用金丝鲤鱼一尾，重一二斤者，如常治净，用盐、酱、葱，必入胡椒末三、四钱，煮熟，置病患前嗅拱《医方摘要》）"},
  "针砂":{o:[],src:["本草纲目"],d:"新十。\n风湿脚痛︰针砂、川乌头为末，和匀炒热，绵包熨之。（《摘玄方》）\n风痹暖手︰针砂四两， 砂三钱，黑脚白矾六钱，研末，以热醋或水拌湿，油纸裹置袋内，任意执之，冷再拌。（《圣济录》）\n脾劳黄病︰针砂四两（醋炒七次），干漆（烧存性）二钱，香附三钱，平胃散五钱，为末，蒸饼丸梧子大。任汤使下。（《摘玄方》）\n湿热黄疮，助脾去湿。针砂丸︰用针砂不拘多少，擂尽锈，淘洗白色，以米醋于铁铫内浸过一指，炒干，再炒三、五次，候通红取出。用陈粳米半升，水浸一夜，捣粉作块，煮半熟，杵烂，入针砂二两半，百草霜（炒）一两半，捣千下，丸梧子大。每服五十丸，用五加皮、牛膝根、木瓜浸酒下。初服若泄泻，其病源去也。（《乾坤生意》）\n水肿尿少︰针砂（醋煮炒干）、猪苓、生地龙各三钱。为末，葱涎研和，敷脐中约一寸浓，缚之，待小便多为度，日二易之。入甘遂更妙。（《德生堂方》）\n泄泻无度，诸药不效︰方同上，不用甘遂。（《医学正传》）\n虚寒下痢，肠滑不禁︰针砂七钱半，官桂一钱，枯矾一钱。为末，以凉水调摊脐上下，缚之。当觉大热，以水润之。可用三、四次，名玉胞肚。（《仁存方》）\n项下气瘿︰针砂入水缸中浸之，饮食皆用此水，十日一换砂，半年自消散。（杨仁斋《直指方》）\n染白须发︰针砂（醋炒七次）一两，诃子、白芨各四钱，百药煎六钱，绿矾二钱，为末，用热醋调刷须发，菜叶包住，次早酸浆洗去。此不坏须，亦不作红。又方︰针砂、荞面各一两。百药煎为末，茶调，夜涂旦洗。再以诃子五钱，没石子（醋炒）一个，百药煎少许，水和涂一夜，温浆洗去，黑而且光。"},
  "钓藤":{o:[],src:["本草纲目"],d:"新三。\n小儿惊热︰钓藤一两，硝石半两，甘草（炙）一分。为散。每服半钱，温水服，日三服。名延龄散。（《圣济录》）\n卒得痫疾︰钓藤、甘草（炙）各二钱。水五合，煎二合。每服枣许，日五、夜三度。（《圣惠\n斑疹不快︰钓藤钩子、紫草茸等分。为末。每服一字或半钱，温酒服。（钱氏方）"},
  "钟乳":{o:["钟乳"],src:["本草备要"],d:"补阳\n甘温。阳明（胃）气分药。木石之精。强阴益阳，通百节，利九窍，补虚劳，下乳汁。服之令人阳气暴充，饮食倍进，形体壮盛。然其性 悍，须命门真火衰者可偶用之。若借以恣欲，多服、久服，不免淋浊痈疽之患。出洞穴中，石液凝成，下垂如冰柱。通中轻薄、如鹅翎管、碎之如爪甲光明者真。炼合各如本方，蛇床为使。恶牡丹、紫石英。忌参、术、羊肉、葱、蒜、胡荽。"},
  "钢铁":{o:[],src:["本草纲目"],d:"新六。\n惊痫发热︰铁粉，水调少许服之。（《圣惠方》）\n急惊涎潮，壮热闷乱。铁粉二钱，朱砂一钱。为末。每服一字，薄荷汤调下。（《杨氏家藏方》）\n伤寒阳毒，狂言妄语乱走，毒气在脏也。铁粉二两，龙胆草一两。为末。磨刀水调服一钱，小儿五分。（《全幼心鉴》）\n头痛鼻塞︰铁粉二两，龙脑半分。研匀。每新汲水服一钱。（《圣惠方》）\n雌雄疔疮︰铁粉一两，蔓菁根三两，捣如泥封之，日二换。（《集玄方》）\n风热脱肛︰铁粉研，同白蔹末敷上，按入。（《直指方》）"},
  "铁":{o:["铁"],src:["本草备要", "本草纲目"],d:"重，坠痰，镇惊\n辛平重坠。镇心平肝，定惊疗狂，消痈解毒。诸药多忌之（李时珍曰∶补肾药尤忌之）。畏磁石、皂荚（皂荚木作薪，则斧裂）。时，砧上打落者名铁落（《素问》用治怒狂），如尘飞起者名铁精，器物生衣者名铁锈，盐、醋浸出者名铁华（李时珍曰∶大抵借金气以平木、坠下解毒，无他义也）。针砂消水肿黄胆，散瘿瘤，乌髭发（乌须方多用之）。"},
  "铁华粉":{o:[],src:["本草纲目"],d:"新一。\n妇人阴挺︰铁胤粉一钱，龙脑半钱，研，水调刷产门。（危氏《得效方》）"},
  "铁浆":{o:[],src:["本草纲目"],d:"旧二，新三。\n时气生疮胸中热。铁浆饮之。（《梅师方》）\n一切疔疮︰铁浆，日饮一升。（《千金方》）\n发背初起︰铁浆饮二升，取利。（《外台秘要》）\n蛇皮恶疮︰铁浆，频涂之。（《谈野翁方》）\n漆疮作痒︰铁浆，频洗，愈。（《外台》）"},
  "铁精":{o:[],src:["本草纲目"],d:"旧五，新一。\n下痢脱肛︰铁精粉敷之。（《至宝方》）\n女人阴脱︰铁精、羊脂，布裹炙热，熨推之。（《圣惠方》）\n男子阴肿︰铁精粉敷之。（《子母秘录》）\n疔肿拔根︰铁渣一两，轻粉一钱，麝香少许，为末。针画十字口，点药入内，醋调面糊敷之，神效。（《普济方》）\n食中有蛊，腹内坚痛，面目青黄，淋露骨立，病变无常。用炉中铁精研末，鸡肝和丸梧子大。食前酒下五丸，不过十日愈。（《肘后》）\n蛇骨刺人毒痛︰铁精粉豆许，吹入疮内。（《肘后方》）"},
  "铁线草":{o:[],src:["本草纲目"],d:"新一。男女诸风，产后风尤妙。铁线草根五钱，五加皮一两，防风二钱。为末。以乌骨鸡一斤重者，水内淹死，去毛肠，砍作肉松，入药剁匀，下麻油些少，炒黄色，随人量入酒煮熟。先以排风藤煎浓汤，沐浴头身，乃饮酒食鸡，发出粘汗即愈。如不沐浴，必发出风丹，乃愈。（滑伯仁《撄宁心要》）"},
  "铁落":{o:[],src:["本草纲目"],d:"新一。\n小儿丹毒︰ 铁屎研末，猪脂和敷之。（《千金方》）"},
  "铁锈":{o:[],src:["本草纲目"],d:"新八。\n风瘙瘾疹︰锈铁磨水涂之。（《集简方》）\n汤火伤疮︰青竹烧油，同铁锈搽之。（《积德堂方》）\n疔肿初起︰多年土内锈钉，火 醋淬，刮下锈末，不论遍次， 取收之。每用少许，人乳和，挑破敷之。仍炒研二钱，以齑水煎滚，待冷调服。（《普济方》）\n脚腿红肿，热如火炙，俗名赤游风。用铁锈水涂解之。（《惠济方》）\n重舌肿胀︰铁锈锁烧红，打下锈，研末。水调一钱，噙咽。（《生生编》）\n小儿口疮︰铁锈末，水调敷之。（《集简方》）\n内热遗精︰铁锈末，冷水服一钱，三服止。（《活人心统》）\n妇人难产︰杂草烧镬锈、白芷等分。为末。每服一钱，童尿、米醋各半，和服见效。（《救急方》）"},
  "铁𦶟":{o:[],src:["本草纲目"],d:"新一。\n项边 子︰以桃核于刀上烧烟熏之。（陈氏《本草》）"},
  "铅":{o:["铅"],src:["本草备要", "本草纲目"],d:"重，坠痰，解毒\n甘寒属肾。禀壬癸之气，水中之金，金丹之母，八石之祖（丹灶家必用之）。安神解毒，坠痰杀虫，乌须（制为梳，以梳须）明目。铅丹（即黄丹，用黑铅加硝、黄、盐、矾炼成）咸寒沉重，味兼盐、矾。内用坠痰去怯，消积杀虫，治惊疳疟痢。外用解热拔毒，去瘀长肉，熬膏必用之药（用水漂去盐硝砂石，微火炒紫色，摊地上，去火毒用）。铅粉主治略同（亦名胡粉锡粉。李时珍曰∶铅粉亦可代铅丹熬膏，然未经盐矾火 。又有豆粉、蛤粉杂之，只入气分，不能入血分也）。"},
  "铅丹":{o:[],src:["本草纲目"],d:"旧八，新二十五。\n消渴烦乱︰黄丹，新汲水服一钱，以荞麦粥压之。（《圣惠方》）\n吐逆不止︰碧霞丹︰用北黄丹四两，米醋半升，煎干，炭火三秤，就铫内 红，冷定为末，粟米饭丸梧子大。每服七丸，醋汤下。（《集验方》）\n伏暑霍乱︰水浸丹，见木部巴豆下。\n小儿吐逆不止，宜此清镇。烧针丸︰用黄丹研末，小枣肉和丸芡子大。每以一丸，针签于灯上烧过，研细，乳汁调下。一加朱砂、枯矾等分。（谢氏《小儿方》）\n反胃气逆︰胃虚。铅丹二两，白矾二两，生石亭脂半两。以丹、矾研匀，入坩锅内，以炭半秤 赤，更养一夜，出毒两日，入亭脂同研，粟米饭和丸绿豆大。每日米饮下十五丸。（《圣济录》）\n泄泻下痢赤白。用枣肉捣烂，入黄丹、白矾各皂子大，粳米饭一团，和丸弹子大，铁线穿，于灯上烧过，为末。米饮服之。（《摘玄方》）\n赤白痢下︰黄丹（炒紫）、黄连（炒）等分。为末，以糊丸麻子大。每服五十丸，生姜、甘草汤下。（《普济方》）\n妊娠下痢疼痛︰用乌鸡卵一个，开孔去白留黄，入铅丹五钱搅匀，泥裹煨干研末。每服二钱，米饮下。一服愈，是男；二服愈，是女。（《三因方》）\n吐血咯血咳血︰黄丹，新汲水服一钱。（《经验方》）\n寒热疟疾，体虚汗多者。黄丹、百草霜等分，为末。发日，空心米饮服三钱，不过二服愈。或糊丸，或蒜丸，皆效。《肘后方》︰用飞炒黄丹一两，恒山末三两，蜜丸梧子大。每服五十丸，温酒下。平旦及未发、将发时，各一服，无不效。《普济方》︰端午日，用黄丹（炒）二两，独蒜一百个，捣丸梧子大。每服九丸，空心长流水面东下。二、三发后乃用，神效。亦治痢疾。\n《三因方》︰用黄丹（炒）、建茶等分。为末。温酒服二钱。又黄丹飞焙，面糊丸芡子大。每枣子一枚，去核，包一丸，纸裹煨熟食之。\n温疟不止︰黄丹（炒）半两，青蒿（童尿浸）二两，为末。每服二钱，寒多酒服，热多茶服。（《仁存堂方》）\n小儿瘅疟，壮热不寒。黄丹二钱，蜜水和服，冷者酒服，名鬼哭丹。（《刘涓子鬼遗方》）\n风痫发止︰驱风散︰用铅丹二两，白矾二两，为末。用三角砖相斗，以七层纸铺砖上，铺丹于纸上，矾铺丹上，以十斤柳木柴烧过为度，取研。每服二钱，温酒下。（王氏《博济方》）\n客忤中恶，道间门外得之，令人心腹刺痛，气冲心胸胀满，不治害人。真丹方寸匕，蜜三合，和灌之。（《肘后方》）\n一切目疾︰昏障，治；只障，不治。蜂蜜半斤，铜锅熬起紫色块，入飞过真黄丹二两，水一碗，再炼，至水气尽，以细生绢铺薄纸一层，滤净，瓶封埋地内三七。每日点眼七次，药粘则洗之。一方︰入诃子肉四个。（《保寿堂方》）\n赤眼痛︰黄丹，蜂蜜调贴太阳穴，立效。（《明目经验方》）\n赤目及翳︰铅丹、白矾等分，为末点之。又方︰铅丹、乌贼骨等分，合研，白蜜蒸点之。（《千金方》）\n眼生珠管︰铅丹半两，鲤鱼胆汁和如膏。日点三、五次。（《圣惠方》）\n痘疹生翳︰黄丹、轻粉等分，为末。吹少许入耳内，左患吹右，右患吹左。（《疹痘方》）\n小儿重舌︰黄丹一豆大，安舌下。（《子母秘录》）\n小儿口疮糜烂︰黄丹一钱，生蜜一两，相和蒸黑。每以鸡毛蘸搽，甚效。（《普济方》）\n腋下胡臭︰黄丹入轻粉，唾调，频掺之。（《普济方》）\n妇人逆产︰真丹涂儿足下。（《集验方》）\n蚰蜓入耳︰黄丹、酥、蜜、杏仁等分，熬膏。绵裹包塞之，闻香即出，抽取。（《圣惠方》）\n蝎虿螫人︰醋调黄丹涂之。（《肘后方》）\n金疮出血︰不可以药速合，则内溃伤肉。只以黄丹、滑石等分，为末敷之。（《集玄方》）\n外痔肿痛︰黄丹、滑石等分，为末。新汲水调，日五上之。（《婴童百问》）\n血风 疮︰黄丹一两，黄蜡一两，香油五钱，熬膏。先以葱、椒汤洗，贴之，（陆氏《积德堂方》）\n远近 疮︰黄丹（飞炒）、黄柏（酒浸七日，焙）各一两，轻粉半两。研细。以苦茶洗净，轻粉填满，次用黄丹护之，外以柏末摊膏贴之，勿揭动，一七见效。（孙氏《集效方》）"},
  "铅霜":{o:[],src:["本草纲目"],d:"旧二，新九。\n小儿惊热，心肺积热，夜卧多惊︰铅霜、牛黄各半分，铁粉一分。研匀。每服一字，竹沥调下。（《圣济录》）\n惊风痫疾，喉闭牙紧︰铅白霜一字，蟾酥少许。为末，乌梅肉蘸药于龈上揩之，仍吹通关药，良久便开。（《普济方》）\n消渴烦热︰铅白霜、枯白矾等分。为末，蜜丸芡子大。绵裹，含化咽汁。\n又方︰铅白霜一两，根黄、硝石各一两。为末。每冷水服一钱。（《圣济录》）\n喉痹肿痛︰铅白霜、甘草半两，青黛一两，为末，醋糊丸芡子大。每含咽一丸，立效。（《圣济录》）\n悬痈肿痛︰铅白霜一分，甘草（半生半炙）一分。为末。绵裹含咽。（《圣惠方》）\n口疳龈烂，气臭血出，不拘大人小儿。铅白霜、铜绿各二钱，白矾豆许。为末扫之。（《宣明方》）\n鼻衄不止︰铅白霜末。新汲水服一字。（《十全博救方》）\n痔疮肿痛︰铅白霜、白片脑各半字。酒调涂之，随手见效。（《婴童百问》）\n室女经闭，恍惚烦热︰铅霜半两，生地黄汁一合。调下，日三服。（《圣惠方》）\n梳发令黑︰铅霜包梳，日日梳之，胜于染者。（《普济方》）"},
  "铜绿":{o:["铜绿"],src:["本草备要"],d:"（即铜青）\n宣，去风痰酸平微毒。治风烂泪眼，恶疮疳疮，妇人血气心痛，吐风痰，合金疮，止血杀虫（治皆肝胆之病，亦金胜木之义）。用醋制，铜刮用。"},
  "铜青":{o:[],src:["本草纲目"],d:"旧二，新十一。\n风痰猝中︰碧琳丹︰治痰涎潮盛，卒中不语，及一切风瘫。用生绿二两，乳细，水化去石，慢火熬干，取辰日、辰时、辰位上修合，再研入麝香一分，糯米粉糊和丸弹子大，阴干。猝中者，每丸作二服，薄荷酒研下；余风，朱砂酒化下。吐出青碧涎，泻下恶物，大效。治小儿，用绿云丹︰铜绿不计多少，研粉，醋面糊丸芡子大。每薄荷酒化服一丸，须臾吐涎如胶，神效。（《经验方》）\n烂弦风眼︰铜青，水调涂碗底，以艾熏干，刮下，涂烂处。（《卫生易简方》）\n赤发秃落︰油磨铜钱衣，涂之即生。（《普济方》）\n面 黑痣︰以草划破，铜绿末敷之，三日勿洗水，自落。浓者，再上之。（《圣济录》）\n走马牙疳︰铜青、滑石、杏仁等分，为末，擦之立愈。（邵真人《经验方》）\n口鼻疳疮︰铜青、枯矾等分。研敷之。又方︰人中白一钱，铜绿三分。研敷之。杨梅毒疮︰铜绿醋煮研末，烧酒调搽，极痛出水，次日即干。或加白矾等分，研掺。（《简便方》）\n疮顽癣︰铜绿七分（研），黄蜡一两化熬，以浓纸拖过，表里别以纸隔贴之。出水妙。亦治杨梅疮及虫咬。（笔峰《杂兴》）\n肠风痔 ︰方见密陀僧下。\n诸蛇螫毒︰铜青敷之。（《千金方》）\n百虫入耳︰生油调铜绿滴入。（《卫生家宝方》）\n头上生虱︰铜青、明矾末，掺之。（《摘玄方》）"},
  "银":{o:["银"],src:["本草备要", "本草纲目"],d:"功用略同。"},
  "银朱":{o:[],src:["本草纲目"],d:"新二十。\n小儿内钓多啼︰银朱半钱，乳香、煨蒜各一钱，为末，研丸黍米大。半岁五丸，薄荷汤下。（《心鉴》）\n男女阴毒︰银朱、轻粉各一钱。用五日独蒜一枚，捣和作饼。贴手心，男左女右，两手合定，放阴下，顷间气回、汗出即愈。但口中微有气，即活。（唐瑶《经验方》）\n痰气结胸︰鹤顶丹︰不问阴阳虚实，炒过陷胸、泻心等药。用银朱半两，明矾一两，同碾。以熨斗盛火，瓦盏盛药，熔化，急刮搓丸。每服一钱，真茶入姜汁少许服之。心上隐隐有声，结胸自散。不动脏腑，不伤真气，明矾化痰，银朱破积，故也。（曾世荣《活幼全书》）\n正水肿病，大便利者︰银朱半两，硫黄四两。为末，面糊丸梧子大。每饮下三十丸。（《普济方》）\n咽喉疼痛︰银朱、海螵蛸末等分。吹之取涎。（《急救方》）\n火焰丹毒︰银朱调鸡子清涂之。（李楼《怪症方》）\n汤火灼伤︰银朱研细，菜油调敷，二次愈。（《多能鄙事》）\n疽疮发背︰银朱、白矾等分，煎汤温洗，却用桑柴火远远炙之，日三次，甚效。（《救急方》）\n鱼脐疔疮，四面赤，中央黑︰银朱，水和丸。每服一丸，温酒下，名走马丹。（《普济方》）\n杨梅毒疮︰银朱、官香等分。为末，以纸卷作捻，点灯置桶中。以鼻吸烟，一日一作，七日愈。\n又方︰银朱二钱，孩儿茶一钱，龙挂香一钱，皂角子一钱，为末。如上法用。\n又方︰银朱、轻粉各一钱，黄蜡、清油各一两，化开和收。以油纸摊贴，疮痂自脱也。\n筋骨疼痛︰猩红三钱，枯矾四钱。为末，作三纸捻。每旦以一捻蘸油点火熏脐，被覆卧之，取汗。（《纂要奇方》）\n日久顽疮不收者︰银朱一钱，千年地下锻石五分，松香五钱，香油一两。为末。化摊纸上贴之。（《应急良方》）\n疮不敛︰方同上。\n血风 疮生脚股上，乃湿毒成风也。黄蜡一两溶化，入银朱一两，搅摊纸上，刺孔贴之。（《简便方》）\n黄水湿疮︰银朱、盐梅和捣敷之。（《集玄方》）\n癣疮有虫︰银朱、牛骨髓，桐油调搽。（《医方摘要》）\n头上生虱︰银朱浸醋，日日梳头。包银朱纸，以碗覆烧之，茶清洗下烟子揉之。包头一夜，至旦虱尽死。（《积德堂方》）"},
  "锡":{o:[],src:["本草纲目"],d:"新二。\n解砒霜毒︰锡器，于粗石上磨水服之。（《济急方》）\n杨梅毒疮︰黑铅、广锡各二钱半（结砂），蜈蚣二条，为末，纸卷作小捻，油浸一夜，点灯日照疮二次，七日见效。（《集玄方》）"},
  "锡吝脂":{o:[],src:["本草纲目"],d:"新一。\n小儿天吊多涎，搐搦不定︰锡吝脂一两（水淘黑汁令尽），水银一分（以少枣肉研，不见星），牛黄半分，麝香半分，研匀，粳米饭丸黍米大。每服三十二丸，新汲水下，名保命丹。（《普济方》）"},
  "锻石":{o:[],src:["本草纲目"],d:"旧十四，新三十二。\n人落水死︰裹锻石纳下部中，水出尽即活。（《千金方》）\n痰厥气绝，心头尚温者︰千年锻石一合。水一盏，煎滚去清水，再用一盏煎极滚，澄清灌之。少顷痰下自愈。（《集玄方》）\n中风口 ︰新锻石醋炒，调如泥，涂之。左涂右，右涂左，立便牵正。（寇氏《衍义》）\n风牙肿痛︰二年锻石、细辛等分。研。搽即止。（《普济方》）\n虫牙作痛︰矿灰，沙糖和，塞孔中。（《普济方》）\n风虫牙痛︰百年陈锻石（为末）四两，蜂蜜三两。拌匀，盐泥固济，火 一日，研末。擦牙神效。名神仙失笑散。（张三丰方）\n干霍乱病︰千年锻石，沙糖水调服二钱，或淡醋汤亦可。名落盏汤。（《摘玄方》）\n偏坠气痛︰陈锻石（炒）、五倍子、山栀子等分。为末。面和醋调，敷之，一夜即消。（《医方摘要》）\n妇人血气︰方见兽部猪血下。\n产后血渴不烦者︰新锻石一两，黄丹半钱。渴时浆水调服一钱。名桃花散。（张洁古《活法机要》）\n白带白淫︰风化锻石一两，白茯苓三两。为末。糊丸梧子大。每服二、三十丸，空心米饮下，绝妙。（《集玄方》）\n水泻不止︰方同上。\n酒积下痢︰锻石五两，水和作团，黄泥包， 一日夜，去泥为末，醋糊丸梧子大。每服三十丸，姜汤空心下。（《摘玄方》）\n血痢十年︰锻石三升熬黄，水一斗投之，澄清。一服一升，日三服。（崔知悌方）\n虚冷脱肛︰锻石烧热，故帛裹坐，冷即易之。（《圣惠方》）\n产门不闭，产后阴道不闭，或阴脱出。锻石一斗熬黄，以水二斗投之，澄清，熏。（《肘后方》）\n产门生合不开︰用铜钱磨利割开，以陈锻石敷之，即愈。（《通变方》）\n腹胁积块︰风化锻石半斤，瓦器炒极热，入大黄末一两，炒红取起，入桂末半两，略烧，入米醋和成膏，摊绢上贴之。内服消块药，甚效。（《丹溪心法》）\n疟疾寒热，一日一发或二、三发，或三日一发。古城锻石二钱，头垢、五灵脂各一钱。研末，饭丸皂子大。每服一丸，五更无根水下，即止。（《集玄方》）\n老小暴嗽︰锻石一两，蛤粉四钱，为末，蒸饼丸豌豆大，焙干。每服三十丸，温齑汁下。（《普济方》）\n猝暴吐血︰锻石于刀头上烧研，井水下二钱。（《普济方》）\n发落不止，乃肺有劳热，瘙痒。用锻石三升，水拌炒焦，酒三升浸之。每服三合，常令酒气相接，则新发更生，神验。（《千金翼》）\n染发乌须︰矿灰一两，水化开，七日，用铅粉一两研匀，好醋调搽，油纸包一夜。先以皂角水洗净乃用。（《集玄方》）\n身面疣目︰苦酒浸锻石，六、七日，取汁频滴之，自落。（《千金方》）\n面 疣痣︰水调矿灰一盏，好糯米全者，半插灰中，半在灰外，经宿米色变如水精。先以针微拨动，点少许于上，经半日汁出，剔去药，不得著水，二日而愈也。（《集玄方》）\n疣痣瘤赘︰锻石一两，用桑灰淋汁熬成膏。刺破点之。（《普济方》）\n痈疽瘀肉︰锻石半斤，荞麦秸灰半斤，淋汁煎成霜，密封。每以针画破涂之，自腐。（《普济方》）\n疔疮恶肿︰锻石、半夏等分，为末，敷之。（《普济方》）\n脑上痈疖︰锻石入饭内捣烂，合之。（李楼《奇方》）\n痰核红肿寒热，状如瘰疬。锻石火 为末，以白果肉同捣，贴之。蜜调亦可。（《活人心统》）\nKT 肿痛︰醋调锻石敷之。（《简便方》）\n多年恶疮︰多年锻石，研末，鸡子清和成块， 过再研，姜汁调敷。（《救急方》）\n疮不合︰古冢中锻石，浓敷之。（《千金方》）\n痔疮有虫︰古锻石、川乌头（炮）等分。为末，烧饭丸梧子大。每服二、三十丸，白汤下。（《活法机要》）\n疥疮有虫︰锻石淋汁，洗之数次。（孙真人方）\n血风湿疮︰千年陈锻石研搽，痛即止，疮即愈，神效。（蔺氏方）\n火焰丹毒︰醋和锻石，涂之，或同青靛涂。（《摘玄方》）\n猝发风疹︰醋浆，和锻石涂之，随手灭。元希声侍郎秘方也。（《外台秘要》）\n夏月痱子︰锻石一两，蛤粉二两，甘草一两。研，扑之。（《集玄方》）\n汤火伤灼︰年久锻石，敷之。或加油调。（《肘后方》）\n杖疮肿痛︰新锻石，麻油调搽，甚妙。（《集简方》）\n刀刃金疮︰锻石裹之，定痛止血，又速愈。疮深不宜速合者，入少滑石敷之。（《肘后方》）\n误吞金银或钱，在腹内不下。锻石、硫黄一皂子大。同研为末。酒调服之。（孙用和《秘宝方》）\n马汗入疮︰锻石敷之。（《摘玄方》）\n蝼蛄咬人︰醋和锻石涂之。（《圣惠方》）\n蚯蚓咬人，其毒如大风，眉须皆落。以锻石水浸之，良。（《经验方》）\n古墓中锻石（名地龙骨）\n\n新三。\n软疖不愈︰烂船底油锻石，研末。油调敷之。（胡氏方）\n下体癣疮︰ 船灰、牛粪，烧烟熏之，一日一次，即安。（《医方摘玄》）\n血风 疮︰船上旧油灰，将泥作釜，火 过研末，入轻粉少许，苦茶洗净，敷之。忌食发物。（邓真人《经验方》）"},
  "长松":{o:[],src:["本草纲目"],d:"新一。\n长松酒︰滋补一切风虚，乃庐山休休子所传。长松一两五钱（状似独活而香，乃酒中圣药也）。熟地黄八钱，生地黄、黄耆（蜜炙）、陈皮各七钱，当归、浓朴、黄柏各五钱，白芍药（煨）、人参、枳壳各四钱，苍术（米泔制）、半夏（制）、天门冬、麦门冬、砂仁、黄连各三钱，木香、蜀椒、胡桃仁各二钱，小红枣肉八个，老米一撮，灯心（五寸长）一百二十根。一料分十剂，绢袋盛之。凡米五升，造酒一尊，煮一袋，窨久乃饮。（《韩氏医通》）"},
  "防葵":{o:[],src:["本草纲目"],d:"旧一，新二。\n肿满洪大︰防葵研末，温酒服一刀圭，至二、三服，身 及小不仁为效。（《肘后方》）\n癫狂邪疾︰方同上。\n伤寒动气，伤寒汗下后，脐左有动气︰防葵散︰用防葵一两，木香、黄芩、柴胡各半两。每服半两，水一盏半，煎八分，温服。（云岐子《保命集》）"},
  "阴地厥":{o:[],src:["本草纲目"],d:"新一。\n男妇吐血后，胸膈虚热︰阴地厥、紫河车、贯众、甘草各半两。每服三钱，水煎服。（《圣济总录》）"},
  "阴阳水":{o:["阴阳水"],src:["本草备要"],d:"（一名生熟水）\n宣、和阴阳治霍乱吐泻有神功（阴阳不和而交争，故上吐下泻。而霍乱饮此辄定者，分其阴阳，使和平也。按∶霍乱有寒、热二证，药中能治此者甚多，然未尝分别言之。仓卒患此，脉候未审，慎勿轻投偏热、寒之剂。曾见有霍乱服姜汤而立毙者，唯饮阴阳水为最稳。霍乱邪在上焦则吐，邪在下焦则泻，邪在中焦则吐泻兼作，此湿霍乱，症轻易治。又有心腹绞痛、不得吐泻者，名干霍乱，俗名绞肠痧，其死甚速。古方用盐熬热，童便调饮，极为得治。勿与谷食，即米汤下咽亦死）。以沸汤半钟，井水半钟和服。"},
  "阿魏":{o:["阿魏"],src:["本草备要"],d:"泻，消积，杀虫\n辛平（一日温）。入脾胃。消肉积，杀细虫，去臭气（谚曰∶黄芩无假，阿魏无真。刘纯曰∶阿魏无真却有真，臭而止臭是为珍），解蕈菜，自死牛马肉毒。治心腹冷痛、疟痢（疟痢多由积滞而起），传尸、疳劳疰虫。出西番。木脂熬成，极臭。试取少许，安铜器一宿，沾处白如银，汞者真（人多以胡蒜白赝之）。用钵研细，热酒器上熏过入药。"},
  "降真香":{o:["降真香"],src:["本草备要"],d:"（焚之能降诸真，故名）\n宣，辟恶、止血、生肌辛温。辟恶气怪异，疗伤折金疮，止血定痛，消肿生肌（周崇逐寇被伤，血出不止，敷花芯石散，不效。军士李高，用紫金藤散敷之，血止痛定，明日结痂无瘢，曾救万人。紫金藤，即降真香之最佳者也）。"},
  "雀瓮":{o:[],src:["本草纲目"],d:"新六。\n撮口噤风︰用棘科上雀儿饭瓮子未开口者，取内物和乳汁研，灌之。又方︰棘刚子五枚，赤足蜈蚣一条，烧存性，研匀，饭丸麻子大。每服三、五丸，乳汁下。亦可末服一字。（并《圣惠》）\n小儿脐风︰白龙散︰用天浆子（有虫者）一枚，真僵蚕（炒）一枚，腻粉少许，研匀。\n以薄荷自然汁调，灌之。取下毒物神效。（《普济方》）\n急慢惊风，口眼 斜，搐搦痰盛︰用天浆子房（去皮，生用）三枚，干蝎（生用）七枚，朱砂一钱，研匀，饭丸粟大。每服二丸，荆芥汤送下。（《圣惠方》）\n乳蛾喉痹︰用天浆子（即红姑娘），徐徐嚼咽。\n小儿痫疾︰棘枝上雀瓮，研，其间虫出，取汁灌之。（《圣惠方》）"},
  "雄黄":{o:["雄黄"],src:["本草备要", "本草纲目"],d:"重，解毒，杀虫\n辛温有毒。得正阳之气，入肝经气分。搜肝强脾，散百节大风，杀百毒，辟鬼魅。治惊痫痰涎，头痛眩晕，暑疟 痢，泄泻积聚（虞雍公道中冒暑，泄痢连月，梦至仙居，延之坐。壁中有词云∶暑毒在脾，湿气连脚，不泄则痢，不痢则疟。独炼雄黄，蒸饼和药，甘草作汤，食之安乐。别作治疗，医家大错。如方服之遂愈）。又能化血为水，燥湿杀虫，治劳疳疮疥蛇伤。赤似鸡冠，明彻不臭，重三五两者良。醋浸，入莱菔汁煮，干用。生山阴者名雌黄，功用略同。劣者名熏黄，烧之则臭，只堪熏疮疥，杀虫虱。"},
  "雌黄":{o:[],src:["本草纲目"],d:"旧七，新五。\n反胃吐食︰雌黄一分，甘草（生）半分。为末，饭丸梧子大。以五叶草、糯米煎汤，每服四丸。（《圣济录》）\n停痰在胃，喘息不通，呼吸欲绝︰雌黄一两，雄黄一钱。为末，化蜡丸弹子大。每服一丸，半夜时投热糯米粥中食之。（《济生方》）\n心痛吐水，不下饮食，发止不定︰雌黄二两，醋二斤，慢火煎成膏，用干蒸饼和丸梧子大。每服七丸，姜汤下。（《圣惠方》）\n妇人久冷，血气攻心，痛不止︰以叶子雌黄二两。细研，醋一升，煎浓，和丸小豆大。每服十五丸，醋汤下。（《圣惠方》）\n小腹痛满，天行病，小腹满，不得小便。雌黄末，蜜丸，纳尿孔中，入半寸。（《肘后方》）\n癫痫螈 ，眼暗嚼舌︰雌黄、黄丹（炒）各一两。为末，入麝香少许，以牛乳汁半升熬成膏，和杵千下，丸麻子大。每温水服三、五丸。（《直指方》）\n肺劳咳嗽︰雌黄一两，入瓦合内，不固济，坐地上，以灰培之，浓二寸；以炭一斤簇定顶，火 三分去一，退火出毒，为末，蟾酥和丸粟米大。每日空心杏仁汤下三丸。（《斗门方》）\n久嗽暴嗽︰金粟丸︰用叶子雌黄一两研。以纸筋泥固济小合子一个，令干，盛药。水调赤石脂封口，更以泥封，待干，架在地上，炭火十斤簇 。候火消三分之一，去火，候冷取出，当如镜面，光明红色；钵内细研，蒸饼丸粟米大。每服三丸、五丸，甘草水服。服后睡良久。（《胜金方》）\n肾消尿数︰干姜半两，以盐四钱（炒黄成颗），雌黄一两半。为末，蒸饼和丸绿豆大。每服十丸至三十丸，空心盐汤下。（《圣济录》）\n小便不禁︰颗块雌黄一两半（研），干姜半两，盐四钱（同炒姜色黄）。为末，水和蒸饼丸绿豆大。每服十丸至二十丸，空心盐汤下之。（《经验方》）\n乌癞虫疮︰雌黄粉，醋和鸡子黄调，涂之。（《圣惠方》）\n牛皮顽癣︰雌黄末，入轻粉，和猪膏敷之。（《直指方》）"},
  "雚菌":{o:[],src:["本草纲目"],d:"旧一。\n蛔虫攻心如刺，吐清汁者︰萑菌一两杵末，羊肉 和食之，日一顿，大效。（《外台秘要》）"},
  "露水":{o:["露水"],src:["本草备要"],d:"润肺\n甘平。止消渴，宜煎润肺之药。秋露造酒最清冽，百花上露，令人好颜色（霜杀物，露滋物，性随时异也。露能解暑，故白露降则处暑矣。疟必由于暑，故治疟药，露一宿服）。"},
  "露蜂房":{o:["露蜂房"],src:["本草备要", "本草纲目"],d:"宣，解毒，杀虫\n甘平有毒。治惊痫螈 ，附骨痈疽，根在脏腑（和蛇蜕、乱发、烧灰酒服。按∶附骨疽不破，附骨成脓，故名。不知者，误作贼风治。附骨疽痛处发热，四体乍热乍寒，小便赤，大便秘而无汗，泻热发散则消。贼风痛处不热，亦不发寒热，觉身冷，欲得热熨则小宽，时有汗，宜风药治之），涂瘰 成 （音漏。炙研，猪脂和涂），止风、虫牙痛（煎水含嗽。时珍曰∶阳明药也，取其以毒攻毒，兼杀虫之功耳），敷小儿重舌（烧灰酒和敷舌下，日数次），起阴痿（烧灰敷阴上）。取悬于树、受风露者，炙用（治痈肿，醋调涂。洗疮，煎用）。"},
  "青盐":{o:["青盐"],src:["本草备要"],d:"（即戎盐）\n补肾，泻血热甘咸而寒。入肾经，助水脏，平血热。治目痛赤涩，吐血溺血，齿舌出血，坚骨固齿（擦牙良），明目乌须。余同食盐，出西羌。不假煎炼，方棱明莹色青者良。"},
  "青鱼":{o:[],src:["本草纲目"],d:"新八。\n乳蛾喉痹︰青鱼胆含咽。一方︰用汁灌鼻中，取吐。万氏︰用胆矾盛青鱼胆中，阴干。\n每用少许，吹喉取吐。一方︰用朴硝代胆矾。\n海螵蛸末等分。龚氏《易简》︰用黄连切片入片脑少许，瓶收密封。每日点之，甚妙。\n各七个、牛胆半两，熊胆二钱半，麝香少许，石决明一两。为末，糊丸梧子大。每空心茶下十丸。（《龙木论》）"},
  "青鱼胆":{o:["青鱼胆"],src:["本草备要"],d:"泻热，治目疾\n苦寒色青。入肝胆。治目疾，点眼消赤肿障翳，咽津吐喉痹痰涎，涂火热疮，疗鱼骨哽。腊月收，阴干。"},
  "青黛":{o:["青黛"],src:["本草备要", "本草纲目"],d:"泻肝，散郁火\n咸寒，色青泻肝。散五脏郁火，解中、下焦蓄蕴风热（《衍义》曰∶一妇患脐、腹、二阴遍生湿疮，热痒而痛，出黄汁，二便涩。用鳗鲡、松脂、黄丹之类涂之，热痛愈甚。其妇嗜酒，喜食鱼、虾发风之物。乃用马齿苋四两研烂，入青黛一两和涂，热痛皆去，仍服八正散而愈。此中、下焦蓄蕴风热。毒瓦斯若不出，当作肠风、内痔。妇不能禁酒物，果仍发痔）。治伤寒发斑，吐咯血痢（阴虚火炎者忌用。合杏仁研，置柿饼中煨食，名圣饼子，治咯血）。小儿惊痫，疳热丹热，敷痈疮、蛇犬毒。即靛花。取娇碧者，水飞净用（内多锻石，故须淘净）。"},
  "韭":{o:["韭"],src:["本草备要", "本草纲目"],d:"补阳，散瘀\n辛温微酸。肝之菜也，入血分而行气。归心益胃，助肾补阳（一名土钟乳，言温补也），除胃热，充肺气，散瘀血，逐停痰。治吐衄损伤，一切血病（捣汁童便和服），噎膈反胃（能消瘀血停痰在胃口，治反胃及胃脘痛。丹溪曰∶有食热物及郁怒，致死血留胃口作痛者，宜加韭汁、桔梗入药，开提气血；有肾气上攻，致心痛者，宜韭汁和五苓散为丸，空心茴香汤下。治反胃宜用牛乳加韭汁、姜汁，细细温服。盖韭汁散瘀，姜汁下气消痰和胃，牛乳解热润燥补虚也。《单方总录》曰∶食不得入，是有火也；食久反出，是无火也。治法虽有寒、热、虚、实之别，要以安其胃气为本。使阴阳升降平均，呕逆自顺而愈矣），解药毒，食毒，狂犬、蛇、虫毒。多食昏神，忌蜜、牛肉（昂按∶今人多以韭炒牛肉，其味甚佳，未见作害。经曰∶毒药攻邪，五谷为养，五畜为益，五菜为充，五果为助，气味合而服之，以补精益气。五菜，韭、薤、葱、葵、藿也；五果，桃、李、枣、杏、栗也）。韭子辛甘而温，补肝肾，助命门，暖腰膝。治筋痿遗尿，泄精溺血，白带白淫（经曰∶足厥阴病则遗尿。思想无穷，入房太甚，发为筋痿及白淫。韭子同龙骨、桑螵蛸，能治诸病，以其入厥阴补肝、肾、命门。命门者，藏精之府也）。蒸、曝、炒，研用（烧烟熏牙虫）。"},
  "预知子":{o:["预知子"],src:["本草备要", "本草纲目"],d:"补劳，泻热\n苦寒。补五劳七伤。治 癖气块，天行温疾，蛇虫咬毒。杀虫疗蛊（缀衣领中，凡遇蛊毒，则闻其声而预知之，故名），利便催生。藤生，子如皂角，褐色光润。出蜀中，云亦难得。"},
  "风延母":{o:[],src:["本草纲目"],d:"新一。\n烂弦风眼︰千里光草，以笋壳叶包煨熟，捻汁滴入目中。（《经验良方》）"},
  "飞廉":{o:[],src:["本草纲目"],d:"旧一。若不痛，非疳也。下部虫如马尾大，相缠出无数。十日瘥，二十日平复。（《千金翼方》）"},
  "食盐":{o:["食盐"],src:["本草备要", "本草纲目"],d:"泻热，润燥，补心，通二便，宣，引吐\n咸甘辛寒。咸润下，故通大、小便；咸走血而寒胜热，故治目赤痈肿，血热热疾；咸补心，故治心虚（以水制火，取既济之义，故补心药用盐炒。一人病笑不休，用盐 赤煎沸，饮之而瘳。经曰∶神有余则笑不休。神，心火也。用盐，水制火也。一妇病此半年，张子和亦用此法而愈）；咸入肾而主骨（故补肾药用盐汤下），故坚肌骨，治骨病齿痛（擦牙亦佳，清火固齿。齿缝出血，夜以盐浓敷龈上，沥涎尽乃卧。或问咸能软坚，何以坚肌骨，不知骨消筋缓，皆因湿热，热淫于内，治以咸寒，譬如生肉易溃，得盐性咸寒，则能坚久不坏也）；咸润燥而辛泄肺（煎盐用皂角收，故味微辛）故治痰饮喘逆（《本经》∶治喘逆。惟哮症忌之）；咸软坚，故治结核积聚。又能涌吐醒酒（水胜火），解毒（火热即毒也，能散火凉血）杀虫（浙西将军蚓毒，每夕蚓鸣于体，一僧教以盐汤浸身，数次而愈），定痛止痒（体如虫行，风热也，盐汤浴三四次佳。亦治一切风气。凡汤火伤，急以盐生掺之，护肉不坏，再用药敷）。多食伤肺、走血、渗津发渴（《经曰》∶咸走血，血病毋多食咸。食咸则口干者，为能渗胃中津液也），凡血病哮喘、水肿、消渴人为大忌（盐品颇多，江淮南北盐生于海；山西解州盐生于池；四川、云南盐生于井；戎盐生于土；光明盐或生于阶州山崖，或产于五原盐池。状若水晶，不假煎炼，一名水晶盐；石盐生于石；木盐生于树；蓬盐生于草，造化之妙，诚难穷矣）。"},
  "香蒲":{o:[],src:["本草纲目"],d:"旧一新一。\n妒乳乳痈︰蒲黄草根捣封之，并煎汁饮及食之。（昝殷《产宝》）\n热毒下痢︰蒲根二两，粟米二合，水煎服，日二次。（《圣济总录》）"},
  "马先蒿":{o:[],src:["本草纲目"],d:"旧一。大疯癞疾，骨肉疽败，眉须堕落，身体痒痛︰以马先蒿（一名马矢蒿，一名烂石草），炒捣末。每服方寸匕，食前温酒下，一日三服，一年都瘥。（《肘后方》）"},
  "马兜铃":{o:["马兜铃"],src:["本草备要", "本草纲目"],d:"泻肺，下气\n体轻而虚。熟则四开象肺，故入肺。寒能清肺热。苦辛能降肺气（时珍曰∶钱乙补肺阿胶散用之，非取其补肺，取其清热降气，则肺自安也。其中阿胶糯米，乃补肺之正药。昂按∶清热降气，泻之即所以补之，若专一于补，适以助火而益嗽也）。治痰嗽喘促，血痔 疮，大肠经热（ ，漏也，音闾，亦音漏。痔属大肠，大肠与肺为表里。肺移热于大肠，故肠风痔 ，清脏热则腑热亦清矣。《千金》单服治水肿，以能泻肺行水也），亦可吐蛊（汤剂中用之，多作吐）。蔓生，实如铃，去筋膜，取子用。"},
  "马兰":{o:[],src:["本草纲目"],d:"新六。\n诸疟寒热︰赤脚马兰捣汁，入水少许，发日早服，或入少糖亦可。（《圣济总录》）\n绞肠沙痛︰马兰根叶，细嚼咽汁，立安。（《寿域神方》）\n打伤出血︰竹节草即马兰，同旱莲草、松香、皂子叶（即柜子叶，冬用皮）。为末。搽入刀口。（《摘玄方》）\n喉痹口紧︰用地白根即马兰根，或叶捣汁，入米醋少许，滴鼻孔中，或灌喉中，取痰自开。（孙一松《试效方》）\n水肿尿涩︰马兰菜一虎口，黑豆、小麦各一撮。酒、水各一钟，煎一钟，食前温服以利小水，四五日愈。（杨起《简便方》）\n缠蛇丹毒︰马兰、甘草擂醋搽之。（《济急方》）"},
  "马勃":{o:["马勃"],src:["本草备要", "本草纲目"],d:"轻，解热，外用敷疮\n辛平轻虚。清肺解热（东垣普济消毒饮中用之），散血止嗽。治喉痹咽痛（吹喉中良，或加白矾，或硝扫喉，取吐痰愈），鼻衄失音，外用敷诸疮良。生湿地朽木上。状如肺肝，紫色虚软，弹之粉出，取粉用。"},
  "马蓝":{o:[],src:["本草纲目"],d:"旧十，新七。\n小儿赤痢︰捣青蓝汁二升，分四服。（《子母秘录》）\n小儿中蛊，下血欲死︰捣青蓝汁，频服之。（《圣惠方》）\n阴阳易病，伤寒初愈，交合阴阳，必病拘急，手足拳，小腹急热，头不能举，名阴阳易，当汗之。满四日难治︰蓝一把，雄鼠屎三十枚，水煎服，取汗。（《肘后方》）\n惊痫发热︰干蓝、凝水石等分。为末，水调敷头上。（《圣惠方》）\n上气咳嗽，呷呀息气，喉中作声，唾粘︰以蓝叶水浸捣汁一升，空腹频服。须臾以杏仁研汁，煮粥食之。一两日将息，依前法更服，吐痰尽方瘥。（《梅师方》）\n飞血赤目热痛︰干蓝叶（切）二升，车前草半两，淡竹叶（切）三握。水四升，煎二升，去滓温洗。冷即再暖，以瘥为度。（《圣济总录》）\n腹中鳖症︰蓝叶一斤（捣）。以水三升，绞汁服一升，日二次。（《千金方》）\n应声虫病，腹中有物作声，随人语言，名应声虫病︰用板蓝汁一盏。分五服，效。（夏子益《奇疾方》）\n卒中水毒︰捣蓝青汁，敷头身令匝。（《肘后方》）\n服药过剂烦闷，及中毒烦闷欲死。捣蓝汁服数升。（《肘后方》）\n卒自缢死︰以蓝汁灌之。（《千金方》）\n毒箭伤人︰蓝青捣饮并敷之。如无蓝，以青布渍汁饮。（《肘后方》）\n唇边生疮，连年不瘥︰以八月蓝叶一斤。捣汁洗之，不过三度瘥。（《千金方》）\n齿 肿痛︰紫蓝，烧灰敷之，日五度。（《广济方》）\n白头秃疮︰粪蓝，煎汁频洗。（《圣济录》）\n天泡热疮︰蓝叶捣敷之，良。（《集简方》）\n疮疹不快︰板蓝根一两，甘草一分。为末。每服半钱或一钱，取雄鸡冠血三、二点，同温酒少许调下。（《钱氏小儿方》）"},
  "马蔺子":{o:["马蔺子"],src:["本草备要"],d:"（一名蠡实）\n泻湿热，解毒甘平。治寒疝喉痹，痈肿疮疖，妇人血气烦闷，血运崩带。利大、小肠。久服令人泻。丛生，叶似薤而长浓，结角子如麻大，赤色有棱。炒用。治疝用醋拌。根、叶同功。"},
  "马蕲":{o:[],src:["本草纲目"],d:"新一。\n慢脾惊风：马芹子、丁香、白僵蚕等分，为末。每服一钱，炙橘皮煎汤下。名醒脾散。（《普济方》）"},
  "马鞭草":{o:["马鞭草"],src:["本草备要", "本草纲目"],d:"泻，破血，消胀，杀虫\n味苦微寒。破血通经，杀虫消胀。治气血症瘕，痈疮阴肿（捣汁涂敷）。墟陌甚多。方茎，叶似益母对生，夏、秋开细紫花，穗如车前草，类蓬蒿而细，根白而小。用苗、叶。"},
  "马齿苋":{o:["马齿苋"],src:["本草备要", "本草纲目"],d:"（一名九头狮子草）\n泻热，散血酸寒。散血解毒，祛风杀虫。治诸淋疳痢（《海上方》∶捣汁，和鸡子白服，治赤白痢），血癖恶疮（多年恶疮，敷两三遍即瘥。烧灰煎膏，涂秃疮湿癣），小儿丹毒（捣汁饮，以滓涂之），利肠滑产。叶如马齿，有大、小二种，小者入药。性至难燥，去茎用（亦忌鱼、鳖同食）。"},
  "驴溺":{o:["驴溺"],src:["本草备要"],d:"泻，杀虫\n辛寒。杀虫，治反胃噎膈（须热饮之。张文仲《备急方》曰∶昔患反胃，奉敕调治，竟不能疗。一卫士云∶服驴屎极验。遂服二合，只吐一半，再服二合，食粥便定。宫中患反胃者五六人，同服之俱瘥）。"},
  "鬼臼":{o:[],src:["本草纲目"],d:"新三。\n子死腹中，胞破不生，此方累效，救人岁万数也︰鬼臼不拘多少，黄色者，去毛为细末，不字神散。（《妇人良方》）\n射工中人，寒热发疮︰鬼臼叶一把，苦酒渍，捣取汁。服一升，日二次。（《千金方》）\n黑黄急病，黑黄，面黑黄，身如土色，不妨食，脉沉，若青脉入口者死。宜烙口中黑脉、百会、玉泉、绝骨、章门、心俞︰用生鬼臼捣汁一小盏服。干者为末，水服"},
  "鬼针草":{o:[],src:["本草纲目"],d:"新一。\n割甲伤肉不愈︰鬼针草苗、鼠粘子根捣汁，和腊猪脂涂。（《千金》）"},
  "鮧鱼":{o:[],src:["本草纲目"],d:"身面白驳︰ 鱼（半斤）一头，去肠，以粳饭、盐、椒如常作 ，以荷叶作三包系之。\n更以荷叶重包，令臭烂。先以布拭赤，乃炙 包，乘热熨，令汗出。以绵衣包之，勿令见风，以瘥为度。（《总录\n涎\n\n新一。\n骨鲠在喉︰栗子肉上皮半两（研末），乳香、 鱼肝各一分，同捣，丸梧子大。以绵裹一丸，水润，外留绵线吞下，钓出。（《总"},
  "鱁鮧":{o:[],src:["本草纲目"],d:"新一。\n折伤出血但不透膜者︰以海味中咸白鳔，大片色白有红丝者，成片铺在伤处，以帛缚之，即止。（《普济方》）\n\n新十一。\n产难︰鱼胶五寸，烧存性为末。温酒服。（《皆效方》）\n产后搐搦强直者︰不可便作风中，乃风入子脏，与破伤风同。用鳔胶一两，以螺粉炒焦，去粉为末。分三服，煎蝉蜕汤下。（《产宝》）\n产后血晕︰鳔胶烧存性，酒和童子小便调服三、五钱良。（《事林广记》）\n经血逆行︰鱼胶切炒，新绵烧灰。每服二钱，米饮调下，即愈。（《多能鄙事》）\n破伤风搐口噤强直者︰危氏香胶散︰用鱼胶（烧存性）一两，麝香少许，为末。每服二钱，苏木煎酒调下。仍煮一钱封疮口。《保命集》︰治破伤风，有表证未解者。用江鳔半两（炒焦），蜈蚣一对（炙研），为呕血不止︰鳔胶长八寸，广二寸，炙黄，刮二钱，以甘蔗节三十五个，取汁调下。（《经验》）\n便毒肿痛露（即羊核）。用石首胶一两，烧存八般头风︰鱼鳔烧存性为末。临卧以葱酒服二钱。\n赤白崩中︰鱼 胶三尺，焙黄研末，同鸡子煎饼，好酒食之。"},
  "鱓（善）鱼":{o:[],src:["本草纲目"],d:"新二。\n疮蛀烂︰用黄鳝鱼数条打死，香油抹腹，蟠疮上系定，顷则痛不可忍，然后取下看，腹有针眼皆虫也。未尽更作，后以人胫骨灰，油调搽之。（《奇效》）\n肉痔出血︰鳝鱼煮食，其性凉也。（《便民食疗》）\n血（尾上取之）"},
  "鱼子":{o:[],src:["本草纲目"],d:"新一。\n决明散︰治一切远年障翳， 生 肉，赤肿疼痛。用鱼子（活水中生下者）半两（以硫黄水温温洗净），石决明、草决明、青葙子、谷精草、枸杞子、黄连、炙甘草、枳实（麸炒）、牡蛎粉、蛇蜕（烧灰）、白芷、龙骨、黄柏各一两，白附子（炮）、白蒺藜（炒）、蝉蜕、黄芩（炒）、羌活各半两，虎睛一只（切作七片五更时茶服，午、夜再服。赤白翳膜鱼、酒、面、辛辣、色欲。凡遇恼不必医也。（《总录》）"},
  "鱼鲊":{o:[],src:["本草纲目"],d:"新二。\n白驳风︰以荷叶裹 令臭，拭代指痛︰先刺去脓血，炙 皮裹之。《千金方》。"},
  "鲍鱼":{o:[],src:["本草纲目"],d:"旧一。\n妊娠感寒腹痛︰干鱼一枚烧灰，酒服方寸匕，取汗瘥。（《子母秘录》）\n头\n\n新三。\n杂物瞇目︰鲍鱼头二枚，地肤子半合，水煮烂。取汁注目中，即出。（《圣惠》）\n鱼脐疔疮︰似新火针疮，四边赤，中央黑。可针刺之，若不大痛，即杀人也。用腊月鱼头灰、发灰等分，以鸡溏屎和，涂之。（预辟瘟疫︰鲍鱼头烧灰方寸匕，合小豆七枚末，米饮服之，令瘟疫气不相染也。（《肘后方》）\n鱼"},
  "鲚鱼":{o:[],src:["本草纲目"],d:"新一。\n有数孔︰用耕 土烧赤，以苦酒浸之，合壁土令热，以大次。（《千金方》）"},
  "鲛鱼":{o:[],src:["本草纲目"],d:"旧一，新一。\n治疰鲛鱼皮散︰颂曰︰胡洽治五尸鬼疰，百毒恶气。鲛鱼皮（炙）、朱砂、雄黄、金牙、蜀椒、细辛、鬼臼、干姜、莽草、天雄、麝香、鸡舌香、桂心各一两，贝母半两，蜈蚣、蜥蜴各（炙）二枚，为末。每服半钱，温酒服，日二。亦可佩之。\n时珍曰︰《千金》鲛鱼皮散︰治鬼疰。用鲛鱼皮（炙）、龙骨、鹿角、犀角、麝香、蜈蚣、雄黄、朱砂、干姜、蜀椒、 荷根、丁香等各一分，贝子十枚。为末。酒服方寸匕，加至二匕，日三服。亦可佩。\n胆（腊月收之）"},
  "鲤鱼":{o:["鲤鱼"],src:["本草备要", "本草纲目"],d:"通，行水\n甘平。下水气，利小便。治咳逆上气，香港脚黄胆，妊娠水肿（古方治水肿，有鲤鱼汤、鲤鱼粥。刘河间曰∶鲤之治水，鸭之利水，所谓因其气相感也）。鲤鱼骨烧灰，疗鱼骨哽。"},
  "鲫鱼":{o:["鲫鱼"],src:["本草备要", "本草纲目"],d:"补土和胃\n甘温。诸鱼属火，独鲫属土。土能制水，故有和胃、实肠、行水之功（作 食，治香港脚及上气）。忌麦冬、芥菜、沙糖、猪肝。"},
  "鲮鲤":{o:[],src:["本草纲目"],d:"旧四，新十九。\n中风瘫痪，手足不举︰用穿山甲（左瘫用右甲，右痪用左甲，炮熟）、大川乌头（炮熟）、红海蛤（如棋子大者）各二两，为末。每用半两，捣葱白汁和成浓饼，径寸半，随左右贴脚心，缚定。密室安坐，以贴药脚浸热汤盆中，待身麻汗出，急去药。宜谨避风，自然手足可举。\n半月再行一次，除根。忌口，远色，调养。亦治诸风疾。（《卫生宝鉴》）\n一两，干枣十个，同烧存性，为末。每服二钱，发日，五更井花水服。（《杨氏家藏》）\n里急︰穿山甲、蛤粉等分，同炒研末。每服一钱，空心温酒下。（《普济方》血︰用穿山甲（烧存性）一两，肉豆蔻三枚，为末。每米饮服二钱。甚者加 皮灰一两，中病即止。（《衍义》）\n香半钱，为末。每服一钱半，真茶汤猪脂调敷。（《千金方》）\n妇人阴 ，硬如卵状︰随病之左右，取穿山甲之左右边五钱，以沙炒焦黄，为末。每服二钱，酒下。（《摘玄方》）\n梳乳，即通。（《单骧方》）\n然铜（生用）半两，为末。每末。每服五分，入麝香少许，温酒服。即发红色，如神。（《直指方》）\n入谷芒热灰中，炮焦为末）二两，入麝香少许。\n马疔肿毒︰穿山甲（烧存性）、贝母等分为末。酒调服，三、四次。乃用下药，利去恶物即愈。（鲍氏方）\n和麻油、轻粉涂之。或只以末涂之。（《直指》）\n敷之。《寿域方》︰用穿山甲（土炒）、斑蝥、熟艾等分，为四壮，效。\n蚁入耳内︰鲮鲤甲烧研，水调，灌入即出。（《肘后》）\n许，吹之。三日水干即愈。（《鲍氏小儿方》）\n黄，为末。每吹一字入耳内。亦治耳聋。（《普济方》）\n水、钟、鼓声。用穿山甲一大片（以蛤粉炒赤），去粉，蝎梢七个，麝香少许，为末，以麻油一滴化蜡，和作梃子，绵裹塞之。（《摄生众妙方》）\n卷作绳，烧烟熏之。（《寿域方》）\n如此七次，为末。随左右眼，用亲》）\n肉"},
  "鳗鲡":{o:["鳗鲡"],src:["本草备要"],d:"补虚，杀虫\n甘平。去风杀虫（按∶虫由风生，故风字从虫）。治骨蒸劳瘵，湿痹风瘙，阴户蚀痒（皆有虫。张鼎云∶其骨烧烟，蚊化为水，熏竹木，辟蛀虫；置衣箱，辟诸蠹），补虚损（有病瘵者，相染已死数人。乃取病者钉之棺中，弃于流水，永绝传染。渔人异之，开视，见一女子尚活。取置渔舍，多食鳗鲡，病愈，遂以为妻。《圣惠方》∶鳗鲡淡炙食，治诸虫，心痛多吐，冷气上攻满闷）。"},
  "鳗鲡鱼":{o:[],src:["本草纲目"],d:"旧三。\n诸虫心痛，多吐清水︰鳗鲡淡煮，饱食三、五度，即瘥。（《外台》）\n骨蒸劳瘦︰用鳗鲡二肠风下虫︰同上。\n膏\n\n旧一。\n一切恶疮 用蛇鱼骨炙为末，入诸色膏药中贴之，外以纸护之。（《经验》）\n血"},
  "鳜鱼":{o:[],src:["本草纲目"],d:"旧一。\n骨鲠竹木刺入咽喉︰不拘大人小儿，日久或入脏腑，痛刺黄瘦甚者，服之皆出。腊月收鳜鱼胆，悬北檐下令干。每用一皂子许，煎酒温呷。\n得吐，则鲠随涎出。未吐再服，以吐为度。酒随量饮，无不出者。蠡、鲩、鲫胆皆可。（《"},
  "鳝鱼":{o:["鳝鱼"],src:["本草备要"],d:"宣，去风\n甘温。补五脏，除风湿。尾血，疗口眼 斜（少和麝香，左 涂右，右 涂左，正即洗去。《千金》云∶鳖血、鸡冠血和伏龙肝，并治口 ），滴耳治耳痛，滴鼻治鼻衄，点目治痘后生翳（时珍曰∶鳝善穿穴，与蛇同性。故能走经络，疗风邪及诸窍之病。风中血脉，用血主之，从其类也）。"},
  "鳢肠":{o:[],src:["本草纲目"],d:"旧一，新十一。\n金陵煎，益髭发，变白为黑︰金陵草一秤，六月以后收采，拣青嫩无泥土者。不用洗，摘去黄叶，烂捣，新布绞取汁，以纱绢滤过，入通油器钵盛之，日中煎五日。又取生姜一斤绞汁，白蜜一斤合和，日中煎，以柳本篦搅勿停手，待如稀饧，药乃成矣。每旦日及午后各服一匙，以温酒一盏化下。如欲作丸，日中再煎，令可丸，大如梧子，每服三十丸。及时多合为佳，其效甚速。（孙真人《千金月令方》）\n乌须固齿︰《摄生妙用方》︰七月取旱莲草（连根）一斤（用无灰酒洗净），青盐四两（腌三宿）。同汁入油锅中，炒存性，研末。日用擦牙，连津咽之。又法︰旱莲取汁，同盐炼干，研末擦牙。《寿亲养老新书》旱莲散︰乌髭固牙。温尉云︰纳合相公用此方，年七十须发不白，恳求始得。后遇张经历朝请，始传分两也。旱莲草一两半，麻枯饼三两，升麻、青盐各三两半，诃子（连核）二十个，皂角三梃，月蚕砂二两。为末，薄醋面糊丸弹子大，晒干入泥瓶中，火煨令烟出存性，取出研末。日用揩牙。\n偏正头痛︰鳢肠草汁滴鼻中。（《圣济总录》）\n一切眼疾，翳膜遮障，凉脑，治头痛，能生发。五月五日平旦合之︰莲子草一握，蓝叶一握，油一斤。同浸，密封四十九日。每卧时，以铁匙点药摩顶上，四十九遍，久久甚佳。（《圣济总录》）\n系臂截疟︰旱莲草捶烂，男左女右，置寸口上，以古文钱压定，帛系住，良久起小泡，谓之天灸。其疟即止，甚效。（王执中《资生经》）\n小便溺血︰金陵草（一名墨头草）、车前草各等分，杵取自然汁，每空心服三杯，愈乃止。（《医学正传》）\n肠风脏毒，下血不止︰旱莲子草，瓦上焙，研末。每服二钱，米饮下。（《家藏经验方》）\n痔漏疮发︰旱莲草一把，连根须洗净，用石臼擂如泥，以极热酒一盏冲入，取汁饮之，滓敷患处，重者不过三服即安。太仆少卿王鸣凤患此，策杖方能移步，服之得瘥。累治有验。（刘松石《保寿堂方》）\n疔疮恶肿︰五月五日收旱莲草阴干，仍露一夜收。遇疾时嚼一叶贴上，外以消毒膏护之，二三日疔脱。（《圣济总录》）\n风牙疼痛︰猢孙头草，入盐少许，于掌心揉擦即止。（《集玄方》）"},
  "鳢鱼":{o:[],src:["本草纲目"],d:"旧三，新二。\n十种水气垂死︰鳢鱼（一斤重者）煮汁，和冬瓜、葱白作羹食。（《心镜》）\n下一切气︰诜曰︰用大鳢一头开肚，入胡椒末半两，大蒜三两颗，缝合，同小豆一升煮熟，下萝卜三、五颗，葱一握，俱切碎，煮熟，空腹食之至饱，并饮汁。至夜，泄恶气无限也。三五日更一作。\n肠痔下血︰鳢鱼作 ，以蒜齑食之。忌冷、毒物。（《外台》）\n一切风疮顽癣疥癞︰年久不愈者，不过二、三服必愈。用黑火柴头鱼一个（即乌鳢也），去肠肚，以苍耳叶填满。外以苍耳安锅底，置鱼于上，少少著水，慢火煨熟，去皮骨淡食。\n勿入盐酱，功效甚大。（《医林集要》）\n浴儿免痘︰除夕黄昏时，用大乌鱼一尾，小者二三尾，煮汤浴儿，遍身七窍俱到。不可嫌腥，以清水洗去也。若不信，但留一手或一足不洗，遇出痘时，则未洗处偏多也。此乃异人所传，不可轻易。（杨拱《医方摘要》）\n肠及肝"},
  "鳢鱼胆":{o:["鳢鱼胆"],src:["本草备要"],d:"泻热\n凡胆皆苦，惟鳢鱼胆甘（昂按∶味终带苦）。喉痹将死者，点入即瘥，病深者水调灌之。俗名乌鱼，即七星鱼（首有七星，夜朝北斗，道家谓之水厌。雁为天厌，犬为地厌。《卫生》歌云∶雁行有序犬有义，黑鱼拱北知臣礼，人无礼义反食之，天地鬼神皆不喜。杨拱《医方摘要》云∶除夕黄昏时，取大黑鳢鱼一尾，小者二三尾，煮汤浴儿，遍身七窃俱到，能免出痘。不可嫌腥，而以清水洗去也。如不信，留一手或一足不洗，遇出痘时，不洗处痘必多。此乃异人所传，不可轻易。《食医心镜》∶鳢鱼一斤以上，和冬瓜、葱白作羹，治十种水气）。"},
  "鸡":{o:["鸡"],src:["本草备要"],d:"补\n属巽属木（故动风）。其肉甘温，补虚温中（日华曰∶黑雌鸡补产后虚劳。马益卿曰∶妊妇宜食牡鸡，取阳精之全于天也。崔行功曰∶妇人产死，多是富贵扰攘，致产妇惊乱故耳。屏人静产，更烂煮牡鸡汁作粳米粥与食，自然无恙。鸡汁性滑而濡，不食其肉，恐难化也。俗家每产后即食鸡啖卵，壮者幸无事，弱者因而致疾矣。龚云林曰∶四五年老母鸡，取汤煮粥食，能固胎）。鸡冠居清高之分，其血乃精华所聚，雄而丹者属阳。故治中恶惊忤（以热血 口、涂面、吹鼻良）；本乎天者亲上，故涂口眼 斜。用老者取其阳气充足也。能食百虫，故治蜈蚣、蚯蚓、蜘蛛咬毒。鸡子甘平。镇心，安五脏，益气补血，清咽开音，散热定惊，止嗽止痢（醋煮食，治赤、白久痢），利产安胎（胞衣不下者，吞卵黄二三枚，解发刺喉，令吐即下）。多食令人滞闷。哺雏蛋壳细研，麻油调，搽痘毒神效。鸡肫皮（一名鸡内金，一名 ，音皮鸱）甘平性涩。鸡之脾也。能消水谷，除热止烦，通小肠、膀胱。治泻痢便数，遗溺溺血，崩带肠风，膈消反胃，小儿食疟。男用雌，女用雄。鸡矢醴微寒，下气消积，利大、小便。《内经》用治膨胀（腊月取雄鸡屎白收之。醋和，涂蚯蚓、蜈蚣咬毒；合米炒，治米症）。"},
  "鸡冠花":{o:[],src:["本草纲目"],d:"新十一。\n吐血不止︰白鸡冠花，醋浸煮七次，为末。每服二钱，热酒下。（《经验方》）\n结阴便血︰鸡冠花、椿根白皮等分，为末，炼蜜丸梧子大。每服三十丸，黄 汤下，日二服。（《圣济总录》）\n粪后下血︰白鸡冠花并子（炒），煎服。（《圣惠方》）\n五痔肛肿久不愈，变成 疮︰用鸡冠花、凤眼草各一两。水二碗，煎汤频洗。（《卫生宝鉴》）\n下血脱肛︰白鸡冠花、防风等分，为末，糊丸梧子大，空心米饮每服七十丸。一方︰白鸡冠花（炒）、棕榈灰、羌活一两。为末。每服二钱，米饮下。（《永类钤方》）\n经水不止︰红鸡冠花一味，晒干为末。每服二钱，空心酒调下。忌鱼腥、猪肉。（孙氏\n《集效方》）\n产后血痛︰白鸡冠花，酒煎服之。（《李楼奇方》）\n妇人白带︰白鸡冠花晒干，为末。每旦空心酒服三钱。赤带，用红者。（孙氏《集效方》）\n白带沙淋︰白鸡冠花、苦壶卢等分，烧存性，空心火酒服之。（《摘玄》）\n赤白下痢︰鸡冠花，煎酒服。赤，用红；白，用白。（《集简方》）"},
  "鸡肠":{o:[],src:["本草纲目"],d:"旧四，新五。\n止小便利︰鸡肠草一斤，于豆豉汁中煮，和米作羹及粥，频食之。（《食医心镜》）。\n小儿下痢赤白︰鸡肠草捣汁一合，和蜜服，甚良。（孟诜《食疗》）。\n气淋胀痛︰鸡肠草三两，石苇（去毛）一两。每用三钱，水一盏，煎服。（《圣济总录》）。\n风热牙痛，浮肿发歇，元脏气虚，小儿疳蚀︰鸡肠草、旱莲草、细辛等分，为末。每日擦三次。名祛痛散。（《普济方》）。\n发背欲死︰鸡肠草捣敷之。（《肘后方》）。\n反花恶疮︰鸡肠草研汁拂之。或为末，猪脂调搽，极效。（《医林正宗》）。\n一切头疮︰鸡肠草烧灰，和盐敷之。（孟诜《食疗》）。\n漆疮瘙痒︰鸡肠草捣涂之。（《肘后方》）。\n射工中人成疮者︰以鸡肠草捣涂之，经日即愈。（卢氏方）"},
  "鸡苏":{o:["鸡苏"],src:["本草备要"],d:"（一名水苏，一名龙脑薄荷）\n轻，宣，散热，理血辛而微温。清肺下气理血，辟恶而消谷。治头风目眩，肺痿血痢，吐衄崩淋，喉腥口臭，邪热诸病（《局方》有龙脑鸡苏丸）。方茎中虚，似苏叶而微长，密齿面皱，气甚辛烈。"},
  "鸢尾":{o:[],src:["本草纲目"],d:"旧一，新一。\n飞尸游蛊著喉中，气欲绝者︰鸢尾根削去皮，纳喉中，摩病处，令血出为佳。（陈藏器\n《本草拾遗》）\n鬼魅邪气︰四物鸢头散︰东海鸢头、黄牙（即金牙）、莨菪子、防葵各一分，为末。酒服方寸\n《短剧方》）"},
  "鸭":{o:["鸭"],src:["本草备要"],d:"补阴\n甘冷。入肺、肾血分，滋阴补虚，除蒸止嗽，利水道，治热痢。白毛乌骨者，为虚劳圣药，取金肃水寒之象也（葛可久有白凤膏）。老者良。酒或童便煮。热血解金、银、丹石、砒霜诸毒及中恶、溺死者。卵甘咸微寒。能滋阴，除心腹膈热。盐藏，食良。"},
  "鸭跖草":{o:[],src:["本草纲目"],d:"新四。\n小便不通︰竹鸡草一两，车前草一两，捣汁入蜜少许，空心服之。（《集简方》）\n下痢赤白︰蓝姑草（即淡竹叶菜），煎汤日服之。（《活幼全书》）\n喉痹肿痛︰鸭跖草汁点之。（《袖珍方》）\n五痔肿痛︰耳环草（一名碧蝉儿花）， 软纳患处，即效。（危亦林《得效方》）"},
  "鹤虱":{o:["鹤虱"],src:["本草备要"],d:"泻，杀虫\n苦辛，有小毒。杀五脏虫，治蛔啮腹痛（面白唇红，时发时止者，为虫痛，肥肉汁调末服）。《沈存中笔记》云∶是杜牛膝子（或曰非也，别是一种）。最黏人衣。有狐气，炒热则香。"},
  "麦门冬":{o:[],src:["本草纲目"],d:"旧三，新九。麦门冬煎，补中益心，悦颜色，安神益气，令人肥健，其力甚快︰取新麦门冬根去心，捣熟绞汁，和白蜜，银器中重汤煮，搅不停手，候如饴乃成。温酒日日化服之。（《图经本草》）\n消渴饮水︰用上元板桥麦门冬（鲜肥者）二大两。宣州黄连（九节者）二大两，去两头尖三、五节，小刀子调理去皮毛了，吹去尘，更以生布摩拭秤之，捣末。以肥大苦瓠汁浸麦门冬，经宿然后去心，即于臼中捣烂，纳黄连末和捣，并手丸如梧子大。食后饮下五十丸，日再。但服两日，其渴必定。若重者，即初服一百五十丸，二日服一百二十丸，三日一百丸，四日八十丸，五日五十丸。合药要天气晴明之夜，方浸药。须净处，禁妇人鸡犬见之。如觉可时，每日只服二十五丸。服讫觉虚，即取白羊头一枚治净，以水三大斗煮烂，取汁一斗以来，细细饮之。勿食肉，勿入盐。不过三剂平复也。（崔元亮《海上集验方》）\n劳气欲绝︰麦门冬一两，甘草（炙）二两，粳米半合，枣二枚，竹叶十五片，水二升，煎一升，分三服。（《南阳活人书》）\n虚劳客热︰麦门冬煎汤频饮。（《本草衍义》）\n不效者︰麦门冬（去心）一斤，捣取自然汁，入蜜二合，分作二服，即止。（《活人心统》）\n衄血不止︰麦门冬（去心）、生地黄各五钱。水煎服，立止。（《保命集》）\n齿缝出血︰麦门冬煎汤漱之。（《兰室宝鉴》）\n咽喉生疮，脾肺虚热上攻也︰麦门冬一两，黄连半两，为末，炼蜜丸梧子大。每服二十丸，麦门冬汤下。（《普济方》）\n乳汁不下︰麦门冬（去心），焙为末。每用三钱，酒磨犀角约一钱许，温热调下，不过二服便下。（《熊氏补遗》）\n下痢口渴，引饮无度︰麦门冬（去心）三两，乌梅肉二十个，细锉，以水一升，煮取七合，细细呷之。（《必效》）\n金石药发︰麦门冬六两，人参四两，甘草（炙）二两，为末，蜜丸梧子大。每服五十丸，饮下，日再服。（《本草图经》）\n男女血虚︰麦门冬三斤（取汁熬成膏）、生地黄三斤（取汁熬成膏）等分。一处滤过，入蜜四之一，再熬成，瓶收。每日白汤点服。忌铁器。（《医方摘要》）"},
  "黄明胶":{o:["黄明胶"],src:["本草备要"],d:"（即牛皮胶）\n补虚甘平。功与阿胶相近，亦可代用。同葱白煮粥，通大便（李时珍曰∶真阿胶难得，牛皮胶亦可权用。其性味皆平补，宜于虚热之人。张仲景治泻痢，阿胶与黄胶、黄蜡并用。陈藏器曰∶诸胶皆能疗风补虚止泄，驴皮主风为最。《经验方》云∶痈疽初起，酒顿黄明胶四两，服尽，毒不内攻。《唐氏方》∶加穿山甲四片，烧存性用。昂谓∶此方若验，胜于服蜡矾丸也）。"},
  "黄环":{o:[],src:["本草纲目"],d:"（《本经》下品）\n野狼跋子（《别录》下品）\n【释名】凌泉（《本经》）、大就（《本经》）、（《吴\n时珍曰︰此物叶黄而圆，故名黄环，如萝 呼白环之义。亦是葛类，故名就葛。跋乃野狼足名，其荚似之，故曰野狼跋子。\n【集解】《别录》曰︰黄环生蜀郡山谷。三月采根，阴干。\n普曰︰蜀黄环，一名生刍。二月生苗，正赤，高二尺。叶黄圆端大，经日叶有汁黄白。五月实圆。三月采根，黄色从理，如车辐解。\n弘景曰︰似防己，亦作车辐理解。《蜀都赋》云︰青珠黄环，即此。或云是大戟花，定非矣。用甚稀，市人鲜有识者。又曰︰野狼跋子出交广，形扁扁。制捣以杂米投水中，鱼无大小皆浮出而死。\n恭曰︰黄环惟襄阳大有，余处虽有亦稀，巴西人谓之就葛，今园庭亦种之。作藤生，大者茎径六、七寸，根亦葛类，陶云似防己者，近之。取葛根误食之，吐利不止，土浆解之，此真黄环也。今太常收剑南来者，乃鸡屎葛根，非黄环也。其花紫色，其子名野狼跋子，角生似皂荚。交广送入太常者，正是黄环子也。花实与葛同时。\n时珍曰︰吴普所说甚详，而唐宋本草不收何也？《范子计然》云︰黄环出魏郡，以黄色者为善。\n【气味】苦，平，有毒。普曰︰神农、黄帝︰有毒；桐君、扁鹊︰苦。权曰︰大寒，有小毒。\n之才曰︰鸢尾为之使。恶茯苓、防己、干姜。\n【主治】蛊毒鬼疰鬼魅，邪气在脏中，除咳逆寒热治痰嗽，消水肿，利小便（时珍）。\n【附方】新一。\n野狼跋子\n【气味】苦，寒，有小毒。\n【主治】恶疮蜗疥。杀虫鱼（《别录》）。苦酒摩，涂疮疥效（弘景）。"},
  "黄矾":{o:[],src:["本草纲目"],d:"新五。\n耳出汁︰黄矾二两烧枯，绵裹二钱塞之。（《圣惠方》）\n妇人颊疮，每年频发︰水银一两半，以猪脂揉擦，令消尽。入黄矾石末二两，胡粉一两，再加猪脂和令如泥。洗疮净，涂之。别以胡粉涂膏上。此甘家秘方也。（《肘后方》）\n身上瘢痕︰黄矾石（烧令汁尽）、胡粉（炒令黄）各八分。细研，以腊月猪脂和研如泥。以生布揩令痛，乃涂药五度。取鹰粪、白燕窠中草（烧灰）等分，和人乳涂之。其瘢自灭，肉平如故。（崔元亮《海上集验方》）\n急疳蚀齿︰黄矾、青矾半钱，白矾（烧）一钱，麝香一分，为末。敷之，吐涎。（《圣惠方》）\n妒精阴疮︰黄矾、青矾、麝香等分。为末，敷之，不过三度。（《千金方》）"},
  "黄荠水":{o:["黄荠水"],src:["本草备要"],d:"宣，涌，吐\n酸咸，吐痰饮、宿食。酸苦涌泄为阴也。"},
  "黄药子":{o:[],src:["本草纲目"],d:"旧二，新五。项下瘿气 黄药子一斤洗锉，酒一斗浸之。每日早晚常服一盏。忌一切毒物，及戒怒。仍以线逐日度之，乃知其效也。（《斗门方》\n吐血不止︰药子一两，水煎服。（《圣惠方》）\n咯血吐血︰《百一选方》︰用蒲黄、黄药子等分，为末，掌中舐之。王衮《博济方》︰用黄\n鼻衄不止︰黄药子为末。每服二钱，煎淡胶汤下。良久，以新水调面一匙头服之。《兵部手集方》只以新汲水磨汁一碗，顿服。（《简要济众方》）\n产后血晕，恶物冲心，四肢冰冷，唇青腹胀，昏迷︰红药子一两，头红花一钱，水二盏，妇人油钗二只，同煎一盏服。大小便俱利，血自下也。（《禹讲师经验方》）\n天泡水疮︰黄药子末，搽之。（《集简方》）"},
  "黄蜀葵":{o:[],src:["本草纲目"],d:"新八。\n沙石淋痛︰黄蜀葵花一两，炒为末，每米饮服一钱，名独圣散。（《普济方》）\n难产催生︰如圣散︰治胎脏干涩难产，剧者并进三服，良久腹中气宽，胎滑即下也。用黄葵花焙研末，熟汤调服二钱。无花，用子半合研末，酒淘去滓，服之。（《产宝鉴》）\n胎死不下︰即上方，用红花酒下。\n痈疽肿毒︰黄蜀葵花，用盐掺，收瓷器中，密封，经年不坏。每用敷之，自平自溃。无花，用根叶亦可。（《直指方》）\n小儿口疮︰黄葵花，烧末敷之。（《肘后方》）\n小儿木舌︰黄蜀葵花（为末）一钱，黄丹五分。敷之。（《直指方》）\n汤火灼伤︰用瓶盛麻油，以箸就树夹取黄葵花，收入瓶内，勿犯人手，密封收之。遇有伤者，以油涂之甚妙。（《经验方》）\n小儿秃疮︰黄蜀葵花、大黄、黄芩等分，为末。米泔净洗，香油调搽。（《普济方》）\n子及根\n\n旧二，新三。\n临产催生︰宗奭曰︰临产时以四十九粒研烂，温水服之，良久即产。《经验后方》︰用子焙研三钱，井华水服。无子用根，煎汁服。\n便痈初起︰淮人用黄蜀葵子十七粒，皂角半梃，为末，以锻石同醋调涂之。（《永类钤方》）\n痈肿不破︰黄葵子研，酒服，一粒则一头，神效。（《卫生易简方》）\n打扑伤损︰黄葵子研，酒服二钱。（《海上方》）"},
  "黄颔蛇":{o:[],src:["本草纲目"],d:"新三。\n犬啮伤 自死蛇一枚，烧焦为末，纳入疮孔中。（《千金方》）\n五月五日自死赤蛇，烧灰。井华水服方寸匕，日一服。（《千金方》）\n恶疮似癞及马疥大如钱者︰自死蛇一条，水渍至烂。去骨取汁涂之，随手瘥。（《千金》）\n蛇头\n\n新二。\n发背肿毒︰蛇头烧灰，醋和敷之，日三易。（《千金》）\n蛤蟆 疮︰五月五日蛇头，及野猪脂同水衣封之，佳。（《千金方》）\n骨\n\n新一。\n一切冷漏︰自死蛇，取骨为末封之。大痛，以杏仁膏摩之，即止。（《千金方》）\n涎\n\n新三。\n噎膈︰用蛇含蛤蟆，泥包烧存性，研末。米饮服。\n久劳咳嗽吐臭痰者︰寻水边蛇吞青蛙未咽者，连蛇打死，黄泥固济， 研。空心酒服一、二钱，至效。忌生冷五七日，永不发也。（《秘韫》方）\n蛙 不愈︰蛇腹蛙，烧灰封之。（《千金》）"},
  "黄颡鱼":{o:[],src:["本草纲目"],d:"新三。\n水气浮肿︰用黄颡三尾，绿豆一合，大蒜三瓣，水煮烂，去鱼食豆，以汁调商陆末一钱服。其水化为清气而消。诗云︰一头黄颡八须鱼，绿豆同煎一合余。白煮作羹水肿自消除。（《集要》）\n瘰疬溃坏︰用黄 鱼破半日，取出洗净，黄泥固济， 存性研，香油调敷。\n疮浸淫︰方同上。（并《普济》）\n涎（翅下取之）\n\n新一。\n生津丸︰治消渴饮水无度。以黄颡鱼涎和青蛤粉、滑石末等分，丸梧子大。每陈粟米汤下三十丸。\n颊骨"},
  "黑大豆":{o:["黑大豆"],src:["本草备要"],d:"补肾，解毒\n甘寒色黑。属水似肾，肾之谷也（豆有五色，各入五脏），故能补肾镇心（肾水足，则心火宁），明目（肾水足则目明），利水下气（古方治水肿，每单用，或加他药），散热祛风（炒热酒沃，饮其汁，治产后中风危笃及妊娠腰痛，兼能发表。《千金》云∶一以去风，一以消血结），活血（《产书》云∶熬令烟绝，酒淋服，下产后余血）解毒（苏颂曰∶古称大豆解百药毒，试之不然，又加甘草，其验乃奇），消肿止痛，捣涂一切肿毒，煮食稀痘疮。紧小者良（小者名马料豆。每晨盐水吞，或盐水煮食，补肾）。畏五参、龙胆、猪肉。忌浓朴（犯之动气），得前胡、杏仁、牡蛎、石蜜、诸胆汁良。"},
  "鼍龙":{o:[],src:["本草纲目"],d:"旧一。\n肠风痔疾︰颂曰︰用皮及骨烧灰，米饮空心服二钱。甚者，入红鸡冠花、白矾为末和之。\n肉"},
  "鼠妇":{o:[],src:["本草纲目"],d:"旧一，新八。\n产妇尿秘︰鼠妇七枚熬，研末，酒服。（《千金翼》）\n撮口脐风︰《圣惠》︰用鼠妇虫杵，绞汁少许，灌之。《陈氏》︰生杵鼠妇及雀瓮汁服之。\n鹅口白疮︰地鸡研水涂之，即愈。（《寿域方》）\n风虫牙痛︰湿生虫一枚，绵裹咬之。勿令人知。（《圣惠》）\n风牙疼痛︰湿生虫、巴豆仁、胡椒各一枚，研匀，饭丸绿豆大。绵裹一丸咬之，良久涎出吐去，效不可言。（《经效济世方》）\n痘疮倒 ︰湿生虫为末，酒服一字，即起。（《痘疹论》）\n蚰蜒入耳︰湿生虫，研烂，涂耳边自出。或摊纸上作捻，安入耳中亦出。（《卫生宝鉴》）\n射工溪毒︰鼠妇、豆豉各七合、巴豆（去心）三枚，脂和，涂之。（《肘后》）"},
  "鼠尾草":{o:[],src:["本草纲目"],d:"旧一，新二。\n大腹水蛊︰方见马鞭草下。久痢休息，时止时作︰鼠尾草花捣末。饮服一钱。（《圣惠方》）\n下血连年︰鼠尾草、地榆各二两。水二升，煮一升，顿服。二十年者，不过再服。亦可为末，饮服之。（《千金方》）\n反花恶疮，内生恶肉，如饭粒，破之血出，随生反出于外。鼠尾草根切，同猪脂捣敷。（《圣济总录》）"},
  "鼠矢":{o:["鼠矢"],src:["本草备要"],d:"宣，调阴阳\n甘而微寒。治伤寒劳复发热，男子阴易腹痛（妇人伤寒初愈，即与交接，毒中男人，名阴易。若女人与伤寒男子交者，名阳易。《活人》有鼠矢汤）。两头尖者，为雄鼠屎。鼠胆明目。汁滴耳中，治二十年老聋（陶弘景曰∶鼠胆随死辄消，不易得也）。鼠肉治儿疳鼠 （河间曰∶鼠性善穿，而治疮 ，因其性为用也）。"},
  "龙":{o:[],src:["本草纲目"],d:"旧十一，新七。\n健忘：久服聪明，益智慧。用白龙骨、虎骨、远志等分，为末。食后酒服方寸匕，日三。（《千金》）\n劳心梦泄：龙骨、远志等分，为末，炼蜜丸如梧子大，朱砂为衣。每服三十丸，莲子汤下。（《心统》）\n暖精益阳：前方去朱砂。每冷水空心下三十丸。（《经验》）\n睡即泄精：白龙骨四分，韭子五合。为散。空心酒服方寸匕。（《梅师方》）\n遗尿淋沥：白龙骨、桑螵蛸等分，为末。每盐汤服二钱。（《梅师方》）\n老疟不止：龙骨末方寸匕，先发一时，酒一升半，煮三沸，及热服尽。温覆取汗，即效。（《肘后》）\n泄泻不止：白龙骨、白石脂等分，为末，水丸梧子大。紫苏、木瓜汤下，量大人、小儿用。（《心鉴》）\n伤寒毒痢：伤寒八、九日至十余日，大烦渴作热，三焦有疮䘌，下痢，或张口吐舌，目烂，口鼻生疮，不识人，用此除热毒止痢。龙骨半斤，水一斗，煮四升，沉之井底。冷服五合，渐渐进之。（《外台方》）\n热病下痢欲死者：龙骨半斤研，水一斗，煮取五升，候极冷，稍饮，得汗即愈，效。（《肘后方》）\n久痢休息不止者：龙骨四两打碎，水五升，煮取二升半。分五服，冷饮。仍以米饮和丸，每服十丸。（《肘后方》）\n久痢脱肛：白龙骨粉，扑之。（姚和众方）鼻衄眩冒欲死者：龙骨末吹之。（《梅师方》）\n吐血衄血、九窍出血：并用龙骨末，吹入鼻中。昔有人衄血一斛，众方不止，用此即断。（《三因方》）\n耳中出血：龙骨末吹入之。（《三因方》）\n男妇溺血：龙骨末，水服方寸匕，日三。（《千金方》）\n小儿脐疮：龙骨煅研，敷之。（《圣惠方》）\n阴囊汗痒：龙骨、牡蛎粉，扑之。（《医宗三法》）"},
  "龙胆草":{o:["龙胆草"],src:["本草备要"],d:"泻肝胆火，下焦湿热\n大苦大寒，沉阴下行。益肝胆而泻火（相火寄于肝胆，有泻无补，泻其邪热，即所以补火也），兼入膀胱、肾经。除下焦之湿热，与防己同功。酒浸亦能外行、上行。治骨间寒热（肾主骨），惊痫邪气（肝经风火），时气温热，热痢疸黄、寒湿香港脚（足伤湿热，则成香港脚。肿而痛者，为湿香港脚，宜清热利湿搜风。又有挛缩枯细，痛而不肿者，名干香港脚，宜养血润燥），咽喉风热，赤睛 肉（泻肝胆火，能明目。元素曰∶柴胡为主，龙胆为使，目疾要药。昂按∶若目疾初起，宜发散，忌用寒凉），痈疽疮疥。过服损胃。甘草水浸一宿，曝用。小豆、贯众为使。忌地黄。"},
  "龙舌草":{o:[],src:["本草纲目"],d:"新一。\n乳痈肿毒︰龙舌草、忍冬藤，研烂，蜜和傅之。（《多能鄙事》）"},
  "龙葵":{o:[],src:["本草纲目"],d:"旧一。\n去热少睡︰龙葵菜同米，煮作羹粥食之。（《食医心镜》）\n茎、叶、根\n\n旧四，新九。\n通利小便︰方见上。\n从高坠下欲死者︰取老鸦眼睛草茎叶捣汁服，以渣敷患处。（《唐瑶经验方》）\n火焰丹肿︰老鸦眼睛草叶，入醋细研敷之，能消赤肿。（苏颂《图经本草》）\n痈肿无头︰龙葵茎叶捣敷。（《经验方》）\n发背痈疽成疮者︰苏颂《图经》云︰用龙葵一两（为末），麝香一分。研匀，涂之甚善。\n《诸疮恶肿︰老鸦眼睛草擂酒服，以渣敷之。（《普济方》）\n疔肿毒疮，黑色 肿者，乃服丹石毒也；赤色者，肉面毒也︰用龙葵根一握（洗切），乳香末、黄连三两，杏仁六十枚，和捣作饼，浓如三钱，依疮大小敷之，觉痒即换去。痒不可忍，切勿搔动。候炊久，疮中似石榴子戢戢然，乃去药。时时以甘草汤温洗，洗后以蜡贴之。终身不得食羊血。如无龙葵，以蔓荆根代之。（《圣济总录》）\n天泡湿疮︰龙葵苗叶捣敷之。\n吐血不止︰天茄子苗半两，人参二钱半，为末。每服二钱，新汲水下。（《圣济总录》）\n辟除蚤虱︰天茄叶铺于席下，次日尽死。\n多年恶疮︰天茄叶贴之，或为末贴。（《救急良方》）\n产后肠出不收︰老鸦酸浆草一把，水煎，先熏后洗，收乃止。（《救急方》）\n子（七月采之）"},
  "龙齿":{o:["龙齿"],src:["本草备要"],d:"涩，镇惊\n涩凉。镇心安魂。治大人痉癫狂热，小儿五惊十二痫（《卫生宝鉴》曰∶龙齿安魂，虎睛定魄。龙属木，主肝，肝藏魂。虎属金，主肺，肺藏魄也）。治同龙骨。"},
  "𦯶麻":{o:[],src:["本草纲目"],d:"新三。\n一切眼疾︰ 麻子一升。为末。以 猪肝批片，蘸末炙服一字，陈米饮下，磨去壳，马尾筛取黄肉去焦壳，每十两可得四两药慢炙熟，为末，醋和丸梧子大。每服三十丸，白汤下。一方︰以KT 实内袋中蒸熟，暴为末，蜜丸。温水下。（《圣济总录》）"},
  "𫚥":{o:[],src:["本草纲目"],d:"新五。\n鳖症疼痛︰《类编》云︰景陈弟长子拱病鳖症，隐隐见皮内，痛不可忍。外医洪氏曰︰可以鲜虾作羹食之。\n下腹未久痛即止。喜曰︰此真鳖症也。吾求其所好，以尝试之尔。乃合一药如疗脾胃者，而明年又作，再如前治而愈，遂绝根本。补肾兴阳︰用虾米一斤，蛤蚧二枚，茴香、蜀椒各四两。并以青盐化酒炙炒，以木香粗末一两和匀，乘热收新瓶中密封。每服一匙，空心盐酒嚼下，甚妙。\n宣吐风痰︰用连壳虾半斤，入葱、姜、酱煮汁。先吃虾，后吃汁，紧束肚腹，以翎探引取吐。\n疮生虫︰用小虾三十尾，去头、足、壳，同糯米饭研烂，隔纱贴疮上，别以纱罩之。\n一夜解下，挂看皆是小赤虫。即以葱、椒汤洗净，用旧茶笼内白竹叶，随大小剪贴，一日二换。待汁出尽，逐日煎苦楝根汤洗之，以好膏贴之。将生肉，勿换膏药。忌发物。（《直指方》）\n血风 疮︰生虾、黄丹捣和贴之，日一换。（《集简方》）"}
};
